export const CATALOG_SPECIES: MockSpecies[] = [{"id":10,"nodeId":199,"scientificName":"Correlophus ciliatus","commonName":"Tắc kè mào (Crested gecko)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 22-26°C (điểm sưởi 27-28°C), Độ ẩm: 60-80%, Môi trường: Rừng mưa nhiệt đới ẩm tầng tán thấp tại New Caledonia","description":"Loài tắc kè ăn đêm cỡ trung bình nổi bật với hai hàng gai da mềm chạy từ phía trên mắt dọc xuống lưng trông như hàng lông mi. Chân có đệm bám mịn và chóp đuôi có khả năng quấn bám cành cây rất linh hoạt.","imageURL":"https://bionexus.vn/images/correlophus-ciliatus.jpg","referenceURL":"https://www.gbif.org/species/2446592"},{"id":11,"nodeId":200,"scientificName":"Rhacodactylus auriculatus","commonName":"Tắc kè Gargoyle (Gargoyle gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-27°C (điểm sưởi 28-29°C), Độ ẩm: 60-80%, Môi trường: Rừng cây bụi ẩm và rừng mưa thứ sinh tại miền nam New Caledonia","description":"Loài tắc kè New Caledonia có hộp sọ gồ ghề với hai u xương nhô lên ở vùng tai trông như tượng quỷ đá Gargoyle. Màu da biến đổi linh hoạt từ xám tro, nâu vân gỗ sang sọc cam và đỏ gạch.","imageURL":"https://bionexus.vn/images/rhacodactylus-auriculatus.jpg","referenceURL":"https://www.gbif.org/species/2446599"},{"id":12,"nodeId":200,"scientificName":"Rhacodactylus leachianus","commonName":"Tắc kè khổng lồ New Caledonia (New Caledonia giant gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-27°C (điểm sưởi 27-29°C), Độ ẩm: 65-80%, Môi trường: Tán rừng già nguyên sinh ẩm ướt tại New Caledonia","description":"Loài tắc kè còn sống lớn nhất thế giới với cơ thể đồ sộ, các nếp da chùng chạy dọc hai bên sườn và chiếc đuôi ngắn mập hình gốc cây. Da màu xanh rêu đốm trắng, hồng hoặc nâu sẫm như địa y.","imageURL":"https://bionexus.vn/images/rhacodactylus-leachianus.jpg","referenceURL":"https://www.gbif.org/species/2446584"},{"id":13,"nodeId":201,"scientificName":"Phelsuma grandis","commonName":"Tắc kè ngày khổng lồ Madagascar (Madagascar giant day gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 25-30°C (điểm sưởi 32-35°C), Độ ẩm: 60-80%, Môi trường: Rừng nhiệt đới và vườn cây ăn quả miền bắc Madagascar","description":"Loài tắc kè hoạt động ban ngày cỡ lớn với màu xanh lục ngọc bích rực rỡ và các vệt đỏ son nổi bật từ mõm qua mắt cùng dọc sống lưng. Đồng tử mắt tròn đen thích nghi hoàn hảo với ánh nắng.","imageURL":"https://bionexus.vn/images/phelsuma-grandis.jpg","referenceURL":"https://www.gbif.org/species/2447558"},{"id":14,"nodeId":201,"scientificName":"Phelsuma laticauda","commonName":"Tắc kè ngày bụi vàng (Gold dust day gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 31-33°C), Độ ẩm: 60-75%, Môi trường: Rừng ẩm ven biển, rặng dừa và chuối tại bắc Madagascar","description":"Loài tắc kè ngày nhỏ nhắn có màu xanh nõn chuối rực sáng, vùng vai và gáy lấm tấm những hạt màu vàng kim li ti như bụi vàng, kèm ba vệt đỏ cam hình giọt nước ở lưng dưới.","imageURL":"https://bionexus.vn/images/phelsuma-laticauda.jpg","referenceURL":"https://www.gbif.org/species/2447506"},{"id":15,"nodeId":201,"scientificName":"Phelsuma madagascariensis","commonName":"Tắc kè ngày Madagascar (Madagascar day gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 31-34°C), Độ ẩm: 65-85%, Môi trường: Rừng mưa nhiệt đới ẩm dọc bờ biển phía đông Madagascar","description":"Loài tắc kè ngày tiêu biểu của bờ đông Madagascar với thân xanh lá cây đậm, hàng đốm đỏ đối xứng dọc sống lưng và vệt đỏ kéo dài từ lỗ mũi xuyên qua mắt tới tận tai.","imageURL":"https://bionexus.vn/images/phelsuma-madagascariensis.jpg","referenceURL":"https://www.gbif.org/species/2447419"},{"id":16,"nodeId":201,"scientificName":"Phelsuma klemmeri","commonName":"Tắc kè ngày đầu vàng (Yellow-headed day gecko)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 30-32°C), Độ ẩm: 60-80%, Môi trường: Rừng tre trúc ven biển tây bắc Madagascar","description":"Loài tắc kè ngày kích thước siêu nhỏ với cơ thể dẹp mảnh tuyệt đẹp: phần đầu màu vàng chanh tươi sáng, dọc hai bên thân ánh lên hai dải màu xanh ngọc lam neon rực rỡ.","imageURL":"https://bionexus.vn/images/phelsuma-klemmeri.jpg","referenceURL":"https://www.gbif.org/species/2447543"},{"id":17,"nodeId":201,"scientificName":"Phelsuma standingi","commonName":"Tắc kè ngày Standing (Standing's day gecko)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 25-31°C (điểm sưởi 34-36°C), Độ ẩm: 45-65%, Môi trường: Rừng cây gai khô hạn và thảo nguyên cây bụi tây nam Madagascar","description":"Loài tắc kè ngày cỡ lớn có hoa văn vằn lưới độc đáo: khi còn non thân mang các khoang vàng và nâu đỏ rực rỡ, khi trưởng thành chuyển sang màu xanh ngọc lam pha xám bạc thanh lịch.","imageURL":"https://bionexus.vn/images/phelsuma-standingi.jpg","referenceURL":"https://www.gbif.org/species/2447446"},{"id":18,"nodeId":201,"scientificName":"Phelsuma cepediana","commonName":"Tắc kè ngày đuôi lam (Blue-tailed day gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-28°C (điểm sưởi 30-32°C), Độ ẩm: 65-85%, Môi trường: Rừng nhiệt đới ẩm và rừng cọ bản địa trên đảo Mauritius","description":"Loài tắc kè ngày đặc hữu của đảo Mauritius với sự phối màu cực kỳ bắt mắt: lưng xanh lục ngọc điểm những vệt đỏ thắm, còn hai bên sườn và toàn bộ đuôi mang sắc xanh coban ánh tím.","imageURL":"https://bionexus.vn/images/phelsuma-cepediana.jpg","referenceURL":"https://www.gbif.org/species/2447483"},{"id":19,"nodeId":201,"scientificName":"Phelsuma ornata","commonName":"Tắc kè ngày hoa văn Mauritius (Ornate day gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 31-33°C), Độ ẩm: 55-75%, Môi trường: Rừng cọ ven biển và bụi cây khô trên đảo Mauritius","description":"Loài tắc kè ngày nhỏ đặc hữu vùng Mascarene với chiếc mặt nạ hoa văn xanh lam, trắng và đỏ gạch trên đỉnh đầu, thân xanh lục điểm đốm đỏ và đuôi xanh ngọc.","imageURL":"https://bionexus.vn/images/phelsuma-ornata.jpg","referenceURL":"https://www.gbif.org/species/2447492"},{"id":20,"nodeId":201,"scientificName":"Phelsuma quadriocellata","commonName":"Tắc kè ngày bốn đốm mắt (Peacock day gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C (điểm sưởi 30-32°C), Độ ẩm: 65-85%, Môi trường: Rừng mưa ẩm cao nguyên và bờ đông Madagascar","description":"Loài tắc kè ngày cỡ nhỏ màu xanh lục tươi, nổi bật với hai hoặc bốn đốm tròn màu đen viền xanh ngọc lam ở hai bên hông trông giống đốm mắt trên lông đuôi chim công.","imageURL":"https://bionexus.vn/images/phelsuma-quadriocellata.jpg","referenceURL":"https://www.gbif.org/species/9595397"},{"id":21,"nodeId":201,"scientificName":"Phelsuma lineata","commonName":"Tắc kè ngày sọc (Lined day gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 31-33°C), Độ ẩm: 60-80%, Môi trường: Rừng ẩm, vườn cây và hàng rào cây xanh ở đông Madagascar","description":"Loài tắc kè ngày cỡ nhỏ có màu xanh lá tươi sáng phía trên lưng, hai bên sườn chạy dọc một dải sọc đen đậm kèm viền trắng kem tương phản rõ nét từ sau mắt tới gốc đuôi.","imageURL":"https://bionexus.vn/images/phelsuma-lineata.jpg","referenceURL":"https://www.gbif.org/species/2447447"},{"id":22,"nodeId":202,"scientificName":"Gekko gecko","commonName":"Tắc kè hoa (Tokay gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 25-31°C (điểm sưởi 32-35°C), Độ ẩm: 65-85%, Môi trường: Rừng nhiệt đới, vách đá vôi và khu dân cư ven rừng Đông Nam Á","description":"Loài tắc kè ăn đêm cỡ lớn nổi tiếng khắp Đông Nam Á với làn da màu xám xanh hoặc xanh lam nhạt điểm hàng trăm đốm cam đỏ rực rỡ, đầu to hàm khỏe và tiếng kêu 'tắc-kè' vang dội.","imageURL":"https://bionexus.vn/images/gekko-gecko.jpg","referenceURL":"https://www.gbif.org/species/2447367"},{"id":23,"nodeId":202,"scientificName":"Gekko vittatus","commonName":"Tắc kè sọc trắng (Lined gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 30-32°C), Độ ẩm: 70-85%, Môi trường: Rừng mưa nhiệt đới và rừng cọ sago tại Indonesia và Melanesia","description":"Loài tắc kè thân thon dài màu nâu đồng đến nâu ô-liu, nổi bật với một dải sọc trắng kem sắc nét chạy dọc giữa sống lưng và chẻ làm hai nhánh chữ Y ở vùng gáy hướng tới mắt.","imageURL":"https://bionexus.vn/images/gekko-vittatus.jpg","referenceURL":"https://www.gbif.org/species/2447322"},{"id":24,"nodeId":202,"scientificName":"Gekko kuhli","commonName":"Tắc kè bay Kuhl (Kuhl's flying gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 30-32°C), Độ ẩm: 75-90%, Môi trường: Tầng tán rừng mưa nhiệt đới đất thấp Đông Nam Á","description":"Loài tắc kè có cấu tạo khí động học kỳ thú: hai bên sườn, bốn bàn chân, hai bên má và toàn bộ chiếc đuôi đều có các diềm da rộng hình thùy giúp chúng vừa ngụy trang vừa lượn dù giữa các thân cây.","imageURL":"https://bionexus.vn/images/gekko-kuhli.jpg","referenceURL":"https://www.gbif.org/species/11192822"},{"id":25,"nodeId":203,"scientificName":"Coleonyx variegatus","commonName":"Thằn lằn da báo sọc miền Tây (Western banded gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 32-34°C), Độ ẩm: 30-45%, Môi trường: Sa mạc đá khô hạn, hẻm núi và đồng cỏ bán hoang mạc Tây Nam Bắc Mỹ","description":"Loài tắc kè có mí mắt động cỡ nhỏ họ hàng gần với thằn lằn da báo, sở hữu làn da mịn màng màu vàng kem nhạt xen kẽ những dải khoang nâu sô-cô-la và đốm nhỏ thanh mảnh.","imageURL":"https://bionexus.vn/images/coleonyx-variegatus.jpg","referenceURL":"https://www.gbif.org/species/2447244"},{"id":26,"nodeId":204,"scientificName":"Nephrurus levis","commonName":"Tắc kè đuôi núm trơn (Smooth knob-tailed gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 31-33°C), Độ ẩm: 30-50%, Môi trường: Đồi cát đỏ và trảng cỏ spinifex khô hạn miền trung và tây nước Úc","description":"Loài tắc kè đất kỳ lạ bản địa nước Úc với cái đầu to, đôi mắt tròn đen khổng lồ như mắt búp bê và chiếc đuôi ngắn bè hình củ cà rốt kết thúc bằng một núm tròn nhỏ ở chóp.","imageURL":"https://bionexus.vn/images/nephrurus-levis.jpg","referenceURL":"https://www.gbif.org/species/2447717"},{"id":27,"nodeId":204,"scientificName":"Nephrurus amyae","commonName":"Tắc kè đuôi núm gai Trung Úc (Centralian rough knob-tail gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 32-34°C), Độ ẩm: 25-45%, Môi trường: Sườn núi đá sa thạch và hẻm đá khô cằn tại miền trung nước Úc","description":"Loài lớn nhất trong chi tắc kè đuôi núm với lớp da màu cam đất nung phủ đầy các cụm gai sần nhọn như vỏ sầu riêng, đầu cực kỳ to rộng và đôi mắt đen sâu thẳm.","imageURL":"https://bionexus.vn/images/nephrurus-amyae.jpg","referenceURL":"https://www.gbif.org/species/2447727"},{"id":28,"nodeId":205,"scientificName":"Strophurus williamsi","commonName":"Tắc kè đuôi gai miền Đông (Eastern spiny-tailed gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-29°C (điểm sưởi 31-33°C), Độ ẩm: 40-60%, Môi trường: Rừng bạch đàn thưa và vùng cây bụi bán khô hạn miền đông nước Úc","description":"Loài tắc kè sống trên cây nhỏ nhắn của Úc có màu xám bạc điểm đốm đen, cặp mắt có tròng mắt hoa văn ren màu đồng cam và hai hàng gai mềm màu cam dọc sống lưng xuống tới đuôi.","imageURL":"https://bionexus.vn/images/strophurus-williamsi.jpg","referenceURL":"https://www.gbif.org/species/2446890"},{"id":29,"nodeId":206,"scientificName":"Uroplatus phantasticus","commonName":"Tắc kè đuôi lá quỷ Satan (Satanic leaf-tailed gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-24°C (điểm sưởi 24-25°C), Độ ẩm: 75-90%, Môi trường: Tầng cây bụi thấp trong rừng mưa núi cao mát ẩm miền đông Madagascar","description":"Bậc thầy ngụy trang bậc nhất giới tự nhiên với chiếc đuôi dẹp phẳng như một chiếc lá khô mục có đầy đủ gân lá, vết rách khuyết ở rìa và cặp gai nhỏ nhô lên phía trên mí mắt như hai chiếc sừng.","imageURL":"https://bionexus.vn/images/uroplatus-phantasticus.jpg","referenceURL":"https://www.gbif.org/species/2445755"},{"id":30,"nodeId":206,"scientificName":"Uroplatus sikorae","commonName":"Tắc kè đuôi lá rêu Sikora (Mossy leaf-tailed gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-25°C (điểm sưởi 25-26°C), Độ ẩm: 75-90%, Môi trường: Rừng mưa ẩm nguyên sinh nhiều rêu và địa y tại miền đông và bắc Madagascar","description":"Loài tắc kè đuôi lá cỡ trung bình có rìa da tua tủa chạy dọc hàm dưới, hai bên thân và bốn chân giúp xóa nhòa ranh giới cơ thể với lớp rêu và địa y trên vỏ cây rừng mưa.","imageURL":"https://bionexus.vn/images/uroplatus-sikorae.jpg","referenceURL":"https://www.gbif.org/species/2445771"},{"id":31,"nodeId":206,"scientificName":"Uroplatus fimbriatus","commonName":"Tắc kè đuôi lá khổng lồ (Common flat-tail gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-26°C (điểm sưởi 26-27°C), Độ ẩm: 75-90%, Môi trường: Rừng mưa nhiệt đới đất thấp và trung du phía đông Madagascar","description":"Loài lớn nhất trong chi tắc kè đuôi lá với chiều dài vượt quá 30 cm, đôi mắt to tròn có đồng tử dọc viền các vòng tròn đồng tâm màu vàng cam và đỏ rực kỳ ảo.","imageURL":"https://bionexus.vn/images/uroplatus-fimbriatus.jpg","referenceURL":"https://www.gbif.org/species/2445758"},{"id":32,"nodeId":206,"scientificName":"Uroplatus henkeli","commonName":"Tắc kè đuôi lá Henkel (Henkel's leaf-tailed gecko)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 22-27°C (điểm sưởi 27-28°C), Độ ẩm: 70-85%, Môi trường: Rừng ẩm đất thấp và rừng chuyển tiếp tại tây bắc Madagascar","description":"Loài tắc kè đuôi lá cỡ lớn bản địa vùng tây bắc Madagascar với chiếc đầu dẹp dài, diềm da mịn viền quanh thân và màu sắc biến thiên từ trắng kem đốm nâu tới vân vỏ cây.","imageURL":"https://bionexus.vn/images/uroplatus-henkeli.jpg","referenceURL":"https://www.gbif.org/species/2445768"},{"id":33,"nodeId":206,"scientificName":"Uroplatus ebenaui","commonName":"Tắc kè đuôi lá mũi giáo (Spearpoint leaf-tailed gecko)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 19-24°C (điểm sưởi 24-25°C), Độ ẩm: 75-90%, Môi trường: Rừng mưa núi cao và rừng ẩm miền bắc và tây bắc Madagascar","description":"Loài tắc kè đuôi lá cỡ nhỏ có hình dáng gần giống tắc kè đuôi lá quỷ Satan nhưng sở hữu chiếc đuôi ngắn nhỏ nhọn ở đầu mút như mũi giáo hoặc chiếc lá khô bị mục rữa.","imageURL":"https://bionexus.vn/images/uroplatus-ebenaui.jpg","referenceURL":"https://www.gbif.org/species/9565477"},{"id":34,"nodeId":206,"scientificName":"Uroplatus lineatus","commonName":"Tắc kè đuôi lá sọc tre (Lined leaf-tailed gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-26°C (điểm sưởi 26-28°C), Độ ẩm: 70-85%, Môi trường: Rừng tre trúc ẩm ướt và rừng cọ đất thấp miền đông Madagascar","description":"Loài tắc kè đuôi lá có hình thái khác biệt nhất trong chi: cơ thể thuôn dài mảnh dẻ với các đường sọc dọc màu vàng kem và nâu gỗ chạy suốt từ mõm tới đuôi như một bẹ tre khô.","imageURL":"https://bionexus.vn/images/uroplatus-lineatus.jpg","referenceURL":"https://www.gbif.org/species/2445744"},{"id":35,"nodeId":207,"scientificName":"Lygodactylus williamsi","commonName":"Tắc kè lùn xanh ngọc lam (Turquoise dwarf gecko)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 31-33°C), Độ ẩm: 60-80%, Môi trường: Chỉ sống trên loài cây dứa dại đặc hữu Pandanus rabaiensis tại rừng Kimboza, Tanzania","description":"Loài tắc kè ngày kích thước tí hon nổi tiếng vì con đực trưởng thành sở hữu màu xanh lam điện quang rực rỡ bậc nhất giới động vật, tương phản với cổ họng đen đậm và bụng màu vàng cam.","imageURL":"https://bionexus.vn/images/lygodactylus-williamsi.jpg","referenceURL":"https://www.gbif.org/species/2446749"},{"id":36,"nodeId":208,"scientificName":"Basiliscus plumifrons","commonName":"Rồng đất Basilisk mào xanh (Plumed basilisk)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-27°C, Độ ẩm: 70-85%, Môi trường: Rừng mưa nhiệt đới ẩm dọc bờ sông suối tại Trung Mỹ (Costa Rica, Nicaragua, Panama)","description":"Loài thằn lằn màu xanh lục bảo rực sáng nổi tiếng khắp thế giới với khả năng chạy bằng hai chân sau trên mặt nước; con đực trưởng thành sở hữu mào đôi trên đầu, mào lưng và mào đuôi cực kỳ đồ sộ.","imageURL":"https://bionexus.vn/images/basiliscus-plumifrons.jpg","referenceURL":"https://www.gbif.org/species/5221810"},{"id":37,"nodeId":209,"scientificName":"Teratoscincus scincus","commonName":"Tắc kè mắt ếch Turkestan (Common wonder gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-31°C (điểm sưởi 33-36°C), Độ ẩm: 25-40%, Môi trường: Đồi cát hoang mạc và bán hoang mạc vùng Trung Á và Trung Đông","description":"Loài tắc kè sa mạc kỳ lạ có đôi mắt lồi to phát sáng như mắt ếch trong đêm và lớp vảy lớn xếp chồng lên nhau như vảy cá hoặc vảy thằn lằn bóng thay vì da hạt mềm.","imageURL":"https://bionexus.vn/images/teratoscincus-scincus.jpg","referenceURL":"https://www.gbif.org/species/2447091"},{"id":38,"nodeId":210,"scientificName":"Stenodactylus sthenodactylus","commonName":"Tắc kè cát ngón mảnh (Elegant gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 25-32°C (điểm sưởi 34-37°C), Độ ẩm: 25-40%, Môi trường: Hoang mạc sỏi đá và cồn cát khô hạn khắp Bắc Phi và Cận Đông","description":"Loài tắc kè sa mạc tí hon với bốn chiếc chân cao mảnh khảnh, cái đầu tròn to và đôi mắt lồi lớn có đồng tử dọc viền răng cưa lấp lánh dưới ánh đèn đêm.","imageURL":"https://bionexus.vn/images/stenodactylus-sthenodactylus.jpg","referenceURL":"https://www.gbif.org/species/5221497"},{"id":39,"nodeId":211,"scientificName":"Paroedura picta","commonName":"Tắc kè báo Madagascar (Panther gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 30-32°C), Độ ẩm: 50-65%, Môi trường: Rừng khô rụng lá và thảm lá mục vùng tây nam và nam Madagascar","description":"Loài tắc kè sống trên mặt đất có cái đầu lớn, đôi mắt to tròn và hoa văn khoang nâu sẫm viền trắng kem tuyệt đẹp; nhiều cá thể mang thêm một dải sọc trắng chạy dọc chính giữa sống lưng.","imageURL":"https://bionexus.vn/images/paroedura-picta.jpg","referenceURL":"https://www.gbif.org/species/2445469"},{"id":40,"nodeId":212,"scientificName":"Lepidodactylus lugubris","commonName":"Thạch sùng trinh sản (Mourning gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C (điểm sưởi 28-30°C), Độ ẩm: 65-85%, Môi trường: Rừng ven biển, rừng ngập mặn và vườn cây khắp vùng nhiệt đới Ấn Độ - Thái Bình Dương","description":"Loài thạch sùng nhỏ nhắn màu nâu kem điểm hàng vạch hình chữ W dọc sống lưng, nổi tiếng trong sinh học vì quần thể hầu như chỉ toàn cá thể cái có khả năng tự sinh sản vô tính.","imageURL":"https://bionexus.vn/images/lepidodactylus-lugubris.jpg","referenceURL":"https://www.gbif.org/species/9164170"},{"id":41,"nodeId":213,"scientificName":"Tarentola mauritanica","commonName":"Tắc kè tường Địa Trung Hải (Moorish gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-29°C (điểm sưởi 31-34°C), Độ ẩm: 40-60%, Môi trường: Vách đá khô, tường đá cổ và thân cây ô-liu quanh lưu vực Địa Trung Hải","description":"Loài tắc kè vách đá cứng cáp đặc trưng của vùng Địa Trung Hải với lớp da dày phủ đầy những hàng u gai sần sùi hình chóp trên lưng và đuôi trông như một chú cá sấu thu nhỏ.","imageURL":"https://bionexus.vn/images/tarentola-mauritanica.jpg","referenceURL":"https://www.gbif.org/species/2445034"},{"id":42,"nodeId":214,"scientificName":"Gonatodes albogularis","commonName":"Tắc kè ngày đầu vàng Trung Mỹ (Yellow-headed gecko)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 30-32°C), Độ ẩm: 65-80%, Môi trường: Rừng nhiệt đới ẩm và rừng khô ven biển Trung Mỹ, Caribe và bắc Nam Mỹ","description":"Loài tắc kè hoạt động ban ngày cỡ nhỏ thuộc họ Sphaerodactylidae có sự dị hình giới tính rõ rệt: con đực có thân màu đen nhung hoặc xanh lam đậm với toàn bộ phần đầu màu vàng cam rực rỡ.","imageURL":"https://bionexus.vn/images/gonatodes-albogularis.jpg","referenceURL":"https://www.gbif.org/species/2447609"},{"id":43,"nodeId":215,"scientificName":"Chamaeleo calyptratus","commonName":"Tắc kè hoa mũ Yemen (Veiled chameleon)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 33-36°C), Độ ẩm: 45-65%, Môi trường: Sườn núi cao nguyên, thung lũng xanh (wadi) và bụi cây keo tại Yemen và Ả Rập Xê Út","description":"Loài tắc kè hoa phổ biến nhất thế giới, dễ nhận diện nhờ chiếc mũ xương cao vút trên đỉnh đầu (đặc biệt ở con đực), thân dẹp bên màu xanh ngọc điểm các dải khoang vàng, cam và xanh lam.","imageURL":"https://bionexus.vn/images/chamaeleo-calyptratus.jpg","referenceURL":"https://www.gbif.org/species/2449133"},{"id":44,"nodeId":216,"scientificName":"Furcifer pardalis","commonName":"Tắc kè hoa báo (Panther chameleon)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 31-33°C), Độ ẩm: 60-80%, Môi trường: Rừng nhiệt đới ẩm ven biển và đảo nhỏ miền bắc và đông Madagascar","description":"Loài tắc kè hoa rực rỡ nhất hành tinh, nổi tiếng vì mỗi vùng địa lý ở Madagascar lại sản sinh ra những cá thể đực mang bảng màu hoàn toàn khác biệt từ xanh ngọc lam, đỏ lửa, cam vàng tới cầu vồng.","imageURL":"https://bionexus.vn/images/furcifer-pardalis.jpg","referenceURL":"https://www.gbif.org/species/5221988"},{"id":45,"nodeId":216,"scientificName":"Furcifer oustaleti","commonName":"Tắc kè hoa khổng lồ Oustalet (Oustalet's chameleon)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 32-35°C), Độ ẩm: 50-70%, Môi trường: Savan cây gỗ, rừng khô và bìa rừng trên khắp đảo Madagascar","description":"Loài tắc kè hoa có chiều dài cơ thể lớn nhất thế giới (đạt tới gần 70 cm), sở hữu chiếc mũ hộp sọ tròn rộng màu nâu đồng, xám rêu và các đốm tròn lớn dọc bên sườn.","imageURL":"https://bionexus.vn/images/furcifer-oustaleti.jpg","referenceURL":"https://www.gbif.org/species/5221973"},{"id":46,"nodeId":216,"scientificName":"Furcifer lateralis","commonName":"Tắc kè hoa thảm (Carpet chameleon)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-26°C (điểm sưởi 28-30°C), Độ ẩm: 60-80%, Môi trường: Cao nguyên trung tâm và vùng cây bụi ẩm tại Madagascar","description":"Loài tắc kè hoa cỡ nhỏ nổi tiếng với hoa văn phức tạp và rực rỡ như một tấm thảm dệt Ba Tư, đặc biệt là ở con cái đang mang trứng với các đốm tròn cam, vàng, đen và xanh ngọc.","imageURL":"https://bionexus.vn/images/furcifer-lateralis.jpg","referenceURL":"https://www.gbif.org/species/5221969"},{"id":47,"nodeId":217,"scientificName":"Trioceros jacksonii","commonName":"Tắc kè hoa ba sừng Jackson (Jackson's chameleon)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-26°C (điểm sưởi 28-30°C), Độ ẩm: 60-80%, Môi trường: Rừng ẩm vùng núi cao mát mẻ tại Kenya và miền bắc Tanzania","description":"Loài tắc kè hoa nổi tiếng với ba chiếc sừng thật có lõi xương nhô thẳng ra phía trước trên trán và mõm của con đực trưởng thành, gợi nhớ trực tiếp đến loài khủng long ba sừng Triceratops.","imageURL":"https://bionexus.vn/images/trioceros-jacksonii.jpg","referenceURL":"https://www.gbif.org/species/8371864"},{"id":48,"nodeId":217,"scientificName":"Trioceros melleri","commonName":"Tắc kè hoa một sừng Meller (Meller's chameleon)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-29°C (điểm sưởi 31-33°C), Độ ẩm: 55-75%, Môi trường: Savan cây gỗ thưa và rừng miombo tại Đông Phi (Tanzania, Malawi, Mozambique)","description":"Loài tắc kè hoa lớn nhất lục địa châu Phi đại lục (ngoài Madagascar), nổi bật với một chiếc sừng nhỏ ở chóp mũi, hai thùy da lớn phía sau đầu như tai voi và hàng vây lưng nhấp nhô.","imageURL":"https://bionexus.vn/images/trioceros-melleri.jpg","referenceURL":"https://www.gbif.org/species/7858801"},{"id":49,"nodeId":217,"scientificName":"Trioceros hoehnelii","commonName":"Tắc kè hoa mũ cao Kenya (High-casqued chameleon)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-25°C (điểm sưởi 27-29°C), Độ ẩm: 60-80%, Môi trường: Cây bụi và đồng cỏ vùng núi cao mát lạnh tại Kenya và đông Uganda","description":"Loài tắc kè hoa vùng núi cao cỡ nhỏ đến trung bình có chiếc mũ sọ nhô cao phủ các tấm vảy lớn, hàng râu gai rõ rệt dưới cằm và một mấu sừng tù nhỏ ở đầu mõm.","imageURL":"https://bionexus.vn/images/trioceros-hoehnelii.jpg","referenceURL":"https://www.gbif.org/species/7582319"},{"id":50,"nodeId":218,"scientificName":"Brookesia superciliaris","commonName":"Tắc kè hoa lá khô sừng mắt (Brown leaf chameleon)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 19-24°C (điểm sưởi 25-26°C), Độ ẩm: 75-90%, Môi trường: Thảm lá khô trên nền rừng mưa nhiệt đới miền đông Madagascar","description":"Loài tắc kè hoa đất kích thước nhỏ với hình dáng hệt như một chiếc lá khô cuộn lại: sống lưng dẹp có gân nổi, hai bên hông có hàng gai xương và phía trên mỗi mắt có một phiến sừng tam giác nhô cao.","imageURL":"https://bionexus.vn/images/brookesia-superciliaris.jpg","referenceURL":"https://www.gbif.org/species/2449345"},{"id":51,"nodeId":219,"scientificName":"Calumma parsonii","commonName":"Tắc kè hoa Parson (Parson's chameleon)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 20-26°C (điểm sưởi 28-30°C), Độ ẩm: 70-90%, Môi trường: Tầng tán rừng mưa nguyên sinh ẩm mát miền đông và bắc Madagascar","description":"Loài tắc kè hoa nặng nhất thế giới với thân hình vạm vỡ màu xanh lục ngọc lam, mí mắt màu cam rực rỡ hoặc vàng tươi và hai mấu sừng dẹp hướng lên ở đầu mõm của con đực.","imageURL":"https://bionexus.vn/images/calumma-parsonii.jpg","referenceURL":"https://www.gbif.org/species/2448847"},{"id":52,"nodeId":220,"scientificName":"Tiliqua scincoides","commonName":"Thằn lằn lưỡi xanh miền Đông (Common bluetongue)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 35-38°C), Độ ẩm: 35-50%, Môi trường: Đồng cỏ, rừng bạch đàn thưa và vườn cây vùng đông và bắc nước Úc","description":"Loài thằn lằn bóng cỡ lớn nổi tiếng với chiếc lưỡi dẹp rộng màu xanh coban tươi sáng dùng để hù dọa kẻ săn mồi, thân hình trụ dài phủ vảy bóng mượt có các dải vằn ngang.","imageURL":"https://bionexus.vn/images/tiliqua-scincoides.jpg","referenceURL":"https://www.gbif.org/species/2462503"},{"id":53,"nodeId":220,"scientificName":"Tiliqua gigas","commonName":"Thằn lằn lưỡi xanh Indonesia (Indonesian blue-tongued skink)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 25-31°C (điểm sưởi 35-38°C), Độ ẩm: 65-85%, Môi trường: Nền rừng mưa nhiệt đới ẩm tại New Guinea và các đảo phía đông Indonesia","description":"Loài thằn lằn lưỡi xanh vùng nhiệt đới ẩm có chiếc đuôi dài hơn các họ hàng nước Úc, bốn chân màu đen bóng đặc trưng và các dải khoang đen sẫm chạy ngang lưng.","imageURL":"https://bionexus.vn/images/tiliqua-gigas.jpg","referenceURL":"https://www.gbif.org/species/2462515"},{"id":54,"nodeId":220,"scientificName":"Tiliqua rugosa","commonName":"Thằn lằn quả thông (Shingleback lizard)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-31°C (điểm sưởi 36-40°C), Độ ẩm: 25-40%, Môi trường: Thảo nguyên khô hạn, vùng cây bụi và bán hoang mạc miền nam và tây nước Úc","description":"Loài thằn lằn lưỡi xanh đặc biệt với lớp vảy lưng to dày xếp chồng gồ ghề như trái thông khô và chiếc đuôi ngắn tù tròn có hình dáng giống hệt chiếc đầu thứ hai để đánh lừa kẻ săn mồi.","imageURL":"https://bionexus.vn/images/tiliqua-rugosa.jpg","referenceURL":"https://www.gbif.org/species/2462522"},{"id":55,"nodeId":221,"scientificName":"Corucia zebrata","commonName":"Thằn lằn bóng đuôi khỉ (Solomon Islands skink)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 31-33°C), Độ ẩm: 70-85%, Môi trường: Tầng tán cao của rừng mưa nhiệt đới trên quần đảo Solomon","description":"Loài thằn lằn bóng còn sống lớn nhất thế giới, chuyên sống trên cây với chiếc đuôi dài cực khỏe có thể quấn bám cành cây như đuôi khỉ và bàn chân có móng vuốt cong sắc.","imageURL":"https://bionexus.vn/images/corucia-zebrata.jpg","referenceURL":"https://www.gbif.org/species/2462499"},{"id":56,"nodeId":222,"scientificName":"Tribolonotus gracilis","commonName":"Thằn lằn cá sấu mắt đỏ (Red-eyed crocodile skink)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C (điểm sưởi 28-30°C), Độ ẩm: 75-90%, Môi trường: Nền rừng mưa nhiệt đới ẩm ướt gần khe suối tại đảo New Guinea","description":"Loài thằn lằn bóng có ngoại hình kỳ ảo như một chú rồng hoặc cá sấu thu nhỏ với bốn hàng vảy gai cứng chạy dọc lưng màu nâu đen và đôi vòng da màu cam đỏ rực rỡ bao quanh mắt.","imageURL":"https://bionexus.vn/images/tribolonotus-gracilis.jpg","referenceURL":"https://www.gbif.org/species/2461081"},{"id":57,"nodeId":223,"scientificName":"Plestiodon fasciatus","commonName":"Thằn lằn bóng năm sọc đuôi lam (Common five-lined skink)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C (điểm sưởi 31-34°C), Độ ẩm: 50-70%, Môi trường: Rừng lá rộng ẩm ướt nhiều gốc cây mục tại miền đông Bắc Mỹ","description":"Loài thằn lằn bóng cỡ nhỏ nổi bật ở giai đoạn còn non với thân màu đen bóng điểm năm đường sọc vàng kem chạy dọc từ đầu xuống lưng và chiếc đuôi màu xanh coban sáng chói.","imageURL":"https://bionexus.vn/images/plestiodon-fasciatus.jpg","referenceURL":"https://www.gbif.org/species/5789613"},{"id":58,"nodeId":223,"scientificName":"Plestiodon laticeps","commonName":"Thằn lằn bóng đầu rộng (Broad-headed skink)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-29°C (điểm sưởi 32-35°C), Độ ẩm: 50-70%, Môi trường: Rừng cây sồi và cây gỗ cứng vùng đông nam và trung tâm Hoa Kỳ","description":"Loài lớn nhất trong nhóm thằn lằn bóng năm sọc Bắc Mỹ: con đực trưởng thành sở hữu thân màu nâu ô-liu bóng láng và một cái đầu phình rộng màu đỏ cam rực lửa vào mùa sinh sản.","imageURL":"https://bionexus.vn/images/plestiodon-laticeps.jpg","referenceURL":"https://www.gbif.org/species/5789628"},{"id":59,"nodeId":224,"scientificName":"Chalcides ocellatus","commonName":"Thằn lằn bóng đốm mắt Địa Trung Hải (Ocellated skink)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-31°C (điểm sưởi 34-38°C), Độ ẩm: 30-45%, Môi trường: Vùng đất cát khô hạn, vườn cây ô-liu và bờ đá quanh Địa Trung Hải và Bắc Phi","description":"Loài thằn lằn bóng thân trụ tròn láng bóng như đánh vecni, phủ hàng trăm đốm nhỏ màu đen có tâm trắng bạc trên nền da màu đồng vàng giúp chúng trườn xuyên qua lớp cát mịn như cá bơi.","imageURL":"https://bionexus.vn/images/chalcides-ocellatus.jpg","referenceURL":"https://www.gbif.org/species/5225137"},{"id":60,"nodeId":225,"scientificName":"Egernia cunninghami","commonName":"Thằn lằn bóng đuôi gai Cunningham (Cunningham's spiny-tailed skink)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 35-38°C), Độ ẩm: 30-50%, Môi trường: Các mỏm núi đá hoa cương (granite) và rừng đá vùng đông nam nước Úc","description":"Loài thằn lằn bóng cỡ lớn sống theo bầy trên các vách đá hoa cương, sở hữu lớp vảy lưng có sống nhọn chạy dọc xuống chiếc đuôi phủ đầy gai cứng dùng để khóa chặt cơ thể trong khe đá.","imageURL":"https://bionexus.vn/images/egernia-cunninghami.jpg","referenceURL":"https://www.gbif.org/species/2463131"},{"id":61,"nodeId":20,"scientificName":"Pogona henrylawsoni","commonName":"Rồng Úc lùn Rankin (Rankin's dragon)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 25-32°C (điểm sưởi 38-42°C), Độ ẩm: 30-40%, Môi trường: Đồng cỏ đất đen nứt nẻ và thảo nguyên khô miền nội địa bang Queensland, nước Úc","description":"Phiên bản thu nhỏ hoàn hảo của loài Rồng Úc quen thuộc: chỉ dài tối đa khoảng 30 cm khi trưởng thành, mõm tròn bầu bĩnh hơn, hầu như không có túi râu gai đen dưới cằm và có hoa văn hình nơ dọc sống lưng.","imageURL":"https://bionexus.vn/images/pogona-henrylawsoni.jpg","referenceURL":"https://www.gbif.org/species/2465649"},{"id":62,"nodeId":20,"scientificName":"Pogona barbata","commonName":"Rồng Úc miền Đông (Eastern bearded dragon)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-31°C (điểm sưởi 36-40°C), Độ ẩm: 35-55%, Môi trường: Rừng bạch đàn, vùng ven biển và đồng cỏ cây gỗ khắp miền đông nước Úc","description":"Họ hàng kích thước lớn của Rồng Úc nội địa với thân hình thon dài hơn, màu da xám tro đến đen sẫm, bộ râu gai dưới cổ họng cực kỳ phát triển và niêm mạc trong khoang miệng màu vàng nghệ chói lọi.","imageURL":"https://bionexus.vn/images/pogona-barbata.jpg","referenceURL":"https://www.gbif.org/species/2465633"},{"id":63,"nodeId":226,"scientificName":"Chlamydosaurus kingii","commonName":"Rồng cổ bành Úc (Frilled lizard)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 26-32°C (điểm sưởi 38-42°C), Độ ẩm: 50-70%, Môi trường: Rừng nhiệt đới khô và savan cây gỗ tại miền bắc nước Úc và nam New Guinea","description":"Loài thằn lằn mang tính biểu tượng của châu Đại Dương với nếp da cổ khổng lồ được nâng đỡ bởi các thanh sụn xương móng: khi xòe rộng trông như chiếc ô tròn đường kính tới 30 cm quanh đầu.","imageURL":"https://bionexus.vn/images/chlamydosaurus-kingii.jpg","referenceURL":"https://www.gbif.org/species/2466087"},{"id":64,"nodeId":227,"scientificName":"Physignathus cocincinus","commonName":"Rồng đất (Chinese water dragon)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ nước: 24-27°C, Độ ẩm: 70-85%, Môi trường: Cành cây rủ bóng trên các dòng suối và sông trong rừng mưa nhiệt đới Việt Nam và Đông Nam Á","description":"Loài thằn lằn bán thủy sinh cỡ lớn bản địa của Việt Nam với toàn thân màu xanh ngọc lục bảo tươi sáng, hàng gai lược chạy từ gáy dọc sống lưng tới chiếc đuôi dài dẹp bên dùng để bơi lội.","imageURL":"https://bionexus.vn/images/physignathus-cocincinus.jpg","referenceURL":"https://www.gbif.org/species/2465402"},{"id":65,"nodeId":228,"scientificName":"Hydrosaurus amboinensis","commonName":"Rồng buồm Indonesia (Amboina sailfin lizard)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 25-28°C, Độ ẩm: 70-85%, Môi trường: Rừng ngập nước ven sông và rừng mưa ven biển tại miền đông Indonesia và New Guinea","description":"Loài lớn nhất trong họ Nhông (Agamidae) với vẻ ngoài thời tiền sử đầy choáng ngợp: gốc đuôi vươn cao một chiếc vây buồm lớn được chống đỡ bởi các gai xương cột sống dài và các ngón chân sau có diềm vảy phẳng để chạy trên mặt nước.","imageURL":"https://bionexus.vn/images/hydrosaurus-amboinensis.jpg","referenceURL":"https://www.gbif.org/species/5226078"},{"id":66,"nodeId":229,"scientificName":"Uromastyx aegyptia","commonName":"Nhông đuôi gai Ai Cập (Egyptian mastigure)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 28-35°C (điểm sưởi 45-50°C), Độ ẩm: 15-30%, Môi trường: Hoang mạc đá sỏi khô nóng khắc nghiệt tại Ai Cập và bán đảo Ả Rập","description":"Loài lớn nhất trong chi nhông đuôi gai với chiều dài đạt tới 75 cm, thân mình to bè dẹp và chiếc đuôi cơ bắp phủ đầy các vòng gai nhọn cứng như một cây chùy chiến thời trung cổ.","imageURL":"https://bionexus.vn/images/uromastyx-aegyptia.jpg","referenceURL":"https://www.gbif.org/species/9013567"},{"id":67,"nodeId":229,"scientificName":"Uromastyx geyri","commonName":"Nhông đuôi gai Sahara (Geyr's spiny-tailed lizard)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 28-35°C (điểm sưởi 46-50°C), Độ ẩm: 15-30%, Môi trường: Vùng núi đá khô nóng giữa trung tâm sa mạc Sahara (Mali, Niger, Algeria)","description":"Một trong những loài nhông đuôi gai đẹp và phổ biến nhất trong nuôi nhốt với kích thước vừa phải và màu da rực sáng như lửa: vàng chanh neon hoặc cam đỏ gạch phủ các đốm hoa văn lưng.","imageURL":"https://bionexus.vn/images/uromastyx-geyri.jpg","referenceURL":"https://www.gbif.org/species/2466112"},{"id":68,"nodeId":229,"scientificName":"Uromastyx ocellata","commonName":"Nhông đuôi gai đốm mắt (Ocellated mastigure)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 27-34°C (điểm sưởi 45-49°C), Độ ẩm: 20-35%, Môi trường: Sườn đồi đá khô cằn dọc bờ tây Biển Đỏ từ Ai Cập tới vùng Sừng châu Phi","description":"Loài nhông đuôi gai cỡ nhỏ có sắc màu đẹp bậc nhất: con đực trưởng thành có đầu và vai màu xanh ngọc lam sáng, lưng màu gạch nung điểm hàng loạt vòng đốm tròn màu trắng vàng như mắt công.","imageURL":"https://bionexus.vn/images/uromastyx-ocellata.jpg","referenceURL":"https://www.gbif.org/species/2466180"},{"id":69,"nodeId":229,"scientificName":"Uromastyx ornata","commonName":"Nhông đuôi gai hoa văn Sinai (Ornate mastigure)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 27-34°C (điểm sưởi 46-50°C), Độ ẩm: 15-30%, Môi trường: Núi đá granite khô nóng tại bán đảo Sinai, tây bắc Ả Rập Xê Út và Yemen","description":"Loài nhông đuôi gai được săn đón bậc nhất giới bò sát cảnh nhờ màu sắc lộng lẫy như tranh vẽ ở con đực: thân xanh lục bảo hoặc xanh coban rực sáng kết hợp các dải đốm vàng tươi và đỏ gạch.","imageURL":"https://bionexus.vn/images/uromastyx-ornata.jpg","referenceURL":"https://www.gbif.org/species/2466148"},{"id":70,"nodeId":229,"scientificName":"Uromastyx acanthinura","commonName":"Nhông đuôi gai Bắc Phi (North African mastigure)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 27-34°C (điểm sưởi 45-50°C), Độ ẩm: 20-35%, Môi trường: Sườn núi đá và bán hoang mạc vùng Maghreb phía bắc sa mạc Sahara","description":"Loài nhông đuôi gai cỡ trung bình đến lớn có thân hình bè rộng, chiếc đuôi gai to nặng và màu da cực kỳ đa dạng theo vùng địa lý từ vàng chanh, cam gạch, xanh lá tới vân lưới đen.","imageURL":"https://bionexus.vn/images/uromastyx-acanthinura.jpg","referenceURL":"https://www.gbif.org/species/2466109"},{"id":71,"nodeId":229,"scientificName":"Uromastyx dispar","commonName":"Nhông đuôi gai Mali (Sudan mastigure)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 28-35°C (điểm sưởi 46-50°C), Độ ẩm: 15-30%, Môi trường: Vùng bán hoang mạc Sahel và các sườn đồi đá phía nam sa mạc Sahara","description":"Loài nhông đuôi gai nổi bật với sự tương phản màu sắc mạnh mẽ ở con đực trưởng thành: đầu, cổ, bốn chân và chiếc đuôi gai có màu đen bóng như than, trong khi toàn bộ lưng rực sáng màu vàng kim hoặc đỏ gạch.","imageURL":"https://bionexus.vn/images/uromastyx-dispar.jpg","referenceURL":"https://www.gbif.org/species/2466101"},{"id":72,"nodeId":230,"scientificName":"Acanthosaura capra","commonName":"Ô rô vảy (Green pricklenape)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 22-27°C (điểm sưởi 28-30°C), Độ ẩm: 70-85%, Môi trường: Rừng thường xanh vùng đồi núi ẩm mát tại miền Trung và Nam Việt Nam, Lào, Campuchia","description":"Loài nhông rừng bản địa của Việt Nam có diện mạo oai vệ với một cặp gai nhọn dài nhô lên ngay phía trên mí mắt sau và một hàng gai lược cao vút dựng đứng trên gáy.","imageURL":"https://bionexus.vn/images/acanthosaura-capra.jpg","referenceURL":"https://www.gbif.org/species/5960762"},{"id":73,"nodeId":230,"scientificName":"Acanthosaura lepidogaster","commonName":"Ô rô bụng vảy (Brown pricklenape)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-27°C (điểm sưởi 27-29°C), Độ ẩm: 70-85%, Môi trường: Rừng thường xanh ẩm vùng trung du và núi thấp tại miền Bắc, Trung Việt Nam và nam Trung Quốc","description":"Loài rồng gai cỡ nhỏ hơn Ô rô vảy, dễ nhận biết nhờ ngoài cặp gai trên mắt và hàng gai gáy còn có thêm một cặp gai nhọn mọc chĩa ra ở hai bên gáy phía trên màng nhĩ.","imageURL":"https://bionexus.vn/images/acanthosaura-lepidogaster.jpg","referenceURL":"https://www.gbif.org/species/5960744"},{"id":74,"nodeId":231,"scientificName":"Calotes versicolor","commonName":"Nhông xanh (Changeable lizard)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 25-32°C (điểm sưởi 35-38°C), Độ ẩm: 55-75%, Môi trường: Trảng cây bụi, bìa rừng, công viên và vườn cây khắp Nam Á và Đông Nam Á","description":"Loài nhông quen thuộc khắp làng quê và công viên Việt Nam với hàng gai lược chạy dọc từ gáy xuống lưng; vào mùa sinh sản, toàn bộ phần đầu và vai của con đực chuyển sang màu đỏ cam rực cháy.","imageURL":"https://bionexus.vn/images/calotes-versicolor.jpg","referenceURL":"https://www.gbif.org/species/9125207"},{"id":75,"nodeId":232,"scientificName":"Intellagama lesueurii","commonName":"Rồng nước miền Đông nước Úc (Eastern water dragon)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-26°C, Độ ẩm: 60-80%, Môi trường: Bờ sông, suối đá và công viên ven biển dọc miền đông Australia","description":"Loài rồng nước cỡ lớn bản địa miền đông nước Úc, nổi bật với vệt đen rộng kéo dài từ sau mắt qua tai, thân xám vằn đen và toàn bộ phần ngực bụng của con đực rực lên màu đỏ son tươi thắm.","imageURL":"https://bionexus.vn/images/intellagama-lesueurii.jpg","referenceURL":"https://www.gbif.org/species/8161292"},{"id":76,"nodeId":233,"scientificName":"Agama agama","commonName":"Nhông đầu đỏ châu Phi (Common agama)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 26-33°C (điểm sưởi 38-42°C), Độ ẩm: 35-55%, Môi trường: Savan đá, mỏm đá kopje và tường nhà khắp vùng châu Phi hạ Sahara","description":"Loài nhông đá nổi tiếng bậc nhất lục địa đen nhờ màu sắc rực rỡ của con đực đầu đàn dưới ánh nắng trưa: toàn bộ cái đầu khoác màu cam đỏ rực lửa trong khi thân mình và chân ánh lên màu xanh coban tím thẫm.","imageURL":"https://bionexus.vn/images/agama-agama.jpg","referenceURL":"https://www.gbif.org/species/5226308"},{"id":77,"nodeId":234,"scientificName":"Iguana iguana","commonName":"Rồng Nam Mỹ (Green iguana)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 26-32°C (điểm sưởi 36-40°C), Độ ẩm: 65-80%, Môi trường: Tầng tán rừng mưa nhiệt đới ven sông suối khắp Trung và Nam Mỹ","description":"Loài cự đà sống trên cây nổi tiếng nhất thế giới với chiếc yếm cổ tròn lớn xòe rộng dưới cằm, hàng gai lược mềm chạy dọc từ gáy tới đuôi và một vảy tròn lớn đặc trưng nằm ngay bên dưới màng nhĩ.","imageURL":"https://bionexus.vn/images/iguana-iguana.jpg","referenceURL":"https://www.gbif.org/species/2459658"},{"id":78,"nodeId":235,"scientificName":"Cyclura cornuta","commonName":"Cự đà tê giác (Rhinoceros iguana)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 26-33°C (điểm sưởi 38-43°C), Độ ẩm: 50-70%, Môi trường: Vùng đá vôi ven biển khô hạn và rừng cây gai trên đảo Hispaniola (Cộng hòa Dominica và Haiti)","description":"Loài cự đà đá khổng lồ mang vẻ đẹp thời tiền sử với lớp da dày màu xám đá than, hai bướu cơ sọ phình to trên đỉnh đầu và từ 3 đến 5 chiếc sừng vảy xương nhô cao trên sống mũi như sừng tê giác.","imageURL":"https://bionexus.vn/images/cyclura-cornuta.jpg","referenceURL":"https://www.gbif.org/species/5960674"},{"id":79,"nodeId":235,"scientificName":"Cyclura lewisi","commonName":"Cự đà lam Grand Cayman (Grand Cayman blue iguana)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 26-33°C (điểm sưởi 38-42°C), Độ ẩm: 55-75%, Môi trường: Rừng cây bụi khô hạn và bờ đá vôi karst trên đảo Grand Cayman (Caribe)","description":"Một trong những loài bò sát quý hiếm và có tuổi thọ cao nhất hành tinh, nổi bật với làn da màu xanh coban đến xanh ngọc lam rực sáng dưới ánh mặt trời nhiệt đới và đôi tròng mắt màu đỏ rượu vang.","imageURL":"https://bionexus.vn/images/cyclura-lewisi.jpg","referenceURL":"https://www.gbif.org/species/7982719"},{"id":80,"nodeId":236,"scientificName":"Ctenosaura similis","commonName":"Cự đà đuôi gai đen (Black spiny-tailed iguana)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 26-33°C (điểm sưởi 38-43°C), Độ ẩm: 45-65%, Môi trường: Rừng khô nhiệt đới, bờ biển đá và tàn tích đá cổ khắp Trung Mỹ và nam Mexico","description":"Loài cự đà đuôi gai cỡ lớn giữ kỷ lục tốc độ chạy trên cạn của toàn bộ thế giới thằn lằn, sở hữu thân màu xám bạc điểm các dải khoang đen đậm, mào gai lưng cao và chiếc đuôi dài đầy vòng gai sắc.","imageURL":"https://bionexus.vn/images/ctenosaura-similis.jpg","referenceURL":"https://www.gbif.org/species/2459603"},{"id":81,"nodeId":236,"scientificName":"Ctenosaura pectinata","commonName":"Cự đà đuôi gai Mexico (Mexican spiny-tailed iguana)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 26-33°C (điểm sưởi 38-43°C), Độ ẩm: 40-60%, Môi trường: Rừng khô rụng lá nhiệt đới và sườn núi đá dọc bờ biển Thái Bình Dương của Mexico","description":"Loài cự đà đuôi gai rất được ưa chuộng trong giới bò sát cảnh nhờ tính cách điềm tĩnh hơn họ hàng C. similis và có các dòng màu tương phản ấn tượng như trắng đen (Panda) và vàng nghệ (Banana).","imageURL":"https://bionexus.vn/images/ctenosaura-pectinata.jpg","referenceURL":"https://www.gbif.org/species/2459612"},{"id":82,"nodeId":237,"scientificName":"Pantherophis guttatus","commonName":"Rắn Ngô (Corn Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 30-32°C), Độ ẩm: 40-60%, Môi trường: Rừng thông, đồng cỏ, trang trại và ven rừng Đông Nam Hoa Kỳ","description":"Loài rắn săn mồi siết mồi hiền lành bậc nhất trong giới bò sát cảnh, nổi bật với hàng đốm yên ngựa màu cam đỏ viền đen dọc lưng và mặt bụng kẻ ô vuông đen trắng như bắp ngô.","imageURL":"https://bionexus.vn/images/pantherophis-guttatus.jpg","referenceURL":"https://www.gbif.org/species/2455615"},{"id":83,"nodeId":237,"scientificName":"Pantherophis obsoletus","commonName":"Rắn Chuột Đen Phương Tây (Western Rat Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C (điểm sưởi 29-31°C), Độ ẩm: 45-65%, Môi trường: Rừng lá rộng, sườn đồi đá và đồng cỏ cây bụi miền Trung Hoa Kỳ","description":"Loài rắn chuột kích thước lớn phân bố phía tây sông Mississippi, có khả năng leo trèo thẳng đứng lên thân cây sồi chỉ bằng cách bám vảy bụng vào kẽ vỏ cây.","imageURL":"https://bionexus.vn/images/pantherophis-obsoletus.jpg","referenceURL":"https://www.gbif.org/species/2455676"},{"id":84,"nodeId":237,"scientificName":"Pantherophis alleghaniensis","commonName":"Rắn Chuột Phương Đông (Eastern Rat Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C (điểm sưởi 29-31°C), Độ ẩm: 50-70%, Môi trường: Rừng rậm, đầm lầy ven biển và vùng nông thôn miền Đông Hoa Kỳ","description":"Loài rắn chuột miền Đông Hoa Kỳ có sự biến thiên màu sắc lớn theo vùng địa lý, từ đen bóng vùng núi phía bắc đến vàng sọc hoặc cam rực ở bán đảo Florida.","imageURL":"https://bionexus.vn/images/pantherophis-alleghaniensis.jpg","referenceURL":"https://www.gbif.org/species/7453543"},{"id":85,"nodeId":237,"scientificName":"Pantherophis bairdi","commonName":"Rắn Chuột Baird (Baird's Rat Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C (điểm sưởi 29-31°C), Độ ẩm: 40-55%, Môi trường: Hẻm núi đá vôi và rừng sồi thông vùng Tây Texas và Bắc Mexico","description":"Loài rắn chuột vùng núi đá khô hạn có sắc vảy ánh kim pha hồng cá hồi, vàng đồng và bốn dải sọc dọc trầm mặc khi trưởng thành.","imageURL":"https://bionexus.vn/images/pantherophis-bairdi.jpg","referenceURL":"https://www.gbif.org/species/2455636"},{"id":86,"nodeId":237,"scientificName":"Pantherophis vulpinus","commonName":"Rắn Cáo Phương Tây (Western Fox Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-27°C (điểm sưởi 28-30°C), Độ ẩm: 45-65%, Môi trường: Đồng cỏ thảo nguyên, đất nông nghiệp và bìa rừng vùng Trung Tây Hoa Kỳ","description":"Loài rắn thảo nguyên có cái đầu màu đồng đỏ nổi bật và tập tính tiết chất dịch có mùi giống cáo đỏ khi bị đe dọa.","imageURL":"https://bionexus.vn/images/pantherophis-vulpinus.jpg","referenceURL":"https://www.gbif.org/species/2455654"},{"id":87,"nodeId":237,"scientificName":"Pantherophis emoryi","commonName":"Rắn Ngô Đồng Bằng Lớn (Great Plains Rat Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C (điểm sưởi 30-32°C), Độ ẩm: 35-55%, Môi trường: Đồi đá thảo nguyên, hẻm núi khô và thung lũng sông miền Trung Hoa Kỳ và Bắc Mexico","description":"Họ hàng gần nhất của rắn ngô đỏ nhưng mang tông màu xám bạc và nâu ô-liu nhã nhặn của vùng Đại Bình Nguyên Bắc Mỹ.","imageURL":"https://bionexus.vn/images/pantherophis-emoryi.jpg","referenceURL":"https://www.gbif.org/species/2455644"},{"id":88,"nodeId":238,"scientificName":"Lampropeltis getula","commonName":"Rắn Vua Phương Đông (Eastern Kingsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-29°C (điểm sưởi 30-32°C), Độ ẩm: 45-65%, Môi trường: Rừng thông, bờ suối và đồng cỏ ven rừng miền Đông Nam Hoa Kỳ","description":"Loài rắn vua nổi tiếng với bộ vảy đen bóng điểm các dải mắt xích trắng vàng và khả năng miễn nhiễm tự nhiên với nọc độc của rắn đuôi chuông.","imageURL":"https://bionexus.vn/images/lampropeltis-getula.jpg","referenceURL":"https://www.gbif.org/species/9799308"},{"id":89,"nodeId":238,"scientificName":"Lampropeltis californiae","commonName":"Rắn Vua California (California Kingsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-29°C (điểm sưởi 30-32°C), Độ ẩm: 35-55%, Môi trường: Đồng cỏ khô, rừng cây bụi chaparral và bán sa mạc miền Tây Bắc Mỹ","description":"Loài rắn vua phổ biến nhất trong giới nuôi bò sát cảnh với những khoanh đen trắng hoặc sọc dọc tương phản sắc nét dọc toàn thân.","imageURL":"https://bionexus.vn/images/lampropeltis-californiae.jpg","referenceURL":"https://www.gbif.org/species/8170369"},{"id":90,"nodeId":238,"scientificName":"Lampropeltis triangulum","commonName":"Rắn Sữa Phương Đông (Eastern Milksnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-27°C (điểm sưởi 28-30°C), Độ ẩm: 45-65%, Môi trường: Rừng lá rộng, cánh đồng đá và chuồng trại nông thôn Đông Bắc Mỹ","description":"Loài rắn sữa miền Đông Bắc Mỹ có hàng đốm yên ngựa đỏ nâu viền đen trên nền xám kem và chữ Y hoặc V sáng màu trên gáy.","imageURL":"https://bionexus.vn/images/lampropeltis-triangulum.jpg","referenceURL":"https://www.gbif.org/species/5224503"},{"id":91,"nodeId":238,"scientificName":"Lampropeltis polyzona","commonName":"Rắn Sữa Đại Tây Dương Trung Mỹ (Atlantic Central American Milksnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 30-31°C), Độ ẩm: 50-70%, Môi trường: Rừng khô nhiệt đới, thảo nguyên chân núi và rừng ẩm Mexico","description":"Loài rắn sữa nổi bật nhất với những khoanh đỏ, đen, trắng hoặc vàng cam rực rỡ của các dòng Sinaloa, Puebla và Nelson trong giới bò sát cảnh.","imageURL":"https://bionexus.vn/images/lampropeltis-polyzona.jpg","referenceURL":"https://www.gbif.org/species/5224530"},{"id":92,"nodeId":238,"scientificName":"Lampropeltis alterna","commonName":"Rắn Vua Khoanh Xám (Gray-banded Kingsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C (điểm sưởi 29-31°C), Độ ẩm: 35-50%, Môi trường: Vách núi đá vôi và hẻm núi sa mạc Chihuahuan ở Tây Texas và Bắc Mexico","description":"Loài rắn vua vùng núi đá sa mạc Chihuahuan có nền xám bạc thanh lịch điểm những dải yên ngựa màu cam đỏ viền đen trắng.","imageURL":"https://bionexus.vn/images/lampropeltis-alterna.jpg","referenceURL":"https://www.gbif.org/species/5224476"},{"id":93,"nodeId":238,"scientificName":"Lampropeltis pyromelana","commonName":"Rắn Vua Núi Sonora (Arizona Mountain Kingsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-27°C (điểm sưởi 28-30°C), Độ ẩm: 40-60%, Môi trường: Rừng thông Ponderosa và hẻm núi suối đá vùng núi Arizona và Bắc Mexico","description":"Loài rắn vua núi cao tuyệt đẹp với chiếc mõm trắng tinh và các vòng đỏ, đen, trắng kem sắc nét sống trên các dãy núi đảo trời Arizona.","imageURL":"https://bionexus.vn/images/lampropeltis-pyromelana.jpg","referenceURL":"https://www.gbif.org/species/9089978"},{"id":94,"nodeId":238,"scientificName":"Lampropeltis mexicana","commonName":"Rắn Vua Mexico (Mexican Kingsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C (điểm sưởi 29-31°C), Độ ẩm: 40-55%, Môi trường: Sườn núi đá, rừng sồi thông và vùng cây bụi cao nguyên Mexico","description":"Loài rắn vua cao nguyên Mexico có nền xám bạc hoặc hồng phớt điểm hàng đốm yên ngựa đỏ hồng viền đen và hoa văn đầu chữ Y cổ điển.","imageURL":"https://bionexus.vn/images/lampropeltis-mexicana.jpg","referenceURL":"https://www.gbif.org/species/5224471"},{"id":95,"nodeId":238,"scientificName":"Lampropeltis splendida","commonName":"Rắn Vua Sa Mạc (Desert Kingsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-29°C (điểm sưởi 30-32°C), Độ ẩm: 35-50%, Môi trường: Đồng cỏ bán khô hạn, thung lũng sông và sa mạc cây bụi Tây Nam Hoa Kỳ và Bắc Mexico","description":"Loài rắn vua vùng bán sa mạc nổi bật với hàng tấm lưng đen nhánh ở giữa và hai bên sườn lấm tấm vàng chanh rực rỡ như dát cốm vàng.","imageURL":"https://bionexus.vn/images/lampropeltis-splendida.jpg","referenceURL":"https://www.gbif.org/species/5224492"},{"id":96,"nodeId":238,"scientificName":"Lampropeltis nigra","commonName":"Rắn Vua Đen Phương Đông (Eastern Black Kingsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C (điểm sưởi 29-31°C), Độ ẩm: 45-65%, Môi trường: Thung lũng sông, rừng gỗ cứng và đồng cỏ miền Đông Trung Bộ Hoa Kỳ","description":"Loài rắn vua mang sắc đen huyền bóng loáng như gỗ mun từ phía đông sông Mississippi đến dãy Appalachian.","imageURL":"https://bionexus.vn/images/lampropeltis-nigra.jpg","referenceURL":"https://www.gbif.org/species/7721444"},{"id":97,"nodeId":238,"scientificName":"Lampropeltis holbrooki","commonName":"Rắn Vua Đốm Muối Tiêu (Speckled Kingsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C (điểm sưởi 29-31°C), Độ ẩm: 50-70%, Môi trường: Đầm lầy, rừng ngập nước, thảo nguyên ẩm và thung lũng sông Mississippi","description":"Loài rắn vua đặc trưng của lưu vực hạ nguồn sông Mississippi với từng chiếc vảy đen đều đính một chấm trắng vàng ở chính giữa như rắc muối tiêu.","imageURL":"https://bionexus.vn/images/lampropeltis-holbrooki.jpg","referenceURL":"https://www.gbif.org/species/7915678"},{"id":98,"nodeId":238,"scientificName":"Lampropeltis elapsoides","commonName":"Rắn Vua Đỏ Scarlet (Scarlet Kingsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C (điểm sưởi 29-31°C), Độ ẩm: 55-75%, Môi trường: Rừng thông lá dài và dưới vỏ cây thông mục miền Đông Nam Hoa Kỳ","description":"Loài rắn vua nhỏ nhất Bắc Mỹ với chiếc mõm đỏ tươi và các vòng đỏ, đen, vàng kem quấn trọn quanh cả mặt bụng, bắt chước hoàn hảo rắn san hô phương Đông.","imageURL":"https://bionexus.vn/images/lampropeltis-elapsoides.jpg","referenceURL":"https://www.gbif.org/species/7794320"},{"id":99,"nodeId":239,"scientificName":"Heterodon nasicus","commonName":"Rắn Mũi Hếch Phương Tây (Western Hognose Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 31-33°C), Độ ẩm: 30-50%, Môi trường: Đồng cỏ cát và thảo nguyên bán khô hạn từ miền Nam Canada đến Bắc Mexico","description":"Loài rắn nhỏ mũm mĩm có chiếc vảy mõm hếch ngược lên như mũi lợn để đào cát và màn kịch giả chết lật ngửa bụng nổi tiếng toàn cầu.","imageURL":"https://bionexus.vn/images/heterodon-nasicus.jpg","referenceURL":"https://www.gbif.org/species/5223725"},{"id":100,"nodeId":239,"scientificName":"Heterodon platirhinos","commonName":"Rắn Mũi Hếch Phương Đông (Eastern Hognose Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C (điểm sưởi 30-32°C), Độ ẩm: 45-65%, Môi trường: Rừng thông đất cát, đồi cát ven biển và bìa rừng miền Đông Hoa Kỳ","description":"Họ hàng kích thước lớn hơn của rắn mũi hếch phương Tây, nổi tiếng với màn bành rộng cổ như rắn hổ mang trước khi lăn ra giả chết.","imageURL":"https://bionexus.vn/images/heterodon-platirhinos.jpg","referenceURL":"https://www.gbif.org/species/5223730"},{"id":101,"nodeId":239,"scientificName":"Heterodon simus","commonName":"Rắn Mũi Hếch Phương Nam (Southern Hognose Snake)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 23-29°C (điểm sưởi 30-32°C), Độ ẩm: 45-65%, Môi trường: Đồi cát rừng thông lá dài vùng đồng bằng ven biển Đông Nam Hoa Kỳ","description":"Loài nhỏ nhất và hiếm nhất trong chi rắn mũi hếch Bắc Mỹ, gắn liền với hệ sinh thái đồi cát rừng thông lá dài đang bị thu hẹp nghiêm trọng.","imageURL":"https://bionexus.vn/images/heterodon-simus.jpg","referenceURL":"https://www.gbif.org/species/5223729"},{"id":102,"nodeId":240,"scientificName":"Pituophis catenifer","commonName":"Rắn Chuột Chũi Thái Bình Dương (Gopher Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-29°C (điểm sưởi 30-33°C), Độ ẩm: 35-55%, Môi trường: Đồng cỏ khô, rừng thông thưa, bán sa mạc và đất nông nghiệp Bắc Mỹ","description":"Loài rắn siết mồi cỡ lớn phổ biến khắp miền Tây và Trung Bắc Mỹ, nổi tiếng với chiếc nắp thanh quản rung lên tạo tiếng rít cực lớn bắt chước rắn đuôi chuông.","imageURL":"https://bionexus.vn/images/pituophis-catenifer.jpg","referenceURL":"https://www.gbif.org/species/2453826"},{"id":103,"nodeId":240,"scientificName":"Pituophis melanoleucus","commonName":"Rắn Thông Phương Đông (Pine Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C (điểm sưởi 30-32°C), Độ ẩm: 45-65%, Môi trường: Rừng thông đất cát và đồi cát khô miền Đông Nam Hoa Kỳ","description":"Loài rắn đào hang khỏe khoắn của rừng thông đất cát miền Đông Hoa Kỳ với hoa văn đốm đen hoặc nâu sẫm nổi bật trên nền trắng kem.","imageURL":"https://bionexus.vn/images/pituophis-melanoleucus.jpg","referenceURL":"https://www.gbif.org/species/9187223"},{"id":104,"nodeId":240,"scientificName":"Pituophis deppei","commonName":"Rắn Thông Mexico (Mexican Pine Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-27°C (điểm sưởi 29-31°C), Độ ẩm: 40-60%, Môi trường: Rừng thông sồi và cao nguyên bán khô hạn miền Trung Mexico","description":"Loài rắn thông đặc hữu của cao nguyên Mexico nổi bật với phần thân giữa rực lên sắc cam đồng giữa những đốm yên ngựa đen tuyền.","imageURL":"https://bionexus.vn/images/pituophis-deppei.jpg","referenceURL":"https://www.gbif.org/species/9208361"},{"id":105,"nodeId":241,"scientificName":"Thamnophis sirtalis","commonName":"Rắn Sọc Garter Thường (Common Garter Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-27°C (điểm sưởi 28-30°C), Độ ẩm: 45-65%, Môi trường: Đồng cỏ ẩm, bờ hồ, đầm lầy và rừng thưa khắp Bắc Mỹ","description":"Loài rắn đẻ con có phạm vi phân bố rộng nhất Bắc Mỹ, nổi tiếng với ba dải sọc dọc chạy suốt lưng và các biến thể sườn đỏ xanh rực rỡ ở bờ Tây.","imageURL":"https://bionexus.vn/images/thamnophis-sirtalis.jpg","referenceURL":"https://www.gbif.org/species/2457522"},{"id":106,"nodeId":241,"scientificName":"Thamnophis marcianus","commonName":"Rắn Sọc Kẻ Ô (Checkered Garter Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C (điểm sưởi 29-31°C), Độ ẩm: 40-60%, Môi trường: Ốc đảo, bờ sông suối và đồng cỏ bán khô hạn Tây Nam Hoa Kỳ đến Trung Mỹ","description":"Loài rắn Garter dễ nuôi nhất trong hồ cạn nhờ hoa văn bàn cờ đen kem sắc nét dọc lưng và khả năng thích nghi với khí hậu ấm khô.","imageURL":"https://bionexus.vn/images/thamnophis-marcianus.jpg","referenceURL":"https://www.gbif.org/species/9342283"},{"id":107,"nodeId":241,"scientificName":"Thamnophis elegans","commonName":"Rắn Sọc Garter Phương Tây (Western Terrestrial Garter Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-26°C (điểm sưởi 28-30°C), Độ ẩm: 40-60%, Môi trường: Đồng cỏ núi cao, rừng lá kim và bờ suối miền Tây Bắc Mỹ","description":"Loài rắn sọc sống trên cạn nhiều nhất ở miền Tây Bắc Mỹ, xuất hiện từ bờ biển Thái Bình Dương lên tới các đồng cỏ núi cao trên 3.000 mét.","imageURL":"https://bionexus.vn/images/thamnophis-elegans.jpg","referenceURL":"https://www.gbif.org/species/2457545"},{"id":108,"nodeId":241,"scientificName":"Thamnophis radix","commonName":"Rắn Sọc Đồng Bằng (Plains Garter Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-27°C (điểm sưởi 28-30°C), Độ ẩm: 40-60%, Môi trường: Thảo nguyên cỏ cao, đầm lầy và bờ hồ vùng Đại Bình Nguyên Bắc Mỹ","description":"Loài rắn sọc đặc trưng của thảo nguyên Bắc Mỹ với đường chỉ sống lưng màu cam rực rỡ và các vạch đen viền trên vảy môi.","imageURL":"https://bionexus.vn/images/thamnophis-radix.jpg","referenceURL":"https://www.gbif.org/species/2457512"},{"id":109,"nodeId":241,"scientificName":"Thamnophis proximus","commonName":"Rắn Ruy Băng Phương Tây (Western Ribbon Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C (điểm sưởi 29-31°C), Độ ẩm: 50-70%, Môi trường: Bờ suối, đầm lầy lau sậy và cành cây bụi rủ sát mặt nước Bắc và Trung Mỹ","description":"Loài rắn nước có thân hình mảnh mai như dải ruy băng với cái đuôi dài chiếm tới một phần ba tổng chiều dài cơ thể.","imageURL":"https://bionexus.vn/images/thamnophis-proximus.jpg","referenceURL":"https://www.gbif.org/species/2457575"},{"id":110,"nodeId":241,"scientificName":"Thamnophis saurita","commonName":"Rắn Ruy Băng Phương Đông (Eastern Ribbon Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-27°C (điểm sưởi 28-30°C), Độ ẩm: 50-70%, Môi trường: Đầm lầy cỏ lác, bờ hồ và suối rừng miền Đông Bắc Mỹ","description":"Họ hàng miền Đông của rắn ruy băng với ba đường kẻ vàng thẳng tắp trên nền nhung nâu đen như được vẽ bằng thước kẻ.","imageURL":"https://bionexus.vn/images/thamnophis-saurita.jpg","referenceURL":"https://www.gbif.org/species/2457577"},{"id":111,"nodeId":242,"scientificName":"Elaphe climacophora","commonName":"Rắn Chuột Nhật Bản Aodaisho (Japanese Rat Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-27°C (điểm sưởi 28-30°C), Độ ẩm: 55-75%, Môi trường: Rừng ôn đới, ruộng bậc thang và khu dân cư nông thôn Nhật Bản","description":"Loài rắn lớn và quen thuộc nhất quần đảo Nhật Bản, mang màu xanh ô-liu pha ngọc bích thanh tao và được tôn vinh như thần hộ mệnh kho thóc.","imageURL":"https://bionexus.vn/images/elaphe-climacophora.jpg","referenceURL":"https://www.gbif.org/species/2458390"},{"id":112,"nodeId":242,"scientificName":"Elaphe quadrivirgata","commonName":"Rắn Bốn Sọc Nhật Bản (Japanese Four-lined Ratsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-27°C (điểm sưởi 28-30°C), Độ ẩm: 55-75%, Môi trường: Đồng cỏ, bờ suối, ruộng lúa và suối nước nóng tự nhiên tại Nhật Bản","description":"Loài rắn đặc hữu Nhật Bản nổi tiếng với tròng mắt màu đỏ hồng ngọc và bốn đường sọc đen chạy thẳng tắp dọc tấm lưng vàng đồng.","imageURL":"https://bionexus.vn/images/elaphe-quadrivirgata.jpg","referenceURL":"https://www.gbif.org/species/2458480"},{"id":113,"nodeId":242,"scientificName":"Elaphe dione","commonName":"Rắn Chuột Thảo Nguyên Á Âu (Dione's Rat Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-27°C (điểm sưởi 28-30°C), Độ ẩm: 40-60%, Môi trường: Thảo nguyên, rừng thưa, thung lũng sông và bán sa mạc từ Đông Âu đến Đông Á","description":"Loài rắn nước có phạm vi phân bố rộng bậc nhất lục địa Á Âu, hiền lành, nhỏ gọn và sở hữu hàng chục kiểu hình địa lý khác nhau.","imageURL":"https://bionexus.vn/images/elaphe-dione.jpg","referenceURL":"https://www.gbif.org/species/2458400"},{"id":114,"nodeId":242,"scientificName":"Elaphe carinata","commonName":"Rắn Hổ Vương (King Ratsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-27°C (điểm sưởi 28-30°C), Độ ẩm: 55-75%, Môi trường: Đồi núi rừng cây lá rộng, thung lũng đá và ruộng bậc thang Đông Á","description":"Loài rắn nước cỡ lớn vùng Đông Á có những hàng vảy lưng gồ cao sắc cạnh viền vàng đen như vảy rồng và tập tính chuyên săn các loài rắn khác.","imageURL":"https://bionexus.vn/images/elaphe-carinata.jpg","referenceURL":"https://www.gbif.org/species/2458466"},{"id":115,"nodeId":242,"scientificName":"Elaphe schrenckii","commonName":"Rắn Chuột Amur (Amur Rat Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-26°C (điểm sưởi 28-30°C), Độ ẩm: 50-70%, Môi trường: Rừng hỗn giao lá rộng - lá kim và thung lũng sông vùng Viễn Đông Nga, Đông Bắc Trung Quốc và Triều Tiên","description":"Loài rắn lớn vùng rừng taiga Amur có bộ vảy đen bóng điểm các vạch chéo màu vàng ngà hoặc trắng kem tương phản mạnh mẽ và tính tình cực kỳ hiền hậu.","imageURL":"https://bionexus.vn/images/elaphe-schrenckii.jpg","referenceURL":"https://www.gbif.org/species/2458438"},{"id":116,"nodeId":242,"scientificName":"Elaphe quatuorlineata","commonName":"Rắn Bốn Sọc Châu Âu (Four-lined Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C (điểm sưởi 29-31°C), Độ ẩm: 45-65%, Môi trường: Rừng thưa Địa Trung Hải, tường đá cổ và vườn ô-liu Nam Âu","description":"Một trong những loài rắn không độc lớn nhất châu Âu với bốn đường kẻ đen chạy dọc tấm lưng nâu vàng và tính khí vô cùng ôn hòa.","imageURL":"https://bionexus.vn/images/elaphe-quatuorlineata.jpg","referenceURL":"https://www.gbif.org/species/9099408"},{"id":117,"nodeId":242,"scientificName":"Elaphe sauromates","commonName":"Rắn Bốn Sọc Phương Đông (Blotched Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C (điểm sưởi 29-31°C), Độ ẩm: 40-60%, Môi trường: Thảo nguyên đá, rừng thưa và sườn đồi khô Đông Nam Âu đến Tây Á","description":"Họ hàng phương Đông của rắn bốn sọc châu Âu, giữ nguyên hàng đốm yên ngựa nâu đen sắc nét trên nền vàng rơm suốt cả đời trưởng thành.","imageURL":"https://bionexus.vn/images/elaphe-sauromates.jpg","referenceURL":"https://www.gbif.org/species/2458386"},{"id":118,"nodeId":243,"scientificName":"Zamenis situla","commonName":"Rắn Báo Châu Âu (European Leopard Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-27°C (điểm sưởi 28-30°C), Độ ẩm: 45-60%, Môi trường: Tường đá khô, vườn ô-liu và sườn đồi cây bụi маquis vùng Địa Trung Hải","description":"Được mệnh danh là loài rắn đẹp nhất châu Âu nhờ hàng đốm đỏ gạch viền đen nổi bật trên nền xám kem hoặc hai dải sọc đỏ chạy dọc lưng.","imageURL":"https://bionexus.vn/images/zamenis-situla.jpg","referenceURL":"https://www.gbif.org/species/2458374"},{"id":119,"nodeId":243,"scientificName":"Zamenis longissimus","commonName":"Rắn Thần Y Aesculapian (Aesculapian Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-26°C (điểm sưởi 28-30°C), Độ ẩm: 50-65%, Môi trường: Rừng lá rộng ấm áp, thung lũng sông và tàn tích đá cổ khắp Trung và Nam Âu","description":"Loài rắn lịch sử gắn liền với cây gậy của thần Y học Asclepius trong văn minh Hy Lạp - La Mã cổ đại, nổi bật với bộ vảy nâu đồng điểm vệt trắng mảnh.","imageURL":"https://bionexus.vn/images/zamenis-longissimus.jpg","referenceURL":"https://www.gbif.org/species/2458538"},{"id":120,"nodeId":243,"scientificName":"Zamenis scalaris","commonName":"Rắn Hình Thang (Ladder Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C (điểm sưởi 30-32°C), Độ ẩm: 40-55%, Môi trường: Đồi cây bụi Địa Trung Hải, rừng thông khô và vườn ô-liu bán đảo Iberia","description":"Loài rắn đặc trưng của bán đảo Iberia và miền Nam nước Pháp, nổi tiếng với hoa văn hình chiếc thang trên lưng lúc nhỏ chuyển thành hai đường kẻ song song khi trưởng thành.","imageURL":"https://bionexus.vn/images/zamenis-scalaris.jpg","referenceURL":"https://www.gbif.org/species/9416124"},{"id":121,"nodeId":244,"scientificName":"Coelognathus radiatus","commonName":"Rắn Hổ Ngựa (Radiated Ratsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-31°C (điểm sưởi 31-33°C), Độ ẩm: 65-85%, Môi trường: Đồng ruộng, trảng cỏ, rừng thứ sinh và vùng ven làng mạc Đông Nam Á","description":"Loài rắn nước cỡ lớn quen thuộc khắp Đông Nam Á với ba vệt đen tỏa ra như tia nắng từ mắt và thế phòng thủ phồng dẹp cổ cao chữ S đầy kịch tính.","imageURL":"https://bionexus.vn/images/coelognathus-radiatus.jpg","referenceURL":"https://www.gbif.org/species/5224321"},{"id":122,"nodeId":245,"scientificName":"Gonyosoma oxycephalum","commonName":"Rắn Đuôi Đỏ Cây (Red-tailed Green Ratsnake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 31-33°C), Độ ẩm: 65-85%, Môi trường: Tán rừng mưa nhiệt đới, rừng ngập mặn và thung lũng ven suối Đông Nam Á","description":"Loài rắn cây tuyệt đẹp của rừng nhiệt đới Đông Nam Á với toàn thân xanh ngọc lục bảo rực rỡ đối lập cùng chiếc đuôi màu nâu đỏ hoặc xám bạc.","imageURL":"https://bionexus.vn/images/gonyosoma-oxycephalum.jpg","referenceURL":"https://www.gbif.org/species/2456135"},{"id":123,"nodeId":245,"scientificName":"Gonyosoma boulengeri","commonName":"Rắn Vòi Voi (Rhinoceros Rat Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-26°C (điểm sưởi 27-29°C), Độ ẩm: 70-85%, Môi trường: Rừng thường xanh cận nhiệt đới núi cao và thung lũng suối miền Bắc Việt Nam và Nam Trung Quốc","description":"Loài rắn cây kỳ thú của vùng núi Bắc Bộ Việt Nam và Nam Trung Quốc với chiếc sừng mềm покрытый vảy nhô ra trước mũi như sừng tê giác.","imageURL":"https://bionexus.vn/images/gonyosoma-boulengeri.jpg","referenceURL":"https://www.gbif.org/species/9454074"},{"id":124,"nodeId":246,"scientificName":"Ahaetulla prasina","commonName":"Rắn Roi Xanh (Asian Vine Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 30-32°C), Độ ẩm: 65-85%, Môi trường: Tán cây bụi, rừng thứ sinh và vườn cây nhiệt đới khắp Đông Nam Á","description":"Loài rắn dây leo có thân hình mảnh như sợi dây rừng, chiếc đầu nhọn như mũi tên và đôi mắt có đồng tử nằm ngang nhìn hai mắt tập trung cực chuẩn.","imageURL":"https://bionexus.vn/images/ahaetulla-prasina.jpg","referenceURL":"https://www.gbif.org/species/2453368"},{"id":125,"nodeId":246,"scientificName":"Ahaetulla nasuta","commonName":"Rắn Roi Mũi Dài Sri Lanka (Sri Lankan Green Vine Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 30-32°C), Độ ẩm: 65-85%, Môi trường: Rừng mưa nhiệt đới thấp và vườn cây rậm rạp tại Sri Lanka","description":"Loài rắn roi cây nổi tiếng của đảo quốc Sri Lanka với phần phụ da nhọn dài vươn ra ở chóp mõm giúp ngụy trang hoàn hảo như một đọt lá non.","imageURL":"https://bionexus.vn/images/ahaetulla-nasuta.jpg","referenceURL":"https://www.gbif.org/species/2453329"},{"id":126,"nodeId":247,"scientificName":"Oxybelis aeneus","commonName":"Rắn Dây Leo Nâu Châu Mỹ (Brown Vine Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 31-33°C), Độ ẩm: 55-75%, Môi trường: Rừng khô nhiệt đới, trảng cây bụi và bìa rừng từ cực nam Arizona đến Nam Mỹ","description":"Bậc thầy ngụy trang thành cành cây khô của châu Mỹ nhiệt đới với chiếc đầu thuôn nhọn và phần trong khoang miệng màu đen tím đặc trưng.","imageURL":"https://bionexus.vn/images/oxybelis-aeneus.jpg","referenceURL":"https://www.gbif.org/species/2453632"},{"id":127,"nodeId":247,"scientificName":"Oxybelis fulgidus","commonName":"Rắn Dây Leo Xanh Nam Mỹ (Green Vine Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 30-32°C), Độ ẩm: 65-85%, Môi trường: Tán rừng mưa nhiệt đới và rừng thứ sinh từ Mexico đến lưu vực Amazon","description":"Loài rắn dây leo xanh lớn và khỏe khoắn của rừng mưa Trung và Nam Mỹ với chiếc lưỡi dài màu xanh lục giữ bất động khi dò tìm mùi con mồi.","imageURL":"https://bionexus.vn/images/oxybelis-fulgidus.jpg","referenceURL":"https://www.gbif.org/species/2453625"},{"id":128,"nodeId":248,"scientificName":"Opheodrys aestivus","commonName":"Rắn Xanh Nhám (Rough Green Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C (điểm sưởi 29-31°C), Độ ẩm: 55-75%, Môi trường: Cây bụi rậm ven sông hồ, đầm lầy và bìa rừng miền Đông Nam Hoa Kỳ","description":"Loài rắn ăn côn trùng hiền lành tuyệt đối của miền Đông Nam Hoa Kỳ với lớp vảy xanh lá cây có gờ nhám và chiếc bụng vàng kem tươi sáng.","imageURL":"https://bionexus.vn/images/opheodrys-aestivus.jpg","referenceURL":"https://www.gbif.org/species/8984671"},{"id":129,"nodeId":248,"scientificName":"Opheodrys vernalis","commonName":"Rắn Xanh Mượt (Smooth Green Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 19-25°C (điểm sưởi 26-28°C), Độ ẩm: 50-70%, Môi trường: Đồng cỏ ẩm, đầm lầy cỏ và trảng rừng thông miền Bắc Hoa Kỳ và Nam Canada","description":"Họ hàng phương Bắc của rắn xanh nhám với lớp vảy trơn láng bóng như lụa xanh và lối sống gắn liền với các thảm cỏ mát mẻ.","imageURL":"https://bionexus.vn/images/opheodrys-vernalis.jpg","referenceURL":"https://www.gbif.org/species/2458587"},{"id":130,"nodeId":249,"scientificName":"Drymarchon couperi","commonName":"Rắn Chàm Phương Đông (Eastern Indigo Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-29°C (điểm sưởi 30-32°C), Độ ẩm: 50-70%, Môi trường: Đồi cát rừng thông lá dài và đầm lầy ven suối ở Florida và Nam Georgia","description":"Loài rắn bản địa dài nhất Bắc Mỹ với lớp vảy đen ánh xanh chàm tím lấp lánh như kim loại và cằm màu cam rực rỡ.","imageURL":"https://bionexus.vn/images/drymarchon-couperi.jpg","referenceURL":"https://www.gbif.org/species/2452317"},{"id":131,"nodeId":249,"scientificName":"Drymarchon corais","commonName":"Rắn Chàm Đuôi Vàng Nam Mỹ (Yellow-tailed Cribo)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 31-33°C), Độ ẩm: 60-80%, Môi trường: Rừng mưa nhiệt đới, trảng cỏ savan ngập nước và bờ sông Nam Mỹ","description":"Loài rắn săn mồi đỉnh cao không độc của rừng nhiệt đới Nam Mỹ với nửa thân trước đen nhánh chuyển dần sang vàng tươi rực rỡ ở phần đuôi.","imageURL":"https://bionexus.vn/images/drymarchon-corais.jpg","referenceURL":"https://www.gbif.org/species/7759294"},{"id":132,"nodeId":250,"scientificName":"Hydrodynastes gigas","commonName":"Rắn Hổ Mang Nước Giả Nam Mỹ (False Water Cobra)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-27°C, Độ ẩm: 65-80%, Môi trường: Đầm lầy ngập nước, rừng Pantanal và lưu vực sông lớn ở Nam Mỹ","description":"Loài rắn bán thủy sinh khổng lồ của vùng đất ngập nước Nam Mỹ có khả năng bành rộng cổ như rắn hổ mang nhưng lại mang tính cách thông minh, tò mò.","imageURL":"https://bionexus.vn/images/hydrodynastes-gigas.jpg","referenceURL":"https://www.gbif.org/species/2454428"},{"id":133,"nodeId":251,"scientificName":"Spilotes pullatus","commonName":"Rắn Chuột Vàng Đen Nam Mỹ (Tiger Rat Snake)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 31-33°C), Độ ẩm: 65-85%, Môi trường: Rừng mưa nhiệt đới, bìa rừng và hành lang cây xanh ven sông từ Mexico đến Argentina","description":"Loài rắn leo cây bán địa sinh nổi bật nhất vùng Tân Nhiệt đới với những vạch chéo màu vàng chanh và đen tuyền đan xen như bộ lông hổ.","imageURL":"https://bionexus.vn/images/spilotes-pullatus.jpg","referenceURL":"https://www.gbif.org/species/9195230"},{"id":134,"nodeId":252,"scientificName":"Centrochelys sulcata","commonName":"Rùa Châu Phi Sulcata (African Spurred Tortoise)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 25-33°C (điểm sưởi 35-40°C), Độ ẩm: 40-60%, Môi trường: Đồng cỏ khô, savan cây bụi gai và rìa nam sa mạc Sahara (vùng Sahel)","description":"Loài rùa cạn sống trên đất liền lớn nhất lục địa châu Phi và lớn thứ ba thế giới, nổi bật với bộ mai vàng nâu vạm vỡ và những chiếc vảy gai lớn như cựa trên hai đùi sau.","imageURL":"https://bionexus.vn/images/centrochelys-sulcata.jpg","referenceURL":"https://www.gbif.org/species/2441533"},{"id":135,"nodeId":253,"scientificName":"Stigmochelys pardalis","commonName":"Rùa Da Báo Châu Phi (Leopard Tortoise)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-32°C (điểm sưởi 34-38°C), Độ ẩm: 45-65%, Môi trường: Thảo nguyên savan và đồng cỏ cây bụi từ Đông Phi xuống Nam Phi","description":"Loài rùa cạn lớn thứ tư thế giới với chiếc mai vòm cao trang trí những đốm và vòng đen trên nền vàng kem tựa như bộ lông báo hoa mai.","imageURL":"https://bionexus.vn/images/stigmochelys-pardalis.jpg","referenceURL":"https://www.gbif.org/species/2441757"},{"id":136,"nodeId":254,"scientificName":"Chelonoidis denticulatus","commonName":"Rùa Chân Vàng Nam Mỹ (Yellow-footed Tortoise)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 31-33°C), Độ ẩm: 70-85%, Môi trường: Sàn rừng mưa nhiệt đới rậm rạp thuộc lưu vực sông Amazon và Orinoco","description":"Loài rùa cạn lớn nhất lục địa Nam Mỹ, sinh sống dưới tán rừng mưa Amazon âm u với những chiếc vảy màu vàng cam tươi tắn trên đầu và tứ chi.","imageURL":"https://bionexus.vn/images/chelonoidis-denticulatus.jpg","referenceURL":"https://www.gbif.org/species/5220281"},{"id":137,"nodeId":254,"scientificName":"Chelonoidis chilensis","commonName":"Rùa Đất Chaco (Chaco Tortoise)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 20-30°C (điểm sưởi 32-35°C), Độ ẩm: 35-55%, Môi trường: Đồng bằng cây bụi gai khô hạn Gran Chaco và thảo nguyên Monte ở Nam Mỹ","description":"Loài rùa cạn kích thước nhỏ gọn của vùng bình nguyên khô hạn Gran Chaco thuộc Argentina, Paraguay và Bolivia với bộ mai vàng nâu viền sẫm.","imageURL":"https://bionexus.vn/images/chelonoidis-chilensis.jpg","referenceURL":"https://www.gbif.org/species/5220283"},{"id":138,"nodeId":254,"scientificName":"Chelonoidis niger","commonName":"Rùa Khổng Lồ Đảo Floreana (Floreana Giant Tortoise)","conservationStatus":"EX","environmentSpecs":"Nhiệt độ: 20-30°C (điểm sưởi 30-34°C), Độ ẩm: 50-75%, Môi trường: Đồi núi lửa khô hạn và vùng cao nguyên ẩm đảo Floreana, quần đảo Galápagos","description":"Loài rùa khổng lồ mang chiếc mai hình yên ngựa vểnh cao của đảo Floreana (Galápagos), đã tuyệt chủng vào giữa thế kỷ 19 chỉ vài thập kỷ sau chuyến viếng thăm của Charles Darwin.","imageURL":"https://bionexus.vn/images/chelonoidis-niger.jpg","referenceURL":"https://www.gbif.org/species/9527499"},{"id":139,"nodeId":22,"scientificName":"Testudo graeca","commonName":"Rùa Đất Hy Lạp (Greek Tortoise)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 20-29°C (điểm sưởi 32-35°C), Độ ẩm: 40-60%, Môi trường: Đồi cây bụi Địa Trung Hải, thảo nguyên đá và rừng thông thưa quanh Địa Trung Hải","description":"Loài rùa cạn cổ điển của lưu vực Địa Trung Hải và Tây Á, dễ nhận biết nhờ đôi cựa sừng nhỏ ở hai bên đùi sau và tấm vảy trên đuôi không tách đôi.","imageURL":"https://bionexus.vn/images/testudo-graeca.jpg","referenceURL":"https://www.gbif.org/species/2441461"},{"id":140,"nodeId":22,"scientificName":"Testudo marginata","commonName":"Rùa Đất Vành Mai (Marginated Tortoise)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-29°C (điểm sưởi 32-35°C), Độ ẩm: 40-60%, Môi trường: Sườn núi đá vôi và rừng cây bụi khô tại Hy Lạp và đảo Sardinia","description":"Loài rùa cạn lớn nhất châu Âu với phần rìa mai phía sau xòe rộng ra ngoài giống như vành mũ sắt của chiến binh cổ đại.","imageURL":"https://bionexus.vn/images/testudo-marginata.jpg","referenceURL":"https://www.gbif.org/species/2441502"},{"id":141,"nodeId":22,"scientificName":"Testudo horsfieldii","commonName":"Rùa Đất Nga Bốn Móng (Russian Tortoise)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 20-28°C (điểm sưởi 32-35°C), Độ ẩm: 30-50%, Môi trường: Thảo nguyên khô, bán sa mạc đất sét và sườn đồi đá vùng Trung Á","description":"Loài rùa cạn nhỏ nhắn dẻo dai của vùng thảo nguyên Trung Á, dễ nhận biết nhờ chiếc mai tròn hơi dẹt màu vàng cát và chỉ có đúng bốn móng trên mỗi bàn chân trước.","imageURL":"https://bionexus.vn/images/testudo-horsfieldii.jpg","referenceURL":"https://www.gbif.org/species/2441514"},{"id":142,"nodeId":22,"scientificName":"Testudo kleinmanni","commonName":"Rùa Đất Ai Cập (Egyptian Tortoise)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 22-32°C (điểm sưởi 34-37°C), Độ ẩm: 30-50%, Môi trường: Đụn cát ven biển và bán sa mạc đá vôi dọc bờ Nam Địa Trung Hải","description":"Loài rùa cạn nhỏ nhất Bắc bán cầu với chiếc mai vòm cao màu vàng ngà phản xạ nắng sa mạc và đôi vệt tam giác đen trên yếm bụng.","imageURL":"https://bionexus.vn/images/testudo-kleinmanni.jpg","referenceURL":"https://www.gbif.org/species/2441511"},{"id":143,"nodeId":255,"scientificName":"Astrochelys radiata","commonName":"Rùa Sao Madagascar (Radiated Tortoise)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 24-32°C (điểm sưởi 34-37°C), Độ ẩm: 45-65%, Môi trường: Rừng cây bụi gai khô hạn và đồi cát miền Nam và Tây Nam đảo Madagascar","description":"Được ca ngợi là một trong những loài rùa cạn đẹp nhất hành tinh với chiếc mai vòm cao đen nhánh tỏa ra những tia vàng rực rỡ như ánh mặt trời.","imageURL":"https://bionexus.vn/images/astrochelys-radiata.jpg","referenceURL":"https://www.gbif.org/species/2441666"},{"id":144,"nodeId":255,"scientificName":"Astrochelys yniphora","commonName":"Rùa Lưỡi Cày Madagascar (Ploughshare Tortoise)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 25-33°C (điểm sưởi 35-38°C), Độ ẩm: 50-75%, Môi trường: Rừng tre khô xen trảng cỏ và cây bụi ven vịnh Baly, Tây Bắc Madagascar","description":"Loài rùa cạn quý hiếm bậc nhất thế giới với tấm vảy yếm trước ngực kéo dài cong vểnh ra phía trước dưới cổ giống hệt một chiếc lưỡi cày.","imageURL":"https://bionexus.vn/images/astrochelys-yniphora.jpg","referenceURL":"https://www.gbif.org/species/2441673"},{"id":145,"nodeId":256,"scientificName":"Pyxis arachnoides","commonName":"Rùa Nhện Madagascar (Spider Tortoise)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 24-33°C (điểm sưởi 34-37°C), Độ ẩm: 45-65%, Môi trường: Đụn cát ven biển và rừng cây bụi gai khô hạn Tây Nam Madagascar","description":"Loài rùa cạn tí hon đặc hữu của vùng bờ biển Tây Nam Madagascar, mang hoa văn tia vàng nối vào nhau như mạng nhện và khớp bản lề ở yếm trước.","imageURL":"https://bionexus.vn/images/pyxis-arachnoides.jpg","referenceURL":"https://www.gbif.org/species/5220309"},{"id":146,"nodeId":257,"scientificName":"Geochelone elegans","commonName":"Rùa Sao Ấn Độ (Indian Star Tortoise)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 25-33°C (điểm sưởi 34-37°C), Độ ẩm: 45-70%, Môi trường: Đồng cỏ khô, rừng cây bụi gai và vùng nông nghiệp bán khô hạn ở Ấn Độ, Pakistan và Sri Lanka","description":"Loài rùa cạn nổi tiếng của tiểu lục địa Ấn Độ với những tấm vảy lưng nhô hình tháp tự nhiên mang họa tiết ngôi sao vàng kem đối xứng.","imageURL":"https://bionexus.vn/images/geochelone-elegans.jpg","referenceURL":"https://www.gbif.org/species/2441535"},{"id":147,"nodeId":258,"scientificName":"Indotestudo elongata","commonName":"Rùa Núi Vàng (Elongated Tortoise)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 24-30°C (điểm sưởi 31-34°C), Độ ẩm: 65-85%, Môi trường: Rừng khộp lá rộng rụng lá, rừng tre nứa và rừng thường xanh đồi núi Đông Nam Á","description":"Loài rùa cạn bản địa quen thuộc nhất của rừng Việt Nam với chiếc mai thuôn dài màu vàng ngà điểm đốm đen và cái đầu chuyển sang màu hồng đào vào mùa sinh sản.","imageURL":"https://bionexus.vn/images/indotestudo-elongata.jpg","referenceURL":"https://www.gbif.org/species/8539576"},{"id":148,"nodeId":259,"scientificName":"Manouria emys","commonName":"Rùa Núi Nâu (Asian Forest Tortoise)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 22-29°C (điểm sưởi 30-32°C), Độ ẩm: 70-90%, Môi trường: Rừng mưa thường xanh ẩm ướt và khe suối rừng núi Đông Nam Á","description":"Loài rùa cạn lớn nhất châu Á và mang nhiều nét tiến hóa cổ xưa nhất trong họ Testudinidae, là loài rùa cạn duy nhất biết vun lá xây tổ gò và canh giữ trứng.","imageURL":"https://bionexus.vn/images/manouria-emys.jpg","referenceURL":"https://www.gbif.org/species/2441830"},{"id":149,"nodeId":260,"scientificName":"Malacochersus tornieri","commonName":"Rùa Bánh Kẹp Châu Phi (Pancake Tortoise)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 24-32°C (điểm sưởi 35-38°C), Độ ẩm: 35-55%, Môi trường: Đồi đá granit nứt nẻ (kopjes) giữa thảo nguyên khô Đông Phi","description":"Loài rùa cạn kỳ lạ nhất thế giới với chiếc mai mỏng dẹt và mềm dẻo như chiếc bánh kếp, cho phép chúng chạy nhanh và luồn sâu vào những khe đá hẹp.","imageURL":"https://bionexus.vn/images/malacochersus-tornieri.jpg","referenceURL":"https://www.gbif.org/species/2441842"},{"id":150,"nodeId":261,"scientificName":"Kinixys homeana","commonName":"Rùa Bản Lề Lưng Gù Home (Home's Hinge-back Tortoise)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 24-29°C (điểm sưởi 30-32°C), Độ ẩm: 75-90%, Môi trường: Sàn rừng mưa nhiệt đới ẩm ướt và đầm lầy ven biển Tây và Trung Phi","description":"Loài rùa cạn rừng mưa Tây Phi sở hữu khớp bản lề độc đáo nằm ngay trên phần sau của mai lưng, giúp gập kín đuôi và hai chân sau như một chiếc hộp.","imageURL":"https://bionexus.vn/images/kinixys-homeana.jpg","referenceURL":"https://www.gbif.org/species/2441703"},{"id":151,"nodeId":262,"scientificName":"Chersina angulata","commonName":"Rùa Mũi Tàu Nam Phi (Angulate Tortoise)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-29°C (điểm sưởi 32-35°C), Độ ẩm: 40-60%, Môi trường: Cồn cát ven biển và thảm thực vật cây bụi fynbos ở Nam Phi và Namibia","description":"Loài rùa cạn đặc trưng của vùng mũi Hảo Vọng với tấm vảy yếm đơn nhô dài dưới cổ như mũi tàu chiến để các con đực tỉ thí mùa giao phối.","imageURL":"https://bionexus.vn/images/chersina-angulata.jpg","referenceURL":"https://www.gbif.org/species/5220285"},{"id":152,"nodeId":263,"scientificName":"Homopus areolatus","commonName":"Rùa Lùn Mỏ Vẹt (Common Padloper)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 19-28°C (điểm sưởi 30-33°C), Độ ẩm: 45-65%, Môi trường: Thảm cây bụi fynbos và đồng cỏ ven biển vùng Cape, Nam Phi","description":"Loài rùa cạn lùn đặc hữu của Nam Phi có chiếc mỏ hàm trên cong nhọn như mỏ vẹt và tâm các tấm vảy lưng lõm sâu viền nâu đỏ.","imageURL":"https://bionexus.vn/images/homopus-areolatus.jpg","referenceURL":"https://www.gbif.org/species/5220261"},{"id":153,"nodeId":264,"scientificName":"Gopherus agassizii","commonName":"Rùa Sa Mạc Mojave (Mojave Desert Tortoise)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 24-34°C (điểm sưởi 35-39°C), Độ ẩm: 25-45%, Môi trường: Thung lũng cát sỏi, rừng cây bụi creosote và cây Joshua thuộc sa mạc Mojave và Colorado","description":"Kỹ sư sinh thái của sa mạc Mojave miền Tây Nam Hoa Kỳ, dành tới 95% cuộc đời trong những hang ngầm mát mẻ nơi hàng chục loài động vật sa mạc khác cùng trú nhờ.","imageURL":"https://bionexus.vn/images/gopherus-agassizii.jpg","referenceURL":"https://www.gbif.org/species/2441814"},{"id":154,"nodeId":264,"scientificName":"Gopherus polyphemus","commonName":"Rùa Đất Gopher (Gopher Tortoise)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 23-32°C (điểm sưởi 33-37°C), Độ ẩm: 45-65%, Môi trường: Đồi cát rừng thông lá dài và đồng cỏ ven biển Đông Nam Hoa Kỳ","description":"Loài rùa cạn chốt chặn sinh thái của miền Đông Nam Hoa Kỳ, nổi tiếng với những đường hầm dài tới 12 mét làm nơi trú ngụ cho hơn 350 loài động vật khác.","imageURL":"https://bionexus.vn/images/gopherus-polyphemus.jpg","referenceURL":"https://www.gbif.org/species/2441812"},{"id":155,"nodeId":264,"scientificName":"Gopherus berlandieri","commonName":"Rùa Đất Texas (Texas Tortoise)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-33°C (điểm sưởi 34-38°C), Độ ẩm: 35-55%, Môi trường: Đồng cỏ cây bụi gai chaparral và bán sa mạc ở Nam Texas và Đông Bắc Mexico","description":"Loài nhỏ nhất trong nhóm rùa đất Bắc Mỹ chi Gopherus, không tự đào hang sâu mà chỉ khoét các hốc nông dưới những bụi xương rồng lê gai.","imageURL":"https://bionexus.vn/images/gopherus-berlandieri.jpg","referenceURL":"https://www.gbif.org/species/2441808"},{"id":156,"nodeId":265,"scientificName":"Trachemys scripta","commonName":"Rùa Tai Đỏ (Pond Slider)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-27°C, Độ ẩm: 50-70%, pH: 6.5-8, Môi trường: Sông chậm, hồ nước ngọt, đầm lầy và ao có nhiều khúc gỗ phơi nắng ở Bắc Mỹ","description":"Loài rùa đầm Bắc Mỹ nổi tiếng với vệt sọc đỏ hoặc vàng tươi sau mắt, từng được nuôi phổ biến nhưng nay nằm trong danh sách 100 loài ngoại lai xâm hại nguy hiểm nhất thế giới.","imageURL":"https://bionexus.vn/images/trachemys-scripta.jpg","referenceURL":"https://www.gbif.org/species/2443002"},{"id":157,"nodeId":266,"scientificName":"Chrysemys picta","commonName":"Rùa Sơn Gấm Bắc Mỹ (Painted Turtle)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 20-26°C, Độ ẩm: 50-70%, pH: 6.5-7.8, Môi trường: Hồ nước ngọt, đầm lầy, ao bùn và suối chảy chậm khắp Bắc Mỹ","description":"Loài rùa nước có phạm vi phân bố rộng nhất Bắc Mỹ với chiếc mai trơn bóng viền đỏ cam rực rỡ như được họa sĩ tô vẽ bằng tay.","imageURL":"https://bionexus.vn/images/chrysemys-picta.jpg","referenceURL":"https://www.gbif.org/species/2443133"},{"id":158,"nodeId":267,"scientificName":"Pseudemys concinna","commonName":"Rùa Sông Cooter Miền Đông (River Cooter)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-26°C, Độ ẩm: 50-70%, pH: 6.5-7.8, Môi trường: Sông lớn chảy vừa đến nhanh có nhiều thảm rong thủy sinh ở Đông và Trung Hoa Kỳ","description":"Loài rùa nước ngọt cỡ lớn chuyên sống ở các dòng sông trong vắt miền Đông Hoa Kỳ với hoa văn chữ C ngược màu vàng trên tấm vảy sườn thứ hai.","imageURL":"https://bionexus.vn/images/pseudemys-concinna.jpg","referenceURL":"https://www.gbif.org/species/8898408"},{"id":159,"nodeId":267,"scientificName":"Pseudemys nelsoni","commonName":"Rùa Bụng Đỏ Florida (Florida Red-bellied Cooter)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-27°C, Độ ẩm: 55-75%, pH: 6.5-7.8, Môi trường: Đầm lầy Everglades, hồ nước ngọt, suối khoáng và vùng nước lợ nhẹ ở Florida","description":"Loài rùa đầm lầy đặc trưng của bán đảo Florida với chiếc mai vòm cao điểm vạch đỏ cam và mặt yếm bụng ánh màu san hô rực rỡ.","imageURL":"https://bionexus.vn/images/pseudemys-nelsoni.jpg","referenceURL":"https://www.gbif.org/species/2442843"},{"id":160,"nodeId":267,"scientificName":"Pseudemys rubriventris","commonName":"Rùa Bụng Đỏ Phương Bắc (Northern Red-bellied Cooter)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ nước: 20-25°C, Độ ẩm: 50-70%, pH: 6.5-7.8, Môi trường: Sông sâu, hồ băng hà và đầm lầy ven biển miền Trung Đại Tây Dương Hoa Kỳ","description":"Họ hàng phương Bắc chịu lạnh giỏi của nhóm rùa bụng đỏ, sinh sống dọc vùng vịnh Chesapeake và có một quần thể di tích tại bang Massachusetts.","imageURL":"https://bionexus.vn/images/pseudemys-rubriventris.jpg","referenceURL":"https://www.gbif.org/species/9601519"},{"id":161,"nodeId":268,"scientificName":"Graptemys pseudogeographica","commonName":"Rùa Bản Đồ Giả (False Map Turtle)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 21-26°C, Độ ẩm: 50-70%, pH: 6.8-8, Môi trường: Sông lớn nhiều khúc gỗ trôi thuộc lưu vực sông Mississippi và Missouri","description":"Loài rùa nước nổi tiếng với đường sống lưng nhô các gai sừng như lưng rồng và những đường vân mảnh trên mai giống đường đồng mức bản đồ địa hình.","imageURL":"https://bionexus.vn/images/graptemys-pseudogeographica.jpg","referenceURL":"https://www.gbif.org/species/9228211"},{"id":162,"nodeId":269,"scientificName":"Malaclemys terrapin","commonName":"Rùa Kim Cương Nước Lợ (Diamondback Terrapin)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ nước: 22-26°C, Độ ẩm: 55-75%, pH: 7.2-8.2, Môi trường: Đầm lầy cỏ muối, cửa sông, vịnh ven biển và rừng ngập mặn bờ Đông và vịnh Mexico Hoa Kỳ","description":"Loài rùa duy nhất trên thế giới chuyên sống trọn đời trong môi trường nước lợ ven biển, sở hữu làn da trắng xám lấm tấm chấm bi đen và các tấm vảy mai hình kim cương đồng tâm.","imageURL":"https://bionexus.vn/images/malaclemys-terrapin.jpg","referenceURL":"https://www.gbif.org/species/2443212"},{"id":163,"nodeId":270,"scientificName":"Terrapene carolina","commonName":"Rùa Hộp Phương Đông Bắc Mỹ (Eastern Box Turtle)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 20-28°C (điểm sưởi 29-31°C), Độ ẩm: 60-80%, Môi trường: Sàn rừng lá rộng ẩm ướt, đồng cỏ ven rừng và thung lũng suối miền Đông Hoa Kỳ","description":"Loài rùa cạn thuộc họ rùa đầm (Emydidae) nổi tiếng của miền Đông Hoa Kỳ với chiếc mai vòm cao điểm hoa văn vàng cam và yếm bụng có bản lề đóng kín tuyệt đối.","imageURL":"https://bionexus.vn/images/terrapene-carolina.jpg","referenceURL":"https://www.gbif.org/species/2443173"},{"id":164,"nodeId":270,"scientificName":"Terrapene ornata","commonName":"Rùa Hộp Hoa Văn Thảo Nguyên (Ornate Box Turtle)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 21-30°C (điểm sưởi 31-34°C), Độ ẩm: 45-65%, Môi trường: Thảo nguyên cỏ ngắn, đồi cát và bán sa mạc vùng Đại Bình Nguyên Bắc Mỹ","description":"Loài rùa hộp thích nghi với thảo nguyên khô và bán sa mạc miền Trung Bắc Mỹ, nổi bật với những đường tia vàng sắc nét tỏa ra trên cả mai lưng lẫn yếm bụng.","imageURL":"https://bionexus.vn/images/terrapene-ornata.jpg","referenceURL":"https://www.gbif.org/species/2443168"},{"id":165,"nodeId":271,"scientificName":"Clemmys guttata","commonName":"Rùa Đốm Sao Bắc Mỹ (Spotted Turtle)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 20-25°C, Độ ẩm: 60-80%, pH: 6-7.5, Môi trường: Đầm lầy nông, suối rừng, vũng nước mùa xuân và đầm rêu than bùn miền Đông Bắc Mỹ","description":"Loài rùa bán thủy sinh tí hon duy nhất của chi Clemmys với tấm mai đen bóng điểm những chấm tròn vàng tươi như bầu trời đêm đầy sao.","imageURL":"https://bionexus.vn/images/clemmys-guttata.jpg","referenceURL":"https://www.gbif.org/species/5961001"},{"id":166,"nodeId":272,"scientificName":"Glyptemys insculpta","commonName":"Rùa Điêu Khắc Gỗ Bắc Mỹ (Wood Turtle)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 18-23°C, Độ ẩm: 55-75%, pH: 6.5-7.6, Môi trường: Suối rừng nước trong đáy cát sỏi và cánh rừng lá rộng ven suối Đông Bắc Mỹ","description":"Loài rùa bán thủy sinh thông minh của miền Đông Bắc Mỹ với từng tấm vảy trên mai nổi gờ đồng tâm trông hệt như được chạm khắc từ gỗ sồi.","imageURL":"https://bionexus.vn/images/glyptemys-insculpta.jpg","referenceURL":"https://www.gbif.org/species/2443115"},{"id":167,"nodeId":273,"scientificName":"Emys orbicularis","commonName":"Rùa Đầm Châu Âu (European Pond Turtle)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ nước: 19-25°C, Độ ẩm: 50-70%, pH: 6.5-7.8, Môi trường: Đầm lầy lau sậy, hồ nước ngọt, kênh đào và cửa sông chảy chậm khắp châu Âu và Tây Á","description":"Loài rùa nước ngọt bản địa biểu tượng của châu Âu với chiếc mai đen bóng điểm hàng trăm chấm và tia vàng li ti như bụi vàng.","imageURL":"https://bionexus.vn/images/emys-orbicularis.jpg","referenceURL":"https://www.gbif.org/species/8909809"},{"id":168,"nodeId":274,"scientificName":"Cuora amboinensis","commonName":"Rùa Hộp Lưng Đen (Southeast Asian Box Turtle)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 24-28°C, Độ ẩm: 70-85%, pH: 6.5-7.5, Môi trường: Đầm lầy trũng, ruộng lúa, rừng ngập nước và suối chảy chậm ở Đông Nam Á","description":"Loài rùa hộp bán thủy sinh bản địa của Việt Nam và Đông Nam Á, có chiếc mai vòm cao đen tuyền và ba sọc vàng tươi chạy dọc mỗi bên đầu.","imageURL":"https://bionexus.vn/images/cuora-amboinensis.jpg","referenceURL":"https://www.gbif.org/species/2443521"},{"id":169,"nodeId":274,"scientificName":"Cuora flavomarginata","commonName":"Rùa Hộp Viền Vàng (Yellow-margined Box Turtle)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 21-28°C (điểm sưởi 29-31°C), Độ ẩm: 65-85%, Môi trường: Rừng lá rộng ẩm cận nhiệt đới, bìa suối và ruộng bậc thang ở Nam Trung Quốc, Đài Loan và quần đảo Ryukyu","description":"Loài rùa hộp sống trên cạn nhiều nhất trong chi Cuora, nổi bật với đường chỉ vàng kem trên sống lưng và đôi vệt vàng tươi viền từ sau mắt ra cổ.","imageURL":"https://bionexus.vn/images/cuora-flavomarginata.jpg","referenceURL":"https://www.gbif.org/species/9116969"},{"id":170,"nodeId":274,"scientificName":"Cuora galbinifrons","commonName":"Rùa Hộp Trán Vàng Miền Bắc (Indochinese Box Turtle)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 20-27°C (điểm sưởi 27-29°C), Độ ẩm: 75-90%, Môi trường: Sàn rừng thường xanh núi cao ẩm ướt tại Việt Nam, Lào và cực nam Trung Quốc","description":"Báu vật rừng già của dãy Trường Sơn và vùng núi Bắc Bộ Việt Nam với chiếc đầu màu vàng chanh tươi sáng và tấm mai hoa văn vệt vàng trên nền nâu đỏ.","imageURL":"https://bionexus.vn/images/cuora-galbinifrons.jpg","referenceURL":"https://www.gbif.org/species/2443503"},{"id":171,"nodeId":274,"scientificName":"Cuora mouhotii","commonName":"Rùa Sa Nhân (Keeled Box Turtle)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 20-27°C (điểm sưởi 28-30°C), Độ ẩm: 70-85%, Môi trường: Sàn rừng núi đá vôi và rừng thường xanh nhiều lá mục ở Việt Nam và Đông Dương","description":"Loài rùa rừng núi đá vôi có diện mạo góc cạnh độc đáo với đỉnh mai phẳng lì có ba gờ sống nổi cao và rìa mai phía sau khía răng cưa sắc nhọn như lá cưa.","imageURL":"https://bionexus.vn/images/cuora-mouhotii.jpg","referenceURL":"https://www.gbif.org/species/2443546"},{"id":172,"nodeId":275,"scientificName":"Mauremys reevesii","commonName":"Rùa Ba Gờ Reeves (Chinese Pond Turtle)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 20-26°C, Độ ẩm: 50-70%, pH: 6.5-7.8, Môi trường: Ao hồ, đầm lầy, ruộng lúa và suối chảy chậm vùng Đông Á","description":"Loài rùa nước Đông Á quen thuộc với ba đường sống gờ nổi rõ dọc chiếc mai nâu hạt dẻ và khả năng tương tác thân thiện như thú cưng với người nuôi.","imageURL":"https://bionexus.vn/images/mauremys-reevesii.jpg","referenceURL":"https://www.gbif.org/species/2443597"},{"id":173,"nodeId":275,"scientificName":"Mauremys sinensis","commonName":"Rùa Cổ Sọc (Chinese Stripe-necked Turtle)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ nước: 22-27°C, Độ ẩm: 55-75%, pH: 6.5-7.8, Môi trường: Sông suối đồng bằng, hồ đầm và kênh rạch ở miền Bắc, Trung Việt Nam, Nam Trung Quốc và Đài Loan","description":"Loài rùa nước ngọt có chiếc cổ và bốn chân trang trí hàng chục đường kẻ sọc mảnh màu vàng xanh song song vô cùng tinh xảo như nét vẽ cọ.","imageURL":"https://bionexus.vn/images/mauremys-sinensis.jpg","referenceURL":"https://www.gbif.org/species/2443244"},{"id":174,"nodeId":276,"scientificName":"Agalychnis callidryas","commonName":"Ếch Cây Mắt Đỏ (Red-eyed Treefrog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C, Độ ẩm: 70-90%, Môi trường: Tầng tán rừng mưa nhiệt đới đất thấp","description":"Loài ếch cây nổi tiếng ở rừng mưa Trung Mỹ với đôi mắt đỏ rực, thân xanh lá tươi, sườn xanh lam sọc vàng và bàn chân màu cam.","imageURL":"https://bionexus.vn/images/agalychnis-callidryas.jpg","referenceURL":"https://www.gbif.org/species/2428197"},{"id":175,"nodeId":277,"scientificName":"Phyllomedusa bicolor","commonName":"Ếch Lá Khổng Lồ Hai Màu (Blue-and-Yellow Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-30°C, Độ ẩm: 65-85%, Môi trường: Tầng tán rừng mưa nhiệt đới ngập nước theo mùa","description":"Loài ếch cây lớn nhất họ Phyllomedusidae ở lưu vực Amazon, có lưng xanh lục đậm, bụng trắng vàng và hàng đốm trắng viền đen dọc sườn.","imageURL":"https://bionexus.vn/images/phyllomedusa-bicolor.jpg","referenceURL":"https://www.gbif.org/species/2427977"},{"id":176,"nodeId":278,"scientificName":"Pithecopus hypochondrialis","commonName":"Ếch Lá Đùi Cam (Orange-legged Leaf Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C, Độ ẩm: 65-85%, Môi trường: Rừng thưa ẩm và trảng cỏ savan ngập nước","description":"Loài ếch lá nhỏ nhắn của Nam Mỹ với lưng xanh lục tươi và mặt trong đùi cùng sườn màu cam đỏ rực rỡ điểm các vạch sọc đen.","imageURL":"https://bionexus.vn/images/pithecopus-hypochondrialis.jpg","referenceURL":"https://www.gbif.org/species/9491182"},{"id":177,"nodeId":279,"scientificName":"Hyla arborea","commonName":"Nhái Bén Châu Âu (European Tree Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-24°C, Độ ẩm: 60-80%, Môi trường: Bụi cây, lau sậy và bìa rừng ngập nắng gần ao hồ","description":"Loài nhái bén nhỏ đặc trưng của châu Âu với da lưng nhẵn bóng màu xanh lá cây và dải sọc đen viền trắng chạy từ mũi qua mắt tới bẹn.","imageURL":"https://bionexus.vn/images/hyla-arborea.jpg","referenceURL":"https://www.gbif.org/species/2427573"},{"id":178,"nodeId":280,"scientificName":"Dryophytes japonicus","commonName":"Nhái Bén Nhật Bản (Japanese Treefrog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-25°C, Độ ẩm: 60-80%, Môi trường: Ruộng lúa nước, bờ mương và đầm lầy cỏ","description":"Loài nhái bén phổ biến khắp Đông Á từ Nhật Bản tới Hàn Quốc và Đông Bắc Á, nổi bật với khả năng biến đổi màu da linh hoạt và chịu lạnh giỏi.","imageURL":"https://bionexus.vn/images/dryophytes-japonicus.jpg","referenceURL":"https://www.gbif.org/species/10857535"},{"id":179,"nodeId":281,"scientificName":"Osteopilus septentrionalis","commonName":"Ếch Cây Cuba (Cuban Treefrog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-29°C, Độ ẩm: 65-85%, Môi trường: Rừng nhiệt đới ẩm, đầm lầy rừng ngập mặn và rừng cọ","description":"Loài ếch cây cỡ lớn bản địa vùng Caribe với làn da sần nhẹ nhiều sắc thái từ trắng xám, nâu đồng tới xanh ô-liu và đôi bàn chân có đĩa bám cực lớn.","imageURL":"https://bionexus.vn/images/osteopilus-septentrionalis.jpg","referenceURL":"https://www.gbif.org/species/2428083"},{"id":180,"nodeId":282,"scientificName":"Trachycephalus resinifictrix","commonName":"Ếch Cây Sữa Amazon (Mission Golden-eyed Treefrog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C, Độ ẩm: 70-90%, Môi trường: Tầng tán rừng mưa nhiệt đới nguyên sinh gần sông suối","description":"Loài ếch cây cỡ lớn của rừng mưa Amazon nổi bật với các dải vằn nâu sô-cô-la xen trắng sữa, da điểm hạt nhỏ và mống mắt có hình chữ thập vàng đen.","imageURL":"https://bionexus.vn/images/trachycephalus-resinifictrix.jpg","referenceURL":"https://www.gbif.org/species/5217956"},{"id":181,"nodeId":283,"scientificName":"Theloderma corticale","commonName":"Ếch Cây Sần Bắc Bộ (Tonkin Bug-eyed Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 18-23°C, Độ ẩm: 75-95%, pH: 6.5-7.5, Môi trường: Khe đá vôi ngập nước và hang đá nhỏ trong rừng thường xanh ẩm","description":"Loài ếch cây nổi tiếng của vùng núi đá vôi miền Bắc Việt Nam với toàn thân phủ gai sần màu xanh rêu đốm nâu đỏ, ngụy trang hoàn hảo như một tảng đá phủ rêu.","imageURL":"https://bionexus.vn/images/theloderma-corticale.jpg","referenceURL":"https://www.gbif.org/species/5217217"},{"id":182,"nodeId":284,"scientificName":"Rhacophorus reinwardtii","commonName":"Ếch Cây Bay Xanh (Reinwardt's Tree Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C, Độ ẩm: 75-90%, Môi trường: Tầng tán rừng mưa nhiệt đới nguyên sinh và thứ sinh","description":"Loài ếch cây bay điển hình của Đông Nam Á với lưng xanh lá mạ và màng da rộng màu đen viền xanh ngọc giữa các ngón tay, ngón chân giúp lượn xa giữa các tán cây.","imageURL":"https://bionexus.vn/images/rhacophorus-reinwardtii.jpg","referenceURL":"https://www.gbif.org/species/5217267"},{"id":183,"nodeId":284,"scientificName":"Rhacophorus nigropalmatus","commonName":"Ếch Cây Bay Wallace (Abah River Flying Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C, Độ ẩm: 75-90%, Môi trường: Tầng tán cao của rừng mưa nhiệt đới cây họ Dầu (Dipterocarpaceae)","description":"Loài ếch bay nổi tiếng nhất thế giới do nhà tự nhiên học Alfred Russel Wallace ghi nhận tại Borneo, sở hữu thân xanh lục ngọc và màng chân rộng màu đen vàng.","imageURL":"https://bionexus.vn/images/rhacophorus-nigropalmatus.jpg","referenceURL":"https://www.gbif.org/species/5217285"},{"id":184,"nodeId":285,"scientificName":"Zhangixalus schlegelii","commonName":"Ếch Cây Xanh Schlegel (Japanese Gliding Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 17-24°C, Độ ẩm: 65-85%, Môi trường: Rừng lá rộng ẩm ven thung lũng và bờ ruộng bậc thang","description":"Loài ếch cây xanh đặc hữu của Nhật Bản với làn da mịn màng màu xanh táo tươi, không có sọc đen qua mắt và đôi mắt có viền mống mắt vàng kim sáng.","imageURL":"https://bionexus.vn/images/zhangixalus-schlegelii.jpg","referenceURL":"https://www.gbif.org/species/10674422"},{"id":185,"nodeId":285,"scientificName":"Zhangixalus arboreus","commonName":"Ếch Cây Rừng Nhật Bản (Forest Green Tree Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 16-24°C, Độ ẩm: 65-85%, Môi trường: Rừng lá rộng ôn đới và rừng hỗn giao vùng núi","description":"Loài ếch cây lớn đặc hữu của Nhật Bản với lưng xanh lá điểm đốm nâu rêu và đôi mắt màu cam đỏ nổi bật, nổi tiếng với tập tính đẻ tổ bọt trắng lớn trên cành cây.","imageURL":"https://bionexus.vn/images/zhangixalus-arboreus.jpg","referenceURL":"https://www.gbif.org/species/10771812"},{"id":186,"nodeId":286,"scientificName":"Ceratophrys cranwelli","commonName":"Ếch Sừng Pacman Cranwell (Cranwell's Horned Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-28°C, Độ ẩm: 65-80%, Môi trường: Trảng cỏ khô và rừng cây bụi gai vùng Gran Chaco","description":"Loài ếch sừng phổ biến nhất trong thú chơi lưỡng cư cảnh với thân hình tròn trịa, cái miệng rộng chiếm gần nửa cơ thể và mí mắt nhô cao như hai chiếc sừng nhỏ.","imageURL":"https://bionexus.vn/images/ceratophrys-cranwelli.jpg","referenceURL":"https://www.gbif.org/species/2424459"},{"id":187,"nodeId":286,"scientificName":"Ceratophrys ornata","commonName":"Ếch Sừng Argentina (Argentinean Horned Frog)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 22-27°C, Độ ẩm: 65-80%, Môi trường: Đồng cỏ ngập nước theo mùa vùng Pampas","description":"Loài ếch sừng rực rỡ của đồng cỏ Pampas với nền da xanh lá cây tươi điểm các mảng đốm nâu đen viền vàng và những vệt đỏ son nổi bật.","imageURL":"https://bionexus.vn/images/ceratophrys-ornata.jpg","referenceURL":"https://www.gbif.org/species/2424454"},{"id":188,"nodeId":286,"scientificName":"Ceratophrys cornuta","commonName":"Ếch Sừng Surinam (Surinam Horned Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-28°C, Độ ẩm: 75-90%, Môi trường: Thảm lá mục dày trên sàn rừng mưa nhiệt đới nguyên sinh","description":"Loài ếch sừng rừng mưa Amazon sở hữu cặp gai thịt trên mí mắt nhô cao nhọn hoắt và hình dáng ngụy trang hệt như một chiếc lá khô góc cạnh trên sàn rừng.","imageURL":"https://bionexus.vn/images/ceratophrys-cornuta.jpg","referenceURL":"https://www.gbif.org/species/2424456"},{"id":189,"nodeId":287,"scientificName":"Lepidobatrachus laevis","commonName":"Ếch Miệng Rộng Budgett (Budgett's Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-27°C, pH: 6.5-7.5, Môi trường: Ao đầm và vũng bùn nước mưa theo mùa vùng Gran Chaco","description":"Loài ếch nước vùng Gran Chaco có ngoại hình kỳ thú với cơ thể dẹt tròn như chiếc bánh, đôi mắt nằm hẳn lên đỉnh đầu và cái miệng rộng chiếm gần hết bề ngang thân.","imageURL":"https://bionexus.vn/images/lepidobatrachus-laevis.jpg","referenceURL":"https://www.gbif.org/species/2424550"},{"id":190,"nodeId":288,"scientificName":"Pyxicephalus adspersus","commonName":"Ếch Yêu Tinh Châu Phi (African Bullfrog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-27°C, Độ ẩm: 60-80%, Môi trường: Thảo nguyên savan khô hạn và vùng cây bụi gai","description":"Một trong những loài ếch lớn nhất thế giới với cơ thể đồ sộ nặng tới hơn 1 kg, lưng xanh ô-liu có các gờ da dọc và cặp mấu xương hàm dưới sắc khỏe như răng nanh.","imageURL":"https://bionexus.vn/images/pyxicephalus-adspersus.jpg","referenceURL":"https://www.gbif.org/species/2429965"},{"id":191,"nodeId":288,"scientificName":"Pyxicephalus edulis","commonName":"Ếch Yêu Tinh Nhỏ (Lesser Bull-frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-27°C, Độ ẩm: 60-80%, Môi trường: Trảng cỏ savan ngập nước theo mùa","description":"Họ hàng kích thước vừa của ếch yêu tinh khổng lồ, phân bố rộng ở thảo nguyên châu Phi với đường sọc sáng dọc sống lưng và vệt trắng rõ trên màng nhĩ.","imageURL":"https://bionexus.vn/images/pyxicephalus-edulis.jpg","referenceURL":"https://www.gbif.org/species/2429964"},{"id":192,"nodeId":23,"scientificName":"Ambystoma mavortium","commonName":"Kỳ Giông Hổ Miền Tây (Western Tiger Salamander)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-22°C, Độ ẩm: 65-80%, Môi trường: Đồng cỏ thảo nguyên, rừng thông thưa và bán hoang mạc gần ao hồ","description":"Loài kỳ giông cạn cỡ lớn của miền Tây Bắc Mỹ với thân hình vạm vỡ, da đen bóng điểm các dải vằn hoặc mảng đốm lớn màu vàng tươi và xanh ô-liu.","imageURL":"https://bionexus.vn/images/ambystoma-mavortium.jpg","referenceURL":"https://www.gbif.org/species/2431978"},{"id":193,"nodeId":23,"scientificName":"Ambystoma tigrinum","commonName":"Kỳ Giông Hổ Miền Đông (Eastern Tiger Salamander)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-22°C, Độ ẩm: 65-80%, Môi trường: Rừng lá rộng và rừng thông có nền đất tơi xốp dễ đào hang","description":"Loài kỳ giông cạn lớn nhất miền Đông Bắc Mỹ với thân hình chắc khỏe, da bóng màu nâu đen điểm nhiều đốm vàng ô-liu tròn bất đối xứng khắp lưng và đuôi.","imageURL":"https://bionexus.vn/images/ambystoma-tigrinum.jpg","referenceURL":"https://www.gbif.org/species/2431993"},{"id":194,"nodeId":289,"scientificName":"Dendrobates tinctorius","commonName":"Ếch Phi Tiêu Độc Nhuộm Màu (Dyeing Poison Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-26°C, Độ ẩm: 80-95%, Môi trường: Thảm lá ẩm và gốc cây gỗ mục trên sàn rừng mưa nguyên sinh","description":"Loài ếch phi tiêu độc lớn nhất chi Dendrobates ở vùng khiên Guiana, nổi tiếng với hàng chục biến thể màu sắc tự nhiên từ xanh lam Azureus tới vàng đen Cobalt.","imageURL":"https://bionexus.vn/images/dendrobates-tinctorius.jpg","referenceURL":"https://www.gbif.org/species/9724339"},{"id":195,"nodeId":289,"scientificName":"Dendrobates auratus","commonName":"Ếch Phi Tiêu Độc Xanh Đen (Green And Black Poison Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-26°C, Độ ẩm: 80-95%, Môi trường: Thảm lá ẩm sàn rừng mưa nhiệt đới đất thấp","description":"Loài ếch phi tiêu độc phổ biến ở Trung Mỹ với sắc xanh bạc hà, xanh ngọc hoặc màu đồng ánh kim nổi bật trên nền da đen nhánh.","imageURL":"https://bionexus.vn/images/dendrobates-auratus.jpg","referenceURL":"https://www.gbif.org/species/5218022"},{"id":196,"nodeId":289,"scientificName":"Dendrobates leucomelas","commonName":"Ếch Phi Tiêu Độc Sọc Vàng (Yellow-banded Poison Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-27°C, Độ ẩm: 75-90%, Môi trường: Rừng mưa nhiệt đới có mùa khô rõ rệt","description":"Loài ếch phi tiêu độc nổi bật của miền bắc Nam Mỹ với những khoang màu vàng tươi hoặc vàng cam xen kẽ khoang đen bóng như ong vò vẽ.","imageURL":"https://bionexus.vn/images/dendrobates-leucomelas.jpg","referenceURL":"https://www.gbif.org/species/5218028"},{"id":197,"nodeId":289,"scientificName":"Dendrobates truncatus","commonName":"Ếch Phi Tiêu Độc Vạch Vàng (Yellow-striped Poison Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-27°C, Độ ẩm: 75-90%, Môi trường: Rừng nhiệt đới ẩm và rừng khô theo mùa ven suối","description":"Loài ếch phi tiêu độc đặc hữu của Colombia với thân màu đen bóng nổi bật hai dải sọc vàng tươi chạy dọc từ chóp mũi tới bẹn.","imageURL":"https://bionexus.vn/images/dendrobates-truncatus.jpg","referenceURL":"https://www.gbif.org/species/5218029"},{"id":198,"nodeId":290,"scientificName":"Oophaga pumilio","commonName":"Ếch Phi Tiêu Độc Dâu Tây (Strawberry Poison Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-26°C, Độ ẩm: 80-95%, Môi trường: Rừng mưa nhiệt đới ẩm có nhiều cây họ Dứa (Bromeliaceae)","description":"Loài ếch độc nhỏ nhắn vùng Caribe Trung Mỹ, nổi tiếng với hình thái chuẩn thân đỏ dâu tây đi kèm bốn chân xanh lam đậm ('Blue Jeans') và tập tính nuôi con bằng trứng.","imageURL":"https://bionexus.vn/images/oophaga-pumilio.jpg","referenceURL":"https://www.gbif.org/species/2429135"},{"id":199,"nodeId":290,"scientificName":"Oophaga histrionica","commonName":"Ếch Phi Tiêu Độc Hề (Harlequin Poison Frog)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 18-25°C, Độ ẩm: 70-85%, Môi trường: Rừng mưa nhiệt đới siêu ẩm vùng Chocó","description":"Loài ếch độc quý hiếm của rừng mưa Chocó (Colombia) với những mảng hoa văn cam đỏ, vàng hoặc trắng tương phản rực rỡ trên nền da đen tuyền.","imageURL":"https://bionexus.vn/images/oophaga-histrionica.jpg","referenceURL":"https://www.gbif.org/species/2429137"},{"id":200,"nodeId":291,"scientificName":"Phyllobates terribilis","commonName":"Ếch Độc Phi Tiêu Vàng (Golden Poison Frog)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 18-25°C, Độ ẩm: 70-85%, Môi trường: Rừng mưa nhiệt đới ẩm nguyên sinh trên sườn đồi thoát nước tốt","description":"Loài lưỡng cư nổi tiếng nhất thế giới về độc tính ngoài tự nhiên ở bờ biển Thái Bình Dương của Colombia, khoác lên mình màu vàng kim, cam hoặc xanh bạc hà rực sáng.","imageURL":"https://bionexus.vn/images/phyllobates-terribilis.jpg","referenceURL":"https://www.gbif.org/species/5218020"},{"id":201,"nodeId":291,"scientificName":"Phyllobates bicolor","commonName":"Ếch Độc Phi Tiêu Chân Đen (Black-legged Poison Dart Frog)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 18-25°C, Độ ẩm: 70-85%, Môi trường: Sàn rừng mưa nhiệt đới ẩm vùng đồi núi thấp","description":"Loài ếch độc lớn thứ hai trong chi Phyllobates tại miền tây Colombia, nổi bật với thân màu vàng cam rực rỡ và bốn chân màu đen điểm chấm xanh lục.","imageURL":"https://bionexus.vn/images/phyllobates-bicolor.jpg","referenceURL":"https://www.gbif.org/species/5218019"},{"id":202,"nodeId":291,"scientificName":"Phyllobates vittatus","commonName":"Ếch Độc Sọc Cam Golfo Dulce (Golfodulcean Poison Frog)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 21-26°C, Độ ẩm: 80-95%, Môi trường: Thảm lá ẩm ven các khe suối đá trong rừng mưa nhiệt đới đất thấp","description":"Loài ếch phi tiêu độc vùng vịnh Golfo Dulce (Costa Rica) với nền thân đen nhánh, hai sọc cam vàng sáng rực chạy dọc lưng và tứ chi điểm đốm xanh ngọc.","imageURL":"https://bionexus.vn/images/phyllobates-vittatus.jpg","referenceURL":"https://www.gbif.org/species/5218018"},{"id":203,"nodeId":292,"scientificName":"Ranitomeya imitator","commonName":"Ếch Phi Tiêu Độc Bắt Chước (Mimic Poison Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-26°C, Độ ẩm: 80-95%, Môi trường: Rừng mưa nhiệt đới nguyên sinh và thứ sinh có nhiều cây họ Chuối mỏ két (Heliconia), Ráy và Dứa cảnh","description":"Loài ếch độc ngón cái tí hon của rừng mưa Peru, nổi tiếng trong sinh học tiến hóa vì khả năng bắt chước hoa văn của ba loài ếch độc khác nhau và sống chung thủy một vợ một chồng.","imageURL":"https://bionexus.vn/images/ranitomeya-imitator.jpg","referenceURL":"https://www.gbif.org/species/2429079"},{"id":204,"nodeId":293,"scientificName":"Epipedobates tricolor","commonName":"Ếch Độc Ba Màu (Phantasmal Poison Frog)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 19-25°C, Độ ẩm: 75-90%, Môi trường: Bờ suối ẩm và đồng cỏ ướt sườn núi Andes","description":"Loài ếch phi tiêu độc vùng sườn núi Andes thuộc Ecuador với cơ thể màu đỏ thẫm hoặc nâu đỏ cắt ngang bởi ba dải sọc trắng kem hay vàng xanh chạy dọc thân.","imageURL":"https://bionexus.vn/images/epipedobates-tricolor.jpg","referenceURL":"https://www.gbif.org/species/2429055"},{"id":205,"nodeId":293,"scientificName":"Epipedobates anthonyi","commonName":"Ếch Độc Sọc Hồng Anthony (Anthony's Poison-Arrow Frog)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 20-26°C, Độ ẩm: 70-90%, Môi trường: Bờ suối có cây bụi rậm rạp và kênh nước quanh đồn điền chuối","description":"Loài ếch phi tiêu độc nhỏ nhắn của nam Ecuador và bắc Peru với nền lưng đỏ nâu và ba dải sọc trắng hồng hoặc xanh ngọc chạy dọc từ đầu tới gốc đuôi.","imageURL":"https://bionexus.vn/images/epipedobates-anthonyi.jpg","referenceURL":"https://www.gbif.org/species/2429056"},{"id":206,"nodeId":294,"scientificName":"Ameerega trivittata","commonName":"Ếch Độc Ba Sọc Xanh (Three-striped Arrow-poison Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-27°C, Độ ẩm: 75-90%, Môi trường: Sàn rừng mưa nhiệt đới đất thấp gần các khe suối và khoảng rừng trống","description":"Loài ếch độc đất cỡ lớn của lưu vực Amazon với làn da lưng hơi nhám màu đen nhung nổi bật hai hoặc ba đường sọc vàng lục chạy từ chóp mũi tới bẹn.","imageURL":"https://bionexus.vn/images/ameerega-trivittata.jpg","referenceURL":"https://www.gbif.org/species/2429038"},{"id":207,"nodeId":294,"scientificName":"Ameerega bilinguis","commonName":"Ếch Độc Hồng Ngọc Ecuador (Ecuador Poison Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-26°C, Độ ẩm: 80-90%, Môi trường: Thảm lá mục rừng mưa nhiệt đới nguyên sinh gần bờ suối","description":"Loài ếch độc đất vùng thượng nguồn Amazon với tấm lưng màu đỏ hồng ngọc hạt nhám, hai sọc vàng kem hai bên lưng và những mảng màu vàng tươi ở nách và bẹn.","imageURL":"https://bionexus.vn/images/ameerega-bilinguis.jpg","referenceURL":"https://www.gbif.org/species/2429017"},{"id":208,"nodeId":295,"scientificName":"Mantella aurantiaca","commonName":"Ếch Vàng Madagascar (Golden Mantella)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 18-25°C, Độ ẩm: 70-85%, Môi trường: Rừng mưa núi cao ẩm mát có nhiều cây dứa dại (Pandanus)","description":"Loài ếch nhỏ bé đặc hữu của rừng ẩm miền đông Madagascar với toàn thân màu cam đỏ hoặc vàng cam trong suốt như thạch và đôi mắt đen láy.","imageURL":"https://bionexus.vn/images/mantella-aurantiaca.jpg","referenceURL":"https://www.gbif.org/species/2423174"},{"id":209,"nodeId":296,"scientificName":"Dyscophus antongilii","commonName":"Ếch Cà Chua Madagascar (Tomato Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C, Độ ẩm: 65-80%, Môi trường: Rừng mưa nhiệt đới đất thấp và rừng thứ sinh ven biển","description":"Loài ếch bầu lớn vùng đông bắc Madagascar có thân hình tròn căng mọng và màu đỏ cam rực rỡ hệt như một quả cà chua chín trên nền rừng ẩm.","imageURL":"https://bionexus.vn/images/dyscophus-antongilii.jpg","referenceURL":"https://www.gbif.org/species/5216573"},{"id":210,"nodeId":296,"scientificName":"Dyscophus guineti","commonName":"Ếch Cà Chua Sambava (Sambava Tomato Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-27°C, Độ ẩm: 65-80%, Môi trường: Rừng mưa nhiệt đới đất thấp và rừng đầm lầy","description":"Loài ếch cà chua phân bố ở các khu rừng ẩm miền đông Madagascar, nổi bật với sắc đỏ cam tươi, nếp gấp lưng rõ và đôi mắt có viền vàng đồng sáng.","imageURL":"https://bionexus.vn/images/dyscophus-guineti.jpg","referenceURL":"https://www.gbif.org/species/5216571"},{"id":211,"nodeId":297,"scientificName":"Kaloula pulchra","commonName":"Ễnh Ương (Malaysian Narrowmouth Toad)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-29°C, Độ ẩm: 65-85%, Môi trường: Vườn cây, đồng ruộng, bờ mương và khu dân cư có đất tơi xốp","description":"Loài nhái bầu quen thuộc khắp Việt Nam và Đông Nam Á với thân hình tròn mập, lưng nâu sô-cô-la viền hai dải màu vàng đồng rộng và tiếng kêu 'ễnh-ương' vang rền đêm mưa.","imageURL":"https://bionexus.vn/images/kaloula-pulchra.jpg","referenceURL":"https://www.gbif.org/species/2421636"},{"id":212,"nodeId":298,"scientificName":"Bombina orientalis","commonName":"Cóc Tía Phương Đông (Oriental Fire-bellied Toad)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 18-23°C, Độ ẩm: 70-85%, pH: 6.5-7.8, Môi trường: Suối đá rừng núi, đầm lầy cỏ và ao nước sạch có nhiều rêu","description":"Loài cóc bán thủy sinh nổi tiếng của vùng Đông Bắc Á với lưng màu xanh ngọc lục bảo đốm đen sần sùi và mặt bụng màu đỏ cam rực lửa như cảnh báo.","imageURL":"https://bionexus.vn/images/bombina-orientalis.jpg","referenceURL":"https://www.gbif.org/species/2423441"},{"id":213,"nodeId":298,"scientificName":"Bombina bombina","commonName":"Cóc Tía Châu Âu (Fire-bellied Toad)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 16-22°C, Độ ẩm: 70-85%, pH: 6.5-7.8, Môi trường: Ao hồ nước tĩnh vùng đồng bằng ngập nắng có nhiều bèo và cỏ nước","description":"Loài cóc bụng lửa đặc trưng của các vùng đồng bằng Trung và Đông Âu, có lưng xám sẫm hòa vào bùn nước và phần bụng màu cam đỏ điểm các chấm trắng li ti.","imageURL":"https://bionexus.vn/images/bombina-bombina.jpg","referenceURL":"https://www.gbif.org/species/2423443"},{"id":214,"nodeId":298,"scientificName":"Bombina variegata","commonName":"Cóc Tía Bụng Vàng (Yellow-bellied Toad)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 16-22°C, Độ ẩm: 70-85%, pH: 6.5-7.8, Môi trường: Vũng nước mưa tạm thời, khe suối nhỏ và vũng nước lầy trong rừng đồi núi","description":"Loài cóc tía vùng đồi núi Trung và Nam Âu với mặt lưng màu xám đất ngụy trang và toàn bộ phần bụng cùng chóp ngón chân màu vàng chanh tươi xen đốm đen.","imageURL":"https://bionexus.vn/images/bombina-variegata.jpg","referenceURL":"https://www.gbif.org/species/2423435"},{"id":215,"nodeId":299,"scientificName":"Xenopus laevis","commonName":"Ếch Có Vuốt Châu Phi (African Clawed Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 18-24°C, pH: 6.5-8, Môi trường: Ao hồ nước tĩnh, đầm lầy và các đoạn sông chảy chậm","description":"Loài ếch sống hoàn toàn dưới nước bản địa vùng hạ Sahara với thân hình thuôn dẹt trơn nhẵn, hệ thống đường bên cảm nhận rung động như cá và ba ngón chân sau có vuốt sừng đen.","imageURL":"https://bionexus.vn/images/xenopus-laevis.jpg","referenceURL":"https://www.gbif.org/species/5217334"},{"id":216,"nodeId":300,"scientificName":"Hymenochirus boettgeri","commonName":"Ếch Có Vuốt Lùn Congo (Congo Dwarf Clawed Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-27°C, pH: 6.5-7.8, Môi trường: Suối rừng chảy chậm, ao đầm rợp bóng cây trong rừng mưa","description":"Loài ếch thủy sinh tí hon của lưu vực sông Congo với toàn bộ cuộc đời sống dưới nước, cả bốn bàn chân đều có màng bơi và kích thước chỉ nhỉnh hơn đồng xu.","imageURL":"https://bionexus.vn/images/hymenochirus-boettgeri.jpg","referenceURL":"https://www.gbif.org/species/2423973"},{"id":217,"nodeId":301,"scientificName":"Megophrys nasuta","commonName":"Ếch Sừng Mũi Dài (Long-nosed Horned Toad)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-25°C, Độ ẩm: 75-90%, Môi trường: Thảm lá mục ẩm ướt trên sàn rừng mưa nhiệt đới nguyên sinh","description":"Loài cóc bùn hóa trang thành lá khô đỉnh cao nhất của rừng mưa Đông Nam Á với hai gai da nhọn trên mí mắt, một mấu da dài ở chóp mũi và các nếp gờ lưng hệt như gân lá.","imageURL":"https://bionexus.vn/images/megophrys-nasuta.jpg","referenceURL":"https://www.gbif.org/species/2424669"},{"id":218,"nodeId":302,"scientificName":"Rhinella marina","commonName":"Cóc Mía Nam Mỹ (South American Cane Toad)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-30°C, Độ ẩm: 55-75%, Môi trường: Trảng cỏ ẩm, bìa rừng nhiệt đới và đất canh tác nông nghiệp","description":"Loài cóc cạn khổng lồ bản địa Trung và Nam Mỹ với cặp tuyến độc mang tai cực lớn hình tam giác sau mắt và các gờ xương nổi cao trên hộp sọ.","imageURL":"https://bionexus.vn/images/rhinella-marina.jpg","referenceURL":"https://www.gbif.org/species/5216933"},{"id":219,"nodeId":303,"scientificName":"Anaxyrus americanus","commonName":"Cóc Thường Bắc Mỹ (American Toad)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-25°C, Độ ẩm: 55-75%, Môi trường: Rừng lá rộng ôn đới, đồng cỏ ẩm và vườn cây ngoại ô","description":"Loài cóc vườn quen thuộc của miền Đông Bắc Mỹ với làn da nâu sần mụn cóc, các gờ xương chữ L sau mắt và tiếng ngân dài du dương vào đêm xuân.","imageURL":"https://bionexus.vn/images/anaxyrus-americanus.jpg","referenceURL":"https://www.gbif.org/species/2422872"},{"id":220,"nodeId":304,"scientificName":"Bufo bufo","commonName":"Cóc Thường Châu Âu (Common Toad)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-23°C, Độ ẩm: 60-80%, Môi trường: Rừng lá rộng, rừng thông ẩm, đồng cỏ và vườn cây","description":"Loài cóc cạn phổ biến nhất lục địa châu Âu với thân hình bầu bĩnh, làn da nâu sần mụn cóc và đôi mắt màu đồng đỏ rực rỡ như hổ phách.","imageURL":"https://bionexus.vn/images/bufo-bufo.jpg","referenceURL":"https://www.gbif.org/species/5217160"},{"id":221,"nodeId":305,"scientificName":"Incilius alvarius","commonName":"Cóc Sa Mạc Sonora (Sonoran Desert Toad)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-32°C, Độ ẩm: 40-60%, Môi trường: Sa mạc cây bụi Creosote và rừng xương rồng Saguaro","description":"Một trong những loài cóc lớn nhất Bắc Mỹ bản địa vùng sa mạc Sonora, khác biệt với làn da lưng tương đối nhẵn màu xanh ô-liu và các nốt tuyến trắng ở khóe miệng.","imageURL":"https://bionexus.vn/images/incilius-alvarius.jpg","referenceURL":"https://www.gbif.org/species/2422432"},{"id":222,"nodeId":306,"scientificName":"Atelopus zeteki","commonName":"Ếch Vàng Panama (Cerro Campana Stubfoot Toad)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 18-25°C, Độ ẩm: 70-85%, Môi trường: Suối đá chảy xiết trong rừng mây nhiệt đới núi cao","description":"Quốc bảo sinh học của đất nước Panama với cơ thể thon mảnh màu vàng kim rực rỡ điểm các đốm đen nhánh và tập tính vẫy tay giao tiếp bên thác nước ồn ào.","imageURL":"https://bionexus.vn/images/atelopus-zeteki.jpg","referenceURL":"https://www.gbif.org/species/5216695"},{"id":223,"nodeId":306,"scientificName":"Atelopus varius","commonName":"Cóc Hề Costa Rica (Variable Harlequin Frog)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 18-25°C, Độ ẩm: 70-85%, Môi trường: Bờ suối đá mát có nhiều sương ẩm trong rừng mưa và rừng mây","description":"Loài cóc hề suối núi rực rỡ của Costa Rica và Panama với những dải hoa văn đen tuyền, vàng chanh và cam đỏ đan xen như trang phục lễ hội.","imageURL":"https://bionexus.vn/images/atelopus-varius.jpg","referenceURL":"https://www.gbif.org/species/5216646"},{"id":224,"nodeId":307,"scientificName":"Hyperolius argus","commonName":"Ếch Lau Sậy Đốm Mắt (Argus Reed Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-28°C, Độ ẩm: 70-85%, Môi trường: Đầm lầy lau sậy, hồ súng và trảng cỏ ngập nước ngọt","description":"Loài ếch cây lau sậy nhỏ nhắn của miền Đông và Nam châu Phi, nổi tiếng với hiện tượng dị hình giới tính kỳ lạ khi con đực có màu xanh lá còn con cái màu nâu đỏ điểm các đốm tròn trắng viền đen.","imageURL":"https://bionexus.vn/images/hyperolius-argus.jpg","referenceURL":"https://www.gbif.org/species/5217725"},{"id":225,"nodeId":307,"scientificName":"Hyperolius marmoratus","commonName":"Ếch Lau Sậy Cẩm Thạch (Painted Reed Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 21-28°C, Độ ẩm: 65-85%, Môi trường: Đầm lầy cỏ, bờ hồ và ruộng nước ngọt","description":"Loài ếch lau sậy đa sắc màu của miền Đông và Nam châu Phi với lưng vẽ những đường sọc hoặc hoa văn cẩm thạch trắng, đen, vàng kim và đôi chân đỏ san hô.","imageURL":"https://bionexus.vn/images/hyperolius-marmoratus.jpg","referenceURL":"https://www.gbif.org/species/5217671"},{"id":226,"nodeId":308,"scientificName":"Breviceps adspersus","commonName":"Ếch Mưa Bụng Tròn Châu Phi (Bushveld Rain Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-27°C, Độ ẩm: 55-75%, Môi trường: Thảo nguyên savan bán khô hạn có nền đất cát tơi xốp","description":"Loài ếch đất vùng thảo nguyên Nam Phi có thân hình tròn xoe như viên sỏi, khuôn mặt xịu ngộ nghĩnh, bốn chân cực ngắn không biết bơi và tập tính phát triển trực tiếp không qua giai đoạn nòng nọc bơi.","imageURL":"https://bionexus.vn/images/breviceps-adspersus.jpg","referenceURL":"https://www.gbif.org/species/5218071"},{"id":227,"nodeId":309,"scientificName":"Leptodactylus pentadactylus","commonName":"Ếch Khổng Lồ Rừng Khói (South American Bullfrog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C, Độ ẩm: 75-90%, Môi trường: Sàn rừng mưa nhiệt đới nguyên sinh gần đầm lầy và suối","description":"Loài ếch đất cỡ lớn của rừng mưa Trung và Nam Mỹ với thân hình vạm vỡ, mặt lưng nâu đồng điểm dải vằn ngang và mặt sau đùi có vân cẩm thạch đỏ đen.","imageURL":"https://bionexus.vn/images/leptodactylus-pentadactylus.jpg","referenceURL":"https://www.gbif.org/species/5217498"},{"id":228,"nodeId":310,"scientificName":"Lithobates catesbeianus","commonName":"Ếch Ương Mỹ (American bullfrog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-25°C, Độ ẩm: 70-85%, Môi trường: Hồ nước ngọt lớn, đầm lầy, ao trang trại và các đoạn sông chảy êm","description":"Loài ếch nước lớn nhất Bắc Mỹ với thân màu xanh ô-liu, nếp da chỉ vòng quanh màng nhĩ mà không chạy dọc lưng và tiếng kêu trầm vang như tiếng bò rống.","imageURL":"https://bionexus.vn/images/lithobates-catesbeianus.jpg","referenceURL":"https://www.gbif.org/species/2427091"},{"id":229,"nodeId":310,"scientificName":"Lithobates pipiens","commonName":"Ếch Báo Phương Bắc (Northern Leopard Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 14-21°C, Độ ẩm: 65-85%, pH: 6.5-7.6, Môi trường: Đồng cỏ ngập nước (wet meadows), đầm lầy lau sậy và bờ hồ nước ngọt","description":"Loài ếch đồng cỏ thanh thoát của Bắc Mỹ với màu nền xanh lá tươi hoặc nâu đồng điểm các đốm tròn đen viền sáng như da báo và hai đường gờ lưng vàng kem.","imageURL":"https://bionexus.vn/images/lithobates-pipiens.jpg","referenceURL":"https://www.gbif.org/species/2427185"},{"id":230,"nodeId":311,"scientificName":"Rana temporaria","commonName":"Ếch Cỏ Châu Âu (European Common Frog)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 12-20°C, Độ ẩm: 65-85%, pH: 6.5-7.5, Môi trường: Đồng cỏ ẩm, rừng lá rộng, đầm lầy rêu và vườn cây ngoại ô","description":"Loài ếch nâu phổ biến nhất khắp châu Âu tới tận Vòng Bắc Cực, dễ nhận biết nhờ vết mặt nạ màu nâu đen hình tam giác kéo từ sau mắt phủ qua màng nhĩ.","imageURL":"https://bionexus.vn/images/rana-temporaria.jpg","referenceURL":"https://www.gbif.org/species/2426805"},{"id":231,"nodeId":23,"scientificName":"Ambystoma maculatum","commonName":"Kỳ Giông Đốm Vàng (Spotted Salamander)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 14-21°C, Độ ẩm: 70-85%, Môi trường: Rừng lá rộng già và rừng hỗn giao có tầng đất mùn sâu","description":"Loài kỳ giông cạn nổi tiếng của các khu rừng lá rộng miền Đông Bắc Mỹ với tấm lưng đen bóng điểm hai hàng đốm tròn màu vàng chanh hoặc vàng cam tươi từ đầu tới đuôi.","imageURL":"https://bionexus.vn/images/ambystoma-maculatum.jpg","referenceURL":"https://www.gbif.org/species/2431951"},{"id":232,"nodeId":23,"scientificName":"Ambystoma opacum","commonName":"Kỳ Giông Cẩm Thạch (Marbled Salamander)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-22°C, Độ ẩm: 65-80%, Môi trường: Rừng lá rộng ẩm vùng đất thấp và sườn đồi nhiều lá mục","description":"Loài kỳ giông cạn nhỏ gọn của miền Đông Hoa Kỳ với nền da đen bóng điểm những dải băng ngang màu trắng bạc hoặc xám trắng tương phản sắc nét như đá cẩm thạch.","imageURL":"https://bionexus.vn/images/ambystoma-opacum.jpg","referenceURL":"https://www.gbif.org/species/2432006"},{"id":233,"nodeId":312,"scientificName":"Salamandra salamandra","commonName":"Kỳ Giông Lửa Châu Âu (Common Fire Salamander)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 14-20°C, Độ ẩm: 70-85%, Môi trường: Rừng lá rộng cổ thụ (sồi, dẻ gai) ẩm mát có thảm rêu và lá mục dày","description":"Loài kỳ giông biểu tượng của các khu rừng sồi cổ thụ châu Âu với làn da đen bóng như sơn mài nổi bật những mảng đốm hoặc sọc màu vàng tươi và cam lửa.","imageURL":"https://bionexus.vn/images/salamandra-salamandra.jpg","referenceURL":"https://www.gbif.org/species/2431776"},{"id":234,"nodeId":312,"scientificName":"Salamandra atra","commonName":"Kỳ Giông Đen Núi Cao (Alpine Salamander)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-25°C, Độ ẩm: 70-85%, Môi trường: Đồng cỏ núi cao, sườn đá vôi ẩm và rừng thông/vân sam vùng núi","description":"Loài kỳ giông đặc trưng của dãy núi Alps với toàn thân phủ một màu đen tuyền bóng mượt và khả năng sinh con trên cạn hoàn toàn không phụ thuộc vào mặt nước.","imageURL":"https://bionexus.vn/images/salamandra-atra.jpg","referenceURL":"https://www.gbif.org/species/2431781"},{"id":235,"nodeId":313,"scientificName":"Cynops pyrrhogaster","commonName":"Sa Giông Bụng Lửa Nhật Bản (Japanese Fire-bellied Newt)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ nước: 14-22°C, Độ ẩm: 70-85%, pH: 6.5-7.6, Môi trường: Suối chảy chậm, ao rừng, đầm lầy và ruộng lúa truyền thống có nước mát","description":"Loài sa giông nổi tiếng đặc hữu của Nhật Bản với mặt lưng màu nâu đen trầm mặc đối lập hoàn toàn với mặt bụng màu đỏ son điểm đốm đen rực rỡ.","imageURL":"https://bionexus.vn/images/cynops-pyrrhogaster.jpg","referenceURL":"https://www.gbif.org/species/2431862"},{"id":236,"nodeId":314,"scientificName":"Triturus marmoratus","commonName":"Sa Giông Cẩm Thạch (Marbled Newt)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ nước: 14-20°C, Độ ẩm: 70-85%, pH: 6.5-7.8, Môi trường: Rừng lá rộng, rừng thông ẩm và vùng đất thạch nam có ao hồ","description":"Một trong những loài sa giông đẹp nhất châu Âu với toàn bộ mặt lưng phủ hoa văn cẩm thạch xanh lục tươi đan xen màu đen nhung và chiếc mào lưng cao ở con đực.","imageURL":"https://bionexus.vn/images/triturus-marmoratus.jpg","referenceURL":"https://www.gbif.org/species/2431886"},{"id":237,"nodeId":314,"scientificName":"Triturus carnifex","commonName":"Sa Giông Mào Ý (Italian Crested Newt)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ nước: 14-21°C, Độ ẩm: 65-80%, pH: 6.8-7.8, Môi trường: Ao hồ sâu có nhiều thực vật thủy sinh, đầm lầy và bể chứa nước đá truyền thống","description":"Loài sa giông mào lớn của bán đảo Ý và vùng núi Alps phía nam, nổi bật với chiếc mào lưng răng cưa hùng vĩ ở con đực mùa xuân và phần bụng vàng cam đốm đen.","imageURL":"https://bionexus.vn/images/triturus-carnifex.jpg","referenceURL":"https://www.gbif.org/species/2431887"},{"id":238,"nodeId":315,"scientificName":"Ichthyosaura alpestris","commonName":"Sa Giông Núi Cao (Alpine newt)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 12-20°C, Độ ẩm: 70-85%, pH: 6.5-7.6, Môi trường: Ao rừng mát, hồ băng tan trên núi cao và các suối chảy chậm","description":"Loài sa giông tuyệt đẹp của vùng núi châu Âu với mặt lưng xanh lam đá phiến, sườn lốm đốm bạc đen như da báo và chiếc bụng màu cam lửa rực rỡ không một vết đốm.","imageURL":"https://bionexus.vn/images/ichthyosaura-alpestris.jpg","referenceURL":"https://www.gbif.org/species/2431783"},{"id":239,"nodeId":316,"scientificName":"Lissotriton vulgaris","commonName":"Sa Giông Thường Châu Âu (Smooth Newt)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 14-20°C, Độ ẩm: 70-85%, pH: 6.5-7.8, Môi trường: Ao vườn, đầm lầy cỏ, mương nước tĩnh và rừng ẩm","description":"Loài sa giông nhỏ nhắn phổ biến nhất châu Âu với những đường sọc đen chạy qua mắt, chiếc mào lưng lượn sóng mềm mại ở con đực mùa xuân và bụng cam điểm đốm tròn đen.","imageURL":"https://bionexus.vn/images/lissotriton-vulgaris.jpg","referenceURL":"https://www.gbif.org/species/5218405"},{"id":240,"nodeId":316,"scientificName":"Lissotriton helveticus","commonName":"Sa Giông Chân Màng (Palmate Newt)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 14-20°C, Độ ẩm: 70-85%, pH: 6-7.5, Môi trường: Ao rừng, đầm lầy đất chua (heathland ponds) và các vũng nước suối đồi","description":"Loài sa giông nhỏ của miền Tây Âu có thân hình hơi vuông vức, đôi bàn chân sau có màng bơi đen xòe rộng và một sợi tơ mảnh kéo dài ở chóp đuôi con đực mùa sinh sản.","imageURL":"https://bionexus.vn/images/lissotriton-helveticus.jpg","referenceURL":"https://www.gbif.org/species/5218410"},{"id":241,"nodeId":317,"scientificName":"Pleurodeles waltl","commonName":"Sa Giông Sườn Gai Iberia (Sharp-ribbed Salamander)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 15-24°C, pH: 6.8-8, Môi trường: Ao hồ sâu, bể chứa nước truyền thống, đầm lầy và các đoạn suối chảy chậm","description":"Loài sa giông lớn nhất châu Âu bản địa bán đảo Iberia và Maroc, nổi tiếng với cơ chế tự vệ có một không hai: đâm đầu xương sườn nhọn xuyên qua các nốt cam dọc hai bên sườn.","imageURL":"https://bionexus.vn/images/pleurodeles-waltl.jpg","referenceURL":"https://www.gbif.org/species/2431875"},{"id":242,"nodeId":318,"scientificName":"Paramesotriton hongkongensis","commonName":"Cá Cóc Hồng Kông (Hong Kong Warty Newt)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ nước: 15-22°C, pH: 6.5-7.6, Môi trường: Vũng nước tĩnh sâu (stream pools) trong các con suối đá rừng núi sạch mát","description":"Loài cá cóc suối núi vùng duyên hải tỉnh Quảng Đông và Hồng Kông với làn da sần cứng màu nâu hạt dẻ, các gờ xương nổi rõ trên đầu và mặt bụng đốm cam đỏ rực rỡ.","imageURL":"https://bionexus.vn/images/paramesotriton-hongkongensis.jpg","referenceURL":"https://www.gbif.org/species/2431847"},{"id":243,"nodeId":319,"scientificName":"Betta splendens","commonName":"Cá Xiêm Rực Rỡ (Siamese Fighting Fish)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ nước: 24-30°C, pH: 6-7.5, Môi trường: Ruộng lúa nước, đầm lầy cỏ và ao tù nhiều thực vật nổi","description":"Loài cá cảnh nổi tiếng bậc nhất Đông Nam Á với cơ quan mê lộ thở khí trời và hàng chục kiểu hình vây Halfmoon, Plakat rực rỡ.","imageURL":"https://bionexus.vn/images/betta-splendens.jpg","referenceURL":"https://www.gbif.org/species/2393998"},{"id":244,"nodeId":319,"scientificName":"Betta albimarginata","commonName":"Cá Xiêm Viền Trắng","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 23-27°C, pH: 5-6.5, Môi trường: Suối rừng nước đen nhiều lá mục có độ pH thấp dưới tán rừng mưa","description":"Loài cá Betta hoang dã ấp trứng trong miệng kích thước nhỏ của đảo Borneo, nổi bật với viền vây trắng muốt trên nền vây đen đỏ.","imageURL":"https://bionexus.vn/images/betta-albimarginata.jpg","referenceURL":"https://www.gbif.org/species/2394012"},{"id":245,"nodeId":320,"scientificName":"Trichogaster lalius","commonName":"Cá Sặc Gấm (Dwarf gourami)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-28°C, pH: 6-7.5, Môi trường: Ao hồ, kênh mương chảy chậm và ruộng lúa có nhiều cây thủy sinh dày","description":"Loài cá sặc nhỏ nổi tiếng trong bể thủy sinh nhờ sắc đỏ cam đan xen xanh ngọc bích lấp lánh dưới ánh đèn.","imageURL":"https://bionexus.vn/images/trichogaster-lalius.jpg","referenceURL":"https://www.gbif.org/species/5211200"},{"id":246,"nodeId":320,"scientificName":"Trichogaster chuna","commonName":"Cá Sặc Mật Ong (Honey gourami)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-28°C, pH: 6-7.5, Môi trường: Đầm lầy, hồ nước tĩnh và ruộng ngập nước có thảm thực vật dày","description":"Loài cá sặc nhỏ nhắn nhất và hiền hòa nhất trong nhóm cá sặc với sắc vàng cam ấm áp như mật ong rừng.","imageURL":"https://bionexus.vn/images/trichogaster-chuna.jpg","referenceURL":"https://www.gbif.org/species/5211191"},{"id":247,"nodeId":321,"scientificName":"Trichopodus leerii","commonName":"Cá Sặc Trân Châu (Pearl Gourami)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ nước: 24-29°C, pH: 5.5-7.5, Môi trường: Đầm lầy than bùn và suối rừng nước đen có độ pH hơi axit và nhiều cây thủy sinh","description":"Một trong những loài cá có cơ quan mê lộ thanh lịch nhất với hàng trăm chấm trắng ánh bạc như ngọc trai phủ khắp cơ thể.","imageURL":"https://bionexus.vn/images/trichopodus-leerii.jpg","referenceURL":"https://www.gbif.org/species/7623402"},{"id":248,"nodeId":321,"scientificName":"Trichopodus trichopterus","commonName":"Cá Sặc Bướm (Three-spot Gourami)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-29°C, pH: 6-8, Môi trường: Ao hồ, kênh rạch, ruộng lúa và đầm lầy vùng đồng bằng nhiều cỏ nước","description":"Loài cá sặc bản địa quen thuộc của Đông Nam Á với hai chấm đen tròn bên hông cùng con mắt tạo thành tên gọi 'sặc ba chấm'.","imageURL":"https://bionexus.vn/images/trichopodus-trichopterus.jpg","referenceURL":"https://www.gbif.org/species/5211169"},{"id":249,"nodeId":322,"scientificName":"Macropodus opercularis","commonName":"Cá Cờ Sọc (Paradise fish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 16-28°C, pH: 6-8, Môi trường: Ruộng lúa nước, ao làng, mương cỏ và các vũng nước tĩnh vùng đồng bằng và trung du","description":"Loài cá cảnh nhiệt đới đầu tiên được du nhập sang châu Âu từ năm 1869, nổi bật với những vạch sọc ngang đỏ và xanh lam cùng đốm nắp mang viền cam.","imageURL":"https://bionexus.vn/images/macropodus-opercularis.jpg","referenceURL":"https://www.gbif.org/species/5211160"},{"id":250,"nodeId":322,"scientificName":"Macropodus ocellatus","commonName":"Cá Cờ Đuôi Tròn (Round-tailed paradise fish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 10-24°C, pH: 6.5-7.8, Môi trường: Đầm lầy cỏ, ao hồ nông và ruộng lúa vùng khí hậu ôn đới và cận nhiệt đới mát","description":"Họ hàng phương Bắc của cá cờ sọc với chiếc vây đuôi tròn hình quạt duyên dáng và khả năng chịu lạnh ngay dưới lớp băng mỏng mùa đông.","imageURL":"https://bionexus.vn/images/macropodus-ocellatus.jpg","referenceURL":"https://www.gbif.org/species/5211151"},{"id":251,"nodeId":323,"scientificName":"Helostoma temminckii","commonName":"Cá Hôn (Kissing Gourami)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-30°C, pH: 6.5-8, Môi trường: Sông chảy chậm, kênh rạch, hồ lớn và các vùng rừng ngập lũ giàu phù du và tảo bám","description":"Loài cá cảnh độc đáo của Đông Nam Á với đôi môi dày có nhiều hàng răng sừng nhỏ dùng để cạo tảo và hành vi 'chạm môi' nổi tiếng.","imageURL":"https://bionexus.vn/images/helostoma-temminckii.jpg","referenceURL":"https://www.gbif.org/species/2392012"},{"id":252,"nodeId":324,"scientificName":"Osphronemus goramy","commonName":"Cá Tai Tượng (Giant Gourami)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-30°C, pH: 6.5-8, Môi trường: Sông lớn, hồ đầm ngập lũ và kênh rạch có nhiều cây cối rủ bóng","description":"Loài cá lớn nhất thuộc nhóm cá có cơ quan mê lộ, nổi tiếng với sự thông minh, nhận biết được chủ nuôi và tuổi thọ trên hai thập kỷ.","imageURL":"https://bionexus.vn/images/osphronemus-goramy.jpg","referenceURL":"https://www.gbif.org/species/2394154"},{"id":253,"nodeId":325,"scientificName":"Paracheirodon innesi","commonName":"Cá Neon Vua (Neon Tetra)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 21-26°C, pH: 5.5-7, Môi trường: Suối rừng nước đen và nước trong chảy chậm dưới tán rừng mưa râm mát","description":"Biểu tượng bất hủ của nghệ thuật bể thủy sinh toàn cầu với dải sọc xanh ngọc điện quang chạy từ mũi tới vây mỡ kết hợp vệt đỏ tươi ở nửa thân sau.","imageURL":"https://bionexus.vn/images/paracheirodon-innesi.jpg","referenceURL":"https://www.gbif.org/species/2353909"},{"id":254,"nodeId":325,"scientificName":"Paracheirodon axelrodi","commonName":"Cá Neon Đỏ (Cardinal Tetra)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-28°C, pH: 5-6.8, Môi trường: Suối rừng ngập lũ nước đen có độ pH axit nhẹ và giàu tannin từ lá cây mục","description":"Nữ hoàng của các bể thủy sinh rừng mưa với dải màu đỏ thẫm kéo dài suốt toàn bộ phần dưới cơ thể từ dưới mắt tới tận gốc đuôi.","imageURL":"https://bionexus.vn/images/paracheirodon-axelrodi.jpg","referenceURL":"https://www.gbif.org/species/2353911"},{"id":255,"nodeId":325,"scientificName":"Paracheirodon simulans","commonName":"Cá Neon Xanh (Green Cardinal)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-28°C, pH: 5-6.8, Môi trường: Suối rừng nước đen trong vắt có nền cát trắng và lá mục dưới tán rừng","description":"Loài nhỏ nhất trong chi Paracheirodon với dải sọc xanh lam ngọc bích chiếm trọn chiều dài cơ thể và chỉ điểm một vệt đỏ rất mờ ở gốc đuôi.","imageURL":"https://bionexus.vn/images/paracheirodon-simulans.jpg","referenceURL":"https://www.gbif.org/species/2353914"},{"id":256,"nodeId":326,"scientificName":"Hemigrammus bleheri","commonName":"Cá Mũi Đỏ Bleher (Petitella bleheri)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-28°C, pH: 5.5-7, Môi trường: Suối rừng nước đen có dòng chảy êm và nhiều lũa cây ngập nước","description":"Loài cá bơi đàn đẹp nhất nhì thế giới thủy sinh với chiếc đầu đỏ tươi như ngọn đèn và vây đuôi kẻ ba vạch đen-trắng sắc sảo.","imageURL":"https://bionexus.vn/images/hemigrammus-bleheri.jpg","referenceURL":"https://www.gbif.org/species/2354371"},{"id":257,"nodeId":327,"scientificName":"Hyphessobrycon herbertaxelrodi","commonName":"Cá Neon Đen (Black neon tetra)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-27°C, pH: 6-7.5, Môi trường: Sông suối nước trong chảy chậm có nhiều thảm cây thủy sinh","description":"Loài cá Tetra khỏe khoắn và lịch lãm với hai dải sọc chạy song song dọc cơ thể: một sọc trắng xanh phát sáng ở trên và một sọc đen nhung rộng ở dưới.","imageURL":"https://bionexus.vn/images/hyphessobrycon-herbertaxelrodi.jpg","referenceURL":"https://www.gbif.org/species/2354640"},{"id":258,"nodeId":327,"scientificName":"Hyphessobrycon erythrostigma","commonName":"Cá Trái Tim Đỏ (Bleeding-heart tetra)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-28°C, pH: 5.8-7.2, Môi trường: Suối rừng nhỏ khuất bóng cây có nhiều cành khô và lá rụng dưới đáy","description":"Loài cá Tetra thân thoi cao nổi bật với một đốm tròn màu đỏ ruby ngay giữa sườn trông hệt như một trái tim đỏ trên nền thân hồng bạc.","imageURL":"https://bionexus.vn/images/hyphessobrycon-erythrostigma.jpg","referenceURL":"https://www.gbif.org/species/2354681"},{"id":259,"nodeId":327,"scientificName":"Hyphessobrycon flammeus","commonName":"Cá Hồng Mi Rio (Flame tetra)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 21-26°C, pH: 6-7.5, Môi trường: Suối nhỏ chảy chậm có đáy cát và nhiều cây cỏ thủy sinh ven bờ","description":"Loài cá Tetra cổ điển với nửa trước thân ánh bạc điểm hai vạch đen ở vai và nửa sau thân cùng các vây chuyển dần sang màu đỏ rực như ngọn lửa.","imageURL":"https://bionexus.vn/images/hyphessobrycon-flammeus.jpg","referenceURL":"https://www.gbif.org/species/2354538"},{"id":260,"nodeId":327,"scientificName":"Hyphessobrycon megalopterus","commonName":"Cá Bóng Ma Đen (Black phantom tetra)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-27°C, pH: 6-7.5, Môi trường: Vùng nước tĩnh trong vắt có nhiều thực vật nổi và rễ cây thủy sinh","description":"Loài cá Tetra mang vẻ đẹp huyền bí với thân màu xám bạc trong mờ, đốm đen viền bạc sau nắp mang và bộ vây lưng đen xòe cao như cánh buồm.","imageURL":"https://bionexus.vn/images/hyphessobrycon-megalopterus.jpg","referenceURL":"https://www.gbif.org/species/2354646"},{"id":261,"nodeId":327,"scientificName":"Hyphessobrycon amandae","commonName":"Cá Neon Lửa (Ember tetra)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-28°C, pH: 5.5-7, Môi trường: Suối nhỏ chảy êm có nền cát và nhiều lá cây mục rợp bóng","description":"Loài cá Tetra tí hon chỉ dài khoảng 2 cm với toàn thân màu cam đỏ trong suốt như hổ phách phát sáng giữa những tán rêu xanh.","imageURL":"https://bionexus.vn/images/hyphessobrycon-amandae.jpg","referenceURL":"https://www.gbif.org/species/2354525"},{"id":262,"nodeId":328,"scientificName":"Gymnocorymbus ternetzi","commonName":"Cá Cánh Buồm Đen (Black Tetra)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 20-27°C, pH: 6-7.8, Môi trường: Các nhánh sông chảy chậm và đầm lầy vùng cận nhiệt đới Nam Mỹ","description":"Loài cá Tetra khỏe mạnh quen thuộc với thân hình thoi dẹt cao, hai vạch đen sẫm sau nắp mang và chiếc vây hậu môn xòe rộng như tà váy đen.","imageURL":"https://bionexus.vn/images/gymnocorymbus-ternetzi.jpg","referenceURL":"https://www.gbif.org/species/2353920"},{"id":263,"nodeId":329,"scientificName":"Inpaichthys kerri","commonName":"Cá Hoàng Đế Xanh (Blue Emperor Tetra)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-27°C, pH: 5.5-7, Môi trường: Suối rừng nhỏ nước trong hơi chua chảy dưới tán rừng mưa Amazon","description":"Loài cá Tetra thanh tú của rừng mưa Brazil với ánh sắc xanh tím hoàng gia óng ánh dọc thân khi bơi dưới ánh đèn thủy sinh.","imageURL":"https://bionexus.vn/images/inpaichthys-kerri.jpg","referenceURL":"https://www.gbif.org/species/2354732"},{"id":264,"nodeId":330,"scientificName":"Moenkhausia pittieri","commonName":"Cá Tetra Kim Cương (Diamond Tetra)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 23-28°C, pH: 6-7.5, Môi trường: Các dòng suối chảy chậm nhiều cỏ nước và bóng râm quanh lưu vực hồ Valencia","description":"Loài cá Tetra lấp lánh nhất Nam Mỹ với hàng trăm chiếc vảy bạc ánh vàng kim phản chiếu ánh sáng như những viên kim cương vụn.","imageURL":"https://bionexus.vn/images/moenkhausia-pittieri.jpg","referenceURL":"https://www.gbif.org/species/2352623"},{"id":265,"nodeId":331,"scientificName":"Trigonostigma heteromorpha","commonName":"Cá Tam Giác (Harlequin Rasbora)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-28°C, pH: 5.5-7.2, Môi trường: Suối rừng đầm lầy than bùn có nước mềm hơi axit và nhiều cây Cryptocoryne","description":"Loài cá bơi đàn kinh điển của Đông Nam Á với thân màu hồng đồng ấm áp và một mảng hình tam giác màu đen xanh sắc nét ở nửa thân sau.","imageURL":"https://bionexus.vn/images/trigonostigma-heteromorpha.jpg","referenceURL":"https://www.gbif.org/species/2367610"},{"id":266,"nodeId":331,"scientificName":"Trigonostigma espei","commonName":"Cá Tam Giác Ánh Đồng (Lambchop rasbora)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-28°C, pH: 5.5-7, Môi trường: Suối rừng nước trong và đầm lầy cỏ có nhiều thực vật thủy sinh","description":"Họ hàng nhỏ nhắn và rực rỡ hơn của cá tam giác thường với thân màu cam đỏ rực sáng và vệt đen mảnh hình chiếc đùi cừu bên hông.","imageURL":"https://bionexus.vn/images/trigonostigma-espei.jpg","referenceURL":"https://www.gbif.org/species/2367616"},{"id":267,"nodeId":332,"scientificName":"Puntigrus tetrazona","commonName":"Cá Tứ Vân (Tiger barb)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-27°C, pH: 6-7.8, Môi trường: Suối rừng nước trong chảy vừa có đáy cát sỏi và lá mục","description":"Loài cá họ Chép năng động với thân hình thoi cao màu vàng bạc cắt ngang bởi bốn dải sọc đen đậm như vằn hổ và viền vây đỏ tươi.","imageURL":"https://bionexus.vn/images/puntigrus-tetrazona.jpg","referenceURL":"https://www.gbif.org/species/8214163"},{"id":268,"nodeId":333,"scientificName":"Pethia conchonius","commonName":"Cá Đuôi Đỏ Ánh Hồng (Rosy Barb)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 17-26°C, pH: 6.5-7.8, Môi trường: Sông suối chảy nhanh, hồ nước mát và kênh mương vùng cận nhiệt đới","description":"Loài cá đòng đong khỏe khoắn có khả năng chịu mát tuyệt vời, nổi bật với sắc hồng đồng rực rỡ và đốm tròn đen viền vàng gần gốc đuôi.","imageURL":"https://bionexus.vn/images/pethia-conchonius.jpg","referenceURL":"https://www.gbif.org/species/7572096"},{"id":269,"nodeId":334,"scientificName":"Sahyadria denisonii","commonName":"Cá Hồng Mi Ấn Độ (Denison barb)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 18-26°C, pH: 6.5-7.8, Môi trường: Suối đá vùng đồi núi có nước chảy xiết, trong mát và giàu oxy hòa tan","description":"Ngôi sao của những bể thủy sinh kích thước lớn với thân hình thoi dài như ngư lôi, sọc đen chạy dọc thân viền vệt đỏ tươi ở đầu và vây đuôi điểm vàng đen.","imageURL":"https://bionexus.vn/images/sahyadria-denisonii.jpg","referenceURL":"https://www.gbif.org/species/8395052"},{"id":270,"nodeId":335,"scientificName":"Epalzeorhynchos bicolor","commonName":"Cá Chuột Đuôi Đỏ (Redtail Sharkminnow)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ nước: 22-27°C, pH: 6.5-7.8, Môi trường: Đáy sông suối có nhiều hốc đá, khúc gỗ chìm và dòng chảy vừa phải","description":"Loài cá tầng đáy nổi tiếng với toàn thân phủ màu đen nhung sâu thẳm tương phản tuyệt đối với chiếc vây đuôi màu đỏ cam rực lửa.","imageURL":"https://bionexus.vn/images/epalzeorhynchos-bicolor.jpg","referenceURL":"https://www.gbif.org/species/2360397"},{"id":271,"nodeId":336,"scientificName":"Crossocheilus oblongus","commonName":"Cá Bút Chì Dọn Rêu (Siamese Algae-eater)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-27°C, pH: 6.2-7.6, Môi trường: Suối đá chảy nhanh có nước trong giàu oxy và nhiều đá cuội phủ tảo","description":"Chiến binh diệt rêu hại số một trong bể thủy sinh, dễ nhận biết nhờ dải sọc đen hình răng cưa chạy từ mũi tới hết tia giữa của vây đuôi trong suốt.","imageURL":"https://bionexus.vn/images/crossocheilus-oblongus.jpg","referenceURL":"https://www.gbif.org/species/2361970"},{"id":272,"nodeId":337,"scientificName":"Carassius auratus","commonName":"Cá Vàng (Goldfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 15-24°C, pH: 6.8-8, Môi trường: Ao hồ nước ngọt tĩnh, sông chảy chậm và các bể cảnh nước mát","description":"Loài cá cảnh có lịch sử thuần hóa lâu đời nhất nhân loại với màu vàng cam rực rỡ và hàng chục kiểu hình nghệ thuật như Oranda, Ryukin, Ranchu.","imageURL":"https://bionexus.vn/images/carassius-auratus.jpg","referenceURL":"https://www.gbif.org/species/4286942"},{"id":273,"nodeId":338,"scientificName":"Cyprinus rubrofuscus","commonName":"Cá Chép Koi","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 15-28°C, pH: 6.8-8.2, Môi trường: Sông lớn, hồ đầm nước ngọt và các hồ cảnh quan ngoài trời","description":"Biểu tượng của sự kiên trì và thịnh vượng trong văn hóa Á Đông với những mảng màu đỏ, trắng, đen (Kohaku, Sanke, Showa) nổi bật khi nhìn từ trên xuống.","imageURL":"https://bionexus.vn/images/cyprinus-rubrofuscus.jpg","referenceURL":"https://www.gbif.org/species/2367196"},{"id":274,"nodeId":339,"scientificName":"Chromobotia macracanthus","commonName":"Cá Chạch Hề (Clown loach)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-30°C, pH: 6-7.5, Môi trường: Sông lớn và vùng đồng bằng ngập lũ theo mùa có đáy bùn cát và nhiều lũa","description":"Loài cá chạch cảnh nổi tiếng nhất thế giới với thân màu cam vàng rực rỡ cắt ngang bởi ba dải đai đen tuyền và cặp vây bụng đỏ tươi.","imageURL":"https://bionexus.vn/images/chromobotia-macracanthus.jpg","referenceURL":"https://www.gbif.org/species/2367815"},{"id":275,"nodeId":340,"scientificName":"Botia striata","commonName":"Cá Chạch Ngựa Vằn (Zebra Loach)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 21-26°C, pH: 6-7.5, Môi trường: Suối đá chảy mát trong rừng có đáy sỏi cuội và lá mục","description":"Loài cá chạch cỡ nhỏ hiền hòa của Ấn Độ với hàng chục đường vạch sọc chéo vàng-đen mịn màng chạy sát nhau dọc khắp cơ thể.","imageURL":"https://bionexus.vn/images/botia-striata.jpg","referenceURL":"https://www.gbif.org/species/2368019"},{"id":276,"nodeId":341,"scientificName":"Pangio kuhlii","commonName":"Cá Chạch Rắn Kuhli (Kuhli loach)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-29°C, pH: 5.5-7.2, Môi trường: Suối rừng chảy chậm có đáy cát mịn phủ dày lá cây mục rợp bóng","description":"Loài cá chạch có dáng thuôn dài như lươn nhỏ với 10–15 khoang vằn màu nâu đen xen kẽ màu hồng cam dọc thân và bốn đôi râu nhỏ quanh miệng.","imageURL":"https://bionexus.vn/images/pangio-kuhlii.jpg","referenceURL":"https://www.gbif.org/species/2367984"},{"id":277,"nodeId":342,"scientificName":"Poecilia reticulata","commonName":"Cá Bảy Màu (Guppy)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-28°C, pH: 6.8-8.2, Môi trường: Suối nhỏ ven bờ, mương nước ngọt và nước lợ nhẹ có nhiều thực vật","description":"Loài cá cảnh đẻ con phổ biến nhất hành tinh với sức sống dẻo dai và hàng trăm dòng màu di truyền lộng lẫy như Full Gold, Dumbo, Koi, Rồng.","imageURL":"https://bionexus.vn/images/poecilia-reticulata.jpg","referenceURL":"https://www.gbif.org/species/2350050"},{"id":278,"nodeId":342,"scientificName":"Poecilia sphenops","commonName":"Cá Hắc Molly (Molly)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-28°C, pH: 7-8.2, Môi trường: Suối nước ngọt giàu khoáng, cửa sông nước lợ và đầm phá ven biển","description":"Loài cá đẻ con hiền lành và chăm chỉ ăn rêu tảo với các dòng màu đen nhung (Black Molly), vàng cam (Gold Dust) và cẩm thạch.","imageURL":"https://bionexus.vn/images/poecilia-sphenops.jpg","referenceURL":"https://www.gbif.org/species/5203748"},{"id":279,"nodeId":342,"scientificName":"Poecilia latipinna","commonName":"Cá Molly Cánh Buồm (Sailfin Molly)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 21-28°C, pH: 7.2-8.4, Môi trường: Đầm lầy ven biển, sông nước ngọt giàu canxi và vùng cửa sông nước lợ nhẹ","description":"Loài cá Molly nổi bật của Bắc Mỹ với chiếc vây lưng rộng lớn căng cao như cánh buồm thuyền khi cá đực múa khoe sắc.","imageURL":"https://bionexus.vn/images/poecilia-latipinna.jpg","referenceURL":"https://www.gbif.org/species/5203752"},{"id":280,"nodeId":342,"scientificName":"Poecilia velifera","commonName":"Cá Molly Cánh Buồm Khổng Lồ (Sail-fin Molly)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ nước: 24-29°C, pH: 7.5-8.5, Môi trường: Các hố sụt đá vôi ngập nước (cenotes), đầm phá ven biển và suối nước cứng bán đảo Yucatán","description":"Loài lớn nhất và tráng lệ nhất trong nhóm cá Molly với chiếc vây lưng khổng lồ điểm những hàng chấm ngọc trai sáng lấp lánh.","imageURL":"https://bionexus.vn/images/poecilia-velifera.jpg","referenceURL":"https://www.gbif.org/species/5203757"},{"id":281,"nodeId":343,"scientificName":"Xiphophorus hellerii","commonName":"Cá Kiếm (Green Swordtail)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 20-27°C, pH: 7-8.2, Môi trường: Suối đá chảy nhanh có nhiều thảm cây thủy sinh lẫn đầm nước ấm vùng đất thấp","description":"Loài cá đẻ con kinh điển với phần thùy dưới vây đuôi của cá đực vươn dài như một thanh kiếm hiệp sĩ cùng sắc đỏ cam hoặc xanh ngọc rực rỡ.","imageURL":"https://bionexus.vn/images/xiphophorus-hellerii.jpg","referenceURL":"https://www.gbif.org/species/8246728"},{"id":282,"nodeId":343,"scientificName":"Xiphophorus variatus","commonName":"Cá Bình Tích Hoa (Variable Platyfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 17-26°C, pH: 7-8.2, Môi trường: Suối chảy chậm, mương nước và đầm lầy có nhiều thực vật thủy sinh vùng cận nhiệt đới","description":"Loài cá mún đa sắc màu của Mexico với khả năng chịu nhiệt độ mát tốt hơn cá mún thường và những biến thể màu Hoàng hôn (Sunset), Tuxedo, Marigold.","imageURL":"https://bionexus.vn/images/xiphophorus-variatus.jpg","referenceURL":"https://www.gbif.org/species/2350220"},{"id":283,"nodeId":342,"scientificName":"Poecilia wingei","commonName":"Cá Bảy Màu Endler (Endler's Livebearer)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 7-8.2, Môi trường: Đầm nước lợ ấm và suối nước ngọt ven biển nhiều tảo lục","description":"Họ hàng gần kích thước siêu nhỏ của cá bảy màu với các mảng màu cam neon, xanh lục bảo và đen ánh kim tương phản mạnh.","imageURL":"https://bionexus.vn/images/poecilia-wingei.jpg","referenceURL":"https://www.gbif.org/species/5203789"},{"id":284,"nodeId":344,"scientificName":"Epiplatys annulatus","commonName":"Cá Killi Chú Hề (Banded Panchax)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-27°C, pH: 6-7.2, Môi trường: Suối nước ngọt chảy chậm, đầm lầy cỏ và rãnh nước nông nhiều thực vật nổi","description":"Loài cá Killi mặt nước siêu nhỏ của Tây Phi với bốn khoanh sọc đen-vàng kem xen kẽ trên thân và chiếc đuôi rực rỡ như đuôi tên lửa.","imageURL":"https://bionexus.vn/images/epiplatys-annulatus.jpg","referenceURL":"https://www.gbif.org/species/2348780"},{"id":285,"nodeId":345,"scientificName":"Oryzias latipes","commonName":"Cá Medaka Nhật Bản (Japanese rice fish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 16-28°C, pH: 6.5-8, Môi trường: Ruộng lúa nước, ao hồ tĩnh, kênh mương nông nhiều rong bèo","description":"Loài cá ruộng lúa truyền thống của Nhật Bản có sức chịu đựng biên độ nhiệt đáng kinh ngạc và nhiều dòng màu Miyuki, Youkihi lấp lánh khi nhìn từ trên xuống.","imageURL":"https://bionexus.vn/images/oryzias-latipes.jpg","referenceURL":"https://www.gbif.org/species/2368377"},{"id":286,"nodeId":346,"scientificName":"Pterophyllum scalare","commonName":"Cá Ông Tiên (Angelfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-30°C, pH: 6-7.4, Môi trường: Vùng nước ngập tĩnh, nhánh sông nhiều rễ cây ngập nước và lau sậy thẳng đứng","description":"Biểu tượng thanh lịch của bể thủy sinh Nam Mỹ với thân tròn dẹt bên, vây lưng và vây bụng vươn cao như cánh buồm tam giác kèm bốn sọc đen dọc.","imageURL":"https://bionexus.vn/images/pterophyllum-scalare.jpg","referenceURL":"https://www.gbif.org/species/5208518"},{"id":287,"nodeId":346,"scientificName":"Pterophyllum altum","commonName":"Cá Ông Tiên Altum","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 26-30°C, pH: 4.8-6.5, Môi trường: Các dòng sông nước đen sâu, trong vắt, rất mềm và có độ pH axit thấp","description":"Loài cá ông tiên lớn nhất và uy nghi nhất với chiều cao sải vây có thể vượt 35 cm, vết lõm sâu đặc trưng trên sống mũi và các sọc nâu đồng sắc nét.","imageURL":"https://bionexus.vn/images/pterophyllum-altum.jpg","referenceURL":"https://www.gbif.org/species/5208522"},{"id":288,"nodeId":347,"scientificName":"Symphysodon aequifasciatus","commonName":"Cá Đĩa Xanh","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 28-31°C, pH: 5.5-6.8, Môi trường: Vùng nước tĩnh ven bờ sông nhánh Amazon nhiều cành lũa đổ và rễ cây chằng chịt","description":"Nữ hoàng của các loài cá cảnh nước ngọt với thân tròn dẹt như chiếc đĩa và 9 vạch sọc dọc đồng đều điểm những đường vân xanh ngọc lam óng ánh.","imageURL":"https://bionexus.vn/images/symphysodon-aequifasciatus.jpg","referenceURL":"https://www.gbif.org/species/5208133"},{"id":289,"nodeId":347,"scientificName":"Symphysodon discus","commonName":"Cá Đĩa Heckel","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 28-31°C, pH: 4.5-6.2, Môi trường: Vùng nước đen cực mềm và có tính axit mạnh (pH 4.2–5.5) giữa rừng ngập lũ Igapó","description":"Loài cá đĩa đầu tiên được khoa học mô tả, dễ dàng nhận diện nhờ sọc đen thứ năm ở chính giữa thân đậm và to bản vượt trội hơn hẳn tám sọc còn lại.","imageURL":"https://bionexus.vn/images/symphysodon-discus.jpg","referenceURL":"https://www.gbif.org/species/5208131"},{"id":290,"nodeId":348,"scientificName":"Mikrogeophagus ramirezi","commonName":"Cá Phượng Hoàng Lam (Ram cichlid)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 26-30°C, pH: 5.5-7, Môi trường: Đầm nước ấm trong vắt, suối cát mịn có các cụm cỏ thủy sinh rải rác","description":"Loài cá rô lùn Nam Mỹ được yêu thích nhất với sắc lam ngọc lấp lánh, trán vàng cam, mắt đỏ gạch có sọc đen chạy dọc qua.","imageURL":"https://bionexus.vn/images/mikrogeophagus-ramirezi.jpg","referenceURL":"https://www.gbif.org/species/2373104"},{"id":291,"nodeId":349,"scientificName":"Apistogramma cacatuoides","commonName":"Cá Rô Lùn Mào Gà (Cockatoo cichlid)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 6-7.5, Môi trường: Vùng nước nông chảy chậm dưới tán rừng mưa với đáy phủ dày lá mục","description":"Loài cá rô lùn Apistogramma khỏe và dễ nuôi nhất, nổi bật với vây lưng dựng đứng như chiếc mào của loài vẹt mào Cockatoo và họa tiết ngọn lửa trên đuôi.","imageURL":"https://bionexus.vn/images/apistogramma-cacatuoides.jpg","referenceURL":"https://www.gbif.org/species/2371275"},{"id":292,"nodeId":349,"scientificName":"Apistogramma agassizii","commonName":"Cá Rô Lùn Agassiz (Agassiz's Dwarf Cichlid)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 5.5-7, Môi trường: Suối rừng nước đen và nước trong có đáy phủ dày lá rụng và cành cây mục","description":"Loài cá rô lùn kinh điển mang tên nhà tự nhiên học Louis Agassiz, nổi bật với chiếc vây đuôi nhọn hình ngọn giáo (spade-tail) và ánh vảy xanh ngọc dọc thân.","imageURL":"https://bionexus.vn/images/apistogramma-agassizii.jpg","referenceURL":"https://www.gbif.org/species/2371326"},{"id":293,"nodeId":350,"scientificName":"Cleithracara maronii","commonName":"Cá Rô Lỗ Khóa (Keyhole cichlid)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-27°C, pH: 6-7.2, Môi trường: Suối nước nâu chảy chậm giàu tannin có nhiều gỗ lũa và tảng đá phẳng","description":"Loài cá rô phi Nam Mỹ vô cùng hiền lành và nhút nhát, mang vệt đen đặc trưng bên sườn giống hệt hình một lỗ khóa cổ điển.","imageURL":"https://bionexus.vn/images/cleithracara-maronii.jpg","referenceURL":"https://www.gbif.org/species/2373115"},{"id":294,"nodeId":351,"scientificName":"Astronotus ocellatus","commonName":"Cá Tai Tượng Châu Phi (Oscar) (Oscar)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 6-7.5, Môi trường: Kênh sông nước chảy chậm, hồ móng ngựa và rừng ngập nước nhiều thân cây đổ","description":"Loài cá Cichlid cỡ lớn thông minh nổi tiếng với đốm tròn đen viền cam đỏ ở gốc đuôi giống con mắt giả và tính cách quấn chủ như thú cưng.","imageURL":"https://bionexus.vn/images/astronotus-ocellatus.jpg","referenceURL":"https://www.gbif.org/species/2370243"},{"id":295,"nodeId":352,"scientificName":"Heros efasciatus","commonName":"Cá Hồng Két Dĩa (Severum)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 6-7.5, Môi trường: Vùng nước tĩnh ven sông nhiều cành cây ngập và thảm thực vật ven bờ","description":"Loài Cichlid thân tròn dẹt duyên dáng thường được ví là 'Cá Đĩa của người mới chơi' nhờ dáng bơi khoan thai và sức sống bền bỉ hơn cá đĩa rất nhiều.","imageURL":"https://bionexus.vn/images/heros-efasciatus.jpg","referenceURL":"https://www.gbif.org/species/5208365"},{"id":296,"nodeId":353,"scientificName":"Andinoacara pulcher","commonName":"Cá Acara Xanh (Blue Acara)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-28°C, pH: 6.5-7.8, Môi trường: Suối nước trong và sông đục chảy chậm có đáy sỏi cát và đá cuội","description":"Loài cá rô phi Nam Mỹ cỡ trung nổi bật với các hàng vảy ánh xanh ngọc lục bảo lấp lánh trên thân và tính cách ôn hòa dễ nuôi ghép.","imageURL":"https://bionexus.vn/images/andinoacara-pulcher.jpg","referenceURL":"https://www.gbif.org/species/7525430"},{"id":297,"nodeId":354,"scientificName":"Rocio octofasciata","commonName":"Cá Rô Mỹ Jack Dempsey (Jack Dempsey)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-28°C, pH: 6.5-7.8, Môi trường: Đầm lầy, kênh rạch nước ấm chảy chậm có đáy bùn cát và nhiều gốc cây","description":"Loài Cichlid Trung Mỹ mạnh mẽ được đặt theo tên nhà vô địch quyền Anh hạng nặng thế giới năm 1920 nhờ tính cách gan dạ và bộ vảy đốm ngọc lam lấp lánh.","imageURL":"https://bionexus.vn/images/rocio-octofasciata.jpg","referenceURL":"https://www.gbif.org/species/2369703"},{"id":298,"nodeId":355,"scientificName":"Pelvicachromis pulcher","commonName":"Cá Rô Lùn Bụng Đỏ Kribensis (Bone Back)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-27°C, pH: 6-7.5, Môi trường: Suối rừng chảy chậm có nhiều hang hốc dưới rễ cây và lá mục","description":"Đại diện nổi tiếng nhất của nhóm cá rô lùn Tây Phi với chiếc bụng màu tím hồng mận chín tuyệt đẹp và tập tính làm tổ trong hang.","imageURL":"https://bionexus.vn/images/pelvicachromis-pulcher.jpg","referenceURL":"https://www.gbif.org/species/2372929"},{"id":299,"nodeId":356,"scientificName":"Cyphotilapia frontosa","commonName":"Cá Đầu Bò Frontosa (Humphead Cichlid)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ nước: 24-27°C, pH: 7.8-9, Môi trường: Vùng vách đá ngầm sâu từ 20 đến 50 mét dưới lòng hồ Tanganyika","description":"Biểu tượng quyền lực của hồ Tanganyika với chiếc bướu trán cao uy nghi, các vây bụng kéo dài thướt tha ánh xanh lam và 6–7 sọc đen đậm trên nền trắng bạc.","imageURL":"https://bionexus.vn/images/cyphotilapia-frontosa.jpg","referenceURL":"https://www.gbif.org/species/2373233"},{"id":300,"nodeId":357,"scientificName":"Julidochromis marlieri","commonName":"Cá Hoàng Đế Kẻ Ô Marlier (Chequered Julie)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-27°C, pH: 7.8-8.8, Môi trường: Các khe đá ngầm và bãi đá cuội ven bờ hồ Tanganyika ở độ sâu 2–15 mét","description":"Loài cá Cichlid thân thuôn dài của hồ Tanganyika với họa tiết kẻ ô bàn cờ đen-vàng kem chạy dọc thân và đường viền xanh lam điện quang nơi rìa vây.","imageURL":"https://bionexus.vn/images/julidochromis-marlieri.jpg","referenceURL":"https://www.gbif.org/species/2372484"},{"id":301,"nodeId":358,"scientificName":"Corydoras panda","commonName":"Cá Chuột Panda (panda)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ nước: 20-25°C, pH: 6-7.4, Môi trường: Các con suối cát trong mát chảy từ sườn Đông dãy Andes giàu oxy hòa tan","description":"Loài cá chuột tầng đáy đáng yêu bậc nhất với màu thân trắng hồng kem điểm vệt đen quanh mắt, vây lưng đen và đốm đen gốc đuôi giống hệt gấu trúc Panda.","imageURL":"https://bionexus.vn/images/corydoras-panda.jpg","referenceURL":"https://www.gbif.org/species/2342738"},{"id":302,"nodeId":358,"scientificName":"Corydoras aeneus","commonName":"Cá Chuột Đồng (Bronze corydoras)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 21-27°C, pH: 6-7.8, Môi trường: Suối cạn đáy cát bùn chảy chậm, vùng ngập lũ có nhiều lá mục","description":"Loài cá dọn đáy hiền lành và phổ biến nhất thế giới với lớp tấm xương giáp hai bên sườn ánh màu đồng cổ và ánh xanh lục kim loại.","imageURL":"https://bionexus.vn/images/corydoras-aeneus.jpg","referenceURL":"https://www.gbif.org/species/2342606"},{"id":303,"nodeId":358,"scientificName":"Corydoras paleatus","commonName":"Cá Chuột Tiêu (Blue Leopard Corydoras)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 18-25°C, pH: 6.2-7.8, Môi trường: Các dòng sông và suối nước mát vùng cận nhiệt đới có đáy cát sỏi mịn","description":"Loài cá chuột vùng cận nhiệt đới Nam Mỹ nổi bật với hoa văn đốm đen muối tiêu điểm ánh xanh ngọc bích trên hai bên nắp mang và thân.","imageURL":"https://bionexus.vn/images/corydoras-paleatus.jpg","referenceURL":"https://www.gbif.org/species/2342720"},{"id":304,"nodeId":358,"scientificName":"Corydoras pygmaeus","commonName":"Cá Chuột Lùn Pygmy (Pygmy Catfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-26°C, pH: 6-7.4, Môi trường: Các nhánh suối nhỏ nước chảy nhẹ có nền cát mịn và thảm cỏ thủy sinh rậm","description":"Một trong những loài cá da trơn nhỏ nhất thế giới, nổi bật với thân màu bạc ánh kim và một đường sọc đen chạy dọc từ mõm tới chấm gốc đuôi.","imageURL":"https://bionexus.vn/images/corydoras-pygmaeus.jpg","referenceURL":"https://www.gbif.org/species/2342634"},{"id":305,"nodeId":358,"scientificName":"Corydoras trilineatus","commonName":"Cá Chuột Ba Sọc (Threestripe corydoras)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-26°C, pH: 6-7.5, Môi trường: Suối rừng nông đáy cát bùn có nhiều cành khô và lá mục","description":"Loài cá chuột hoa văn da báo tuyệt đẹp với mạng lưới đường vân đen ngoằn ngoèo trên đầu, vệt đen chóp vây lưng và ba đường sọc chạy dọc giữa sườn.","imageURL":"https://bionexus.vn/images/corydoras-trilineatus.jpg","referenceURL":"https://www.gbif.org/species/2342746"},{"id":306,"nodeId":359,"scientificName":"Pterygoplichthys gibbiceps","commonName":"Cá Tỳ Bà Da Báo Cánh Buồm","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-28°C, pH: 6.2-7.6, Môi trường: Các dòng sông lớn, vùng rừng ngập lũ và đầm phá giàu gỗ lũa mục","description":"Loài cá tỳ bà cỡ lớn ấn tượng với chiếc vây lưng khổng lồ gồm 12–13 tia giương cao như cánh buồm và họa tiết đốm da báo nâu sẫm viền vàng lưới toàn thân.","imageURL":"https://bionexus.vn/images/pterygoplichthys-gibbiceps.jpg","referenceURL":"https://www.gbif.org/species/2339957"},{"id":307,"nodeId":360,"scientificName":"Kryptopterus vitreolus","commonName":"Cá Nheo Thủy Tinh","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-27°C, pH: 6-7.2, Môi trường: Suối rừng có dòng chảy vừa phải, nước hơi nâu nhẹ và nhiều cây rủ bóng","description":"Loài cá da trơn kỳ thú với toàn bộ khối cơ thân trong suốt như pha lê, để lộ rõ cột sống và tạo hiệu ứng tán sắc cầu vồng khi ánh sáng chiếu xiên.","imageURL":"https://bionexus.vn/images/kryptopterus-vitreolus.jpg","referenceURL":"https://www.gbif.org/species/7916021"},{"id":308,"nodeId":361,"scientificName":"Synodontis petricola","commonName":"Cá Trê Đá Hồ Tanganyika (Cuckoo Catfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-27°C, pH: 7.5-8.8, Môi trường: Các vách đá ngầm và hang hốc đá vôi ven bờ hồ Tanganyika tới độ sâu 30 mét","description":"Loài cá trê nhỏ năng động của hồ Tanganyika với họa tiết đốm báo đen tròn trên nền da vàng nâu và toàn bộ các tia vây đầu tiên đều viền trắng tuyết sắc nét.","imageURL":"https://bionexus.vn/images/synodontis-petricola.jpg","referenceURL":"https://www.gbif.org/species/2344304"},{"id":309,"nodeId":362,"scientificName":"Melanotaenia boesemani","commonName":"Cá Cầu Vồng Boeseman (Boeseman's Rainbowfish)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 7-8.2, Môi trường: Các hồ nước ngọt nông trong vắt nằm trên nền đá vôi nhiều thảm thực vật thủy sinh","description":"Kiệt tác màu sắc của đảo New Guinea với nửa thân trước màu xanh lam tím óng ánh và nửa thân sau rực lên màu cam nghệ tươi như hai loài cá ghép làm một.","imageURL":"https://bionexus.vn/images/melanotaenia-boesemani.jpg","referenceURL":"https://www.gbif.org/species/2411651"},{"id":310,"nodeId":363,"scientificName":"Glossolepis incisus","commonName":"Cá Cầu Vồng Đỏ Cá Hồi (Red Rainbowfish)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 23-27°C, pH: 7-8, Môi trường: Vùng ven bờ nhiều thảm rong thủy sinh của hồ nước ngọt nhiệt đới Sentani","description":"Loài cá cầu vồng lớn nổi bật với màu đỏ cá hồi rực cháy toàn thân ở con đực trưởng thành điểm những chiếc vảy lấp lánh ánh bạc như gương.","imageURL":"https://bionexus.vn/images/glossolepis-incisus.jpg","referenceURL":"https://www.gbif.org/species/5214486"},{"id":311,"nodeId":364,"scientificName":"Carinotetraodon travancoricus","commonName":"Cá Nóc Lùn Ấn Độ (Malabar Pufferfish)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 6.5-7.8, Môi trường: Các dòng sông và hồ nước ngọt ấm có thảm rong thủy sinh dày đặc","description":"Loài cá nóc nhỏ nhất thế giới, chỉ bằng hạt đậu Hà Lan, có đôi mắt to đảo độc lập như tắc kè hoa và dáng bơi lượn bằng vây ngực như trực thăng.","imageURL":"https://bionexus.vn/images/carinotetraodon-travancoricus.jpg","referenceURL":"https://www.gbif.org/species/2407801"},{"id":312,"nodeId":365,"scientificName":"Polypterus senegalus","commonName":"Cá Cửu Sừng Hoàng Đế","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-29°C, pH: 6.5-7.8, Môi trường: Đầm lầy ven sông, vùng ngập nước nông nhiều bùn và thực vật thủy sinh","description":"Hóa thạch sống từ kỷ Phấn Trắng với dãy 8–11 vây lưng nhỏ tách rời như hàng gai lưng khủng long, lớp vảy láng bóng cứng như men sứ và đôi vây ngực có cuống thịt.","imageURL":"https://bionexus.vn/images/polypterus-senegalus.jpg","referenceURL":"https://www.gbif.org/species/4287129"},{"id":313,"nodeId":366,"scientificName":"Erpetoichthys calabaricus","commonName":"Cá Cửu Sừng Dây (Reed)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 6.5-7.5, Môi trường: Đầm lầy cỏ lau nước ngọt và nước lợ nhẹ chảy chậm ven rừng ngập","description":"Họ hàng thân dài mảnh như rắn của cá cửu sừng với màu lưng xanh ô liu, bụng vàng nghệ, đốm đen trên vây ngực và cặp ống khứu giác nhô ra trước mũi.","imageURL":"https://bionexus.vn/images/erpetoichthys-calabaricus.jpg","referenceURL":"https://www.gbif.org/species/2346564"},{"id":314,"nodeId":367,"scientificName":"Apteronotus albifrons","commonName":"Cá Dao Ma Đen (Black ghost knifefish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 6-7.5, Môi trường: Các dòng sông chảy nhanh có đáy cát và suối rừng rậm rạp nhiều khúc cây chìm","description":"Loài cá phát điện yếu màu đen nhung huyền bí với một vệt trắng chạy dọc sống mũi và hai vòng đai trắng quanh đuôi, di chuyển tiến-lùi điêu luyện bằng dải vây bụng gợn sóng.","imageURL":"https://bionexus.vn/images/apteronotus-albifrons.jpg","referenceURL":"https://www.gbif.org/species/2401878"},{"id":315,"nodeId":368,"scientificName":"Gnathonemus petersii","commonName":"Cá Mũi Voi (Elephantnose Fish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 6.5-7.5, Môi trường: Các con sông nước đục chảy chậm có đáy bùn mềm và nhiều cành cây chìm","description":"Loài cá kỳ lạ của châu Phi với phần cằm dưới kéo dài thành chiếc 'vòi' mềm linh hoạt giống vòi voi để sục tìm giun trong bùn kèm hai vệt trắng kem nối giữa vây lưng và vây hậu môn.","imageURL":"https://bionexus.vn/images/gnathonemus-petersii.jpg","referenceURL":"https://www.gbif.org/species/2402409"},{"id":316,"nodeId":369,"scientificName":"Scleropages formosus","commonName":"Cá Rồng Châu Á (Asian arowana)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 26-30°C, pH: 6-7.2, Môi trường: Sông suối rừng nước đen chảy chậm và rừng đầm lầy than bùn ngập nước","description":"Hóa thạch sống quyền quý của Đông Nam Á với những hàng vảy lớn ánh kim rực rỡ như vảy rồng, đôi râu hướng thẳng về phía trước và dáng bơi tuần tra oai vệ sát mặt nước.","imageURL":"https://bionexus.vn/images/scleropages-formosus.jpg","referenceURL":"https://www.gbif.org/species/2402231"},{"id":317,"nodeId":370,"scientificName":"Osteoglossum bicirrhosum","commonName":"Cá Ngân Long (Silver Arawana)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 25-30°C, pH: 6-7.2, Môi trường: Vùng rừng ngập lũ (Várzea và Igapó), hồ đầm thông với sông lớn nhiều cành cây rủ trên mặt nước","description":"Loài cá rồng Nam Mỹ có thân dẹt dài uyển chuyển như dải lụa bạc ánh ngũ sắc, vây lưng và vây hậu môn kéo dài nối sát vây đuôi và khả năng bật nhảy săn mồi ngoạn mục.","imageURL":"https://bionexus.vn/images/osteoglossum-bicirrhosum.jpg","referenceURL":"https://www.gbif.org/species/5212838"},{"id":318,"nodeId":371,"scientificName":"Astyanax mexicanus","commonName":"Cá Mù Hang Động Mexico (Mexican Tetra)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 20-26°C, pH: 6.5-8, Môi trường: Hang động đá vôi ngầm tối tăm hoàn toàn và các dòng suối mặt đất vùng cận nhiệt đới","description":"Loài cá Tetra nổi tiếng thế giới với dạng hình sinh thái sống trong hang đá ngầm có cơ thể trắng hồng ánh bạc và đôi mắt tiêu biến hoàn toàn được phủ kín bằng lớp da.","imageURL":"https://bionexus.vn/images/astyanax-mexicanus.jpg","referenceURL":"https://www.gbif.org/species/5204344"},{"id":319,"nodeId":372,"scientificName":"Serrasalmus rhombeus","commonName":"Cá Piranha Đen Mắt Đỏ (Redeye piranha)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 6-7.2, Môi trường: Các dòng sông lớn, ghềnh thác và nhánh sông sâu của lưu vực Amazon","description":"Loài Piranha lớn nhất hiện còn sống với thân hình thoi sẫm màu ánh khói bạc, đôi mắt đỏ rực như ngọn lửa và bộ hàm sở hữu lực cắn mạnh bậc nhất giới động vật có xương sống.","imageURL":"https://bionexus.vn/images/serrasalmus-rhombeus.jpg","referenceURL":"https://www.gbif.org/species/2354124"},{"id":320,"nodeId":373,"scientificName":"Colossoma macropomum","commonName":"Cá Chim Trắng Lớn Tambaqui (Tambaqui)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ nước: 24-30°C, pH: 5.8-7.5, Môi trường: Các sông lớn và vùng rừng ngập lũ mùa mưa (Várzea) giàu cây ăn quả và hạt","description":"Họ hàng ăn thực vật khổng lồ của cá Piranha với thân hình tròn lớn nửa dưới màu đen sẫm và bộ răng hàm vuông phẳng giống hệt răng hàm con người dùng để nghiền vỡ hạt cao su.","imageURL":"https://bionexus.vn/images/colossoma-macropomum.jpg","referenceURL":"https://www.gbif.org/species/2353152"},{"id":321,"nodeId":374,"scientificName":"Pangasianodon hypophthalmus","commonName":"Cá Tra Sọc (Cá Mập Nước Ngọt Thái) (Striped Catfish)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 24-30°C, pH: 6.5-7.8, Môi trường: Các dòng sông lớn sâu và vùng ngập lũ đồng bằng châu thổ mùa nước nổi","description":"Loài cá da trơn bơi tầng giữa có dáng thuôn khí động học kèm vây lưng cao giống cá mập và các dải sọc ánh bạc chạy dọc sườn rất đẹp khi còn nhỏ.","imageURL":"https://bionexus.vn/images/pangasianodon-hypophthalmus.jpg","referenceURL":"https://www.gbif.org/species/2340714"},{"id":322,"nodeId":375,"scientificName":"Platydoras armatulus","commonName":"Cá Trê Gai Sọc Trắng (Southern Striped Raphael)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-28°C, pH: 6-7.5, Môi trường: Đáy sông suối chảy chậm có nhiều rễ cây chìm, hốc đá và lá mục","description":"Loài cá trê bọc giáp gai nổi bật với màu thân nâu sô-cô-la đậm được chia đôi bởi một đường sọc vàng kem sắc nét chạy suốt từ đầu đến hết chạc đuôi.","imageURL":"https://bionexus.vn/images/platydoras-armatulus.jpg","referenceURL":"https://www.gbif.org/species/2343888"},{"id":323,"nodeId":376,"scientificName":"Brachypelma hamorii","commonName":"Nhện Tarantula Đầu Gối Đỏ Mexico (Mexican redknee)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 23-28°C, Độ ẩm: 55-70%, Môi trường: Rừng rụng lá nhiệt đới khô và trảng cây bụi có nền đất pha cát dễ đào hang","description":"Biểu tượng kinh điển nhất của giới chơi nhện cảnh toàn cầu với thân đen nhung điểm các đốt gối chân màu cam đỏ tươi rực rỡ và tính tình điềm tĩnh.","imageURL":"https://bionexus.vn/images/brachypelma-hamorii.jpg","referenceURL":"https://www.gbif.org/species/2153428"},{"id":324,"nodeId":376,"scientificName":"Brachypelma smithi","commonName":"Nhện Tarantula Đầu Gối Đỏ Guerrero (Mexican Orangeknee)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 23-28°C, Độ ẩm: 55-70%, Môi trường: Sườn đồi rừng khô nhiệt đới có nhiều hốc đá và gốc cây","description":"Loài nhện đầu gối đỏ chị em cực kỳ gần gũi với B. hamorii nhưng sở hữu sắc cam hồng rực sáng hơn trên đầu gối và viền mai ngực màu vàng kem liền mạch.","imageURL":"https://bionexus.vn/images/brachypelma-smithi.jpg","referenceURL":"https://www.gbif.org/species/2153432"},{"id":325,"nodeId":376,"scientificName":"Brachypelma boehmei","commonName":"Nhện Tarantula Chân Lửa Mexico (Mexican fireleg)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 24-29°C, Độ ẩm: 50-65%, Môi trường: Rừng cây bụi khô hạn trên sườn đồi đất sỏi đá","description":"Một trong những loài nhện đất có màu sắc rực rỡ nhất thế giới với toàn bộ mai ngực và ba đốt chân ngoài mang sắc cam đỏ rực cháy tương phản với đốt đùi đen nhánh.","imageURL":"https://bionexus.vn/images/brachypelma-boehmei.jpg","referenceURL":"https://www.gbif.org/species/2153425"},{"id":326,"nodeId":376,"scientificName":"Brachypelma emilia","commonName":"Nhện Tarantula Chân Đỏ Tam Giác Đen (Mexican redleg)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-28°C, Độ ẩm: 55-68%, Môi trường: Rừng khô bán hoang mạc và đồng cỏ cây bụi","description":"Loài nhện Tarantula Mexico dễ nhận diện ngay lập tức nhờ họa tiết hình tam giác đen tuyền nổi bật trên tấm mai ngực màu cam hồng và đôi chân đỏ cam.","imageURL":"https://bionexus.vn/images/brachypelma-emilia.jpg","referenceURL":"https://www.gbif.org/species/2153435"},{"id":327,"nodeId":376,"scientificName":"Brachypelma auratum","commonName":"Nhện Tarantula Đầu Gối Lửa Mexico (Mexican Flameknee)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 22-27°C, Độ ẩm: 55-70%, Môi trường: Rừng rụng lá nhiệt đới trên sườn đồi núi đá tới độ cao 1.000 m","description":"Loài nhện lớn và đậm màu trong chi Brachypelma với lớp lông đen nhung dày và hai đốm đỏ rực như ngọn lửa hẹp sắc nét ngay trên khớp gối.","imageURL":"https://bionexus.vn/images/brachypelma-auratum.jpg","referenceURL":"https://www.gbif.org/species/2153441"},{"id":328,"nodeId":376,"scientificName":"Brachypelma klaasi","commonName":"Nhện Tarantula Hồng Mexico (Mexican pink beauty)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 23-28°C, Độ ẩm: 60-72%, Môi trường: Rừng rụng lá nhiệt đới ven biển có mùa khô rõ rệt","description":"Loài nhện ред và thanh lịch nhất chi Brachypelma với tấm mai ngực đen tuyền không viền và lớp lông dày màu hồng cam phấn phủ từ đốt chày tới bàn chân.","imageURL":"https://bionexus.vn/images/brachypelma-klaasi.jpg","referenceURL":"https://www.gbif.org/species/2153443"},{"id":329,"nodeId":377,"scientificName":"Poecilotheria metallica","commonName":"Nhện Tarantula Xanh Ánh Kim Gooty (Peacock Tarantula)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 24-29°C, Độ ẩm: 65-80%, Môi trường: Tán cây cổ thụ có nhiều hốc mục trong rừng khô nhiệt đới miền nam Ấn Độ","description":"Viên ngọc bích sống của giới chân khớp với toàn thân phủ sắc xanh lam coban ánh kim loại kết hợp hoa văn trắng hình học đối xứng trên lưng và điểm vàng chanh dưới chân.","imageURL":"https://bionexus.vn/images/poecilotheria-metallica.jpg","referenceURL":"https://www.gbif.org/species/2154249"},{"id":330,"nodeId":377,"scientificName":"Poecilotheria regalis","commonName":"Nhện Tarantula Hoa Văn Hoàng Gia Ấn Độ (Indian Ornamental)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 24-29°C, Độ ẩm: 65-80%, Môi trường: Các hốc cây cao trên thân cây gỗ tếch và rừng nhiệt đới gió mùa","description":"Loài nhện cây lớn của Ấn Độ với họa tiết lá sồi trắng xám tinh xảo trên lưng và mặt dưới hai chân trước kẻ vằn đen-vàng tươi như biển cảnh báo.","imageURL":"https://bionexus.vn/images/poecilotheria-regalis.jpg","referenceURL":"https://www.gbif.org/species/2154248"},{"id":331,"nodeId":377,"scientificName":"Poecilotheria hanumavilasumica","commonName":"Nhện Tarantula Đảo Rameshwaram (Rameshwaram Ornamental)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 25-30°C, Độ ẩm: 65-78%, Môi trường: Đồn điền me, dừa và cây thốt nốt ven biển nhiệt đới","description":"Loài nhện cây cực hiếm chỉ được khoa học phát hiện năm 2004 trong các hốc cây me cổ thụ quanh khu đền Hanumavilasum trên đảo Rameshwaram.","imageURL":"https://bionexus.vn/images/poecilotheria-hanumavilasumica.jpg","referenceURL":"https://www.gbif.org/species/2154253"},{"id":332,"nodeId":378,"scientificName":"Dolomedes plantarius","commonName":"Nhện Bè Lớn Châu Âu (Great Raft Spider)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 18-25°C, Độ ẩm: 75-90%, Môi trường: Đầm lầy nước ngọt không ô nhiễm, kênh rạch thực vật thủy sinh dày","description":"Một trong những loài nhện lớn nhất châu Âu có khả năng đi lại nhẹ nhàng trên mặt nước và lặn xuống dưới nước để bắt cá con hay nòng nọc.","imageURL":"https://bionexus.vn/images/dolomedes-plantarius.jpg","referenceURL":"https://www.gbif.org/species/2150951"},{"id":333,"nodeId":379,"scientificName":"Limulus polyphemus","commonName":"Sam Mỹ Đại Tây Dương (American Horseshoe Crab)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ nước: 18-25°C, pH: 7.8-8.3, Môi trường: Vùng đáy cát bùn ven bờ biển, cửa sông và bãi triều đẻ trứng","description":"Hóa thạch sống có lịch sử tiến hóa hơn 445 triệu năm với chiếc mai hình móng ngựa màu nâu đồng, chiếc đuôi nhọn dài và 9 con mắt phân bố khắp cơ thể.","imageURL":"https://bionexus.vn/images/limulus-polyphemus.jpg","referenceURL":"https://www.gbif.org/species/1010610"},{"id":334,"nodeId":380,"scientificName":"Tachypleus tridentatus","commonName":"Sam Ba Gai Châu Á (Tri-spine Horseshoe Crab)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 22-28°C, pH: 7.8-8.3, Môi trường: Bãi triều cát bùn cửa sông và vùng biển nông ven bờ","description":"Loài sam lớn nhất thế giới phân bố dọc bờ biển Việt Nam và Đông Á, luôn đi thành từng cặp đực bám lưng cái khăng khít nên tạo thành câu thành ngữ 'dính như sam'.","imageURL":"https://bionexus.vn/images/tachypleus-tridentatus.jpg","referenceURL":"https://www.gbif.org/species/1010608"},{"id":335,"nodeId":381,"scientificName":"Procambarus clarkii","commonName":"Tôm Hùm Đất Đỏ Louisiana (Red Swamp Crayfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 18-26°C, pH: 6.8-8, Môi trường: Đầm lầy nước ngọt, ruộng ngập nước, ao hồ và sông suối chảy chậm","description":"Loài tôm hùm đất nổi tiếng của Bắc Mỹ với lớp vỏ đỏ thẫm điểm các gai hạt sần trên càng và nhiều biến thể màu cảnh như Trắng Tuyết, Cam, Ghost.","imageURL":"https://bionexus.vn/images/procambarus-clarkii.jpg","referenceURL":"https://www.gbif.org/species/2227300"},{"id":336,"nodeId":381,"scientificName":"Procambarus alleni","commonName":"Tôm Hùm Đất Xanh Điện Quang Florida (Florida Crayfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 20-26°C, pH: 7-8, Môi trường: Đầm lầy cỏ Everglades, suối nước ngọt và ao hồ nhiều rễ cây","description":"Loài tôm hùm nước ngọt cảnh nổi bật với lớp vỏ màu xanh lam coban điện quang rực sáng tự nhiên điểm các chấm trắng nhỏ trên càng.","imageURL":"https://bionexus.vn/images/procambarus-alleni.jpg","referenceURL":"https://www.gbif.org/species/2227203"},{"id":337,"nodeId":382,"scientificName":"Cambarellus puer","commonName":"Tôm Hùm Đất Lùn Đầm Lầy (Swamp Dwarf Crayfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 18-25°C, pH: 6.5-7.8, Môi trường: Đầm lầy nông nhiều cỏ nước, lá mục và rễ cây thủy sinh","description":"Một trong những loài tôm hùm đất lùn nhỏ nhất thế giới, chỉ dài khoảng 3 cm, cực kỳ hiền lành và không hề cắt phá cây thủy sinh.","imageURL":"https://bionexus.vn/images/cambarellus-puer.jpg","referenceURL":"https://www.gbif.org/species/2227434"},{"id":338,"nodeId":383,"scientificName":"Cherax quadricarinatus","commonName":"Tôm Hùm Nước Ngọt Móng Đỏ Úc (Redclaw)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-29°C, pH: 7-8.2, Môi trường: Sông suối chảy chậm vùng nhiệt đới có nhiều khúc cây gỗ chìm và hốc bờ đất","description":"Loài tôm hùm nước ngọt nhiệt đới cỡ lớn của Úc với lớp giáp màu xanh lam ngọc lục bảo bóng bẩy, bốn đường gờ dọc trên đầu và vệt đỏ tươi nơi mép càng con đực.","imageURL":"https://bionexus.vn/images/cherax-quadricarinatus.jpg","referenceURL":"https://www.gbif.org/species/4648609"},{"id":339,"nodeId":383,"scientificName":"Cherax destructor","commonName":"Tôm Hùm Nước Ngọt Yabby Úc (Yabby)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ nước: 18-26°C, pH: 7-8.2, Môi trường: Sông suối đục, đầm nước tạm thời (billabongs) và hồ chứa có bờ đất sét","description":"Loài tôm hùm nước ngọt biểu tượng của nước Úc với cặp càng bản rộng cực khỏe và nhiều dòng màu xanh ngọc trai (Blue Pearl), trắng sứ tuyệt đẹp trong bể cảnh.","imageURL":"https://bionexus.vn/images/cherax-destructor.jpg","referenceURL":"https://www.gbif.org/species/4417558"},{"id":340,"nodeId":384,"scientificName":"Astacus astacus","commonName":"Tôm Hùm Sông Quý Tộc Châu Âu (Noble Crayfish)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ nước: 12-20°C, pH: 7-8.2, Môi trường: Sông suối nước trong mát, giàu oxy có bờ đất nhiều rễ cây sủi và đáy sỏi đá","description":"Loài tôm hùm nước ngọt bản địa lớn và danh giá nhất châu Âu, từng là món ăn chỉ dành cho giới quý tộc Bắc Âu trước khi suy giảm mạnh vì dịch nấm tôm Bắc Mỹ.","imageURL":"https://bionexus.vn/images/astacus-astacus.jpg","referenceURL":"https://www.gbif.org/species/2226998"},{"id":341,"nodeId":385,"scientificName":"Austropotamobius pallipes","commonName":"Tôm Hùm Sông Chân Trắng (White-clawed Crayfish)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 10-18°C, pH: 7.2-8.4, Môi trường: Suối đá vôi nước trong vắt, mát lành và giàu canxi","description":"Loài tôm hùm nước ngọt bản địa duy nhất của quần đảo Anh, nổi bật với lớp vỏ nâu đồng nhẵn và mặt dưới hai chiếc càng sáng màu trắng ngà.","imageURL":"https://bionexus.vn/images/austropotamobius-pallipes.jpg","referenceURL":"https://www.gbif.org/species/4312658"},{"id":342,"nodeId":386,"scientificName":"Pacifastacus leniusculus","commonName":"Tôm Hùm Nước Ngọt Tín Hiệu (Signal Crayfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 12-22°C, pH: 7-8.2, Môi trường: Sông suối đá cuội, hồ nước trong vùng ôn đới","description":"Loài tôm hùm nước ngọt miền Tây Bắc Mỹ có lớp vỏ nâu xanh nhẵn bóng và đốm trắng lam nổi bật ngay khớp kẹp càng giống như cờ hiệu của nhân viên đường sắt.","imageURL":"https://bionexus.vn/images/pacifastacus-leniusculus.jpg","referenceURL":"https://www.gbif.org/species/2226990"},{"id":343,"nodeId":387,"scientificName":"Caridina multidentata","commonName":"Tép Amano (Tép Yamato)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 20-27°C, pH: 6.4-7.6, Môi trường: Suối nước ngọt chảy ra cửa biển (ấu trùng nở ra phải trôi ra vùng nước lợ - mặn để phát triển rồi mới ngược dòng về nước ngọt)","description":"Chiến binh diệt rêu hại số một trong nghệ thuật bể thủy sinh thiên nhiên do bậc thầy Takashi Amano giới thiệu ra toàn thế giới từ thập niên 1980.","imageURL":"https://bionexus.vn/images/caridina-multidentata.jpg","referenceURL":"https://www.gbif.org/species/5863054"},{"id":344,"nodeId":388,"scientificName":"Macrobrachium rosenbergii","commonName":"Tôm Càng Xanh Khổng Lồ (Giant River Prawn)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 25-31°C, pH: 7-8.2, Môi trường: Sông lớn, kênh rạch nước ngọt và vùng hạ lưu cửa sông nước lợ nhẹ","description":"Loài tôm nước ngọt lớn nhất thế giới bản địa vùng sông Cửu Long Việt Nam, nổi bật với cặp càng dài mảnh màu xanh lam ngọc bích vươn xa đầy uy lực ở con đực trưởng thành.","imageURL":"https://bionexus.vn/images/macrobrachium-rosenbergii.jpg","referenceURL":"https://www.gbif.org/species/2224546"},{"id":345,"nodeId":389,"scientificName":"Birgus latro","commonName":"Cua Dừa Khổng Lồ (Coconut Crab)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 25-30°C, Độ ẩm: 75-85%, Môi trường: Rừng ven biển, hốc đá vôi san hô và rừng dừa trên các đảo nhiệt đới","description":"Loài động vật chân khớp trên cạn nặng nhất hành tinh, phát triển từ cua ẩn sĩ nhưng khi trưởng thành không còn mang vỏ ốc mà có lớp vỏ bụng hóa vôi siêu cứng.","imageURL":"https://bionexus.vn/images/birgus-latro.jpg","referenceURL":"https://www.gbif.org/species/4311512"},{"id":346,"nodeId":390,"scientificName":"Pomacea canaliculata","commonName":"Ốc Táo Vàng Nam Mỹ (Ốc Bươu Vàng) (Channeled Applesnail)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 20-30°C, pH: 6.8-8.2, Môi trường: Đầm lầy, ao hồ nước tĩnh và sông suối chảy chậm nhiều thực vật nước","description":"Loài ốc nước ngọt cỡ lớn có vỏ xoắn cầu với rãnh sâu giữa các vòng xoắn; dòng đột biến vàng tươi từng được nuôi làm ốc cảnh trước khi trở thành loài xâm hại ruộng lúa.","imageURL":"https://bionexus.vn/images/pomacea-canaliculata.jpg","referenceURL":"https://www.gbif.org/species/2292582"},{"id":347,"nodeId":390,"scientificName":"Pomacea paludosa","commonName":"Ốc Táo Florida (Florida Applesnail)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 20-28°C, pH: 7-8.2, Môi trường: Đầm lầy cỏ Everglades, hồ nước ngọt trong và suối đá vôi","description":"Loài ốc nước ngọt bản địa lớn nhất Bắc Mỹ và là nguồn thức ăn sống còn duy nhất của loài chim Diều ăn ốc Everglades đang nguy cấp.","imageURL":"https://bionexus.vn/images/pomacea-paludosa.jpg","referenceURL":"https://www.gbif.org/species/2292584"},{"id":348,"nodeId":391,"scientificName":"Marisa cornuarietis","commonName":"Ốc Sừng Cừu Khổng Lồ","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 22-28°C, pH: 7-8.2, Môi trường: Vùng nước nông ấm áp nhiều thực vật thủy sinh","description":"Mặc dù mang chiếc vỏ cuộn tròn phẳng hệt như ốc sừng cừu Planorbidae, loài ốc này thực chất lại thuộc họ Ốc Táo (Ampullariidae) và có nắp miệng vỏ cứng rõ rệt.","imageURL":"https://bionexus.vn/images/marisa-cornuarietis.jpg","referenceURL":"https://www.gbif.org/species/2292586"},{"id":349,"nodeId":392,"scientificName":"Faunus ater","commonName":"Ốc Đinh Đen (Ốc Devil)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-29°C, pH: 7.2-8.4, Môi trường: Đầm phá cửa sông nước lợ và hạ lưu sông suối có nền cát bùn giàu mùn","description":"Loài ốc cảnh tầng đáy sang trọng với chiếc vỏ hình tháp nhọn đen bóng như đá núi lửa và phần thân mềm màu đen điểm xúc tu xám bạc.","imageURL":"https://bionexus.vn/images/faunus-ater.jpg","referenceURL":"https://www.gbif.org/species/5857723"},{"id":350,"nodeId":393,"scientificName":"Theodoxus fluviatilis","commonName":"Ốc Nerita Sông Châu Âu","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 16-25°C, pH: 7.2-8.5, Môi trường: Bề mặt đá cuội và gỗ chìm trong các dòng sông suối giàu canxi và oxy","description":"Đại diện tiêu biểu của họ Ốc Nerita vùng nước ngọt ôn đới với chiếc vỏ hình giọt nước dẹt bám chặt vào mặt đá giữa dòng chảy mạnh và họa tiết hoa văn tinh xảo.","imageURL":"https://bionexus.vn/images/theodoxus-fluviatilis.jpg","referenceURL":"https://www.gbif.org/species/2291444"},{"id":351,"nodeId":394,"scientificName":"Planorbarius corneus","commonName":"Ốc Táo Đỏ Sừng Cừu","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 16-27°C, pH: 6.8-8.2, Môi trường: Ao hồ tĩnh, đầm lầy và kênh rạch có nhiều thực vật thủy sinh","description":"Loài ốc sừng cừu lớn nhất châu Âu và cực kỳ quen thuộc trong giới thủy sinh với các biến thể Táo Đỏ, Táo Hồng, Táo Xanh ngọc lấp lánh.","imageURL":"https://bionexus.vn/images/planorbarius-corneus.jpg","referenceURL":"https://www.gbif.org/species/2290946"},{"id":352,"nodeId":395,"scientificName":"Lymnaea stagnalis","commonName":"Ốc Tai Hồ Lớn","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 15-25°C, pH: 7-8.2, Môi trường: Ao hồ nước tĩnh, đầm nước ngọt giàu rong bèo","description":"Loài ốc phổi nước ngọt cỡ lớn có chiếc vỏ xoắn nhọn thanh thoát và đôi râu đầu dẹt rộng hình tam giác như tai mèo, thường xuyên bò lộn ngược ngay dưới mặt nước.","imageURL":"https://bionexus.vn/images/lymnaea-stagnalis.jpg","referenceURL":"https://www.gbif.org/species/2291253"},{"id":353,"nodeId":396,"scientificName":"Viviparus viviparus","commonName":"Ốc Vặn Sông Ba Sọc (Viviparus River Snail)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 15-25°C, pH: 7-8.2, Môi trường: Đáy bùn cát của các dòng sông chảy chậm và hồ lớn giàu oxy","description":"Loài ốc nắp mang nước ngọt đẻ con trực tiếp, có vỏ hình nón tròn trịa màu vàng lục điểm ba dải sọc nâu đỏ chạy song song quanh vòng xoắn.","imageURL":"https://bionexus.vn/images/viviparus-viviparus.jpg","referenceURL":"https://www.gbif.org/species/5725685"},{"id":354,"nodeId":397,"scientificName":"Helix pomatia","commonName":"Ốc Sên Rượu Vang Châu Âu (Ốc Burgundy)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 16-24°C, Độ ẩm: 70-85%, Môi trường: Rừng lá rộng thưa, vườn nho, sườn đồi đá vôi nhiều bụi cây ẩm","description":"Loài ốc sên cạn lớn nhất châu Âu với chiếc vỏ tròn dày màu nâu kem ấm áp, gắn liền với văn hóa ẩm thực và lịch sử tự nhiên từ thời Đế chế La Mã.","imageURL":"https://bionexus.vn/images/helix-pomatia.jpg","referenceURL":"https://www.gbif.org/species/2294287"},{"id":355,"nodeId":398,"scientificName":"Cepaea nemoralis","commonName":"Ốc Sên Vườn Viền Môi Đen (Brown Lipped Snail)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-24°C, Độ ẩm: 70-85%, Môi trường: Rừng thưa, bờ rào cây bụi, đồng cỏ và công viên đô thị","description":"Loài ốc sên cạn nổi tiếng nhất trong sách giáo khoa tiến hóa nhờ sự đa hình màu vỏ rực rỡ từ vàng tươi, hồng phấn đến sọc vằn kèm viền môi miệng vỏ màu đen nhánh.","imageURL":"https://bionexus.vn/images/cepaea-nemoralis.jpg","referenceURL":"https://www.gbif.org/species/2294280"},{"id":356,"nodeId":398,"scientificName":"Cepaea hortensis","commonName":"Ốc Sên Vườn Viền Môi Trắng (White Lipped Snail)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 14-22°C, Độ ẩm: 70-85%, Môi trường: Cánh đồng cỏ ẩm, ven rừng và vùng đồi núi mát","description":"Loài chị em gần gũi của ốc sên C. nemoralis với chiếc vỏ vàng tươi hoặc kẻ sọc đen nổi bật, được phân biệt chắc chắn nhờ đường gờ môi trắng muốt quanh miệng vỏ.","imageURL":"https://bionexus.vn/images/cepaea-hortensis.jpg","referenceURL":"https://www.gbif.org/species/2294279"},{"id":357,"nodeId":399,"scientificName":"Anodonta anatina","commonName":"Trai Sông Vịt Châu Âu (Duck Mussel)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 14-24°C, pH: 7-8.2, Môi trường: Đáy bùn cát của các dòng sông chảy chậm, kênh đào và hồ nước ngọt","description":"Loài trai nước ngọt phổ biến của lục địa Á - Âu với lớp vỏ bầu dục không răng bản lề (Anodonta) và khả năng lọc sạch hàng chục lít nước mỗi ngày.","imageURL":"https://bionexus.vn/images/anodonta-anatina.jpg","referenceURL":"https://www.gbif.org/species/4559631"},{"id":358,"nodeId":400,"scientificName":"Unio pictorum","commonName":"Trai Sông Họa Sĩ (Painter's Mussel)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 14-24°C, pH: 7-8.2, Môi trường: Đáy cát sỏi của các dòng sông lớn và hồ nước trong","description":"Loài trai sông có chiếc vỏ thuôn dài cân đối từng được các danh họa châu Âu suốt nhiều thế kỷ dùng làm khay đựng và pha màu vẽ hội họa.","imageURL":"https://bionexus.vn/images/unio-pictorum.jpg","referenceURL":"https://www.gbif.org/species/4374772"},{"id":359,"nodeId":401,"scientificName":"Margaritifera margaritifera","commonName":"Trai Ngọc Nước Ngọt Phương Bắc (Freshwater Pearl Mussel)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 8-18°C, pH: 6.5-7.5, Môi trường: Sông suối nước chảy nhanh, cực kỳ tinh khiết, nghèo dinh dưỡng và có cá hồi sinh sống","description":"Một trong những loài động vật không xương sống sống thọ nhất hành tinh với tuổi thọ vượt quá 200 năm và khả năng kết tạo những viên ngọc trai nước ngọt quý giá.","imageURL":"https://bionexus.vn/images/margaritifera-margaritifera.jpg","referenceURL":"https://www.gbif.org/species/7911174"},{"id":360,"nodeId":402,"scientificName":"Corbicula fluminea","commonName":"Hến Sông Vàng Châu Á (Asian Clam)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 18-28°C, pH: 6.8-8.2, Môi trường: Đáy cát và cát pha bùn giàu oxy của các dòng sông, suối và hồ nước ngọt","description":"Loài hai mảnh vỏ nước ngọt quen thuộc của các dòng sông Việt Nam với chiếc vỏ vàng óng có gờ nổi đồng tâm, đóng vai trò như những chiếc máy lọc sinh học tự nhiên dưới nền cát.","imageURL":"https://bionexus.vn/images/corbicula-fluminea.jpg","referenceURL":"https://www.gbif.org/species/8190231"},{"id":361,"nodeId":403,"scientificName":"Osmoderma eremita","commonName":"Bọ Hung Ẩn Sĩ Mùi Đào (Hermit Beetle)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 18-26°C, Độ ẩm: 65-80%, Môi trường: Mùn gỗ mục bên trong các hốc cây sồi, dẻ gai và đoạn cổ thụ hàng trăm năm tuổi","description":"Loài bọ cánh cứng rừng già quý hiếm của châu Âu với lớp vỏ màu nâu đồng đen bóng ánh kim và hương thơm trái đào chín đặc trưng do con đực tiết ra.","imageURL":"https://bionexus.vn/images/osmoderma-eremita.jpg","referenceURL":"https://www.gbif.org/species/1079588"},{"id":362,"nodeId":24,"scientificName":"Nepenthes alata","commonName":"Nắp Ấm Cánh","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-30°C, Độ ẩm: 65-85%, Môi trường: Rừng sương mù núi thấp và sườn đồi thoáng sáng","description":"Loài nắp ấm biểu tượng của quần đảo Philippines với chiếc ấm hình trụ thon có phần bụng hơi phình và hai dải cánh tua rua chạy dọc mặt trước.","imageURL":"https://bionexus.vn/images/nepenthes-alata.jpg","referenceURL":"https://www.gbif.org/species/3702270"},{"id":363,"nodeId":24,"scientificName":"Nepenthes ventricosa","commonName":"Nắp Ấm Bụng Phình","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-27°C, Độ ẩm: 65-85%, Môi trường: Rừng rêu nhiệt đới núi cao từ 1.000 đến 2.000 m","description":"Loài nắp ấm cao nguyên nổi tiếng với chiếc ấm tròn trịa thắt eo duyên dáng như chiếc bình gốm sứ trắng hồng kèm vành môi đỏ tươi xếp nếp.","imageURL":"https://bionexus.vn/images/nepenthes-ventricosa.jpg","referenceURL":"https://www.gbif.org/species/3702158"},{"id":364,"nodeId":24,"scientificName":"Nepenthes mirabilis","commonName":"Nắp Ấm Hoa Kỳ (Cây Bình Nước)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-34°C, Độ ẩm: 65-90%, Môi trường: Đầm lầy đất cát ngập nước theo mùa, trảng cỏ ẩm và ven suối đất thấp","description":"Loài nắp ấm có phạm vi phân bố rộng lớn nhất thế giới và rất quen thuộc tại miền Trung - Nam Bộ Việt Nam với khả năng thích nghi mạnh ở vùng đầm lầy nắng gắt.","imageURL":"https://bionexus.vn/images/nepenthes-mirabilis.jpg","referenceURL":"https://www.gbif.org/species/3190712"},{"id":365,"nodeId":24,"scientificName":"Nepenthes bicalcarata","commonName":"Nắp Ấm Hai Nanh","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 24-33°C, Độ ẩm: 75-90%, Môi trường: Rừng đầm lầy than bùn nhiệt đới đất thấp ẩm ướt quanh năm","description":"Loài nắp ấm độc nhất vô nhị với hai chiếc gai nhọn hoắt cong xuống dưới nắp ấm trông như cặp răng nanh rắn độc và cuống ấm phình rỗng làm tổ cho kiến cộng sinh.","imageURL":"https://bionexus.vn/images/nepenthes-bicalcarata.jpg","referenceURL":"https://www.gbif.org/species/3702248"},{"id":366,"nodeId":24,"scientificName":"Nepenthes truncata","commonName":"Nắp Ấm Lá Cụt Khổng Lồ","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 20-30°C, Độ ẩm: 65-85%, Môi trường: Sườn núi đá dốc và rừng nhiệt đới từ 0 đến 1.500 m","description":"Một trong những loài nắp ấm có chiếc bình bẫy mồi to lớn nhất hành tinh, nhận diện ngay từ xa nhờ phiến lá có chóp bị cắt ngang vuông vức độc đáo.","imageURL":"https://bionexus.vn/images/nepenthes-truncata.jpg","referenceURL":"https://www.gbif.org/species/3702212"},{"id":367,"nodeId":24,"scientificName":"Nepenthes villosa","commonName":"Nắp Ấm Răng Lược Lông Nhung","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 8-20°C, Độ ẩm: 75-95%, Môi trường: Rừng rêu sương mù núi cao lạnh giá từ 2.400 đến 3.200 m","description":"Báu vật vùng đỉnh núi Kinabalu với lớp lông nhung màu nâu vàng phủ khắp tua cuốn và chiếc vành môi (peristome) xếp tầng thành hàng răng kiếm tinh xảo.","imageURL":"https://bionexus.vn/images/nepenthes-villosa.jpg","referenceURL":"https://www.gbif.org/species/3702128"},{"id":368,"nodeId":24,"scientificName":"Nepenthes lowii","commonName":"Nắp Ấm Thượng Hạng Low","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 10-22°C, Độ ẩm: 75-90%, Môi trường: Rừng rêu đỉnh núi cao từ 1.650 đến 2.600 m","description":"Loài nắp ấm kỳ lạ bậc nhất giới thực vật khi chiếc ấm trên không còn bắt côn trùng mà biến thành một chiếc 'nhà vệ sinh' có nắp tiết kem ngọt dành cho đồi cói núi.","imageURL":"https://bionexus.vn/images/nepenthes-lowii.jpg","referenceURL":"https://www.gbif.org/species/3702034"},{"id":369,"nodeId":24,"scientificName":"Nepenthes clipeata","commonName":"Nắp Ấm Khiên Vách Đá","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 18-28°C, Độ ẩm: 70-85%, Môi trường: Vách đá granit gần như thẳng đứng ở độ cao 600–800 m","description":"Loài nắp ấm leo vách đá có hình thái lá hình khiên (peltate) độc đáo với cuống ấm mọc lùi vào mặt dưới phiến lá tròn để treo chiếc ấm lơ lửng ngoài mép vực.","imageURL":"https://bionexus.vn/images/nepenthes-clipeata.jpg","referenceURL":"https://www.gbif.org/species/3702027"},{"id":370,"nodeId":24,"scientificName":"Nepenthes albomarginata","commonName":"Nắp Ấm Cổ Trắng","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-31°C, Độ ẩm: 70-85%, Môi trường: Rừng kerangas đất thấp, vách đá ven biển và rừng núi thấp","description":"Loài nắp ấm dễ nhận diện nhất Đông Nam Á nhờ một vòng cổ màu trắng muốt như nhung nằm sát dưới vành môi ấm dùng làm mồi nhử mối.","imageURL":"https://bionexus.vn/images/nepenthes-albomarginata.jpg","referenceURL":"https://www.gbif.org/species/3702230"},{"id":371,"nodeId":24,"scientificName":"Nepenthes gracilis","commonName":"Nắp Ấm Mảnh","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 23-33°C, Độ ẩm: 70-90%, Môi trường: Ven rừng đầm lầy đất thấp, đồi đất chua và bờ bụi ngập nắng","description":"Loài nắp ấm thân leo mảnh mai nhưng sở hữu cơ chế bẫy mồi tốc độ cao bằng lực bật của giọt mưa rơi xuống mặt nắp ấm.","imageURL":"https://bionexus.vn/images/nepenthes-gracilis.jpg","referenceURL":"https://www.gbif.org/species/3702049"},{"id":372,"nodeId":24,"scientificName":"Nepenthes reinwardtiana","commonName":"Nắp Ấm Hai Mắt","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-30°C, Độ ẩm: 70-85%, Môi trường: Sườn đồi đất cát nghèo dinh dưỡng và sống phụ sinh trên cây gỗ","description":"Loài nắp ấm nổi tiếng với hai chấm tròn không phủ sáp nằm đối xứng bên trong thành ấm tạo thành hình ảnh 'đôi mắt' nhìn chằm chằm vào con mồi.","imageURL":"https://bionexus.vn/images/nepenthes-reinwardtiana.jpg","referenceURL":"https://www.gbif.org/species/7167252"},{"id":373,"nodeId":24,"scientificName":"Nepenthes sanguinea","commonName":"Nắp Ấm Đỏ Máu","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-28°C, Độ ẩm: 65-85%, Môi trường: Rừng sương mù núi cao từ 900 đến 1.800 m","description":"Loài nắp ấm cao nguyên của bán đảo Mã Lai rất được yêu thích nhờ những chiếc ấm lớn màu đỏ rượu vang hoặc cam đào và sức chịu đựng biên độ nhiệt tuyệt vời.","imageURL":"https://bionexus.vn/images/nepenthes-sanguinea.jpg","referenceURL":"https://www.gbif.org/species/3702234"},{"id":374,"nodeId":24,"scientificName":"Nepenthes veitchii","commonName":"Nắp Ấm Cổ Áo Hoàng Gia Veitch","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 16-28°C, Độ ẩm: 70-88%, Môi trường: Sống bám (phụ sinh) trên thân cây rừng hoặc mọc trên đất cát kerangas từ 0 đến 1.600 m","description":"Được mệnh danh là 'Ông hoàng vành môi' của chi Nepenthes với chiếc cổ áo peristome xòe rộng lộng lẫy kẻ sọc vàng óng và đỏ thẫm kèm lớp lông nhung phủ khắp thân.","imageURL":"https://bionexus.vn/images/nepenthes-veitchii.jpg","referenceURL":"https://www.gbif.org/species/3702168"},{"id":375,"nodeId":24,"scientificName":"Nepenthes fusca","commonName":"Nắp Ấm Nâu Đốm","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 14-25°C, Độ ẩm: 70-88%, Môi trường: Sống phụ sinh trên tán cây rừng rêu sương mù từ 1.200 đến 2.500 m","description":"Loài nắp ấm vùng cao nguyên Borneo có chiếc ấm thuôn dài đốm nâu tía và phần nắp hẹp dài uốn cong hình tam giác rất thanh thoát.","imageURL":"https://bionexus.vn/images/nepenthes-fusca.jpg","referenceURL":"https://www.gbif.org/species/3702129"},{"id":376,"nodeId":24,"scientificName":"Nepenthes stenophylla","commonName":"Nắp Ấm Lá Hẹp","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 14-25°C, Độ ẩm: 70-88%, Môi trường: Rừng rêu núi cao và rừng cây bụi trên đá cát từ 900 đến 2.600 m","description":"Loài nắp ấm cao nguyên Borneo nổi bật với những chiếc ấm hình ống trụ thon dài điểm hoa văn đốm nâu hồng và phần mấu lồi tiết mật dưới gốc nắp.","imageURL":"https://bionexus.vn/images/nepenthes-stenophylla.jpg","referenceURL":"https://www.gbif.org/species/3702099"},{"id":377,"nodeId":24,"scientificName":"Nepenthes tentaculata","commonName":"Nắp Ấm Tua Xúc Tu","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-23°C, Độ ẩm: 75-92%, Môi trường: Thảm rêu Sphagnum ướt đẫm trong rừng mây từ 1.200 đến 2.550 m","description":"Loài nắp ấm rừng rêu đặc trưng với những sợi tua mảnh như xúc tu mọc dọc hai bên mặt trên của nắp ấm và sắc ấm tím than huyền bí.","imageURL":"https://bionexus.vn/images/nepenthes-tentaculata.jpg","referenceURL":"https://www.gbif.org/species/4930497"},{"id":378,"nodeId":24,"scientificName":"Nepenthes burbidgeae","commonName":"Nắp Ấm Sứ Vẽ Burbidge","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 13-24°C, Độ ẩm: 75-90%, Môi trường: Rừng núi trên đất đá siêu bazơ (ultramafic) giàu kim loại nặng ở độ cao 1.200–1.800 m","description":"Một trong những loài nắp ấm thanh nhã nhất đảo Borneo với chiếc ấm tròn màu trắng kem sữa điểm những nét chấm phá màu đỏ rượu vang như tranh thủy mặc.","imageURL":"https://bionexus.vn/images/nepenthes-burbidgeae.jpg","referenceURL":"https://www.gbif.org/species/3702164"},{"id":379,"nodeId":24,"scientificName":"Nepenthes eymae","commonName":"Nắp Ấm Ly Rượu Vang Eyma","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 13-24°C, Độ ẩm: 75-90%, Môi trường: Rừng rêu sương mù núi cao từ 1.000 đến 2.000 m tại Sulawesi","description":"Loài nắp ấm nổi tiếng của đảo Sulawesi với những chiếc ấm trên có hình dáng giống hệt một chiếc ly rượu vang pha lê kèm nắp ấm hẹp hình mũi tên.","imageURL":"https://bionexus.vn/images/nepenthes-eymae.jpg","referenceURL":"https://www.gbif.org/species/3702202"},{"id":380,"nodeId":24,"scientificName":"Nepenthes hamata","commonName":"Nắp Ấm Răng Câu","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-23°C, Độ ẩm: 75-92%, Môi trường: Rừng rêu sương mù đỉnh núi cao từ 1.400 đến 2.500 m","description":"Biểu tượng dữ dội nhất của dòng cây ăn thịt cao nguyên với hàng răng đen bóng cong vút như lưỡi câu cá xếp dọc vành môi và những sợi lông tua trên nắp ấm.","imageURL":"https://bionexus.vn/images/nepenthes-hamata.jpg","referenceURL":"https://www.gbif.org/species/4930512"},{"id":381,"nodeId":24,"scientificName":"Nepenthes hirsuta","commonName":"Nắp Ấm Lông Nhám","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-30°C, Độ ẩm: 70-88%, Môi trường: Rừng nhiệt đới chân núi và đồi đá sa thạch từ 200 đến 1.100 m","description":"Loài nắp ấm bản địa đảo Borneo dễ nhận biết nhờ lớp lông tơ cứng phủ dọc thân leo và những chiếc ấm hình bầu dục điểm đốm đỏ tía.","imageURL":"https://bionexus.vn/images/nepenthes-hirsuta.jpg","referenceURL":"https://www.gbif.org/species/4930505"},{"id":382,"nodeId":24,"scientificName":"Nepenthes khasiana","commonName":"Nắp Ấm Ấn Độ Khasia","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 16-28°C, Độ ẩm: 70-88%, Môi trường: Sườn đồi mưa nhiều bậc nhất thế giới ở độ cao 500–1.500 m tại Meghalaya","description":"Loài nắp ấm duy nhất bản địa của đất nước Ấn Độ, được người dân tộc Khasi gọi là 'Tiew-rakot' (hoa quỷ ăn thịt) và sử dụng dịch ấm chưa mở trong y học cổ truyền.","imageURL":"https://bionexus.vn/images/nepenthes-khasiana.jpg","referenceURL":"https://www.gbif.org/species/3702236"},{"id":383,"nodeId":24,"scientificName":"Nepenthes madagascariensis","commonName":"Nắp Ấm Đảo Madagascar","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-32°C, Độ ẩm: 70-88%, Môi trường: Đầm lầy cát ven biển, trảng cỏ ngập nước và ven đầm phá nhiệt đới","description":"Loài nắp ấm đầu tiên trong lịch sử được nhà thực vật học châu Âu Étienne de Flacourt ghi chép vào năm 1658 tại vùng cực tây của chi Nepenthes.","imageURL":"https://bionexus.vn/images/nepenthes-madagascariensis.jpg","referenceURL":"https://www.gbif.org/species/3702243"},{"id":384,"nodeId":24,"scientificName":"Nepenthes distillatoria","commonName":"Nắp Ấm Tích Lan (Loài Chuẩn Chi Nepenthes)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 22-31°C, Độ ẩm: 75-90%, Môi trường: Rừng mưa nhiệt đới đất thấp và sườn đồi ẩm lầy từ 0 đến 700 m","description":"Loài chuẩn (type species) của toàn bộ chi Nắp ấm được đại danh hào Carl Linnaeus đặt tên năm 1753, lấy cảm hứng từ thần dược Nepenthe giúp quên đi ưu phiền trong sử thi Odyssey.","imageURL":"https://bionexus.vn/images/nepenthes-distillatoria.jpg","referenceURL":"https://www.gbif.org/species/3702080"},{"id":385,"nodeId":24,"scientificName":"Nepenthes macfarlanei","commonName":"Nắp Ấm Lông Trắng Macfarlane","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 14-25°C, Độ ẩm: 75-90%, Môi trường: Rừng rêu sương mù núi cao từ 1.000 đến 2.150 m","description":"Loài nắp ấm cao nguyên bán đảo Mã Lai nổi bật với chiếc ấm đốm đỏ tía trên nền trắng kem và chùm lông trắng dài mọc dày đặc ngay mặt dưới nắp ấm.","imageURL":"https://bionexus.vn/images/nepenthes-macfarlanei.jpg","referenceURL":"https://www.gbif.org/species/3702025"},{"id":386,"nodeId":24,"scientificName":"Nepenthes muluensis","commonName":"Nắp Ấm Đỉnh Mulu","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-23°C, Độ ẩm: 75-92%, Môi trường: Thảm cây bụi đỉnh núi cao đầy nắng gió từ 1.700 đến 2.400 m","description":"Viên ngọc nhỏ vùng đỉnh núi Sarawak với những chiếc ấm trên mang hai tông màu đối lập tuyệt đẹp: thân ấm tím sô-cô-la đậm và phần miệng kèm nắp trắng muốt như tuyết.","imageURL":"https://bionexus.vn/images/nepenthes-muluensis.jpg","referenceURL":"https://www.gbif.org/species/3702021"},{"id":387,"nodeId":24,"scientificName":"Nepenthes murudensis","commonName":"Nắp Ấm Núi Murud","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-23°C, Độ ẩm: 75-92%, Môi trường: Rừng lùn và trảng cây bụi đỉnh núi sa thạch từ 2.000 đến 2.420 m","description":"Loài nắp ấm đặc hữu của ngọn núi thiêng Murud ở Sarawak, mang những chiếc ấm lớn khỏe khoắn kết hợp đặc điểm hình thái giữa N. tentaculata và N. reinwardtiana.","imageURL":"https://bionexus.vn/images/nepenthes-murudensis.jpg","referenceURL":"https://www.gbif.org/species/3702269"},{"id":388,"nodeId":24,"scientificName":"Nepenthes northiana","commonName":"Nắp Ấm Nữ Hoàng Đá Vôi North","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 22-31°C, Độ ẩm: 75-90%, Môi trường: Khe nứt trên vách núi đá vôi dựng đứng ẩm râm ở độ cao 0–500 m","description":"Loài nắp ấm đá vôi lộng lẫy được đặt theo tên nữ họa sĩ Marianne North sau khi bức tranh sơn dầu bà vẽ chiếc ấm này tại Sarawak năm 1876 làm chấn động giới thực vật học Hoàng gia Anh.","imageURL":"https://bionexus.vn/images/nepenthes-northiana.jpg","referenceURL":"https://www.gbif.org/species/3702210"},{"id":389,"nodeId":24,"scientificName":"Nepenthes smilesii","commonName":"Nắp Ấm Nhiệt Đới Đông Dương (Nắp Ấm Smiles)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-33°C, Độ ẩm: 60-85%, Môi trường: Trảng cỏ thông ẩm, đầm lầy cát có mùa khô khắc nghiệt kéo dài từ 0 đến 1.500 m","description":"Loài nắp ấm bản địa kiên cường của vùng Đông Dương và Việt Nam, sở hữu bộ thân rễ phình củ dưới lòng đất giúp cây nảy chồi xanh tốt trở lại ngay sau những đám cháy cỏ mùa khô.","imageURL":"https://bionexus.vn/images/nepenthes-smilesii.jpg","referenceURL":"https://www.gbif.org/species/3702171"},{"id":390,"nodeId":24,"scientificName":"Nepenthes merrilliana","commonName":"Nắp Ấm Khổng Lồ Merrill","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 22-32°C, Độ ẩm: 75-90%, Môi trường: Rừng mưa nhiệt đới ven biển và sườn núi dốc trên đất ultramafic từ 0 đến 1.100 m","description":"Đối thủ cạnh tranh trực tiếp với N. rajah về danh hiệu chiếc ấm có dung tích lớn nhất thế giới ở vùng đất thấp, với những chiếc bình bầu dục khổng lồ treo lủng lẳng dưới tán rừng Mindanao.","imageURL":"https://bionexus.vn/images/nepenthes-merrilliana.jpg","referenceURL":"https://www.gbif.org/species/3702170"},{"id":391,"nodeId":24,"scientificName":"Nepenthes aristolochioides","commonName":"Nắp Ấm Hoa Phòng Kỷ (Nắp Ấm Cửa Sổ)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 12-23°C, Độ ẩm: 75-92%, Môi trường: Rừng rêu sương mù núi cao từ 1.800 đến 2.500 m","description":"Một trong những thiết kế bẫy mồi thông minh nhất thế giới thực vật với miệng ấm quay ngang ở mặt trước và vòm đỉnh ấm mỏng lấy sáng giống hệt loài hoa Phòng kỷ (Aristolochia).","imageURL":"https://bionexus.vn/images/nepenthes-aristolochioides.jpg","referenceURL":"https://www.gbif.org/species/3702095"},{"id":392,"nodeId":24,"scientificName":"Nepenthes bongso","commonName":"Nắp Ấm Thần Núi Bongso","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 14-25°C, Độ ẩm: 70-88%, Môi trường: Rừng sương mù núi cao từ 1.000 đến 2.700 m tại Sumatra","description":"Loài nắp ấm cao nguyên Sumatra mang vẻ đẹp huyền bí với những chiếc ấm màu tím than sẫm gần như đen bóng và vành môi rộng gợn sóng.","imageURL":"https://bionexus.vn/images/nepenthes-bongso.jpg","referenceURL":"https://www.gbif.org/species/3702220"},{"id":393,"nodeId":24,"scientificName":"Nepenthes densiflora","commonName":"Nắp Ấm Hoa Dày Aceh","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 11-22°C, Độ ẩm: 75-90%, Môi trường: Rừng rêu và trảng cây bụi núi cao từ 1.700 đến 3.200 m","description":"Loài nắp ấm vùng núi cao bắc Sumatra có những chiếc ấm hình phễu cứng cáp và chùm hoa mọc dày đặc hơn bất kỳ loài nắp ấm nào khác trên đảo.","imageURL":"https://bionexus.vn/images/nepenthes-densiflora.jpg","referenceURL":"https://www.gbif.org/species/3702162"},{"id":394,"nodeId":24,"scientificName":"Nepenthes spathulata","commonName":"Nắp Ấm Lá Hình Thìa","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 14-26°C, Độ ẩm: 70-88%, Môi trường: Rừng núi cao từ 1.100 đến 2.900 m","description":"Loài nắp ấm rất được ưa chuộng trong lai tạo nhờ chiếc ấm lớn cứng cáp mang sắc xanh táo tươi tắn đối lập hoàn toàn với vành môi đỏ tím thẫm xòe rộng.","imageURL":"https://bionexus.vn/images/nepenthes-spathulata.jpg","referenceURL":"https://www.gbif.org/species/3702151"},{"id":395,"nodeId":24,"scientificName":"Nepenthes spectabilis","commonName":"Nắp Ấm Đốm Hoa Tuyệt Đẹp","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 14-25°C, Độ ẩm: 70-88%, Môi trường: Rừng rêu sương mù núi cao từ 1.400 đến 2.200 m","description":"Đúng như tên khoa học 'spectabilis' (ngoạn mục), loài cây này sở hữu những chiếc ấm hình ống dài thanh thoát được trang trí bằng họa tiết đốm báo và vành môi kẻ sọc cầu vồng.","imageURL":"https://bionexus.vn/images/nepenthes-spectabilis.jpg","referenceURL":"https://www.gbif.org/species/3702130"},{"id":396,"nodeId":24,"scientificName":"Nepenthes tobaica","commonName":"Nắp Ấm Hồ Toba","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 16-28°C, Độ ẩm: 65-85%, Môi trường: Sườn đồi thông, vách đất mở và ven rừng núi từ 380 đến 1.800 m","description":"Loài nắp ấm tiêu biểu bao phủ các sườn đồi quanh hồ siêu núi lửa Toba ở Sumatra với sức leo khỏe và hàng chục chiếc ấm nhỏ xinh đung đưa trên mỗi bụi.","imageURL":"https://bionexus.vn/images/nepenthes-tobaica.jpg","referenceURL":"https://www.gbif.org/species/3702262"},{"id":397,"nodeId":24,"scientificName":"Nepenthes vieillardii","commonName":"Nắp Ấm Tân Đảo (New Caledonia)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-29°C, Độ ẩm: 65-85%, Môi trường: Trảng cây bụi maquis trên đất đá ultramafic giàu kim loại và rừng ẩm từ 0 đến 850 m","description":"Loài nắp ấm duy nhất bản địa của đảo New Caledonia — cực đông nam của toàn bộ chi Nepenthes — có khả năng chịu hạn và nắng gió trên nền đất giàu niken.","imageURL":"https://bionexus.vn/images/nepenthes-vieillardii.jpg","referenceURL":"https://www.gbif.org/species/4930508"},{"id":398,"nodeId":24,"scientificName":"Nepenthes vogelii","commonName":"Nắp Ấm Hoa Văn Vogel","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-26°C, Độ ẩm: 70-88%, Môi trường: Rừng rêu núi cao từ 1.000 đến 1.500 m (thường sống phụ sinh trên rêu)","description":"Loài nắp ấm nhỏ nhắn nhưng cực kỳ duyên dáng được đặt theo tên ông Art Vogel — cựu quản lý nhà kính Vườn thực vật Leiden — với chiếc ấm trên hình phễu thắt eo kẻ sọc.","imageURL":"https://bionexus.vn/images/nepenthes-vogelii.jpg","referenceURL":"https://www.gbif.org/species/3702106"},{"id":399,"nodeId":404,"scientificName":"Sarracenia flava","commonName":"Bình Tử Thảo Vàng","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-32°C, Độ ẩm: 60-80%, Môi trường: Đầm lầy cỏ ẩm ngập nắng và rừng thông lá dài ẩm ướt","description":"Loài bình tử thảo cao lớn và nổi bật bậc nhất Bắc Mỹ với những chiếc ống lá vươn thẳng đứng như những chiếc kèn đồng màu vàng chanh tươi sáng dưới nắng hè.","imageURL":"https://bionexus.vn/images/sarracenia-flava.jpg","referenceURL":"https://www.gbif.org/species/5421391"},{"id":400,"nodeId":404,"scientificName":"Sarracenia leucophylla","commonName":"Bình Tử Thảo Đầu Trắng","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 10-32°C, Độ ẩm: 60-80%, Môi trường: Đồng cỏ ngập nước ven rừng thông và đầm lầy đất cát chua","description":"Nữ hoàng sắc đẹp của chi Bình tử thảo Bắc Mỹ với phần đầu ống và chiếc nắp lượn sóng mang màu trắng sứ được thêu dệt bởi mạng lưới gân đỏ tía tinh xảo.","imageURL":"https://bionexus.vn/images/sarracenia-leucophylla.jpg","referenceURL":"https://www.gbif.org/species/5421380"},{"id":401,"nodeId":404,"scientificName":"Sarracenia psittacina","commonName":"Bình Tử Thảo Mỏ Vẹt","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-32°C, Độ ẩm: 65-85%, Môi trường: Đầm lầy ngập nước nông và trảng cỏ lầy thường xuyên bị ngập lũ","description":"Loài bình tử thảo có cơ chế bẫy mồi giống chiếc lờ bắt tôm duy nhất trong chi: các ống lá nằm rạp sát đất với chiếc đầu tròn khoằm như mỏ vẹt.","imageURL":"https://bionexus.vn/images/sarracenia-psittacina.jpg","referenceURL":"https://www.gbif.org/species/5421394"},{"id":402,"nodeId":404,"scientificName":"Sarracenia alata","commonName":"Bình Tử Thảo Nhạt (Yellow Trumpets)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 10-32°C, Độ ẩm: 60-80%, Môi trường: Trảng cỏ thông ẩm và đầm lầy thấm nước trên sườn đồi cát","description":"Loài bình tử thảo duy nhất mở rộng phân bố vượt sang phía tây sông Mississippi tới tận bang Texas, với những chiếc ống bẫy thanh mảnh màu vàng lục nhạt đến đỏ sẫm.","imageURL":"https://bionexus.vn/images/sarracenia-alata.jpg","referenceURL":"https://www.gbif.org/species/5421377"},{"id":403,"nodeId":404,"scientificName":"Sarracenia oreophila","commonName":"Bình Tử Thảo Xanh Núi (Green Pitcherplant)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 8-28°C, Độ ẩm: 60-80%, Môi trường: Bờ suối cát sa thạch và đầm lầy thấm nước trên núi","description":"Loài bình tử thảo nguy cấp nhất Bắc Mỹ với những chiếc ấm mùa xuân xanh mướt điểm gân tím ở cổ và tập tính thu mình thành lá dẹt hình lưỡi liềm khi hè khô nóng tới.","imageURL":"https://bionexus.vn/images/sarracenia-oreophila.jpg","referenceURL":"https://www.gbif.org/species/5421400"},{"id":404,"nodeId":405,"scientificName":"Darlingtonia californica","commonName":"Cây Nắp Ấm Rắn Hổ Mang (Loa Kèn Hổ Mang) (California Pitcher Plant)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 8-24°C, Độ ẩm: 65-85%, Môi trường: Đầm lầy và bờ suối có mạch nước ngầm lạnh mát chảy liên tục qua bộ rễ","description":"Loài duy nhất trong chi Darlingtonia với hình dáng giống hệt một con rắn hổ mang đang ngóc đầu phùng mang và thè chiếc lưỡi chẻ đôi màu đỏ lục đầy mật ngọt.","imageURL":"https://bionexus.vn/images/darlingtonia-californica.jpg","referenceURL":"https://www.gbif.org/species/5939805"},{"id":405,"nodeId":406,"scientificName":"Cephalotus follicularis","commonName":"Cây Ấm Đất Úc (Australian Pitcher Plant)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 12-26°C, Độ ẩm: 60-80%, Môi trường: Đầm lầy than bùn pha cát ẩm ven biển và bờ suối rỉ nước","description":"Loài duy nhất trong toàn bộ họ Ấm đất Úc (Cephalotaceae) — một kiệt tác tiến hóa hội tụ hoàn toàn độc lập với họ Nắp ấm — tạo ra những chiếc ấm nhỏ xinh như chiếc hài có răng cưa đỏ thẫm.","imageURL":"https://bionexus.vn/images/cephalotus-follicularis.jpg","referenceURL":"https://www.gbif.org/species/5576485"},{"id":406,"nodeId":407,"scientificName":"Drosera rotundifolia","commonName":"Cây Gọng Vó Lá Tròn (Common Sundew)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-26°C, Độ ẩm: 65-85%, Môi trường: Đầm lầy rêu than bùn Sphagnum ngập nắng và đất ngập nước nghèo dinh dưỡng","description":"Loài cây gọng vó nổi tiếng nhất trong lịch sử sinh học — từng được chính Charles Darwin nghiên cứu suốt nhiều năm — với những chiếc lá tròn phủ sương keo đỏ rực dưới nắng.","imageURL":"https://bionexus.vn/images/drosera-rotundifolia.jpg","referenceURL":"https://www.gbif.org/species/3191030"},{"id":407,"nodeId":407,"scientificName":"Drosera filiformis","commonName":"Cây Gọng Vó Lá Chỉ","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-28°C, Độ ẩm: 60-80%, Môi trường: Đầm lầy cát ẩm ven biển và trảng cỏ than bùn ngập nắng","description":"Loài gọng vó thanh mảnh với những chiếc lá vươn cao thẳng tắp như những sợi tơ hồng đính hàng nghìn viên pha lê sương lấp lánh dưới ánh mặt trời.","imageURL":"https://bionexus.vn/images/drosera-filiformis.jpg","referenceURL":"https://www.gbif.org/species/3191183"},{"id":408,"nodeId":407,"scientificName":"Drosera binata","commonName":"Cây Gọng Vó Lá Chẻ Đôi (Gọng Vó Sừng Hươu)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-28°C, Độ ẩm: 60-80%, Môi trường: Bờ suối cát ẩm, vách đá rỉ nước và đầm lầy ven biển","description":"Loài gọng vó cỡ lớn cực kỳ ấn tượng của châu Đại Dương với những chiếc lá chẻ đôi liên tiếp thành hình chiếc nĩa hoặc cặp sừng hươu giăng lưới bắt côn trùng.","imageURL":"https://bionexus.vn/images/drosera-binata.jpg","referenceURL":"https://www.gbif.org/species/3191053"},{"id":409,"nodeId":407,"scientificName":"Drosera indica","commonName":"Cây Gọng Vó Ấn Độ (Cỏ Trói Gà Lá Kim) (Indian Sundew)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 22-34°C, Độ ẩm: 60-85%, Môi trường: Trảng cát ẩm ngập nước theo mùa, bờ ruộng và đầm lầy đất thấp","description":"Loài gọng vó thân thảo một năm bản địa Việt Nam và nhiệt đới châu Á, có lá dài mảnh phủ lông keo lấp lánh và những bông hoa hồng phấn nở rộ dưới nắng mai.","imageURL":"https://bionexus.vn/images/drosera-indica.jpg","referenceURL":"https://www.gbif.org/species/3190722"},{"id":410,"nodeId":407,"scientificName":"Drosera adelae","commonName":"Cây Gọng Vó Lá Mác (Chị Em Rừng Mưa)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-28°C, Độ ẩm: 70-90%, Môi trường: Bờ suối đá râm mát ẩm ướt dưới tán rừng mưa nhiệt đới","description":"Một trong ba loài 'Gọng vó chị em vùng Queensland' nổi tiếng, sở hữu những phiến lá rộng hình lưỡi mác phủ sương keo và thích nghi hoàn hảo với ánh sáng dịu trong nhà.","imageURL":"https://bionexus.vn/images/drosera-adelae.jpg","referenceURL":"https://www.gbif.org/species/3191182"},{"id":411,"nodeId":407,"scientificName":"Drosera prolifera","commonName":"Cây Gọng Vó Lá Thận Đẻ Con","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-27°C, Độ ẩm: 75-92%, Môi trường: Vách đá rêu ẩm và bờ suối râm mát dưới tán rừng mưa nguyên sinh","description":"Thành viên thứ hai của bộ ba chị em Queensland với những chiếc lá hình trái tim tròn xinh xắn và tập tính sinh sản vô tính độc đáo ngay trên chóp ngồng hoa.","imageURL":"https://bionexus.vn/images/drosera-prolifera.jpg","referenceURL":"https://www.gbif.org/species/3191051"},{"id":412,"nodeId":407,"scientificName":"Drosera madagascariensis","commonName":"Cây Gọng Vó Thân Đứng Madagascar","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 60-85%, Môi trường: Đầm lầy than bùn ngập nắng và bờ suối cát ẩm vùng nhiệt đới","description":"Loài gọng vó nhiệt đới có dáng vươn cao độc đáo như một cây cột đỏ rực, sử dụng chính phần cuống của những chiếc lá già bên dưới làm trụ chống để vươn lên cao.","imageURL":"https://bionexus.vn/images/drosera-madagascariensis.jpg","referenceURL":"https://www.gbif.org/species/3191240"},{"id":413,"nodeId":407,"scientificName":"Drosera scorpioides","commonName":"Cây Gọng Vó Lùn Bọ Cạp","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-26°C, Độ ẩm: 55-75%, Môi trường: Trảng cát thạch nam và đất pha sét sỏi ẩm vào mùa đông","description":"Loài lớn nhất và ấn tượng nhất trong nhóm Gọng vó lùn Tây Úc, có những chiếc lá cong vòng phủ lông tuyến dài trông như chiếc càng và đuôi bọ cạp.","imageURL":"https://bionexus.vn/images/drosera-scorpioides.jpg","referenceURL":"https://www.gbif.org/species/3190919"},{"id":414,"nodeId":407,"scientificName":"Drosera gigantea","commonName":"Cây Gọng Vó Khổng Lồ (Gọng Vó Măng Tây)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-24°C, Độ ẩm: 55-75%, Môi trường: Đầm lầy cát ngập nước vào mùa đông và khô kiệt vào mùa hè","description":"Loài gọng vó dạng cây bụi thẳng đứng lớn nhất thế giới, mọc lên từ củ ngầm dưới lòng đất với chồi non trông giống hệt ngọn măng tây trước khi bung tán lá bắt mồi.","imageURL":"https://bionexus.vn/images/drosera-gigantea.jpg","referenceURL":"https://www.gbif.org/species/3191018"},{"id":415,"nodeId":407,"scientificName":"Drosera peltata","commonName":"Cây Gọng Vó Lá Khiên (Cỏ Trói Gà Củ)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 14-26°C, Độ ẩm: 60-80%, Môi trường: Đồi thông ẩm, trảng cỏ núi cao và đất cát ẩm theo mùa","description":"Loài gọng vó có củ duy nhất phân bố tự nhiên tại vùng cao nguyên Đà Lạt (Việt Nam), nổi bật với thân mảnh vươn cao đính những chiếc lá hình trăng khuyết lấp lánh sương.","imageURL":"https://bionexus.vn/images/drosera-peltata.jpg","referenceURL":"https://www.gbif.org/species/3190855"},{"id":416,"nodeId":408,"scientificName":"Aldrovanda vesiculosa","commonName":"Cây Bẫy Kẹp Nước (Bèo Bắt Mồi) (Bladderwort)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ nước: 20-30°C, Độ ẩm: 70-90%, pH: 5.5-6.8, Môi trường: Đầm nước ngọt nông ấm áp, giàu axit humic từ lá cói mục và nghèo nitơ","description":"Họ hàng thủy sinh duy nhất của cây Bẫy Kẹp Dionaea muscipula, trôi nổi lơ lửng dưới mặt nước như những vòng bánh xe xanh trong suốt với hàng trăm chiếc bẫy vỏ sò siêu nhạy.","imageURL":"https://bionexus.vn/images/aldrovanda-vesiculosa.jpg","referenceURL":"https://www.gbif.org/species/3190715"},{"id":417,"nodeId":409,"scientificName":"Pinguicula vulgaris","commonName":"Cây Bắt Ruồi Hoa Tím Thường (Common Butterwort)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-24°C, Độ ẩm: 65-85%, Môi trường: Đầm lầy than bùn, bờ suối núi đá vôi rỉ nước và đồng cỏ ẩm vùng núi","description":"Loài chuẩn của chi Cây bắt ruồi (Pinguicula) với những chiếc lá xếp hình sao biển phủ lớp dịch nhầy bóng mượt như bơ tươi và bông hoa tím biếc duyên dáng như hoa violet.","imageURL":"https://bionexus.vn/images/pinguicula-vulgaris.jpg","referenceURL":"https://www.gbif.org/species/5415065"},{"id":418,"nodeId":409,"scientificName":"Pinguicula lusitanica","commonName":"Cây Bắt Ruồi Bồ Đào Nha (Pale Butterwort)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-25°C, Độ ẩm: 65-85%, Môi trường: Đầm lầy than bùn ẩm ven biển Đại Tây Dương có khí hậu ôn hòa","description":"Loài bắt ruồi thu nhỏ của vùng duyên hải Tây Âu với các phiến lá cuộn mép điểm những đường gân đỏ tinh tế và những bông hoa nhỏ màu tím hồng họng vàng.","imageURL":"https://bionexus.vn/images/pinguicula-lusitanica.jpg","referenceURL":"https://www.gbif.org/species/5667916"},{"id":419,"nodeId":410,"scientificName":"Utricularia gibba","commonName":"Rong Ly Bướu (Humped Bladderwort)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 18-30°C, Độ ẩm: 70-95%, pH: 5.5-6.8, Môi trường: Ao hồ nước tĩnh, đầm lầy nông và ruộng ngập nước","description":"Loài thực vật ăn thịt có phạm vi phân bố rộng khắp thế giới và sở hữu bộ gen nhân nhỏ gọn bậc nhất trong tất cả các loài thực vật có hoa.","imageURL":"https://bionexus.vn/images/utricularia-gibba.jpg","referenceURL":"https://www.gbif.org/species/3172407"},{"id":420,"nodeId":410,"scientificName":"Utricularia aurea","commonName":"Rong Ly Hoa Vàng (Rong Trứng Chuối)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 20-32°C, Độ ẩm: 70-95%, pH: 5.5-6.8, Môi trường: Ao đầm nước ngọt tĩnh, kênh mương trong và ruộng lúa vùng trũng","description":"Loài rong ăn thịt bản địa quen thuộc của các đầm sen, ao súng Việt Nam với những tán lá xẻ mịn như lông chim chìm dưới nước và ngồng hoa vàng rực vươn cao trên mặt nước.","imageURL":"https://bionexus.vn/images/utricularia-aurea.jpg","referenceURL":"https://www.gbif.org/species/8001590"},{"id":421,"nodeId":410,"scientificName":"Utricularia vulgaris","commonName":"Rong Ly Lớn Châu Âu (Greater Bladderwort)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 12-26°C, Độ ẩm: 70-95%, pH: 5.5-6.8, Môi trường: Hồ nước ngọt tĩnh, đầm lầy than bùn và kênh nước sạch","description":"Một trong những loài rong ly thủy sinh lớn nhất thế giới với những chiếc túi bẫy chân không to tới 5 mm có thể nhìn thấy rõ bằng mắt thường khi nhấc cành rong lên.","imageURL":"https://bionexus.vn/images/utricularia-vulgaris.jpg","referenceURL":"https://www.gbif.org/species/3172427"},{"id":422,"nodeId":411,"scientificName":"Paphiopedilum delenatii","commonName":"Lan hài hồng (Delanat's Paphiopedilum)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 16-26°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Hốc mùn axit trên vách đá granit ẩm ven suối rừng thường xanh độ cao 700–1.300 m","description":"Niềm tự hào của hệ thực vật Việt Nam và là một trong số ít các loài lan hài châu Á sở hữu sắc hoa hồng phấn cùng hương thơm cam chanh thanh khiết.","imageURL":"https://bionexus.vn/images/paphiopedilum-delenatii.jpg","referenceURL":"https://www.gbif.org/species/2825640"},{"id":423,"nodeId":411,"scientificName":"Paphiopedilum rothschildianum","commonName":"Lan hài Rothschild (Rothschild's Paphiopedilum)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 16-27°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Vách đá siêu mafic (ultramafic) ẩm ven suối trong rừng núi thấp độ cao 500–1.200 m","description":"Được mệnh danh là 'Vua của các loài Lan Hài' với đôi cánh hoa sọc nâu đỏ giương ngang uy nghi như đôi cánh đại bàng đang sải lượn.","imageURL":"https://bionexus.vn/images/paphiopedilum-rothschildianum.jpg","referenceURL":"https://www.gbif.org/species/2825321"},{"id":424,"nodeId":411,"scientificName":"Paphiopedilum sanderianum","commonName":"Lan hài Sander (Sander's Paphiopedilum)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 20-29°C, Độ ẩm: 75-90%, pH: 5.5-7, Môi trường: Vách đá vôi dựng đứng ẩm ướt và râm mát ở độ cao 150–900 m","description":"Kỳ quan của họ Phong lan thế giới với hai cánh hoa bên buông rủ dài kỷ lục tới gần 1 mét như hai dải râu rồng uốn lượn trong gió.","imageURL":"https://bionexus.vn/images/paphiopedilum-sanderianum.jpg","referenceURL":"https://www.gbif.org/species/2825664"},{"id":425,"nodeId":411,"scientificName":"Paphiopedilum callosum","commonName":"Lan hài chai (Callus Paphiopedilum)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 16-27°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Đá tảng phủ mùn lá dày hoặc gốc cây mục trong rừng thường xanh núi thấp độ cao 300–1.300 m","description":"Loài lan hài rừng lá vân cẩm thạch rất đẹp của vùng Tây Nguyên với chiếc cánh đài lưng to tròn điểm các sọc gân màu rượu vang nổi bật.","imageURL":"https://bionexus.vn/images/paphiopedilum-callosum.jpg","referenceURL":"https://www.gbif.org/species/2825207"},{"id":426,"nodeId":411,"scientificName":"Paphiopedilum sukhakulii","commonName":"Lan hài Sukhakul (Sukhakul's Paphiopedilum)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 16-26°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Lớp mùn lá ẩm ven suối dưới tán rừng thường xanh núi đá sa thạch độ cao 800–1.000 m","description":"Loài lan hài đặc hữu của vùng núi Phu Luang (Thái Lan) dễ nhận diện nhờ hai cánh hoa mở ngang thẳng tắp điểm dày đặc chấm bi đen sẫm.","imageURL":"https://bionexus.vn/images/paphiopedilum-sukhakulii.jpg","referenceURL":"https://www.gbif.org/species/2825346"},{"id":427,"nodeId":411,"scientificName":"Paphiopedilum niveum","commonName":"Lan hài trắng tuyết (Snow-White Paphiopedilum)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 20-30°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Khe đá vôi ven biển hướng bắc/đông có gió biển mát và mùn lá mục độ cao 10–300 m","description":"Bông lan hài nhỏ nhắn mang sắc trắng ngần như tuyết điểm nhẹ bụi phấn tím trên nền bộ lá khảm vân xanh bạc dày dặn.","imageURL":"https://bionexus.vn/images/paphiopedilum-niveum.jpg","referenceURL":"https://www.gbif.org/species/2825192"},{"id":428,"nodeId":411,"scientificName":"Paphiopedilum bellatulum","commonName":"Lan hài xinh (Enchanting Paphiopedilum)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 15-26°C, Độ ẩm: 65-80%, pH: 5.5-7, Môi trường: Khe vách đá vôi ẩm râm mát có rêu phủ ở độ cao 800–1.600 m","description":"Loài lan hài thuộc nhóm Brachypetalum nổi tiếng với những cánh hoa tròn trịa ôm khum quanh chiếc túi môi như quả trứng chim đa đa.","imageURL":"https://bionexus.vn/images/paphiopedilum-bellatulum.jpg","referenceURL":"https://www.gbif.org/species/2825473"},{"id":429,"nodeId":411,"scientificName":"Paphiopedilum concolor","commonName":"Lan hài đồng màu (One Colored Paphiopedilum)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 18-29°C, Độ ẩm: 65-80%, pH: 5.5-7, Môi trường: Hốc đá vôi thấp thoáng sáng trong rừng karst nhiệt đới độ cao 100–1.000 m","description":"Loài lan hài đá vôi quen thuộc của Việt Nam với sắc hoa vàng ngà đồng nhất điểm những chấm bi tím nhỏ nhắn duyên dáng.","imageURL":"https://bionexus.vn/images/paphiopedilum-concolor.jpg","referenceURL":"https://www.gbif.org/species/2825331"},{"id":430,"nodeId":411,"scientificName":"Paphiopedilum armeniacum","commonName":"Lan hài vàng mơ (Apricot Orange Paphiopedilum)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 10-24°C, Độ ẩm: 65-80%, pH: 5.5-7, Môi trường: Vách đá vôi dốc đứng có lớp mùn mỏng ở độ cao 1.200–2.000 m","description":"Khi vừa được công bố năm 1982, loài lan hài này đã gây chấn động giới thực vật học bởi sắc vàng hoàng kim chói lọi chưa từng thấy ở chi Paphiopedilum.","imageURL":"https://bionexus.vn/images/paphiopedilum-armeniacum.jpg","referenceURL":"https://www.gbif.org/species/2825659"},{"id":431,"nodeId":411,"scientificName":"Paphiopedilum micranthum","commonName":"Lan hài hoa nhỏ (Tiny Flowered Paphiopedilum)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 10-24°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Khe đá vôi hướng bắc lạnh ẩm có rêu trong rừng núi cao 600–1.600 m","description":"Báu vật của núi đá vôi Đông Bắc Việt Nam với sự tương phản thú vị giữa đôi cánh hoa nhỏ nhắn và chiếc túi môi phồng căng mọng như quả bóng bay màu hồng phấn.","imageURL":"https://bionexus.vn/images/paphiopedilum-micranthum.jpg","referenceURL":"https://www.gbif.org/species/2825201"},{"id":432,"nodeId":411,"scientificName":"Paphiopedilum malipoense","commonName":"Lan hài xanh (Malipo Paphiopedilum)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 12-24°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Hốc mùn trên sườn núi đá vôi râm mát độ cao 700–1.500 m","description":"Loài lan hài quý hiếm mang sắc hoa xanh ngọc bích pha vân nâu hạt dẻ và tỏa hương thơm ngọt ngào như quả mâm xôi hay táo xanh.","imageURL":"https://bionexus.vn/images/paphiopedilum-malipoense.jpg","referenceURL":"https://www.gbif.org/species/2825273"},{"id":433,"nodeId":411,"scientificName":"Paphiopedilum insigne","commonName":"Lan hài rực rỡ (Splendid Paphiopedilum)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 12-24°C, Độ ẩm: 65-80%, pH: 5.5-7, Môi trường: Vách đá vôi và đá sa thạch ẩm cạnh thác nước ở độ cao 1.000–1.500 m","description":"Loài lan hài lịch sử được đưa về châu Âu từ năm 1819, nổi bật với toàn bộ bề mặt hoa như được phủ một lớp sơn mài bóng loáng.","imageURL":"https://bionexus.vn/images/paphiopedilum-insigne.jpg","referenceURL":"https://www.gbif.org/species/2825576"},{"id":434,"nodeId":411,"scientificName":"Paphiopedilum villosum","commonName":"Lan hài lông (Villose Paphiopedilum)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 12-25°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Bì sinh trên chạc cây cổ thụ nhiều rêu hoặc hốc đá rừng núi cao 1.100–2.000 m","description":"Một trong số ít các loài lan hài sống phụ sinh (bám cây) trên các thân gỗ lớn ở rừng sương mù Tây Nguyên và Tây Bắc Việt Nam.","imageURL":"https://bionexus.vn/images/paphiopedilum-villosum.jpg","referenceURL":"https://www.gbif.org/species/2825586"},{"id":435,"nodeId":411,"scientificName":"Paphiopedilum spicerianum","commonName":"Lan hài Spicer (Spicer’s Paphiopedilum)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 14-25°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Hốc đá vôi dựng đứng trên các hẻm núi sông suối độ cao 300–1.300 m","description":"Dễ dàng nhận diện ngay từ cái nhìn đầu tiên nhờ chiếc cánh đài lưng màu trắng muốt uốn cong như mái vòm có vạch sọc tím chạy dọc chính giữa.","imageURL":"https://bionexus.vn/images/paphiopedilum-spicerianum.jpg","referenceURL":"https://www.gbif.org/species/2825197"},{"id":436,"nodeId":411,"scientificName":"Paphiopedilum lowii","commonName":"Lan hài Low (Low's Paphiopedilum)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 18-28°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Phụ sinh trên cành cây cao hoặc vách đá vôi trong rừng nhiệt đới độ cao 200–1.600 m","description":"Loài lan hài nhiều hoa rực rỡ của quần đảo Mã Lai với hai cánh hoa xoắn duyên dáng, phần gốc vàng đốm nâu chuyển dần sang chóp muỗng màu tím lavender.","imageURL":"https://bionexus.vn/images/paphiopedilum-lowii.jpg","referenceURL":"https://www.gbif.org/species/2825644"},{"id":437,"nodeId":411,"scientificName":"Paphiopedilum philippinense","commonName":"Lan hài Philippines (Philippine Paphiopedilum)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 22-32°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Đá vôi ven biển đến sườn núi đá vôi thoáng nắng độ cao 0–500 m","description":"Loài lan hài chịu nhiệt và ưa sáng nổi tiếng của Philippines với những cánh hoa xoắn ốc màu đỏ tía buông rủ bên dưới cánh đài trắng sọc nâu.","imageURL":"https://bionexus.vn/images/paphiopedilum-philippinense.jpg","referenceURL":"https://www.gbif.org/species/2825516"},{"id":438,"nodeId":412,"scientificName":"Phragmipedium besseae","commonName":"Lan hài Besse (Besse's Phragmipedium)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 14-24°C, Độ ẩm: 75-90%, pH: 5.5-7, Môi trường: Vách đá granit ẩm ướt có nước rỉ liên tục cạnh thác nước độ cao 1.100–1.800 m","description":"Viên ngọc đỏ rực của dãy núi Andes Nam Mỹ, loài lan hài đã cách mạng hóa ngành lai tạo chi Phragmipedium nhờ sắc đỏ cam phát sáng.","imageURL":"https://bionexus.vn/images/phragmipedium-besseae.jpg","referenceURL":"https://www.gbif.org/species/2814289"},{"id":439,"nodeId":412,"scientificName":"Phragmipedium caudatum","commonName":"Lan hài đuôi dài (Tailed Phragmipedium)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 14-25°C, Độ ẩm: 70-85%, pH: 5.5-7, Môi trường: Phụ sinh trên cành cây phủ rêu hoặc vách đá ẩm ở độ cao 1.000–2.500 m","description":"Đối trọng Nam Mỹ của Lan Hài Râu Dài P. sanderianum với đôi cánh hoa xoắn như dải ruy-băng dài hơn nửa mét.","imageURL":"https://bionexus.vn/images/phragmipedium-caudatum.jpg","referenceURL":"https://www.gbif.org/species/2814310"},{"id":440,"nodeId":413,"scientificName":"Cypripedium calceolus","commonName":"Lan hài châu Âu (Lady's Slipper Orchid)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 5-22°C, Độ ẩm: 60-80%, pH: 5.5-7, Môi trường: Rừng lá rộng rụng lá và rừng thông thưa trên nền đất đá vôi ẩm mát","description":"Loài lan hài ôn đới biểu tượng của châu Âu với sự phối màu cổ điển giữa chiếc hài vàng tươi bóng bẩy và bộ cánh màu nâu hạt dẻ.","imageURL":"https://bionexus.vn/images/cypripedium-calceolus.jpg","referenceURL":"https://www.gbif.org/species/2820517"},{"id":441,"nodeId":413,"scientificName":"Cypripedium reginae","commonName":"Lan hài nữ hoàng (Showy Lady's Slipper)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 5-23°C, Độ ẩm: 65-85%, pH: 5.5-7, Môi trường: Đầm lầy rêu trung tính đến hơi kiềm và bờ rừng ẩm","description":"Một trong những loài lan địa sinh lộng lẫy nhất Bắc Mỹ và là quốc hoa của tiểu bang Minnesota (Hoa Kỳ).","imageURL":"https://bionexus.vn/images/cypripedium-reginae.jpg","referenceURL":"https://www.gbif.org/species/2820340"},{"id":442,"nodeId":413,"scientificName":"Cypripedium acaule","commonName":"Lan hài hồng Bắc Mỹ (Mocassin Flower)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 5-24°C, Độ ẩm: 60-80%, pH: 5.5-7, Môi trường: Rừng thông và rừng sồi có tầng đất mùn lá thông chua (pH 4.0–5.0)","description":"Loài lan hài rừng thông Bắc Mỹ đặc trưng bởi chiếc túi môi hồng gân đỏ xẻ dọc ở chính giữa thay vì có lỗ tròn phía trên như các loài khác.","imageURL":"https://bionexus.vn/images/cypripedium-acaule.jpg","referenceURL":"https://www.gbif.org/species/2820380"},{"id":443,"nodeId":413,"scientificName":"Cypripedium parviflorum","commonName":"Lan hài vàng Bắc Mỹ (American Yellow Lady's-slipper)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 5-24°C, Độ ẩm: 60-80%, pH: 5.5-7, Môi trường: Đầm lầy ẩm, trảng cỏ ven rừng và sườn đồi đất mùn giàu mùn lá","description":"Họ hàng Bắc Mỹ của Lan Hài Vàng Châu Âu với đôi cánh hoa bên xoắn tít như lọn tóc và tỏa hương thơm vani - táo nhẹ nhàng.","imageURL":"https://bionexus.vn/images/cypripedium-parviflorum.jpg","referenceURL":"https://www.gbif.org/species/2820475"},{"id":444,"nodeId":414,"scientificName":"Vanilla planifolia","commonName":"Lan vani","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 70-90%, pH: 5.5-7, Môi trường: Rừng mưa nhiệt đới đất thấp ẩm ướt nơi dây leo bám dọc thân cây gỗ","description":"Loài phong lan dây leo duy nhất được trồng làm cây hương liệu thương mại toàn cầu, cung cấp hương Vani tự nhiên quý giá từ quả nang lên men.","imageURL":"https://bionexus.vn/images/vanilla-planifolia.jpg","referenceURL":"https://www.gbif.org/species/2803398"},{"id":445,"nodeId":415,"scientificName":"Cattleya jongheana","commonName":"Lan Cattleya Jonghe","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 12-25°C, Độ ẩm: 65-85%, pH: 5.5-7, Môi trường: Khe đá thạch anh và thân cây Vellozia trên núi cao 1.300–1.600 m","description":"Viên ngọc quý của chi Lan Hoàng hậu (Cattleya) Brazil với kích thước hoa khổng lồ so với giả hành nhỏ nhắn và chiếc môi gợn sóng vàng kim rực rỡ.","imageURL":"https://bionexus.vn/images/cattleya-jongheana.jpg","referenceURL":"https://www.gbif.org/species/2811885"},{"id":446,"nodeId":416,"scientificName":"Dendrobium aphyllum","commonName":"Lan hạc vỹ","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-32°C, Độ ẩm: 60-85%, pH: 5.5-7, Môi trường: Bì sinh trên thân cây gỗ lớn trong rừng nửa rụng lá và rừng thường xanh độ cao 200–1.500 m","description":"Một trong những loài lan rừng thân thòng được yêu thích nhất tại Việt Nam, khi vào xuân sẽ rụng hết lá để bung nở những suối hoa màu hồng phấn dịu dàng.","imageURL":"https://bionexus.vn/images/dendrobium-aphyllum.jpg","referenceURL":"https://www.gbif.org/species/5316701"},{"id":447,"nodeId":417,"scientificName":"Astrophytum asterias","commonName":"Xương rồng sao biển (Sand Dollar Cactus)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Đồng bằng sỏi đá vôi khô hạn dưới tán cây bụi gai thấp độ cao 50–400 m","description":"Loài xương rồng không gai hoàn hảo về mặt hình học với 8 múi đối xứng và các hàng núm lông trắng xếp như vỏ cầu gai (nhím biển).","imageURL":"https://bionexus.vn/images/astrophytum-asterias.jpg","referenceURL":"https://www.gbif.org/species/5384219"},{"id":448,"nodeId":417,"scientificName":"Astrophytum myriostigma","commonName":"Xương rồng mũ giám mục","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Sườn đồi đá vôi khô cằn ở độ cao 750–2.200 m","description":"Biểu tượng kinh điển của dòng xương rồng nghệ thuật với hình khối ngôi sao 5 cánh không một chiếc gai nhọn và lớp vảy trắng bạc phản xạ ánh nắng sa mạc.","imageURL":"https://bionexus.vn/images/astrophytum-myriostigma.jpg","referenceURL":"https://www.gbif.org/species/7282451"},{"id":449,"nodeId":417,"scientificName":"Astrophytum capricorne","commonName":"Xương rồng sừng dê","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Đồi đá vôi sỏi thạch cao khô nóng độ cao 700–1.500 m","description":"Nổi bật với bộ gai dẹp dài uốn lượn xoắn ốc bao quanh đỉnh thân và bông hoa lớn màu vàng chanh có đáy họng đỏ tươi rực rỡ.","imageURL":"https://bionexus.vn/images/astrophytum-capricorne.jpg","referenceURL":"https://www.gbif.org/species/7282583"},{"id":450,"nodeId":417,"scientificName":"Astrophytum ornatum","commonName":"Xương rồng mũ thầy tu","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Vách đá vôi dựng đứng trong các hẻm núi bán hoang mạc độ cao 800–2.000 m","description":"Vị khổng lồ của chi Xương rồng Sao với thân hình trụ xoắn nhẹ được trang điểm bởi những dải chấm trắng tạo thành họa tiết hình học tuyệt đẹp.","imageURL":"https://bionexus.vn/images/astrophytum-ornatum.jpg","referenceURL":"https://www.gbif.org/species/7282413"},{"id":451,"nodeId":417,"scientificName":"Astrophytum caput-medusae","commonName":"Xương rồng đầu Medusa","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 16-35°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Trảng cây bụi gai Tamaulipan khô hạn ở độ cao 100–200 m","description":"Loài xương rồng có hình thái kỳ dị nhất thế giới khi không mang thân hình cầu hay hình trụ mà mọc thành chùm xúc tu dài vươn ra từ củ ngầm.","imageURL":"https://bionexus.vn/images/astrophytum-caput-medusae.jpg","referenceURL":"https://www.gbif.org/species/5623659"},{"id":452,"nodeId":418,"scientificName":"Lophophora williamsii","commonName":"Xương rồng peyote (Peyote)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Bán hoang mạc đá vôi dưới bóng cây bụi gai ở độ cao 100–1.900 m","description":"Loài xương rồng củ cái không gai màu xanh lam phấn sinh trưởng cực chậm trên sa mạc đá vôi Bắc Mỹ.","imageURL":"https://bionexus.vn/images/lophophora-williamsii.jpg","referenceURL":"https://www.gbif.org/species/5384220"},{"id":453,"nodeId":418,"scientificName":"Lophophora diffusa","commonName":"Xương rồng peyote Querétaro (Peyote)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Thung lũng đất sét đá vôi khô hạn ở độ cao 1.300–1.800 m","description":"Họ hàng đặc hữu vùng Querétaro của chi Lophophora với màu da xanh vàng tươi sáng và các núm thân xếp xoắn mềm mại không chia rãnh sâu.","imageURL":"https://bionexus.vn/images/lophophora-diffusa.jpg","referenceURL":"https://www.gbif.org/species/7282936"},{"id":454,"nodeId":419,"scientificName":"Ariocarpus retusus","commonName":"Xương rồng đá sống","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Đồi đá vôi sỏi trắng khô cằn ở độ cao 1.200–2.400 m","description":"Bậc thầy ngụy trang của sa mạc Mexico với các múi thân hóa sừng xám trắng trông hệt như những mảnh đá vôi góc cạnh nằm sát mặt đất.","imageURL":"https://bionexus.vn/images/ariocarpus-retusus.jpg","referenceURL":"https://www.gbif.org/species/3084099"},{"id":455,"nodeId":419,"scientificName":"Ariocarpus fissuratus","commonName":"Xương rồng đá nứt (Chautle-living Rock)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Sườn đồi đá vôi phẳng nắng gắt ở độ cao 600–1.600 m","description":"Đỉnh cao của tiến hóa ngụy trang (mimicry) trong giới thực vật khi bề mặt biểu bì có các rãnh nứt nẻ y hệt đá trầm tích bị nắng gió sa mạc bào mòn.","imageURL":"https://bionexus.vn/images/ariocarpus-fissuratus.jpg","referenceURL":"https://www.gbif.org/species/3084097"},{"id":456,"nodeId":419,"scientificName":"Ariocarpus kotschoubeyanus","commonName":"Xương rồng đá sống lùn","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Bãi bùn đất sét đá vôi phẳng ngập nước ngắn ngày vào mùa mưa ở độ cao 1.000–1.900 m","description":"Loài nhỏ nhắn nhất chi Xương rồng Đá sống, thường bị lớp bùn khô sa mạc phủ kín và chỉ lộ diện khi bông hoa tím hồng to bằng cả thân cây bung nở.","imageURL":"https://bionexus.vn/images/ariocarpus-kotschoubeyanus.jpg","referenceURL":"https://www.gbif.org/species/7283031"},{"id":457,"nodeId":419,"scientificName":"Ariocarpus trigonus","commonName":"Xương rồng đá sống ba cạnh","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Sườn đồi đá vôi và đá phiến khô cằn ở độ cao 500–1.400 m","description":"Khác biệt với hầu hết các loài Ariocarpus hoa tím hồng, loài này sở hữu những chiếc lá củ cong nhọn vươn cao và vòng hoa màu vàng ngà thanh nhã.","imageURL":"https://bionexus.vn/images/ariocarpus-trigonus.jpg","referenceURL":"https://www.gbif.org/species/7282951"},{"id":458,"nodeId":419,"scientificName":"Ariocarpus agavoides","commonName":"Xương rồng đá lá thùa (Tamaulipas Living Rock Cactus)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Đồi sỏi đá vôi khô hạn ở độ cao 1.100–1.300 m","description":"Mang hình dáng lai giữa một cây Thùa (Agave) thu nhỏ và một cây xương rồng củ với bông hoa tím hồng rực rỡ vươn lên từ búi lông trắng.","imageURL":"https://bionexus.vn/images/ariocarpus-agavoides.jpg","referenceURL":"https://www.gbif.org/species/7283173"},{"id":459,"nodeId":420,"scientificName":"Echinocactus platyacanthus","commonName":"Xương rồng thùng khổng lồ","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 12-36°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Bán hoang mạc đá vôi ở độ cao 1.100–2.400 m","description":"Một trong những loài xương rồng hình cầu lớn nhất thế giới, khi trưởng thành trông như một chiếc thùng rượu khổng lồ đầy gai giữa hoang mạc.","imageURL":"https://bionexus.vn/images/echinocactus-platyacanthus.jpg","referenceURL":"https://www.gbif.org/species/7279711"},{"id":460,"nodeId":420,"scientificName":"Echinocactus horizonthalonius","commonName":"Xương rồng khăn xếp (Turk's-head Cactus)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-36°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Sườn đồi sỏi đá vôi khô nắng ở độ cao 400–1.800 m","description":"Loài xương rồng cầu sa mạc nổi bật với lớp biểu bì phủ phấn xanh lam bạc và những chiếc gai lớn dẹp cong ôm ngang thân như móng vuốt đại bàng.","imageURL":"https://bionexus.vn/images/echinocactus-horizonthalonius.jpg","referenceURL":"https://www.gbif.org/species/3084090"},{"id":461,"nodeId":421,"scientificName":"Ferocactus latispinus","commonName":"Xương rồng lưỡi quỷ","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-35°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Đồng cỏ khô và sườn đồi đá núi lửa ở độ cao 1.500–2.500 m","description":"Được yêu thích nhất trong chi Xương rồng Thùng gai móc nhờ chiếc gai trung tâm dẹp to bản màu đỏ ruby cong xuống như chiếc lưỡi quỷ.","imageURL":"https://bionexus.vn/images/ferocactus-latispinus.jpg","referenceURL":"https://www.gbif.org/species/7284444"},{"id":462,"nodeId":421,"scientificName":"Ferocactus wislizeni","commonName":"Xương rồng thùng lưỡi câu (Fishhook Barrel Cactus)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 10-38°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Đồng bằng sỏi sa mạc và sườn đồi đá ở độ cao 200–1.600 m","description":"Loài xương rồng thùng biểu tượng của miền Viễn Tây Hoa Kỳ với những chiếc gai móc câu cứng cáp và vòng hoa cam đỏ rực rỡ trên đỉnh vào mùa hè.","imageURL":"https://bionexus.vn/images/ferocactus-wislizeni.jpg","referenceURL":"https://www.gbif.org/species/3084153"},{"id":463,"nodeId":421,"scientificName":"Ferocactus cylindraceus","commonName":"Xương rồng thùng California (California Barrel Cactus)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-38°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Vách đá hẻm núi và sườn đồi sỏi granit khô nóng độ cao 50–1.500 m","description":"Khi được tưới nước hoặc đón sương sớm, toàn bộ lớp gai dày của loài xương rồng này chuyển sang màu đỏ rực như ngọn đuốc giữa sa mạc Mojave.","imageURL":"https://bionexus.vn/images/ferocactus-cylindraceus.jpg","referenceURL":"https://www.gbif.org/species/3084150"},{"id":464,"nodeId":422,"scientificName":"Carnegiea gigantea","commonName":"Xương rồng khổng lồ Saguaro (Saguaro)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-40°C, Độ ẩm: 20-45%, pH: 6-7.8, Môi trường: Bình nguyên và sườn đồi đá sa mạc Sonoran độ cao 0–1.350 m","description":"Biểu tượng bất tử của sa mạc Bắc Mỹ và là loài xương rồng lớn nhất Hoa Kỳ, vươn cao như những tòa tháp sống với các cánh tay vươn thẳng lên bầu trời.","imageURL":"https://bionexus.vn/images/carnegiea-gigantea.jpg","referenceURL":"https://www.gbif.org/species/5384200"},{"id":465,"nodeId":423,"scientificName":"Cephalocereus senilis","commonName":"Xương rồng ông già (Old Man Cactus)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 12-35°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Vách đá vôi dốc đứng trong hẻm núi bán hoang mạc độ cao 1.000–2.000 m","description":"Loài xương rồng được yêu thích khắp thế giới nhờ bộ 'râu tóc' màu trắng bạc bồng bềnh che giấu những chiếc gai nhọn sắc bén bên dưới.","imageURL":"https://bionexus.vn/images/cephalocereus-senilis.jpg","referenceURL":"https://www.gbif.org/species/7283905"},{"id":466,"nodeId":424,"scientificName":"Mammillaria plumosa","commonName":"Xương rồng lông vũ","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 12-34°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Khe đá vôi dựng đứng ở độ cao 780–1.350 m","description":"Không có gai nhọn đâm tay, toàn bộ gai của loài xương rồng này biến đổi thành những chiếc lông vũ trắng muốt mềm mịn đan kết như bông tuyết.","imageURL":"https://bionexus.vn/images/mammillaria-plumosa.jpg","referenceURL":"https://www.gbif.org/species/5625311"},{"id":467,"nodeId":424,"scientificName":"Mammillaria hahniana","commonName":"Xương rồng bà già","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 12-34°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Sườn núi đá dốc đứng độ cao 750–2.200 m","description":"Cặp đôi hoàn hảo với Xương Rồng Ông Già, nổi bật với thân hình cầu tròn trịa khoác áo lông trắng bạc và đội vương miện hoa hồng cánh sen mỗi mùa xuân.","imageURL":"https://bionexus.vn/images/mammillaria-hahniana.jpg","referenceURL":"https://www.gbif.org/species/7280027"},{"id":468,"nodeId":424,"scientificName":"Mammillaria elongata","commonName":"Xương rồng ngón tay","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-35°C, Độ ẩm: 30-60%, pH: 6-7.8, Môi trường: Vách đá vôi và trảng cây bụi bán hoang mạc độ cao 1.300–2.300 m","description":"Một trong những loài xương rồng dễ trồng và siêng đẻ nhánh nhất, tạo thành từng cụm ngón tay phủ ren gai vàng óng ánh.","imageURL":"https://bionexus.vn/images/mammillaria-elongata.jpg","referenceURL":"https://www.gbif.org/species/8406968"},{"id":469,"nodeId":424,"scientificName":"Mammillaria bombycina","commonName":"Xương rồng gối tơ","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 10-32°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Sườn núi đá rừng sồi - thông khô ở độ cao 2.200–2.500 m","description":"Tên khoa học 'bombycina' có nghĩa là 'mượt như tơ tằm', miêu tả lớp lông trắng óng ả làm nền cho những chiếc gai móc màu hổ phách đỏ.","imageURL":"https://bionexus.vn/images/mammillaria-bombycina.jpg","referenceURL":"https://www.gbif.org/species/7281441"},{"id":470,"nodeId":424,"scientificName":"Mammillaria herrerae","commonName":"Xương rồng quả bóng golf (Golf ball)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 12-32°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Đồi đá vôi sỏi trắng ở độ cao 1.800–2.050 m","description":"Loài xương rồng mini quý hiếm trông giống hệt một quả bóng golf màu trắng tinh khôi với bông hoa hồng tím to lớn nở trên đỉnh.","imageURL":"https://bionexus.vn/images/mammillaria-herrerae.jpg","referenceURL":"https://www.gbif.org/species/7279962"},{"id":471,"nodeId":424,"scientificName":"Mammillaria luethyi","commonName":"Xương rồng Luethy","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 14-32°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Mặt phẳng đá vôi lộ thiên ở độ cao khoảng 800–1.000 m","description":"Một kiệt tác vi mô của họ Xương rồng với hàng trăm đốm gai hình bông hoa tuyết trắng mịn và bông hoa tím hồng có tâm trắng phát sáng.","imageURL":"https://bionexus.vn/images/mammillaria-luethyi.jpg","referenceURL":"https://www.gbif.org/species/5626189"},{"id":472,"nodeId":425,"scientificName":"Gymnocalycium mihanovichii","commonName":"Xương rồng mặt trăng","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-34°C, Độ ẩm: 35-65%, pH: 6-7.8, Môi trường: Dưới bóng cây bụi thưa trên đồng bằng đất cát bán khô hạn độ cao 50–500 m","description":"Loài xương rồng nổi tiếng nhất trong giới chơi cây đột biến màu (Variegated Gymno) với các múi thân có gờ ngang như bậc thang và hoa hình phễu thanh tao.","imageURL":"https://bionexus.vn/images/gymnocalycium-mihanovichii.jpg","referenceURL":"https://www.gbif.org/species/7282762"},{"id":473,"nodeId":425,"scientificName":"Gymnocalycium baldianum","commonName":"Xương rồng cằm hoa đỏ","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-32°C, Độ ẩm: 35-60%, pH: 6-7.8, Môi trường: Trảng cỏ núi cao nhiều đá ở độ cao 500–2.000 m","description":"Một trong số ít các loài thuộc chi Gymnocalycium sở hữu sắc hoa đỏ huyết dụ đến đỏ hồng rực rỡ thay vì màu trắng ngà thông thường.","imageURL":"https://bionexus.vn/images/gymnocalycium-baldianum.jpg","referenceURL":"https://www.gbif.org/species/7283488"},{"id":474,"nodeId":425,"scientificName":"Gymnocalycium saglionis","commonName":"Xương rồng cằm khổng lồ","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-35°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Sườn đồi đá khô hạn ở độ cao 500–2.600 m","description":"Vị khổng lồ của chi Xương rồng Nụ trần với các núm thân xếp xoắn ốc khỏe khoắn và bộ gai cong cứng cáp đổi màu đỏ sẫm mỗi khi được tưới nước.","imageURL":"https://bionexus.vn/images/gymnocalycium-saglionis.jpg","referenceURL":"https://www.gbif.org/species/7282338"},{"id":475,"nodeId":426,"scientificName":"Copiapoa cinerea","commonName":"Xương rồng tro Copiapoa","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-30°C, Độ ẩm: 30-60%, pH: 6-7.8, Môi trường: Sườn đồi đá ven biển nơi chỉ có sương mù đại dương Camanchaca độ cao 50–1.000 m","description":"Biểu tượng sống của sa mạc khô cằn nhất hành tinh (Atacama) với lớp da phủ sáp phấn trắng toát điểm những chiếc gai đen bóng như sừng.","imageURL":"https://bionexus.vn/images/copiapoa-cinerea.jpg","referenceURL":"https://www.gbif.org/species/7284333"},{"id":476,"nodeId":427,"scientificName":"Melocactus matanzanus","commonName":"Xương rồng mũ Thổ lùn (Dwarf Turk's Cap Cactus)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 18-34°C, Độ ẩm: 45-70%, pH: 6-7.8, Môi trường: Đồi đá serpentine khô thoáng gần bờ biển độ cao 50–300 m","description":"Loài xương rồng kỳ thú vùng biển Caribe: khi đạt độ tuổi trưởng thành, thân cầu xanh ngừng lớn để đội lên đầu một chiếc mũ nhung màu cam gạch chuyên dùng để nở hoa.","imageURL":"https://bionexus.vn/images/melocactus-matanzanus.jpg","referenceURL":"https://www.gbif.org/species/7280560"},{"id":477,"nodeId":428,"scientificName":"Obregonia denegrii","commonName":"Xương rồng atisô (Artichoke Cactus)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Sườn đồi đá vôi sỏi ở độ cao 750–1.200 m","description":"Loài duy nhất thuộc chi Obregonia, mang hình dáng độc đáo như một búp atisô thu nhỏ với các lá củ hình tam giác lật ngược.","imageURL":"https://bionexus.vn/images/obregonia-denegrii.jpg","referenceURL":"https://www.gbif.org/species/3947317"},{"id":478,"nodeId":429,"scientificName":"Pelecyphora aselliformis","commonName":"Xương rồng gai bọ","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 14-34°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Đồi đá vôi khô cằn ở độ cao 1.800–2.400 m","description":"Một trong những loài xương rồng có cấu trúc gai kỳ lạ nhất: các gai không mọc tỏa tròn mà xếp khít thành hai hàng răng lược trên đỉnh núm thân dẹp như lưỡi rìu.","imageURL":"https://bionexus.vn/images/pelecyphora-aselliformis.jpg","referenceURL":"https://www.gbif.org/species/7280604"},{"id":479,"nodeId":430,"scientificName":"Leuchtenbergia principis","commonName":"Xương rồng lá thùa (Leuchtenbergia)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 14-36°C, Độ ẩm: 25-50%, pH: 6-7.8, Môi trường: Đồng bằng và sườn đồi đá vôi khô hạn ở độ cao 1.400–2.000 m","description":"Loài duy nhất trong chi Leuchtenbergia, mang ngoại hình của một cây Thùa (Agave) nhưng lại nở ra những bông hoa xương rồng màu vàng tươi thơm ngát ở đầu lá.","imageURL":"https://bionexus.vn/images/leuchtenbergia-principis.jpg","referenceURL":"https://www.gbif.org/species/8383830"},{"id":480,"nodeId":431,"scientificName":"Opuntia microdasys","commonName":"Xương rồng tai thỏ","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-36°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Vùng bán hoang mạc và đồng cỏ khô độ cao 1.000–2.100 m","description":"Loài xương rồng cảnh quen thuộc bậc nhất với những bẹ thân tròn xinh xắn như cặp tai thỏ và các đốm chấm bi đều đặn.","imageURL":"https://bionexus.vn/images/opuntia-microdasys.jpg","referenceURL":"https://www.gbif.org/species/7283961"},{"id":481,"nodeId":432,"scientificName":"Schlumbergera truncata","commonName":"Hoa càng cua","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 15-28°C, Độ ẩm: 55-80%, pH: 6-7.8, Môi trường: Bì sinh trên cành cây rêu hoặc hốc đá ẩm trong rừng mưa nhiệt đới núi thấp 100–1.000 m","description":"Khác hẳn các loài xương rồng sa mạc, Tiểu Quỳnh là loài xương rồng rừng mưa sống bám cây và bung nở hàng trăm bông hoa lụa rực rỡ đúng dịp lễ cuối năm.","imageURL":"https://bionexus.vn/images/schlumbergera-truncata.jpg","referenceURL":"https://www.gbif.org/species/5383983"},{"id":482,"nodeId":433,"scientificName":"Epiphyllum oxypetalum","commonName":"Hoa quỳnh (Dutchman's Pipe Cactus)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 16-32°C, Độ ẩm: 60-85%, pH: 6-7.8, Môi trường: Phụ sinh trên cây gỗ lớn trong rừng nhiệt đới ẩm độ cao 0–1.800 m","description":"'Nữ hoàng bóng đêm' trong văn hóa thưởng hoa phương Đông với đóa hoa trắng muốt khổng lồ chỉ hé nở và tỏa hương thơm ngát suốt vài giờ đồng hồ trong đêm thanh vắng.","imageURL":"https://bionexus.vn/images/epiphyllum-oxypetalum.jpg","referenceURL":"https://www.gbif.org/species/5384031"},{"id":483,"nodeId":434,"scientificName":"Rhipsalis baccifera","commonName":"Xương rồng tầm gửi (Mistletoe Cactus)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 16-30°C, Độ ẩm: 60-85%, pH: 6-7.8, Môi trường: Phụ sinh buông rủ từ cành cây cổ thụ trong rừng mưa nhiệt đới độ cao 0–1.600 m","description":"Loài xương rồng tự nhiên duy nhất có phạm vi phân bố vượt qua Đại Tây Dương sang tới châu Phi và châu Á, tạo nên những bức rèm xanh mướt buông rủ từ tán rừng.","imageURL":"https://bionexus.vn/images/rhipsalis-baccifera.jpg","referenceURL":"https://www.gbif.org/species/3084036"},{"id":484,"nodeId":435,"scientificName":"Aloe arborescens","commonName":"Lô hội thân cây","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-35°C, Độ ẩm: 35-65%, pH: 6-7.8, Môi trường: Sườn núi đá và vách đá ven biển tới cao nguyên độ cao 0–2.000 m","description":"Loài lô hội bụi lớn nổi tiếng với sức sống mãnh liệt và những chùm hoa màu cam đỏ rực rỡ vươn cao như ngọn đuốc sưởi ấm mùa đông.","imageURL":"https://bionexus.vn/images/aloe-arborescens.jpg","referenceURL":"https://www.gbif.org/species/2777537"},{"id":485,"nodeId":436,"scientificName":"Euphorbia milii","commonName":"Xương rồng bát tiên","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 16-36°C, Độ ẩm: 40-75%, pH: 6-7.8, Môi trường: Rừng cây bụi khô trên sườn núi đá granit độ cao 200–1.500 m","description":"Loài cây cảnh phong thủy quen thuộc trong mọi khu vườn Việt Nam, nở hoa rực rỡ suốt bốn mùa trên nền thân gai khỏe khoắn.","imageURL":"https://bionexus.vn/images/euphorbia-milii.jpg","referenceURL":"https://www.gbif.org/species/3067157"},{"id":486,"nodeId":436,"scientificName":"Euphorbia decaryi","commonName":"Đại kích Decary","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 18-34°C, Độ ẩm: 35-60%, pH: 6-7.8, Môi trường: Rừng gai khô hạn trên nền đất cát và đá vôi ven biển độ cao 0–200 m","description":"Loài cây mọng nước nghệ thuật quý hiếm của Madagascar với những chiếc lá dày cứng có mép gợn sóng nhịp nhàng như đường viền kim loại đồng cổ.","imageURL":"https://bionexus.vn/images/euphorbia-decaryi.jpg","referenceURL":"https://www.gbif.org/species/3068904"},{"id":487,"nodeId":437,"scientificName":"Pachypodium lamerei","commonName":"Cọ Madagascar","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 16-36°C, Độ ẩm: 35-65%, pH: 6-7.8, Môi trường: Rừng khô hạn trên nền đá vôi và đá granit độ cao 50–800 m","description":"Dù mang tên 'Cọ Madagascar', loài cây này hoàn toàn không phải họ Cau dừa mà là một cây mọng nước thuộc họ Trúc đào (Apocynaceae) với hoa trắng thơm như hoa đại.","imageURL":"https://bionexus.vn/images/pachypodium-lamerei.jpg","referenceURL":"https://www.gbif.org/species/5535474"},{"id":488,"nodeId":437,"scientificName":"Pachypodium geayi","commonName":"Cọ Madagascar lá bạc","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 16-36°C, Độ ẩm: 30-60%, pH: 6-7.8, Môi trường: Bán hoang mạc đá vôi và cát đỏ độ cao 0–600 m","description":"Họ hàng cao lớn hơn của P. lamerei, phân biệt dễ dàng nhờ phiến lá hẹp dài như dải lụa mang ánh xám bạc và lớp lông nhung mịn màng.","imageURL":"https://bionexus.vn/images/pachypodium-geayi.jpg","referenceURL":"https://www.gbif.org/species/5535488"},{"id":489,"nodeId":437,"scientificName":"Pachypodium brevicaule","commonName":"Pachypodium thân ngắn","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 12-30°C, Độ ẩm: 30-55%, pH: 6-7.8, Môi trường: Bề mặt đá thạch anh (quartzite) lộ thiên ở độ cao 1.250–2.000 m","description":"Một trong những loài cây củ (caudiciform) độc đáo nhất thế giới khi toàn bộ thân gỗ rút ngắn thành một khối củ dẹp xám bạc nằm bẹp trên mặt đá như củ gừng hóa thạch.","imageURL":"https://bionexus.vn/images/pachypodium-brevicaule.jpg","referenceURL":"https://www.gbif.org/species/7155422"},{"id":490,"nodeId":438,"scientificName":"Adansonia grandidieri","commonName":"Bao báp Grandidier","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 18-36°C, Độ ẩm: 40-70%, pH: 6-7.8, Môi trường: Rừng rụng lá khô hạn và đồng bằng ven sông mùa lũ độ cao 0–100 m","description":"Biểu tượng thiên nhiên vĩ đại nhất của đảo quốc Madagascar, tạo nên 'Đại lộ Bao báp' (Allée des Baobabs) nổi tiếng toàn cầu.","imageURL":"https://bionexus.vn/images/adansonia-grandidieri.jpg","referenceURL":"https://www.gbif.org/species/5663154"},{"id":491,"nodeId":438,"scientificName":"Adansonia za","commonName":"Bao báp Za","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-36°C, Độ ẩm: 40-70%, pH: 6-7.8, Môi trường: Rừng khô rụng lá, savan và rừng gai ở độ cao 0–800 m","description":"Loài bao báp có phạm vi phân bố rộng nhất tại Madagascar, được người bản địa Sakalava tôn kính như cây thiêng của rừng khô.","imageURL":"https://bionexus.vn/images/adansonia-za.jpg","referenceURL":"https://www.gbif.org/species/5663122"},{"id":492,"nodeId":439,"scientificName":"Beaucarnea recurvata","commonName":"Cây chân voi (Stripy Ponytail)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 35-65%, pH: 6-7.8, Môi trường: Rừng khô nhiệt đới trên sườn núi đá vôi độ cao 200–900 m","description":"Loài cây nội thất và sân vườn cao cấp rất được ưa chuộng nhờ phần gốc củ phình to bề thế mang ý nghĩa tích tụ tài lộc và tán lá mềm mại buông rủ.","imageURL":"https://bionexus.vn/images/beaucarnea-recurvata.jpg","referenceURL":"https://www.gbif.org/species/2768035"},{"id":493,"nodeId":440,"scientificName":"Agave victoriae-reginae","commonName":"Thùa nữ hoàng Victoria","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-36°C, Độ ẩm: 25-55%, pH: 6-7.8, Môi trường: Vách đá vôi dốc đứng ở độ cao 800–2.000 m","description":"Được mệnh danh là 'Nữ hoàng của chi Thùa' với khối hoa thị tròn trịa hoàn hảo được vẽ những đường nét sơn trắng sắc sảo trên nền lá xanh lục đậm.","imageURL":"https://bionexus.vn/images/agave-victoriae-reginae.jpg","referenceURL":"https://www.gbif.org/species/2766696"},{"id":494,"nodeId":440,"scientificName":"Agave americana","commonName":"Thùa Mỹ","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-38°C, Độ ẩm: 25-65%, pH: 6-7.8, Môi trường: Đồng bằng bán hoang mạc và sườn đồi đá ở độ cao 100–2.500 m","description":"Loài Thùa cảnh quan hùng vĩ với những phiến lá dày màu xanh phấn bạc hoặc viền vàng uốn cong uyển chuyển.","imageURL":"https://bionexus.vn/images/agave-americana.jpg","referenceURL":"https://www.gbif.org/species/2767031"},{"id":495,"nodeId":441,"scientificName":"Pygathrix nemaeus","commonName":"Chà vá chân nâu (Red-shanked Douc Langur)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 18-32°C, Độ ẩm: 65-90%, Môi trường: Tán rừng thường xanh nguyên sinh và thứ sinh trên núi đá hoặc sườn đồi độ cao 0–1.600 m","description":"Được mệnh danh là 'Nữ hoàng của các loài linh trưởng' nhờ bộ lông năm màu rực rỡ tuyệt đẹp, đặc biệt dễ quan sát tại bán đảo Sơn Trà (Đà Nẵng).","imageURL":"https://bionexus.vn/images/pygathrix-nemaeus.jpg","referenceURL":"https://www.gbif.org/species/2436529"},{"id":496,"nodeId":441,"scientificName":"Pygathrix nigripes","commonName":"Chà vá chân đen (Black-shanked Douc Langur)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 20-34°C, Độ ẩm: 60-85%, Môi trường: Rừng thường xanh nhiệt đới, rừng nửa rụng lá và rừng khô ven biển độ cao 0–1.500 m","description":"Đại diện phương Nam của chi Voọc Chà Vá tại Việt Nam, nổi bật với khuôn mặt ánh xanh lam độc đáo và đôi chân đen tuyền săn chắc.","imageURL":"https://bionexus.vn/images/pygathrix-nigripes.jpg","referenceURL":"https://www.gbif.org/species/4267166"},{"id":497,"nodeId":442,"scientificName":"Trachypithecus delacouri","commonName":"Voọc mông trắng (Delacour's Langur)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 15-34°C, Độ ẩm: 65-90%, Môi trường: Rừng trên núi đá vôi dựng đứng (karst) ngập nước chân núi độ cao 10–600 m","description":"Loài linh trưởng đặc hữu chỉ có duy nhất tại Việt Nam với ngoại hình không thể nhầm lẫn nhờ mảng lông trắng muốt ở mông và đùi.","imageURL":"https://bionexus.vn/images/trachypithecus-delacouri.jpg","referenceURL":"https://www.gbif.org/species/4267062"},{"id":498,"nodeId":442,"scientificName":"Trachypithecus poliocephalus","commonName":"Voọc Cát Bà (Cat Ba Hooded Black Leaf Monkey)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 14-33°C, Độ ẩm: 70-90%, Môi trường: Vách núi đá vôi dựng đứng sát mặt biển vịnh Lan Hạ - Cát Bà độ cao 0–300 m","description":"Một trong những loài linh trưởng quý hiếm nhất hành tinh, chỉ tồn tại duy nhất trên các đảo đá vôi của Vườn quốc gia Cát Bà.","imageURL":"https://bionexus.vn/images/trachypithecus-poliocephalus.jpg","referenceURL":"https://www.gbif.org/species/7262019"},{"id":499,"nodeId":442,"scientificName":"Trachypithecus francoisi","commonName":"Voọc đen má trắng (François’s Langur)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 10-32°C, Độ ẩm: 65-85%, Môi trường: Rừng trên núi đá vôi karst nhiệt đới và cận nhiệt đới độ cao 100–1.500 m","description":"Loài voọc núi đá vôi phương Bắc sở hữu hai dải râu trắng chạy vắt qua má trông như một bộ ria mép quý tộc trên khuôn mặt đen.","imageURL":"https://bionexus.vn/images/trachypithecus-francoisi.jpg","referenceURL":"https://www.gbif.org/species/2436539"},{"id":500,"nodeId":442,"scientificName":"Trachypithecus germaini","commonName":"Voọc bạc Đông Dương (Indochinese Silvered Langur)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 22-34°C, Độ ẩm: 65-85%, Môi trường: Rừng ngập mặn ven biển, rừng tràm, rừng thường xanh đất thấp và núi đá vôi Kiên Lương độ cao 0–800 m","description":"Loài voọc khoác bộ lông màu xám tro ánh bạc thanh lịch và đôi mắt tròn hiền hậu, còn gọi là Voọc bạc Trường Sơn - Nam Bộ.","imageURL":"https://bionexus.vn/images/trachypithecus-germaini.jpg","referenceURL":"https://www.gbif.org/species/4267065"},{"id":501,"nodeId":443,"scientificName":"Nomascus leucogenys","commonName":"Vượn đen má trắng (Northern White-cheeked Gibbon)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 16-32°C, Độ ẩm: 70-90%, Môi trường: Tầng tán cao của rừng thường xanh nhiệt đới nguyên sinh độ cao 200–1.600 m","description":"Ca sĩ của đại ngàn Trường Sơn với đôi tay dài sải chuyền cành điêu luyện và sự dị hình giới tính rõ rệt giữa con đực đen và con cái vàng.","imageURL":"https://bionexus.vn/images/nomascus-leucogenys.jpg","referenceURL":"https://www.gbif.org/species/4267270"},{"id":502,"nodeId":443,"scientificName":"Nomascus gabriellae","commonName":"Vượn đen má vàng (Red-cheeked Gibbon)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 20-34°C, Độ ẩm: 65-85%, Môi trường: Tán rừng thường xanh và rừng nửa rụng lá nhiệt đới độ cao 100–1.500 m","description":"Loài vượn biểu tượng của rừng già Nam Trường Sơn và Cát Tiên, sống cả đời trên ngọn cây cao và gần như không bao giờ đặt chân xuống mặt đất.","imageURL":"https://bionexus.vn/images/nomascus-gabriellae.jpg","referenceURL":"https://www.gbif.org/species/4267267"},{"id":503,"nodeId":444,"scientificName":"Nycticebus pygmaeus","commonName":"Cu li nhỏ (Pygmy slow loris)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 16-32°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh thứ sinh, rừng tre nứa và rừng hỗn giao độ cao 0–1.500 m","description":"Loài linh trưởng kiếm ăn đêm nhỏ bé nhất Việt Nam với đôi mắt to tròn long lanh phản chiếu ánh sáng trong bóng tối.","imageURL":"https://bionexus.vn/images/nycticebus-pygmaeus.jpg","referenceURL":"https://www.gbif.org/species/2436628"},{"id":504,"nodeId":444,"scientificName":"Nycticebus bengalensis","commonName":"Cu li lớn (Bengal Slow Loris)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 16-32°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh nhiệt đới, rừng bán thường xanh độ cao 0–2.000 m","description":"Loài cu li có kích thước lớn nhất chi Nycticebus, di chuyển chậm rãi không một tiếng động trên cành cây vào ban đêm.","imageURL":"https://bionexus.vn/images/nycticebus-bengalensis.jpg","referenceURL":"https://www.gbif.org/species/4267329"},{"id":505,"nodeId":445,"scientificName":"Macaca arctoides","commonName":"Khỉ mặt đỏ (Stump-tailed Macaque)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 12-32°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh núi thấp và núi cao, thường kiếm ăn nhiều trên nền đất rừng độ cao 100–2.500 m","description":"Loài khỉ to khỏe có chiếc đuôi cụt sát mông và khuôn mặt đỏ bừng càng đậm màu hơn khi trưởng thành hoặc khi tiếp xúc với ánh nắng.","imageURL":"https://bionexus.vn/images/macaca-arctoides.jpg","referenceURL":"https://www.gbif.org/species/2436605"},{"id":506,"nodeId":445,"scientificName":"Macaca leonina","commonName":"Khỉ đuôi lợn (Northern Pig-tailed Macaque)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 16-34°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh, rừng tre nứa và rừng nửa rụng lá độ cao 50–2.000 m","description":"Loài khỉ thông minh có chiếc đuôi ngắn cong vểnh lên trên giống đuôi lợn và hệ thống biểu cảm nét mặt giao tiếp xã hội rất phong phú.","imageURL":"https://bionexus.vn/images/macaca-leonina.jpg","referenceURL":"https://www.gbif.org/species/4267148"},{"id":507,"nodeId":445,"scientificName":"Macaca assamensis","commonName":"Khỉ mốc (Assamese Macaque)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 8-30°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh trên núi đá vôi và rừng sương mù núi cao độ cao 200–2.700 m","description":"Loài khỉ vùng núi cao phương Bắc có bộ lông dày ấm áp ánh xám mốc để thích nghi với cái lạnh sương mù trên các dãy núi đá vôi.","imageURL":"https://bionexus.vn/images/macaca-assamensis.jpg","referenceURL":"https://www.gbif.org/species/2436610"},{"id":508,"nodeId":446,"scientificName":"Tragulus kanchil","commonName":"Cheo cheo Nam Dương (Lesser Oriental Chevrotain)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-34°C, Độ ẩm: 70-90%, Môi trường: Tầng dưới rừng mưa nhiệt đới đất thấp, rừng tre nứa và bìa rừng ẩm độ cao 0–1.000 m","description":"Loài thú móng guốc nhỏ bé chỉ nặng chưa đầy 2 kilôgam, nổi tiếng trong văn học dân gian Đông Nam Á bởi sự nhanh nhẹn và khôn ngoan.","imageURL":"https://bionexus.vn/images/tragulus-kanchil.jpg","referenceURL":"https://www.gbif.org/species/7261464"},{"id":509,"nodeId":447,"scientificName":"Rusa unicolor","commonName":"Nai (Sambar)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 15-34°C, Độ ẩm: 60-85%, Môi trường: Rừng thường xanh, rừng khộp rụng lá và trảng cỏ ven suối trong rừng độ cao 0–3.000 m","description":"Loài thú ăn cỏ cỡ lớn uy nghi của rừng già Việt Nam, đóng vai trò sinh thái then chốt trong việc duy trì các trảng cỏ tự nhiên dưới tán rừng.","imageURL":"https://bionexus.vn/images/rusa-unicolor.jpg","referenceURL":"https://www.gbif.org/species/7261386"},{"id":510,"nodeId":448,"scientificName":"Bos javanicus","commonName":"Bò rừng (Banteng)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 20-36°C, Độ ẩm: 55-85%, Môi trường: Rừng khộp rụng lá thưa (Dipterocarp), trảng cỏ savan và rừng hỗn giao độ cao 0–1.500 m","description":"Biểu tượng hoang dã của hệ sinh thái rừng khộp Tây Nguyên với thân hình vạm vỡ, cặp sừng cong vút và bốn chiếc tất trắng cùng mảng mông trắng nổi bật.","imageURL":"https://bionexus.vn/images/bos-javanicus.jpg","referenceURL":"https://www.gbif.org/species/2441027"},{"id":511,"nodeId":449,"scientificName":"Capricornis milneedwardsii","commonName":"Sơn dương (Mainland serow)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 10-32°C, Độ ẩm: 60-85%, Môi trường: Vách núi đá vôi (karst) dựng đứng hiểm trở có rừng che phủ độ cao 200–3.500 m","description":"Bậc thầy leo trèo trên các vách núi đá vôi dựng đứng của Việt Nam với cặp móng guốc có đệm đàn hồi bám chặt vào những gờ đá chỉ rộng vài phân.","imageURL":"https://bionexus.vn/images/capricornis-milneedwardsii.jpg","referenceURL":"https://www.gbif.org/species/7261423"},{"id":512,"nodeId":450,"scientificName":"Elephas maximus","commonName":"Voi châu Á (Asian Elephant)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 18-36°C, Độ ẩm: 60-85%, Môi trường: Rừng thường xanh, rừng khộp, rừng tre nứa và thung lũng sông suối độ cao 0–2.000 m","description":"Loài thú trên cạn vĩ đại nhất châu Á và là biểu tượng văn hóa lâu đời của vùng Tây Nguyên Việt Nam.","imageURL":"https://bionexus.vn/images/elephas-maximus.jpg","referenceURL":"https://www.gbif.org/species/5219461"},{"id":513,"nodeId":451,"scientificName":"Manis javanica","commonName":"Tê tê Java (Sunda Pangolin)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 20-34°C, Độ ẩm: 65-90%, Môi trường: Rừng thường xanh nhiệt đới, rừng thứ sinh và rừng khộp có nhiều tổ kiến, mối độ cao 0–1.500 m","description":"Loài thú có vảy độc đáo duy nhất trên thế giới, khi gặp nguy hiểm sẽ cuộn tròn thành một quả cầu giáp sừng kín mít không thú ăn thịt nào cắn thủng được.","imageURL":"https://bionexus.vn/images/manis-javanica.jpg","referenceURL":"https://www.gbif.org/species/5219628"},{"id":514,"nodeId":451,"scientificName":"Manis pentadactyla","commonName":"Tê tê vàng (Chinese Pangolin)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 12-32°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh cận nhiệt đới, rừng hỗn giao và rừng tre nứa trên đồi núi độ cao 100–2.000 m","description":"Đại diện phương Bắc của họ Tê tê tại Việt Nam, chuyên sống trên mặt đất và đào những đường hầm sâu tới 4–5 mét vào lòng đồi để bắt mối ngầm.","imageURL":"https://bionexus.vn/images/manis-pentadactyla.jpg","referenceURL":"https://www.gbif.org/species/5219638"},{"id":515,"nodeId":452,"scientificName":"Arctictis binturong","commonName":"Cầy mực (Binturong)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 18-34°C, Độ ẩm: 70-90%, Môi trường: Tầng tán cao của rừng mưa nhiệt đới nguyên sinh nhiều cây sung vả độ cao 0–1.500 m","description":"Loài lớn nhất trong họ Cầy (Viverridae) với ngoại hình lai giữa một chú gấu đen nhỏ và một con mèo rừng cùng chiếc đuôi cuốn thứ năm độc đáo.","imageURL":"https://bionexus.vn/images/arctictis-binturong.jpg","referenceURL":"https://www.gbif.org/species/2434615"},{"id":516,"nodeId":453,"scientificName":"Catopuma temminckii","commonName":"Báo lửa (Asian Golden Cat)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 12-34°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh nhiệt đới, rừng đá vôi và rừng rụng lá độ cao 0–3.000 m","description":"Loài mèo hoang dã cỡ trung tuyệt đẹp của rừng già châu Á với bộ lông màu vàng đồng đến đỏ hung rực rỡ và đôi chân dài thanh thoát.","imageURL":"https://bionexus.vn/images/catopuma-temminckii.jpg","referenceURL":"https://www.gbif.org/species/2435094"},{"id":517,"nodeId":454,"scientificName":"Pardofelis marmorata","commonName":"Mèo gấm (Marbled Cat)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 15-32°C, Độ ẩm: 70-90%, Môi trường: Tán rừng thường xanh nhiệt đới ẩm nguyên sinh độ cao 100–2.500 m","description":"Bản sao thu nhỏ hoàn hảo của Báo Gấm với bộ lông họa tiết đá cẩm thạch và chiếc đuôi bông xù cực dài giúp giữ thăng bằng trên cành cây cao.","imageURL":"https://bionexus.vn/images/pardofelis-marmorata.jpg","referenceURL":"https://www.gbif.org/species/2435089"},{"id":518,"nodeId":455,"scientificName":"Prionailurus viverrinus","commonName":"Mèo cá (Fishing Cat)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 20-35°C, Độ ẩm: 70-90%, Môi trường: Rừng ngập mặn, đầm lầy lau sậy, rừng tràm và ven sông suối đất thấp độ cao 0–500 m","description":"Loài mèo hoang dã phá vỡ định kiến 'mèo sợ nước', chuyên lặn ngụp săn cá điêu luyện trong các đầm lầy và rừng ngập mặn.","imageURL":"https://bionexus.vn/images/prionailurus-viverrinus.jpg","referenceURL":"https://www.gbif.org/species/2434899"},{"id":519,"nodeId":455,"scientificName":"Prionailurus bengalensis","commonName":"Mèo rừng (Mainland Leopard Cat)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-35°C, Độ ẩm: 60-85%, Môi trường: Rừng thường xanh, rừng thứ sinh, rừng ngập mặn và bìa rừng độ cao 0–3.000 m","description":"Loài mèo hoang dã có phạm vi phân bố rộng nhất châu Á với bộ lông đốm hoa báo tuyệt đẹp và khả năng thích nghi cao từ rừng ngập mặn đến núi cao.","imageURL":"https://bionexus.vn/images/prionailurus-bengalensis.jpg","referenceURL":"https://www.gbif.org/species/2434903"},{"id":520,"nodeId":456,"scientificName":"Neofelis nebulosa","commonName":"Báo gấm (Clouded Leopard)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 14-34°C, Độ ẩm: 65-90%, Môi trường: Rừng thường xanh nhiệt đới nguyên sinh rậm rạp độ cao 100–2.500 m","description":"Sát thủ thầm lặng trên tán rừng già châu Á với bộ lông họa tiết đám mây huyền ảo và cấu trúc hộp sọ tiến hóa độc lập giữa nhóm đại miêu và tiểu miêu.","imageURL":"https://bionexus.vn/images/neofelis-nebulosa.jpg","referenceURL":"https://www.gbif.org/species/2435079"},{"id":521,"nodeId":457,"scientificName":"Helarctos malayanus","commonName":"Gấu chó (Sun Bear)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 18-34°C, Độ ẩm: 65-90%, Môi trường: Rừng mưa nhiệt đới đất thấp và rừng thường xanh núi thấp độ cao 0–1.500 m","description":"Loài gấu nhỏ nhắn nhất thế giới, dành phần lớn thời gian leo trèo trên cây cao để tìm tổ ong mật và quả rừng chín.","imageURL":"https://bionexus.vn/images/helarctos-malayanus.jpg","referenceURL":"https://www.gbif.org/species/2433403"},{"id":522,"nodeId":458,"scientificName":"Ursus thibetanus","commonName":"Gấu ngựa (Asiatic Black Bear)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 5-32°C, Độ ẩm: 60-85%, Môi trường: Rừng thường xanh núi cao, rừng sồi dẻ và rừng hỗn giao độ cao 200–3.500 m","description":"Loài gấu lớn mang biểu tượng vầng trăng khuyết màu trắng ngà nổi bật trước ngực và đôi tai tròn lớn dựng cao.","imageURL":"https://bionexus.vn/images/ursus-thibetanus.jpg","referenceURL":"https://www.gbif.org/species/9335699"},{"id":523,"nodeId":459,"scientificName":"Cuon alpinus","commonName":"Sói đỏ (Dhole)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 10-35°C, Độ ẩm: 55-85%, Môi trường: Rừng thường xanh, rừng khộp rụng lá và trảng cỏ xen rừng độ cao 0–3.000 m","description":"Thợ săn bầy đàn kiệt xuất của rừng già châu Á với bộ lông đỏ hung như lửa và tinh thần hợp tác săn mồi kỷ luật cao.","imageURL":"https://bionexus.vn/images/cuon-alpinus.jpg","referenceURL":"https://www.gbif.org/species/2434317"},{"id":524,"nodeId":460,"scientificName":"Lutrogale perspicillata","commonName":"Rái cá lông mượt (Smooth-coated Otter)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 18-35°C, Độ ẩm: 70-90%, Môi trường: Sông lớn, hồ nước ngọt, rừng tràm ngập nước và rừng ngập mặn ven biển độ cao 0–1.000 m","description":"Kình ngư săn cá số một của các vùng đất ngập nước Đông Nam Á với bộ lông mượt mà ôm sát cơ thể thủy động học.","imageURL":"https://bionexus.vn/images/lutrogale-perspicillata.jpg","referenceURL":"https://www.gbif.org/species/2433686"},{"id":525,"nodeId":461,"scientificName":"Ratufa bicolor","commonName":"Sóc đen (Black Giant Squirrel)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 15-32°C, Độ ẩm: 65-85%, Môi trường: Tầng tán cao của rừng thường xanh nhiệt đới và cận nhiệt đới độ cao 0–2.000 m","description":"Một trong những loài sóc cây lớn nhất hành tinh với chiếc đuôi dài hơn nửa mét buông rủ xuống dưới cành cây khi nghỉ ngơi.","imageURL":"https://bionexus.vn/images/ratufa-bicolor.jpg","referenceURL":"https://www.gbif.org/species/2437566"},{"id":526,"nodeId":462,"scientificName":"Petaurista philippensis","commonName":"Sóc bay lớn (Indian Giant Flying Squirrel)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 14-32°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh lá rộng và rừng hỗn giao có nhiều cây cổ thụ rỗng thân độ cao 100–2.200 m","description":"Tàu lượn bóng đêm của rừng già nhiệt đới với khả năng căng màng da lượn êm ru hàng chục mét giữa các ngọn cây cao.","imageURL":"https://bionexus.vn/images/petaurista-philippensis.jpg","referenceURL":"https://www.gbif.org/species/5219697"},{"id":527,"nodeId":463,"scientificName":"Lophura edwardsi","commonName":"Gà lôi lam mào trắng (Vietnam Pheasant)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 18-32°C, Độ ẩm: 75-90%, Môi trường: Tầng dưới rừng thường xanh mưa ẩm đất thấp và chân núi độ cao 0–600 m","description":"Báu vật đặc hữu cực kỳ quý hiếm của rừng mưa Bắc Trung Bộ Việt Nam với bộ lông xanh tím ánh thép lấp lánh và chiếc mào trắng thanh lịch.","imageURL":"https://bionexus.vn/images/lophura-edwardsi.jpg","referenceURL":"https://www.gbif.org/species/5227960"},{"id":528,"nodeId":463,"scientificName":"Lophura nycthemera","commonName":"Gà lôi trắng (Silver Pheasant)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 12-30°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh núi thấp và núi cao, rừng tre nứa độ cao 200–2.100 m","description":"Loài chim trĩ tuyệt đẹp của các khu rừng già Việt Nam, từng được chọn làm hình tượng thêu trên phẩm phục quan văn hàm Ngũ phẩm thời phong kiến.","imageURL":"https://bionexus.vn/images/lophura-nycthemera.jpg","referenceURL":"https://www.gbif.org/species/5227966"},{"id":529,"nodeId":463,"scientificName":"Lophura diardi","commonName":"Gà lôi hông tía (Siamese Fireback)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 20-34°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh đất thấp, rừng bán thường xanh và rừng tre nứa độ cao 0–800 m","description":"Một trong những loài gà lôi đẹp nhất Đông Dương với chùm mào hình giọt nước trên đỉnh đầu và mảng lông lưng ánh vàng rực lửa chỉ lộ ra khi vỗ cánh.","imageURL":"https://bionexus.vn/images/lophura-diardi.jpg","referenceURL":"https://www.gbif.org/species/5227987"},{"id":530,"nodeId":464,"scientificName":"Polyplectron bicalcaratum","commonName":"Gà tiền mặt vàng (Grey Peacock-Pheasant)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-32°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh rậm rạp và rừng hỗn giao tre nứa độ cao 100–1.800 m","description":"Khi xòe tròn bộ cánh và đuôi để tán tỉnh bạn tình, Gà Tiền Mặt Vàng biến thành một chiếc quạt khổng lồ đính hàng chục viên ngọc bích phát sáng.","imageURL":"https://bionexus.vn/images/polyplectron-bicalcaratum.jpg","referenceURL":"https://www.gbif.org/species/2474079"},{"id":531,"nodeId":465,"scientificName":"Pavo muticus","commonName":"Công (Green Peafowl)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 20-36°C, Độ ẩm: 55-85%, Môi trường: Rừng khộp rụng lá, rừng bán thường xanh gần sông suối và trảng cỏ độ cao 0–1.000 m","description":"Loài chim đẹp và lộng lẫy bậc nhất hệ động vật Việt Nam với bộ lông xanh ngọc lục bảo dát vàng kim khác biệt hoàn toàn với Công lam Ấn Độ.","imageURL":"https://bionexus.vn/images/pavo-muticus.jpg","referenceURL":"https://www.gbif.org/species/2473599"},{"id":532,"nodeId":466,"scientificName":"Buceros bicornis","commonName":"Hồng hoàng (Great Hornbill)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 18-34°C, Độ ẩm: 65-90%, Môi trường: Tán rừng thường xanh nhiệt đới nguyên sinh có nhiều cây cổ thụ họ Dầu độ cao 0–1.500 m","description":"Chúa tể bầu trời rừng già nhiệt đới với chiếc mũ sừng màu vàng tươi uy nghi và tiếng đập cánh phần phật vang dội như đoàn tàu chạy qua tán rừng.","imageURL":"https://bionexus.vn/images/buceros-bicornis.jpg","referenceURL":"https://www.gbif.org/species/2476012"},{"id":533,"nodeId":467,"scientificName":"Aceros nipalensis","commonName":"Niệc cổ hung (Rufous-necked Hornbill)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 10-28°C, Độ ẩm: 70-90%, Môi trường: Rừng thường xanh lá rộng núi cao nguyên sinh độ cao 600–2.200 m","description":"Một trong những loài chim họ Hồng hoàng có màu sắc rực rỡ nhất châu Á với sự phối hợp táo bạo giữa cổ cam lửa, viền mắt xanh lam và mỏ ngà sọc đen.","imageURL":"https://bionexus.vn/images/aceros-nipalensis.jpg","referenceURL":"https://www.gbif.org/species/5228459"},{"id":534,"nodeId":468,"scientificName":"Anthracoceros albirostris","commonName":"Cao cát bụng trắng (Oriental Pied Hornbill)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-35°C, Độ ẩm: 65-85%, Môi trường: Rừng thường xanh, rừng thứ sinh, rừng ngập mặn và đảo ven biển độ cao 0–1.200 m","description":"Loài hồng hoàng cỡ trung phổ biến và lanh lợi nhất trong các khu rừng Việt Nam, góp phần phát tán hạt giống tái sinh rừng tự nhiên.","imageURL":"https://bionexus.vn/images/anthracoceros-albirostris.jpg","referenceURL":"https://www.gbif.org/species/2475991"},{"id":535,"nodeId":469,"scientificName":"Grus antigone","commonName":"Sếu đầu đỏ (Sarus Crane)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 20-36°C, Độ ẩm: 60-85%, Môi trường: Đồng cỏ ngập nước theo mùa có nhiều cây năng kim (Eleocharis) và đầm lầy đất thấp độ cao 0–300 m","description":"Loài chim biết bay cao lớn nhất hành tinh và là biểu tượng sinh thái thiêng liêng của vùng đất ngập nước Đồng Tháp Mười (Vườn quốc gia Tràm Chim).","imageURL":"https://bionexus.vn/images/grus-antigone.jpg","referenceURL":"https://www.gbif.org/species/2474945"},{"id":536,"nodeId":470,"scientificName":"Leptoptilos javanicus","commonName":"Già đẫy nhỏ (Lesser Adjutant)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 22-36°C, Độ ẩm: 65-85%, Môi trường: Rừng ngập mặn ven biển, bãi bùn cửa sông và đầm lầy rừng tràm độ cao 0–300 m","description":"Loài chim họ Hạc khổng lồ với dáng đi khoan thai nghiêm nghị như một sĩ quan quân đội, gắn liền với các hệ sinh thái đất ngập nước Nam Bộ.","imageURL":"https://bionexus.vn/images/leptoptilos-javanicus.jpg","referenceURL":"https://www.gbif.org/species/2481947"},{"id":537,"nodeId":471,"scientificName":"Mycteria leucocephala","commonName":"Cò lạo Ấn Độ (Painted Stork)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-36°C, Độ ẩm: 60-85%, Môi trường: Đầm lầy nước ngọt nông, cánh đồng ngập nước và rừng ngập mặn độ cao 0–300 m","description":"Loài cò hạc tuyệt đẹp với chùm lông cánh và lông đuôi nhuộm màu hồng cánh sen tươi thắm như một bức tranh thủy mặc.","imageURL":"https://bionexus.vn/images/mycteria-leucocephala.jpg","referenceURL":"https://www.gbif.org/species/2481938"},{"id":538,"nodeId":472,"scientificName":"Platalea minor","commonName":"Cò thìa (Black-faced Spoonbill)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 10-30°C, Độ ẩm: 65-85%, Môi trường: Bãi bồi cửa sông ven biển, rừng ngập mặn và đầm nuôi trồng thủy sản quảng canh độ cao 0–50 m","description":"Loài chim di cư quý hiếm bậc nhất đường bay Đông Á - Úc, hàng năm bay hàng ngàn kilômét về trú đông tại Vườn quốc gia Xuân Thủy (Nam Định).","imageURL":"https://bionexus.vn/images/platalea-minor.jpg","referenceURL":"https://www.gbif.org/species/2480805"},{"id":539,"nodeId":473,"scientificName":"Houbaropsis bengalensis","commonName":"Ô tác (Bengal Florican)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 20-36°C, Độ ẩm: 55-85%, Môi trường: Đồng cỏ tự nhiên ngập nước theo mùa xen trảng cây bụi thấp độ cao 0–300 m","description":"Một trong những loài chim đồng cỏ nguy cấp nhất thế giới, đại diện duy nhất của bộ Ô tác (Otidiformes) có mặt tại Đông Nam Á.","imageURL":"https://bionexus.vn/images/houbaropsis-bengalensis.jpg","referenceURL":"https://www.gbif.org/species/2474855"},{"id":540,"nodeId":474,"scientificName":"Pitta nympha","commonName":"Đuôi cụt tiên (Fairy Pitta)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 16-30°C, Độ ẩm: 70-90%, Môi trường: Tầng thảm mục ẩm ướt dưới tán rừng lá rộng thường xanh độ cao 0–1.200 m","description":"Được mệnh danh là 'Nàng tiên bảy sắc' của tầng đáy rừng ẩm với bộ lông phối bảy gam màu rực rỡ như một viên ngọc biết nhảy nhót.","imageURL":"https://bionexus.vn/images/pitta-nympha.jpg","referenceURL":"https://www.gbif.org/species/2489521"},{"id":541,"nodeId":475,"scientificName":"Cissa hypoleuca","commonName":"Giẻ cùi vàng (Indochinese Green Magpie)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 16-30°C, Độ ẩm: 70-90%, Môi trường: Tầng tán trung bình của rừng thường xanh ẩm và rừng tre nứa độ cao 200–1.500 m","description":"Viên ngọc lục bảo của rừng Trường Sơn với chiếc bụng vàng tươi óng ả và chiếc mỏ đỏ thắm nổi bật giữa tán lá xanh.","imageURL":"https://bionexus.vn/images/cissa-hypoleuca.jpg","referenceURL":"https://www.gbif.org/species/2482586"},{"id":542,"nodeId":476,"scientificName":"Ophiophagus hannah","commonName":"Rắn hổ chúa (King Cobra)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 20-34°C, Độ ẩm: 65-90%, Môi trường: Rừng thường xanh nguyên sinh, rừng tre nứa và ven suối rừng độ cao 0–2.000 m","description":"Vị vua tối cao của thế giới loài rắn với chiều dài có thể vượt quá 5 mét và trí thông minh, sự cảnh giác vượt trội so với mọi loài bò sát khác.","imageURL":"https://bionexus.vn/images/ophiophagus-hannah.jpg","referenceURL":"https://www.gbif.org/species/2469850"},{"id":543,"nodeId":477,"scientificName":"Naja atra","commonName":"Rắn hổ mang (Chinese Cobra)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 15-34°C, Độ ẩm: 65-85%, Môi trường: Rừng thấp, đồi cây bụi, bờ ruộng và vùng nông thôn trung du độ cao 0–1.500 m","description":"Loài rắn hổ mang tiêu biểu của miền Bắc Việt Nam, nổi tiếng với phản xạ ngóc cao đầu bành rộng mang cổ và phát ra tiếng phì hơi đe dọa rất lớn.","imageURL":"https://bionexus.vn/images/naja-atra.jpg","referenceURL":"https://www.gbif.org/species/2470319"},{"id":544,"nodeId":478,"scientificName":"Bungarus fasciatus","commonName":"Rắn cạp nong (Banded Krait)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-34°C, Độ ẩm: 65-90%, Môi trường: Bờ suối rừng, đầm lầy, đồng ruộng và rừng thứ sinh ẩm độ cao 0–1.500 m","description":"Loài rắn độc có hoa văn khoanh vàng - khoanh đen nổi bật bậc nhất tự nhiên Việt Nam với tiết diện thân hình tam giác rất rõ và chóp đuôi tù.","imageURL":"https://bionexus.vn/images/bungarus-fasciatus.jpg","referenceURL":"https://www.gbif.org/species/5226830"},{"id":545,"nodeId":478,"scientificName":"Bungarus multicinctus","commonName":"Rắn cạp nia bắc (Many-banded Krait)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 15-32°C, Độ ẩm: 70-90%, Môi trường: Ven suối đá rừng núi, đầm lầy và ruộng lúa vùng trung du độ cao 0–1.500 m","description":"Loài rắn độc hoạt động về đêm có các khoanh đen - trắng tương phản sắc nét và sở hữu một trong những loại độc tố thần kinh mạnh nhất châu Á.","imageURL":"https://bionexus.vn/images/bungarus-multicinctus.jpg","referenceURL":"https://www.gbif.org/species/5226813"},{"id":546,"nodeId":479,"scientificName":"Protobothrops cornutus","commonName":"Rắn lục sừng (Horned Pit Viper)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 12-26°C, Độ ẩm: 75-95%, Môi trường: Rừng thường xanh trên núi đá vôi và rừng sương mù núi cao độ cao 250–2.000 m","description":"Một trong những loài rắn lục kỳ lạ và hiếm gặp nhất Việt Nam với cặp 'sừng' bằng vảy nhô cao ngay trên mắt.","imageURL":"https://bionexus.vn/images/protobothrops-cornutus.jpg","referenceURL":"https://www.gbif.org/species/2444155"},{"id":547,"nodeId":480,"scientificName":"Glyptostrobus pensilis","commonName":"Thông nước (Chinese Swamp Cypress)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 15-30°C, Độ ẩm: 75-95%, Môi trường: Đầm lầy than bùn ngập nước ngọt quanh năm trên cao nguyên độ cao 500–750 m","description":"'Hóa thạch sống' từ kỷ Phấn Trắng còn sót lại tại vùng đầm lầy tỉnh Đắk Lắk (Tây Nguyên) với hệ thống rễ thở nhô lên mặt nước độc nhất vô nhị.","imageURL":"https://bionexus.vn/images/glyptostrobus-pensilis.jpg","referenceURL":"https://www.gbif.org/species/2684155"},{"id":548,"nodeId":481,"scientificName":"Fokienia hodginsii","commonName":"Pơ mu (Fokienia)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 8-24°C, Độ ẩm: 75-95%, Môi trường: Rừng sương mù núi cao ẩm mát trên nền đá granit hoặc đá phiến độ cao 900–2.500 m","description":"Loài cây hạt trần cổ thụ biểu tượng của những cánh rừng sương mù đỉnh núi cao Việt Nam, nổi tiếng với quần thể hàng ngàn cây Pơ Mu di sản tại Tây Giang (Quảng Nam).","imageURL":"https://bionexus.vn/images/fokienia-hodginsii.jpg","referenceURL":"https://www.gbif.org/species/2684887"},{"id":549,"nodeId":482,"scientificName":"Calocedrus macrolepis","commonName":"Bách xanh (Chinese Incense-cedar)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 10-26°C, Độ ẩm: 70-90%, Môi trường: Rừng thường xanh trên núi đá vôi và núi đất độ cao 800–2.000 m","description":"Loài cây lá kim quý hiếm mọc chênh vênh trên các đỉnh núi đá vôi và sườn núi cao Việt Nam với tán lá xanh thẫm tỏa hương trầm dịu nhẹ.","imageURL":"https://bionexus.vn/images/calocedrus-macrolepis.jpg","referenceURL":"https://www.gbif.org/species/2683942"},{"id":550,"nodeId":483,"scientificName":"Taiwania cryptomerioides","commonName":"Bách Đài Loan (Coffin Tree)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 6-22°C, Độ ẩm: 75-95%, Môi trường: Rừng hỗn giao lá rộng - lá kim sương mù núi cao độ cao 1.600–2.600 m","description":"Một trong những loài cây hạt trần khổng lồ và cổ xưa nhất thế giới, tại Việt Nam chỉ còn một quần thể tự nhiên khoảng 100 cây ở dãy Hoàng Liên Sơn (Lào Cai - Yên Bái).","imageURL":"https://bionexus.vn/images/taiwania-cryptomerioides.jpg","referenceURL":"https://www.gbif.org/species/5284272"},{"id":551,"nodeId":484,"scientificName":"Pinus krempfii","commonName":"Thông lá dẹt (Krempf's Pine)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 10-24°C, Độ ẩm: 75-95%, Môi trường: Rừng sương mù hỗn giao đỉnh núi cao Tây Nguyên độ cao 1.200–2.000 m","description":"Kỳ quan tiến hóa thực vật đặc hữu của cao nguyên Lâm Viên (Việt Nam): loài thông duy nhất trong chi Pinus có lá dẹp bản rộng thay vì lá kim tròn.","imageURL":"https://bionexus.vn/images/pinus-krempfii.jpg","referenceURL":"https://www.gbif.org/species/5285794"},{"id":552,"nodeId":485,"scientificName":"Taxus wallichiana","commonName":"Thông đỏ nam (East Himalayan Yew)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 6-22°C, Độ ẩm: 75-95%, Môi trường: Tầng dưới rừng sương mù núi cao lạnh ẩm độ cao 1.300–3.000 m","description":"Loài cây hạt trần quý giá sống dưới tán rừng già núi cao, nổi tiếng với những quả mọng có lớp áo hạt màu đỏ ruby bao lấy hạt và hoạt chất dược học quý.","imageURL":"https://bionexus.vn/images/taxus-wallichiana.jpg","referenceURL":"https://www.gbif.org/species/5284540"},{"id":553,"nodeId":485,"scientificName":"Taxus chinensis","commonName":"Thông đỏ bắc (Chinese Yew)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 8-24°C, Độ ẩm: 70-90%, Môi trường: Rừng nguyên sinh trên đỉnh núi đá vôi ẩm mát độ cao 900–2.000 m","description":"Đại diện của chi Thông Đỏ chuyên sinh sống trên các đỉnh núi đá vôi hiểm trở miền Bắc Việt Nam với tuổi thọ có thể lên tới hàng ngàn năm.","imageURL":"https://bionexus.vn/images/taxus-chinensis.jpg","referenceURL":"https://www.gbif.org/species/8641859"},{"id":554,"nodeId":486,"scientificName":"Cephalotaxus mannii","commonName":"Đỉnh tùng (Mann's Yew Plum)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 10-25°C, Độ ẩm: 75-90%, Môi trường: Rừng thường xanh mưa mùa nhiệt đới núi cao độ cao 800–2.000 m","description":"Loài cây hạt trần quý hiếm có bộ lá xếp hai bên cành phẳng phiu như chiếc lược ngà và hạt chín to tròn giống quả mận rừng.","imageURL":"https://bionexus.vn/images/cephalotaxus-mannii.jpg","referenceURL":"https://www.gbif.org/species/2685261"},{"id":555,"nodeId":487,"scientificName":"Melopsittacus undulatus","commonName":"Vẹt yến phụng (Budgerigar)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-32°C, Độ ẩm: 40-65%, Môi trường: Thảo nguyên cây bụi khô, rừng bạch đàn thưa và đồng cỏ nội địa độ cao 0–600 m","description":"Loài vẹt cảnh nhỏ nhắn phổ biến nhất thế giới với tính cách vui tươi, dễ thuần hóa và khả năng bắt chước giọng nói đáng kinh ngạc.","imageURL":"https://bionexus.vn/images/melopsittacus-undulatus.jpg","referenceURL":"https://www.gbif.org/species/2479798"},{"id":556,"nodeId":488,"scientificName":"Nymphicus hollandicus","commonName":"Vẹt mào cockatiel (Cockatiel)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-32°C, Độ ẩm: 40-65%, Môi trường: Thảo nguyên cây bụi, savan gần nguồn nước ngọt nội địa độ cao 0–500 m","description":"Thành viên nhỏ nhất của họ Vẹt mào Úc, nổi tiếng với chiếc mào biểu cảm và tài huýt sáo những giai điệu âm nhạc trong trẻo.","imageURL":"https://bionexus.vn/images/nymphicus-hollandicus.jpg","referenceURL":"https://www.gbif.org/species/2479977"},{"id":557,"nodeId":489,"scientificName":"Agapornis roseicollis","commonName":"Vẹt uyên ương má hồng (Rosy-faced Lovebird)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-32°C, Độ ẩm: 40-65%, Môi trường: Thung lũng đá khô hạn, savan cây bụi gần sông suối độ cao 0–1.500 m","description":"Đại diện nổi tiếng nhất của chi Vẹt Uyên Ương (Lovebird), luôn quấn quýt thành từng đôi không rời và ríu rít chải lông cho nhau.","imageURL":"https://bionexus.vn/images/agapornis-roseicollis.jpg","referenceURL":"https://www.gbif.org/species/9770031"},{"id":558,"nodeId":489,"scientificName":"Agapornis fischeri","commonName":"Vẹt uyên ương Fischer (Fischer's Lovebird)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 18-30°C, Độ ẩm: 45-70%, Môi trường: Trảng cỏ savan có cây keo (Acacia) và cây bao báp ở độ cao 1.100–2.000 m","description":"Loài vẹt uyên ương sở hữu bảng màu nhiệt đới rực rỡ như ánh hoàng hôn thảo nguyên Serengeti kèm đôi mắt viền trắng to tròn.","imageURL":"https://bionexus.vn/images/agapornis-fischeri.jpg","referenceURL":"https://www.gbif.org/species/2479544"},{"id":559,"nodeId":489,"scientificName":"Agapornis personatus","commonName":"Vẹt uyên ương mặt nạ (Yellow-collared Lovebird)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-30°C, Độ ẩm: 45-70%, Môi trường: Trảng cỏ savan có cây bao báp làm hốc tổ ở độ cao 1.100–1.800 m","description":"Nổi bật trong nhóm vẹt mắt trắng nhờ chiếc 'mặt nạ' đen tuyền tương phản sắc nét với vòng cổ màu vàng chanh tươi sáng.","imageURL":"https://bionexus.vn/images/agapornis-personatus.jpg","referenceURL":"https://www.gbif.org/species/2479553"},{"id":560,"nodeId":489,"scientificName":"Agapornis lilianae","commonName":"Vẹt uyên ương Lilian (Nyasa Lovebird)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 45-70%, Môi trường: Rừng cây Mopane ven sông và savan ngập lũ độ cao 300–1.000 m","description":"Loài vẹt uyên ương nhỏ nhắn và hiền hòa của lưu vực sông Luangwa, phân biệt với A. fischeri nhờ phao câu màu xanh lục thay vì xanh tím.","imageURL":"https://bionexus.vn/images/agapornis-lilianae.jpg","referenceURL":"https://www.gbif.org/species/2479559"},{"id":561,"nodeId":489,"scientificName":"Agapornis nigrigenis","commonName":"Vẹt uyên ương má đen (Black-cheeked Lovebird)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 45-70%, Môi trường: Rừng cây Mopane gần nguồn nước cố định ở độ cao 600–1.000 m","description":"Sự kết hợp hài hòa giữa nét mặt của Lovebird Mặt đen và Lovebird Lilian với mảng yếm màu cam đào ấm áp dưới cổ họng.","imageURL":"https://bionexus.vn/images/agapornis-nigrigenis.jpg","referenceURL":"https://www.gbif.org/species/2479545"},{"id":562,"nodeId":490,"scientificName":"Pyrrhura molinae","commonName":"Vẹt conure má xanh (Green-cheeked Parakeet)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-30°C, Độ ẩm: 50-75%, Môi trường: Rừng nhiệt đới ẩm, rừng hành lang ven sông và rừng mây chân núi Andes độ cao 100–2.400 m","description":"Một trong những loài vẹt cảnh cỡ trung được yêu thích nhất thế giới nhờ tính cách tinh nghịch như chú hề nhỏ nhưng giọng kêu lại rất êm tai.","imageURL":"https://bionexus.vn/images/pyrrhura-molinae.jpg","referenceURL":"https://www.gbif.org/species/2479804"},{"id":563,"nodeId":490,"scientificName":"Pyrrhura perlata","commonName":"Vẹt conure bụng đỏ (Crimson-bellied Parakeet)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 55-80%, Môi trường: Tán rừng mưa nhiệt đới đất thấp nguyên sinh độ cao 50–600 m","description":"Được đánh giá là một trong những loài đẹp nhất chi Pyrrhura nhờ mảng bụng đỏ tươi như nhung và đôi cánh ánh xanh coban.","imageURL":"https://bionexus.vn/images/pyrrhura-perlata.jpg","referenceURL":"https://www.gbif.org/species/2479851"},{"id":564,"nodeId":490,"scientificName":"Pyrrhura frontalis","commonName":"Vẹt conure bụng nâu (Maroon-bellied Parakeet)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 16-30°C, Độ ẩm: 50-75%, Môi trường: Rừng Đại Tây Dương (Mata Atlântica), rừng thông Araucaria và bìa rừng độ cao 0–1.400 m","description":"Loài vẹt Conure thân thiện và điềm đạm của vùng rừng Đại Tây Dương Nam Mỹ, rất quấn chủ và dễ huấn luyện các trò tương tác.","imageURL":"https://bionexus.vn/images/pyrrhura-frontalis.jpg","referenceURL":"https://www.gbif.org/species/2479840"},{"id":565,"nodeId":491,"scientificName":"Aratinga solstitialis","commonName":"Vẹt mặt trời (Sun Parakeet)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 50-75%, Môi trường: Trảng cỏ savan nhiệt đới xen các rặng cọ Mauritia và rừng thưa độ cao 100–1.200 m","description":"Ngọn lửa rực rỡ của vùng savan Nam Mỹ với bộ lông vàng cam chói lọi như ánh mặt trời nhiệt đới và trí thông minh lanh lợi.","imageURL":"https://bionexus.vn/images/aratinga-solstitialis.jpg","referenceURL":"https://www.gbif.org/species/2479158"},{"id":566,"nodeId":491,"scientificName":"Aratinga jandaya","commonName":"Vẹt Jandaya (Jandaya Parakeet)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 50-75%, Môi trường: Rừng khô Caatinga, rừng cọ ven biển và bìa rừng nhiệt đới độ cao 0–700 m","description":"Họ hàng gần gũi nhất của Vẹt Mặt Trời với sự tương phản bắt mắt giữa phần đầu - bụng vàng cam rực lửa và đôi cánh xanh lục ngọc bích.","imageURL":"https://bionexus.vn/images/aratinga-jandaya.jpg","referenceURL":"https://www.gbif.org/species/2479106"},{"id":567,"nodeId":492,"scientificName":"Myiopsitta monachus","commonName":"Vẹt thầy tu (Monk Parakeet)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 10-32°C, Độ ẩm: 45-70%, Môi trường: Đồng cỏ thưa có cây gỗ, rừng bạch đàn và công viên đô thị độ cao 0–1.500 m","description":"Kiến trúc sư độc nhất vô nhị trong họ Vẹt và là một trong những loài vẹt cỡ trung nói giỏi, rõ chữ nhất khi nuôi làm cảnh.","imageURL":"https://bionexus.vn/images/myiopsitta-monachus.jpg","referenceURL":"https://www.gbif.org/species/2479407"},{"id":568,"nodeId":493,"scientificName":"Forpus coelestis","commonName":"Vẹt lùn Thái Bình Dương (Pacific Parrotlet)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-32°C, Độ ẩm: 45-70%, Môi trường: Rừng khô nhiệt đới, trảng cây bụi xương rồng và thung lũng ven biển độ cao 0–1.500 m","description":"Được mệnh danh là 'Vẹt Amazon bỏ túi' (Pocket Parrot) vì chỉ to bằng ngón tay cái nhưng lại sở hữu cá tính mạnh mẽ và trí thông minh của loài vẹt lớn.","imageURL":"https://bionexus.vn/images/forpus-coelestis.jpg","referenceURL":"https://www.gbif.org/species/2479087"},{"id":569,"nodeId":494,"scientificName":"Bolborhynchus lineola","commonName":"Vẹt sọc vằn (Barred Parakeet)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-28°C, Độ ẩm: 55-80%, Môi trường: Rừng mây núi cao và rừng tre trúc Chusquea ở độ cao 1.000–3.000 m","description":"Loài vẹt núi cao nổi tiếng hiền lành, ít tiếng ồn và có dáng đi lạch bạch cúi thấp đầu rất ngộ nghĩnh.","imageURL":"https://bionexus.vn/images/bolborhynchus-lineola.jpg","referenceURL":"https://www.gbif.org/species/5229121"},{"id":570,"nodeId":495,"scientificName":"Brotogeris chiriri","commonName":"Vẹt cánh vàng (Yellow-chevroned Parakeet)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-32°C, Độ ẩm: 50-75%, Môi trường: Rừng thưa Cerrado, đầm lầy Pantanal và rừng cọ độ cao 0–1.200 m","description":"Loài vẹt nhỏ năng động vùng đồng thảo Brazil, khi sải cánh bay sẽ để lộ dải lông vàng tươi sáng rực giữa bầu trời.","imageURL":"https://bionexus.vn/images/brotogeris-chiriri.jpg","referenceURL":"https://www.gbif.org/species/2479583"},{"id":571,"nodeId":496,"scientificName":"Pionites melanocephalus","commonName":"Vẹt caique đầu đen (Black-headed Parrot)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 55-80%, Môi trường: Tầng tán cao của rừng mưa nhiệt đới đất thấp nguyên sinh độ cao 0–1.000 m","description":"Được mệnh danh là 'Chú hề nhảy lò cò' của thế giới loài vẹt nhờ bộ lông phối 5 màu sắc nét như tranh vẽ và thói quen bật nhảy trên hai chân.","imageURL":"https://bionexus.vn/images/pionites-melanocephalus.jpg","referenceURL":"https://www.gbif.org/species/2479437"},{"id":572,"nodeId":496,"scientificName":"Pionites leucogaster","commonName":"Vẹt caique bụng trắng (Green-thighed Parrot)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 55-80%, Môi trường: Rừng mưa nhiệt đới ngập nước theo mùa (Várzea) và rừng đất thấp độ cao 0–500 m","description":"Người anh em phương Nam của Caique Đầu Đen với chiếc mũ màu cam vàng tươi sáng và tính cách hiếu động không ngừng nghỉ.","imageURL":"https://bionexus.vn/images/pionites-leucogaster.jpg","referenceURL":"https://www.gbif.org/species/2479441"},{"id":573,"nodeId":497,"scientificName":"Poicephalus senegalus","commonName":"Vẹt Senegal (Senegal Parrot)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-34°C, Độ ẩm: 45-70%, Môi trường: Trảng cỏ savan có cây gỗ lớn và rừng thưa Tây Phi độ cao 0–1.000 m","description":"Loài vẹt châu Phi cỡ trung nổi tiếng với tính cách điềm tĩnh, ít la hét ồn ào và sự gắn kết sâu sắc với người chăm sóc.","imageURL":"https://bionexus.vn/images/poicephalus-senegalus.jpg","referenceURL":"https://www.gbif.org/species/2479964"},{"id":574,"nodeId":497,"scientificName":"Poicephalus meyeri","commonName":"Vẹt Meyer (Brown Parrot)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-32°C, Độ ẩm: 45-70%, Môi trường: Rừng thưa Miombo, savan cây keo và rừng ven sông độ cao 0–2.000 m","description":"Một trong những loài vẹt châu Phi hiền lành và êm ả nhất, điểm xuyết những mảng lông vàng nghệ trên đỉnh đầu và đôi vai.","imageURL":"https://bionexus.vn/images/poicephalus-meyeri.jpg","referenceURL":"https://www.gbif.org/species/2479968"},{"id":575,"nodeId":498,"scientificName":"Psittacus erithacus","commonName":"Vẹt xám châu Phi (Grey Parrot)","conservationStatus":"EN","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 55-80%, Môi trường: Rừng mưa nhiệt đới đất thấp nguyên sinh và rừng ngập nước lưu vực sông Congo độ cao 0–1.800 m","description":"Trí tuệ kiệt xuất bậc nhất thế giới loài chim, có khả năng nhận thức khái niệm màu sắc, hình khối, con số và giao tiếp ngôn ngữ tương đương trẻ nhỏ 4–5 tuổi.","imageURL":"https://bionexus.vn/images/psittacus-erithacus.jpg","referenceURL":"https://www.gbif.org/species/2480181"},{"id":576,"nodeId":499,"scientificName":"Psittacula krameri","commonName":"Vẹt đuôi dài cổ khoang (Rose-ringed parakeet)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-35°C, Độ ẩm: 45-75%, Môi trường: Rừng thưa, công viên cây xanh, vườn cây ăn quả và vùng đồng bằng độ cao 0–1.600 m","description":"Loài vẹt cổ điển được nuôi làm cảnh từ thời cổ đại Ấn Độ và Hy Lạp - La Mã, nổi tiếng với giọng nói trong trẻo và các biến thể màu lam, vàng, trắng.","imageURL":"https://bionexus.vn/images/psittacula-krameri.jpg","referenceURL":"https://www.gbif.org/species/2479226"},{"id":577,"nodeId":499,"scientificName":"Psittacula eupatria","commonName":"Vẹt lớn (Alexandrine parakeet)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-35°C, Độ ẩm: 50-80%, Môi trường: Rừng khộp rụng lá, rừng khô ven biển và rừng ngập mặn độ cao 0–900 m","description":"Loài vẹt bản địa có kích thước lớn nhất tại Việt Nam, dễ dàng phân biệt với Vẹt Cổ Hồng nhờ mảng phù hiệu màu đỏ tía nổi bật trên hai bờ vai.","imageURL":"https://bionexus.vn/images/psittacula-eupatria.jpg","referenceURL":"https://www.gbif.org/species/5229055"},{"id":578,"nodeId":499,"scientificName":"Psittacula alexandri","commonName":"Vẹt ngực đỏ (Red-breasted Parakeet)","conservationStatus":"NT","environmentSpecs":"Nhiệt độ: 18-35°C, Độ ẩm: 55-85%, Môi trường: Rừng thường xanh đất thấp, rừng khộp, rừng tràm và vùng trung du độ cao 0–1.500 m","description":"Loài vẹt quen thuộc nhất trong văn hóa dân gian Việt Nam ('Con két ăn trái ổi tàu') với bộ ngực hồng đỏ và cặp ria mép đen ngộ nghĩnh.","imageURL":"https://bionexus.vn/images/psittacula-alexandri.jpg","referenceURL":"https://www.gbif.org/species/5229045"},{"id":579,"nodeId":499,"scientificName":"Psittacula cyanocephala","commonName":"Vẹt đầu mận (Plum-headed parakeet)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 18-34°C, Độ ẩm: 45-75%, Môi trường: Rừng lá rộng thưa, bìa rừng và thung lũng canh tác độ cao 0–1.300 m","description":"Một trong những loài vẹt có sắc đầu quyến rũ nhất thế giới: đầu chim trống chuyển màu kỳ ảo từ đỏ hồng sang tím mận dưới các góc ánh sáng khác nhau.","imageURL":"https://bionexus.vn/images/psittacula-cyanocephala.jpg","referenceURL":"https://www.gbif.org/species/5229044"},{"id":580,"nodeId":500,"scientificName":"Eclectus roratus","commonName":"Vẹt Eclectus (Moluccan Eclectus)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 55-80%, Môi trường: Tán rừng mưa nhiệt đới đất thấp có nhiều cây cổ thụ rỗng thân độ cao 0–1.000 m","description":"Hiện tượng kỳ thú của ngành điểu học thế giới khi chim trống và chim mái mang hai màu lông đối lập hoàn toàn như hai loài khác biệt.","imageURL":"https://bionexus.vn/images/eclectus-roratus.jpg","referenceURL":"https://www.gbif.org/species/2480075"},{"id":581,"nodeId":501,"scientificName":"Ara ararauna","commonName":"Vẹt Macaw xanh vàng (Blue-and-yellow Macaw)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-34°C, Độ ẩm: 55-80%, Môi trường: Rừng mưa nhiệt đới ngập nước (Várzea), đầm lầy cọ Mauritia và rừng hành lang độ cao 0–500 m","description":"Biểu tượng kinh điển của dòng vẹt đuôi dài Macaw Nam Mỹ với sải cánh rộng hơn 1 mét, trí thông minh cao và tính cách phóng khoáng.","imageURL":"https://bionexus.vn/images/ara-ararauna.jpg","referenceURL":"https://www.gbif.org/species/5959231"},{"id":582,"nodeId":501,"scientificName":"Ara chloropterus","commonName":"Vẹt Macaw đỏ xanh (Red-and-green Macaw)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-34°C, Độ ẩm: 55-80%, Môi trường: Rừng mưa nhiệt đới đất thấp và sườn núi thấp độ cao 0–1.000 m","description":"Loài lớn nhất trong chi Ara và được giới chơi vẹt mệnh danh là 'Người khổng lồ dịu dàng' (Gentle Giant) nhờ tính cách điềm đạm, tình cảm.","imageURL":"https://bionexus.vn/images/ara-chloropterus.jpg","referenceURL":"https://www.gbif.org/species/5959225"},{"id":583,"nodeId":501,"scientificName":"Ara macao","commonName":"Vẹt Macaw đỏ (Scarlet Macaw)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-34°C, Độ ẩm: 60-85%, Môi trường: Tán rừng mưa nhiệt đới ẩm đất thấp và rừng ven sông lớn độ cao 0–1.000 m","description":"Quốc điểu của Honduras và là một trong những loài chim rực rỡ nhất hành tinh với ba dải màu đỏ - vàng - lam chói lọi khi bay qua vòm rừng Amazon.","imageURL":"https://bionexus.vn/images/ara-macao.jpg","referenceURL":"https://www.gbif.org/species/5959227"},{"id":584,"nodeId":501,"scientificName":"Ara severus","commonName":"Vẹt Macaw trán nâu (Chestnut-fronted Macaw)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 55-80%, Môi trường: Rừng đầm lầy cọ, rừng hành lang ven sông và bìa rừng mưa độ cao 0–1.500 m","description":"Lựa chọn hàng đầu trong nhóm 'Mini Macaw' nhờ mang đầy đủ vẻ đẹp vùng da mặt trắng và trí thông minh của đại Macaw trong một kích thước vừa vặn.","imageURL":"https://bionexus.vn/images/ara-severus.jpg","referenceURL":"https://www.gbif.org/species/5959228"},{"id":585,"nodeId":502,"scientificName":"Diopsittaca nobilis","commonName":"Vẹt Macaw vai đỏ (Northern Red-shouldered Macaw)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 20-32°C, Độ ẩm: 50-75%, Môi trường: Trảng cỏ savan Cerrado, đầm lầy cọ Mauritia và rừng thưa độ cao 0–1.200 m","description":"Em út nhỏ bé nhất của đại gia đình vẹt Macaw: chỉ dài 30 cm nhưng có gương mặt trắng tinh anh và giọng nói lanh lảnh cực kỳ rõ chữ.","imageURL":"https://bionexus.vn/images/diopsittaca-nobilis.jpg","referenceURL":"https://www.gbif.org/species/2479365"},{"id":586,"nodeId":503,"scientificName":"Anodorhynchus hyacinthinus","commonName":"Vẹt Macaw lam tím (Hyacinth Macaw)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ: 20-35°C, Độ ẩm: 50-80%, Môi trường: Trảng cỏ savan có rặng cọ Acrocomia/Attalea và vùng ngập nước Pantanal độ cao 100–600 m","description":"Vị vua tuyệt đối của thế giới loài vẹt với chiều dài đạt tròn 1 mét và bộ lông xanh lam coban quý phái điểm hai nét vàng kim quanh mắt và khóe miệng như đang mỉm cười.","imageURL":"https://bionexus.vn/images/anodorhynchus-hyacinthinus.jpg","referenceURL":"https://www.gbif.org/species/2479359"},{"id":587,"nodeId":504,"scientificName":"Cacatua galerita","commonName":"Vẹt mào vàng lớn (Sulphur-crested Cockatoo)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ: 15-34°C, Độ ẩm: 45-75%, Môi trường: Rừng bạch đàn, rừng mưa nhiệt đới và công viên cây xanh độ cao 0–1.500 m","description":"Biểu tượng sống động của nước Úc với chiếc mào vàng rực xòe rộng như chiếc vương miện mỗi khi chú chim nhảy múa.","imageURL":"https://bionexus.vn/images/cacatua-galerita.jpg","referenceURL":"https://www.gbif.org/species/2479888"},{"id":588,"nodeId":504,"scientificName":"Cacatua sulphurea","commonName":"Vẹt mào vàng nhỏ (Yellow-crested Cockatoo)","conservationStatus":"CR","environmentSpecs":"Nhiệt độ: 20-34°C, Độ ẩm: 50-80%, Môi trường: Rừng khô nhiệt đới, rừng bán thường xanh trên đảo độ cao 0–1.200 m","description":"Loài vẹt mào quý hiếm của quần đảo Indonesia, dễ phân biệt với họ hàng nước Úc nhờ kích thước nhỏ gọn và đốm má màu vàng tươi dịu dàng.","imageURL":"https://bionexus.vn/images/cacatua-sulphurea.jpg","referenceURL":"https://www.gbif.org/species/2479893"},{"id":589,"nodeId":505,"scientificName":"Amphiprion ocellaris","commonName":"Cá hề cam (Clown Anemonefish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô nông đới Ấn Độ Dương - Tây Thái Bình Dương độ sâu 1–15 m, cộng sinh cùng hải quỳ","description":"Ngôi sao điện ảnh nổi tiếng nhất đại dương với sắc cam trắng tươi tắn và đời sống cộng sinh kỳ diệu giữa những xúc tu hải quỳ đầy độc tố.","imageURL":"https://bionexus.vn/images/amphiprion-ocellaris.jpg","referenceURL":"https://www.gbif.org/species/5212106"},{"id":590,"nodeId":505,"scientificName":"Amphiprion percula","commonName":"Cá hề viền đen (Blackfinned Clownfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô nhiệt đới nông độ sâu 1–15 m, cộng sinh cùng hải quỳ Heteractis magnifica và Stichodactyla gigantea","description":"Người anh em song sinh của Cá Hề Ocellaris, được giới chơi cá biển săn đón nhờ các mảng viền đen đậm nét như vẽ mực tàu quanh ba dải sọc trắng.","imageURL":"https://bionexus.vn/images/amphiprion-percula.jpg","referenceURL":"https://www.gbif.org/species/5212094"},{"id":591,"nodeId":505,"scientificName":"Amphiprion clarkii","commonName":"Cá hề Clark (Clark's Anemonefish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô ven bờ và đầm phá độ sâu 1–60 m","description":"Loài cá hề dẻo dai và có khả năng thích nghi cao nhất thế giới khi có thể cộng sinh với cả 10 loài hải quỳ chủ khác nhau trong tự nhiên.","imageURL":"https://bionexus.vn/images/amphiprion-clarkii.jpg","referenceURL":"https://www.gbif.org/species/5212081"},{"id":592,"nodeId":505,"scientificName":"Amphiprion frenatus","commonName":"Cá hề cà chua (Blackback Anemonefish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô nông độ sâu 1–12 m, cộng sinh chuyên biệt với hải quỳ vú (Entacmaea quadricolor)","description":"Loài cá hề bản địa rất quen thuộc tại vùng biển Nha Trang - Phú Quốc (Việt Nam) với sắc đỏ cà chua rực lửa và một dải băng trắng ngang trán.","imageURL":"https://bionexus.vn/images/amphiprion-frenatus.jpg","referenceURL":"https://www.gbif.org/species/5212111"},{"id":593,"nodeId":505,"scientificName":"Amphiprion perideraion","commonName":"Cá hề hồng (False Skunk Striped Anemonefish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Đầm phá và rạn san hô ngoài khơi độ sâu 3–30 m, cộng sinh cùng hải quỳ Heteractis crispa và H. magnifica","description":"Một trong những loài cá hề hiền hòa và thanh lịch nhất với tông màu hồng đào dịu mắt cùng đường kẻ trắng mảnh chạy dọc sống lưng.","imageURL":"https://bionexus.vn/images/amphiprion-perideraion.jpg","referenceURL":"https://www.gbif.org/species/5212059"},{"id":594,"nodeId":505,"scientificName":"Amphiprion sandaracinos","commonName":"Cá hề sọc lưng (Orange Anemonefish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô ngoài khơi và sườn dốc rạn độ sâu 3–20 m","description":"Dễ dàng nhận diện ngay từ xa nhờ dải sọc trắng chạy dọc sống lưng như vệt lông chồn hương trên nền thân màu cam vàng tươi sáng.","imageURL":"https://bionexus.vn/images/amphiprion-sandaracinos.jpg","referenceURL":"https://www.gbif.org/species/5212089"},{"id":595,"nodeId":505,"scientificName":"Amphiprion polymnus","commonName":"Cá hề yên ngựa (Brownsaddle Clownfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Đáy cát bùn pha san hô gần bờ độ sâu 2–30 m, cộng sinh cùng hải quỳ thảm Stichodactyla haddoni","description":"Loài cá hề đặc trưng của các bãi cát ven rạn san hô Việt Nam với hoa văn mảng trắng giữa lưng giống hệt chiếc yên ngựa.","imageURL":"https://bionexus.vn/images/amphiprion-polymnus.jpg","referenceURL":"https://www.gbif.org/species/5212096"},{"id":596,"nodeId":505,"scientificName":"Amphiprion sebae","commonName":"Cá hề Sebae (Sebae Clownfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Đáy cát và sườn rạn san hô độ sâu 2–25 m","description":"Một trong những loài cá hề lớn nhất Ấn Độ Dương với chiếc đuôi vàng chanh nổi bật và dải sọc trắng mở rộng vắt chéo qua vây lưng.","imageURL":"https://bionexus.vn/images/amphiprion-sebae.jpg","referenceURL":"https://www.gbif.org/species/5212118"},{"id":597,"nodeId":505,"scientificName":"Amphiprion melanopus","commonName":"Cá hề đen (Black Anemonefish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Đầm phá và mặt bằng rạn san hô độ sâu 1–18 m, cộng sinh với hải quỳ vú Entacmaea quadricolor","description":"Mang vẻ đẹp rực nóng như than hồng đang cháy với phần bụng đen nhánh được viền quanh bởi đầu và các vây màu đỏ lửa.","imageURL":"https://bionexus.vn/images/amphiprion-melanopus.jpg","referenceURL":"https://www.gbif.org/species/5212069"},{"id":598,"nodeId":505,"scientificName":"Amphiprion ephippium","commonName":"Cá hề yên đỏ (Red Saddleback Anemonefish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô ven bờ và đầm phá độ sâu 2–15 m","description":"Loài cá hề độc đáo của biển Andaman khi cá trưởng thành rũ bỏ toàn bộ các vạch trắng để khoác tấm áo cam đỏ điểm mảng yên đen bóng.","imageURL":"https://bionexus.vn/images/amphiprion-ephippium.jpg","referenceURL":"https://www.gbif.org/species/5212057"},{"id":599,"nodeId":505,"scientificName":"Amphiprion akallopisos","commonName":"Cá hề sọc mũi (Nosestripe Anemonefish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô có dòng chảy vừa phải độ sâu 3–25 m","description":"Họ hàng Ấn Độ Dương của Cá Hề Sọc Lưng Cam với chiếc đuôi màu trắng tinh và đường sọc trắng mảnh chạy dọc đỉnh vây lưng.","imageURL":"https://bionexus.vn/images/amphiprion-akallopisos.jpg","referenceURL":"https://www.gbif.org/species/5212090"},{"id":600,"nodeId":505,"scientificName":"Amphiprion bicinctus","commonName":"Cá hề hai sọc (Two-banded Anemonefish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8.1-8.4, Môi trường: Rạn san hô nông Biển Đỏ độ sâu 1–30 m","description":"Biểu tượng rực rỡ của hệ sinh thái rạn san hô Biển Đỏ với hai dải sọc trắng sáng lấp lánh giữa rừng xúc tu hải quỳ.","imageURL":"https://bionexus.vn/images/amphiprion-bicinctus.jpg","referenceURL":"https://www.gbif.org/species/5212077"},{"id":601,"nodeId":506,"scientificName":"Premnas biaculeatus","commonName":"Cá hề nâu đỏ (Maroon clownfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô đầm phá và sườn rạn độ sâu 1–16 m, chỉ cộng sinh với hải quỳ vú Entacmaea quadricolor","description":"Nữ hoàng uy quyền của nhóm cá hề với kích thước cá cái đạt tới 17 cm, màu đỏ nhung thẫm quý phái và các biến thể sọc vàng kim (Gold Stripe Maroon).","imageURL":"https://bionexus.vn/images/premnas-biaculeatus.jpg","referenceURL":"https://www.gbif.org/species/2398709"},{"id":602,"nodeId":507,"scientificName":"Chromis viridis","commonName":"Cá thia xanh (Green Chromis)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Bơi thành đàn lớn phía trên các bụi san hô sừng hươu (Acropora) ở độ sâu 1–12 m","description":"Loài cá bơi đàn đẹp và hiền lành bậc nhất cho bể cá cảnh biển: khi bơi theo đàn dưới ánh đèn bể rạn sẽ chuyển màu lung linh từ xanh ngọc sang xanh lam.","imageURL":"https://bionexus.vn/images/chromis-viridis.jpg","referenceURL":"https://www.gbif.org/species/5212219"},{"id":603,"nodeId":508,"scientificName":"Chrysiptera parasema","commonName":"Cá thia đuôi vàng (Goldtail Demoiselle)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Sống quanh các cụm san hô nhánh trong đầm phá kín sóng độ sâu 1–16 m","description":"Viên ngọc xanh coban đuôi vàng nhỏ nhắn, khỏe mạnh và là một trong những loài cá nhập môn tuyệt vời nhất cho người mới chơi bể cá biển.","imageURL":"https://bionexus.vn/images/chrysiptera-parasema.jpg","referenceURL":"https://www.gbif.org/species/2399271"},{"id":604,"nodeId":508,"scientificName":"Chrysiptera hemicyanea","commonName":"Cá thia xanh lam (Azure Demoiselle)","conservationStatus":"VU","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô đầm phá giàu san hô cứng độ sâu 1–20 m","description":"Phiên bản nâng cấp rực rỡ hơn của Cá Thia Đuôi Vàng khi mảng vàng hoàng yến phủ kín toàn bộ phần bụng dưới và đuôi.","imageURL":"https://bionexus.vn/images/chrysiptera-hemicyanea.jpg","referenceURL":"https://www.gbif.org/species/2399258"},{"id":605,"nodeId":509,"scientificName":"Dascyllus aruanus","commonName":"Cá thia ba sọc (Banded Humbug)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Trú ẩn theo đàn trong các bụi san hô nhánh Acropora và Pocillopora ở độ sâu 1–15 m","description":"Loài cá thia mang họa tiết ba vạch đen trắng cổ điển như viên kẹo bạc hà Humbug, cực kỳ khỏe mạnh trong bể cá biển.","imageURL":"https://bionexus.vn/images/dascyllus-aruanus.jpg","referenceURL":"https://www.gbif.org/species/5212047"},{"id":606,"nodeId":509,"scientificName":"Dascyllus trimaculatus","commonName":"Cá thia đồng tiền (Threespot Damselfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô độ sâu 1–50 m; cá non thường sống chung với hải quỳ hoặc cầu gai gai dài","description":"Chú cá mang bộ lễ phục đen tuyền điểm ba chấm trắng tròn như quân cờ Domino rất ngộ nghĩnh.","imageURL":"https://bionexus.vn/images/dascyllus-trimaculatus.jpg","referenceURL":"https://www.gbif.org/species/5212031"},{"id":607,"nodeId":510,"scientificName":"Paracanthurus hepatus","commonName":"Cá đuôi gai xanh hoàng gia (Palette Surgeonfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-27°C, pH: 8.1-8.4, Môi trường: Sườn ngoài rạn san hô có dòng chảy mạnh ở độ sâu 2–40 m","description":"Biểu tượng đại dương toàn cầu (nguyên mẫu nhân vật Dory) với màu xanh coban hoàng gia, chiếc đuôi vàng chanh và ngạnh gai sắc bén ở cuống đuôi.","imageURL":"https://bionexus.vn/images/paracanthurus-hepatus.jpg","referenceURL":"https://www.gbif.org/species/2379534"},{"id":608,"nodeId":511,"scientificName":"Zebrasoma flavescens","commonName":"Cá đuôi gai vàng (Yellow Tang)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-27°C, pH: 8.1-8.4, Môi trường: Rạn san hô đầm phá và sườn rạn ngoài khơi độ sâu 2–45 m","description":"Loài cá đuôi gai nổi tiếng bậc nhất trong thú chơi bể cá rạn san hô (Reef tank) nhờ sắc vàng chanh chói lọi và khả năng dọn sạch rêu tảo hại trên đá sống.","imageURL":"https://bionexus.vn/images/zebrasoma-flavescens.jpg","referenceURL":"https://www.gbif.org/species/2379869"},{"id":609,"nodeId":511,"scientificName":"Zebrasoma xanthurum","commonName":"Cá đuôi gai tím đuôi vàng (Yellowtail Tang)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8.1-8.4, Môi trường: Rạn san hô giàu san hô nhánh độ sâu 2–20 m","description":"Viên ngọc quý của Biển Đỏ với sắc tím nhung sang trọng kết hợp chiếc đuôi và viền vây ngực màu vàng nghệ rực sáng.","imageURL":"https://bionexus.vn/images/zebrasoma-xanthurum.jpg","referenceURL":"https://www.gbif.org/species/2379882"},{"id":610,"nodeId":511,"scientificName":"Zebrasoma scopas","commonName":"Cá đuôi gai nâu (Brushtail Tang)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Đầm phá và sườn rạn san hô độ sâu 1–40 m","description":"Chuyên gia kiểm soát rêu tảo cần mẫn và dẻo dai với họa tiết hàng ngàn đường chấm li tiสี xanh lam nhạt xếp sóng dọc thân.","imageURL":"https://bionexus.vn/images/zebrasoma-scopas.jpg","referenceURL":"https://www.gbif.org/species/2379864"},{"id":611,"nodeId":511,"scientificName":"Zebrasoma desjardinii","commonName":"Cá đuôi gai buồm Ấn Độ (Indian Sailfin Tang)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8.1-8.4, Môi trường: Rạn san hô đầm phá và vùng rạn ngoài khơi độ sâu 2–30 m","description":"Khi giương cao cả vây lưng và vây hậu môn, chiều cao cơ thể của loài cá này tăng lên gấp đôi tạo thành một cánh buồm tròn đầy họa tiết nghệ thuật.","imageURL":"https://bionexus.vn/images/zebrasoma-desjardinii.jpg","referenceURL":"https://www.gbif.org/species/2379874"},{"id":612,"nodeId":512,"scientificName":"Acanthurus leucosternon","commonName":"Cá đuôi gai xanh phấn (Powder Blue Surgeonfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-27°C, pH: 8.1-8.4, Môi trường: Mặt bằng rạn san hô nông ngập nắng có sóng vỗ mạnh độ sâu 1–20 m","description":"Một trong những loài cá đuôi gai có phối màu thanh nhã và nổi bật nhất thế giới với sắc xanh phấn (Powder blue) cùng vây lưng vàng tươi.","imageURL":"https://bionexus.vn/images/acanthurus-leucosternon.jpg","referenceURL":"https://www.gbif.org/species/5209210"},{"id":613,"nodeId":512,"scientificName":"Acanthurus lineatus","commonName":"Cá đuôi gai sọc (Lined Surgeonfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-27°C, pH: 8.1-8.4, Môi trường: Đỉnh rạn san hô ngoài khơi nơi có sóng vỗ giàu oxy độ sâu 1–15 m","description":"Chiến binh rực rỡ của đỉnh sóng san hô với bộ áo kẻ sọc vàng - xanh điện quang bắt mắt và tốc độ bơi lướt cực nhanh.","imageURL":"https://bionexus.vn/images/acanthurus-lineatus.jpg","referenceURL":"https://www.gbif.org/species/5209244"},{"id":614,"nodeId":512,"scientificName":"Acanthurus achilles","commonName":"Cá đuôi gai Achilles (Achilles Tang)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 23-26°C, pH: 8.1-8.4, Môi trường: Đới sóng vỗ mạnh (surge zone) trên rạn san hô đá độ sâu 0–10 m","description":"Biểu tượng quý tộc của dòng cá đuôi gai với tấm áo đen nhung lịch lãm và giọt lửa màu cam chói lọi ngay tại vị trí 'gót chân Achilles' ở cuống đuôi.","imageURL":"https://bionexus.vn/images/acanthurus-achilles.jpg","referenceURL":"https://www.gbif.org/species/5209178"},{"id":615,"nodeId":512,"scientificName":"Acanthurus triostegus","commonName":"Cá đuôi gai vằn (Convict Surgeonfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Đầm phá san hô, bãi đá thủy triều và mặt rạn nông độ sâu 0–30 m","description":"Được gọi là 'Cá đuôi gai tù nhân' (Convict Tang) nhờ bộ đồng phục kẻ sọc đen trên nền trắng bạc và tính cách ôn hòa thích bơi theo đàn.","imageURL":"https://bionexus.vn/images/acanthurus-triostegus.jpg","referenceURL":"https://www.gbif.org/species/5209217"},{"id":616,"nodeId":512,"scientificName":"Acanthurus olivaceus","commonName":"Cá đuôi gai vai cam (Orange band Surgeonfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Đáy cát sỏi xen đá san hô chân rạn ở độ sâu 5–45 m","description":"Loài cá đuôi gai có sự lột xác màu sắc ngoạn mục từ màu vàng chanh tươi sáng lúc nhỏ sang màu xám bạc đeo 'quân hàm' màu cam lửa trên vai khi trưởng thành.","imageURL":"https://bionexus.vn/images/acanthurus-olivaceus.jpg","referenceURL":"https://www.gbif.org/species/5209196"},{"id":617,"nodeId":512,"scientificName":"Acanthurus pyroferus","commonName":"Cá đuôi gai đội lốt (Mimic Surgeonfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Đầm phá và sườn rạn san hô độ sâu 4–40 m","description":"Bậc thầy hóa trang của rạn san hô Thái Bình Dương với khả năng bắt chước y hệt ngoại hình của các loài cá thiên thần lùn khi còn nhỏ.","imageURL":"https://bionexus.vn/images/acanthurus-pyroferus.jpg","referenceURL":"https://www.gbif.org/species/5209154"},{"id":618,"nodeId":512,"scientificName":"Acanthurus sohal","commonName":"Cá đuôi gai Sohal (Sohal Surgeonfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8.1-8.4, Môi trường: Đỉnh rạn san hô ngoài khơi nơi sóng vỗ dữ dội độ sâu 0–20 m","description":"Vị vua của các rạn san hô Biển Đỏ với dáng bơi dũng mãnh như cá thu và cặp ngạnh đuôi màu cam sáng rực nổi bật trên nền vây xanh lam.","imageURL":"https://bionexus.vn/images/acanthurus-sohal.jpg","referenceURL":"https://www.gbif.org/species/5209184"},{"id":619,"nodeId":513,"scientificName":"Naso lituratus","commonName":"Cá kỳ lân gai cam (Orange Spine Surgeonfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô đá và đầm phá ngoài khơi độ sâu 3–50 m","description":"Được người chơi cá biển Việt Nam yêu mến gọi là 'Cá Môi Son' nhờ đôi môi màu cam đỏ tươi tắn trên gương mặt xám bạc lịch lãm.","imageURL":"https://bionexus.vn/images/naso-lituratus.jpg","referenceURL":"https://www.gbif.org/species/5209096"},{"id":620,"nodeId":513,"scientificName":"Naso elegans","commonName":"Cá kỳ lân thanh lịch (Elegant Unicornfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Sườn rạn san hô và đầm phá độ sâu 5–30 m","description":"Phiên bản Ấn Độ Dương rực sáng hơn của Cá Môi Son với chiếc vây lưng màu vàng kim chạy dọc từ gáy đến tận cuống đuôi.","imageURL":"https://bionexus.vn/images/naso-elegans.jpg","referenceURL":"https://www.gbif.org/species/5209095"},{"id":621,"nodeId":514,"scientificName":"Zanclus cornutus","commonName":"Cá thù lù (Moorish Idol)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8.1-8.4, Môi trường: Rạn san hô nông đến sâu từ 3 đến 180 m","description":"Loài cá duy nhất còn tồn tại của họ Zanclidae với hình dáng thanh tao kỳ vĩ và chiếc cờ lưng trắng phất phơ theo từng nhịp bơi.","imageURL":"https://bionexus.vn/images/zanclus-cornutus.jpg","referenceURL":"https://www.gbif.org/species/2374663"},{"id":622,"nodeId":515,"scientificName":"Centropyge bispinosa","commonName":"Cá thiên thần lùn hai gai (Twospined Angelfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Khe đá và hang hốc rạn san hô ngoài khơi độ sâu 5–45 m","description":"Viên ngọc lưỡng sắc phổ biến và khỏe mạnh bậc nhất của nhóm Cá thiên thần lùn (Dwarf Angelfish) với sắc tím lam quyện cùng sắc cam rực lửa.","imageURL":"https://bionexus.vn/images/centropyge-bispinosa.jpg","referenceURL":"https://www.gbif.org/species/2396495"},{"id":623,"nodeId":515,"scientificName":"Centropyge bicolor","commonName":"Cá thiên thần hai màu (Bicolor Angelfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-27°C, pH: 8.1-8.4, Môi trường: Đầm phá san hô và khe đá sườn rạn độ sâu 3–25 m","description":"Một trong những loài cá cảnh biển có sự đối lập màu sắc ấn tượng nhất: nửa trước vàng chanh rực sáng và nửa sau xanh lam thẫm như bầu trời đêm.","imageURL":"https://bionexus.vn/images/centropyge-bicolor.jpg","referenceURL":"https://www.gbif.org/species/2396484"},{"id":624,"nodeId":516,"scientificName":"Pomacanthus imperator","commonName":"Cá thiên thần hoàng đế (Emperor Angelfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8.1-8.4, Môi trường: Hang động và vách đá rạn san hô trưởng thành độ sâu 3–70 m","description":"Hoàng đế đích thực của rạn san hô nhiệt đới với bộ hoàng bào kẻ sọc vàng - xanh lam lộng lẫy và sự biến đổi hình thái kỳ diệu từ lúc nhỏ đến khi trưởng thành.","imageURL":"https://bionexus.vn/images/pomacanthus-imperator.jpg","referenceURL":"https://www.gbif.org/species/2396426"},{"id":625,"nodeId":516,"scientificName":"Pomacanthus semicirculatus","commonName":"Cá thiên thần bán nguyệt (Semicircle Angelfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô ven bờ và các hang đá ngầm độ sâu 1–40 m","description":"Loài cá thiên thần lớn khỏe mạnh và dễ thích nghi nhất trong chi Pomacanthus với các chóp vây kéo dài thướt tha viền xanh neon.","imageURL":"https://bionexus.vn/images/pomacanthus-semicirculatus.jpg","referenceURL":"https://www.gbif.org/species/2396399"},{"id":626,"nodeId":516,"scientificName":"Pomacanthus xanthometopon","commonName":"Cá thiên thần mặt vàng (Yellowface Angelfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8.1-8.4, Môi trường: Đầm phá và vách rạn san hô ngoài khơi nhiều hang hốc độ sâu 5–30 m","description":"Một kiệt tác hội họa dưới đáy biển khi mỗi chiếc vảy trên thân đều có tâm xanh lam viền vàng kim và khuôn mặt đeo mặt nạ xanh - vàng rực rỡ.","imageURL":"https://bionexus.vn/images/pomacanthus-xanthometopon.jpg","referenceURL":"https://www.gbif.org/species/2396411"},{"id":627,"nodeId":516,"scientificName":"Pomacanthus annularis","commonName":"Cá thiên thần vòng xanh (Bluering Angelfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Vùng rạn san hô ven bờ và vách đá nhiều bọt biển độ sâu 3–30 m","description":"Loài cá thiên thần biển tiêu biểu của vùng biển Đông Nam Á với những đường cong màu xanh neon phát sáng trên nền thân vàng đồng và chiếc đuôi trắng muốt.","imageURL":"https://bionexus.vn/images/pomacanthus-annularis.jpg","referenceURL":"https://www.gbif.org/species/2396404"},{"id":628,"nodeId":517,"scientificName":"Pygoplites diacanthus","commonName":"Cá thiên thần hoàng gia (Royal Angelfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-27°C, pH: 8.1-8.4, Môi trường: Hang động và gờ đá rạn san hô giàu hải miên ở độ sâu 3–45 m","description":"Loài duy nhất thuộc chi Pygoplites, được giới chơi cá cảnh biển tôn vinh là một trong những loài cá rạn có hoa văn vương giả đẹp nhất hành tinh.","imageURL":"https://bionexus.vn/images/pygoplites-diacanthus.jpg","referenceURL":"https://www.gbif.org/species/2396596"},{"id":629,"nodeId":518,"scientificName":"Chelmon rostratus","commonName":"Cá bướm mỏ nhọn (Banded Longsnout Butterflyfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô ven bờ, cửa sông và đầm phá độ sâu 1–25 m","description":"Loài cá bướm nổi tiếng của vùng biển Việt Nam với chiếc mỏ dài thanh mảnh chuyên gắp giun ống và đặc biệt được nuôi trong bể san hô để diệt hải quỳ rác Aiptasia.","imageURL":"https://bionexus.vn/images/chelmon-rostratus.jpg","referenceURL":"https://www.gbif.org/species/5209920"},{"id":630,"nodeId":519,"scientificName":"Forcipiger flavissimus","commonName":"Cá bướm mỏ dài vàng (Big long-nosed Butterflyfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Vách rạn san hô ngoài khơi và đầm phá độ sâu 2–60 m","description":"Sở hữu chiếc mỏ dài mảnh như chiếc nhíp y tế ('Forcipiger' nghĩa là mang kẹp nhíp) và sắc vàng tươi sáng giúp bừng sáng mọi bể cá cảnh biển.","imageURL":"https://bionexus.vn/images/forcipiger-flavissimus.jpg","referenceURL":"https://www.gbif.org/species/2385706"},{"id":631,"nodeId":520,"scientificName":"Chaetodon auriga","commonName":"Cá bướm cánh chỉ (Cross-stripe Butterfly)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Rạn san hô nông, bãi đá và đầm phá độ sâu 1–35 m","description":"Một trong những loài cá bướm khỏe mạnh, dẻo dai và đẹp mắt nhất với họa tiết các đường kẻ chéo chữ V vuông góc (chevron) và sợi chỉ vây lưng duyên dáng.","imageURL":"https://bionexus.vn/images/chaetodon-auriga.jpg","referenceURL":"https://www.gbif.org/species/2385390"},{"id":632,"nodeId":520,"scientificName":"Chaetodon lunula","commonName":"Cá bướm mặt trăng (Halfmoon Butterflyfish)","conservationStatus":"LC","environmentSpecs":"Nhiệt độ nước: 24-28°C, pH: 8-8.4, Môi trường: Đầm phá san hô và vách đá rạn độ sâu 1–30 m","description":"Được gọi là 'Cá bướm Gấu trúc Mỹ' (Raccoon Butterflyfish) nhờ chiếc mặt nạ đen viền trắng ngộ nghĩnh và khả năng dọn sạch hải quỳ rác Aiptasia.","imageURL":"https://bionexus.vn/images/chaetodon-lunula.jpg","referenceURL":"https://www.gbif.org/species/2385531"}];

